static float frand(void) { return (float)det_rand() / ((float)RAND_MAX + 1.0f); }  // Math.random in [0,1)
static float num(cJSON *o, const char *k, float def) {
    cJSON *n = cJSON_GetObjectItem(o, k);
    return cJSON_IsNumber(n) ? (float)n->valuedouble : def;
}
static int has(cJSON *o, const char *k) { return cJSON_GetObjectItem(o, k) != NULL; }
static const char *str(cJSON *o, const char *k) { return cJSON_GetStringValue(cJSON_GetObjectItem(o, k)); }
static int RND_between(int min, int max) { return (int)floorf(frand() * (max - min + 1) + min); }  // Phaser.Math.Between

