static float _basePlayerPxSpeed = 82.5f, _baseEnemySpeed = 0.77f * 0.3f, _baseProjectileSpeed = 0xa5,
             _baseGoldMultiplier = 1, _baseEnemyHealthMultiplier = 1, _baseExperienceMultiplier = 1;
