// I tasti premuti in questo frame (keydown di Phaser), letti una volta da menu_update/game_update: li usano le combinazioni e i segreti
static int KeyQ[32], nKeyQ;
static void KeyQ_poll(void) {
    nKeyQ = 0;
    for (int k; (k = GetKeyPressed()) && nKeyQ < 32;) KeyQ[nKeyQ++] = k;
    static int pos;  // sviluppo: VS_TYPE digita un tasto per frame dopo 1,5 s (^ _ < > frecce, ! Esc, # Invio, - meno)
    const char *s = getenv("VS_TYPE");
    if (!s || GetTime() < 1.5 || !s[pos] || nKeyQ >= 32) return;
    int ch = s[pos++];
    KeyQ[nKeyQ++] = ch == '^' ? KEY_UP : ch == '_' ? KEY_DOWN : ch == '<' ? KEY_LEFT : ch == '>' ? KEY_RIGHT : ch == '!' ? KEY_ESCAPE : ch == '#' ? KEY_ENTER
                  : ch == '-' ? KEY_MINUS : ch >= 'a' && ch <= 'z' ? ch - 32 : ch;
}
static int js_keyCode(int k) {  // KeyboardEvent.keyCode dal tasto di raylib
    if ((k >= KEY_A && k <= KEY_Z) || (k >= KEY_ZERO && k <= KEY_NINE)) return k;
    switch (k) {
    case KEY_UP: return 38; case KEY_DOWN: return 40; case KEY_LEFT: return 37; case KEY_RIGHT: return 39;
    case KEY_ESCAPE: return 27; case KEY_ENTER: case KEY_KP_ENTER: return 13; case KEY_MINUS: return 189; case KEY_KP_SUBTRACT: return 109;
    }
    return 1000 + k;
}
// Phaser.Input.Keyboard.KeyCombo (resetOnWrongKey, resetOnMatch) + ProcessKeyCombo; vero quando la combinazione e' completa
typedef struct { const int *codes; int n, index; float tLast, maxKeyDelay; } KeyCombo;
static int KeyCombo_process(KeyCombo *c, int code, float t) {
    int keyMatched = 0;
    if (code == c->codes[c->index] && !(c->index > 0 && c->maxKeyDelay > 0 && t > c->tLast + c->maxKeyDelay)) keyMatched = 1, c->index++, c->tLast = t;
    if (!keyMatched) { c->index = 0; return 0; }
    if (c->index < c->n) return 0;
    c->index = 0;  // ResetKeyCombo
    return 1;
}
static float now_ms(void) { return (float)(GetTime() * 1000); }  // event.timeStamp
static int tflag;  // Core.tflag: la catena di Smith (spam nel menu, spam, spam, humbug in partita entro 30 s)
static float tflagUntil;

// ============================================================================
// 0xaa4f: StageModifiers
// ============================================================================
typedef struct {
    float TimeLimit, ClockSpeed, PlayerPxSpeed, EnemySpeed, ProjectileSpeed, GoldMultiplier, EnemyHealthMultiplier,
        LuckBonus, XPBonus, StartingSpawns, EndCycles;
    struct { float start, hpPerMinute, speedPerMinute; int has; } TimeMods;
} StageModifiers;

static void StageModifiers_init(StageModifiers *m) {
    *m = (StageModifiers){ 0x708, 1, 1, 1, 1, 1, 1, 0, 1, 0, 0, { 0, 0, 0, 0 } };
}
static float orv(cJSON *o, const char *k, float def) { float v = num(o, k, 0); return v ? v : def; }  // a.x ? a.x : def
static Color hexc(unsigned c, float a) { return (Color){ (c >> 16) & 255, (c >> 8) & 255, c & 255, (unsigned char)(255 * fmaxf(0, fminf(1, a))) }; }
static void StageModifiers_Set(StageModifiers *m, cJSON *o) {
    if (!o) return;
    m->TimeLimit = orv(o, "TimeLimit", 0x708);
    m->ClockSpeed = orv(o, "ClockSpeed", 1);
    m->PlayerPxSpeed = orv(o, "PlayerPxSpeed", 1);
    m->EnemySpeed = orv(o, "EnemySpeed", 1);
    m->ProjectileSpeed = orv(o, "ProjectileSpeed", 1);
    m->GoldMultiplier = orv(o, "GoldMultiplier", 1);
    m->EnemyHealthMultiplier = orv(o, "EnemyHealthMultiplier", 1);
    m->LuckBonus = orv(o, "LuckBonus", 0);
    m->XPBonus = orv(o, "XPBonus", 1);
    m->StartingSpawns = orv(o, "StartingSpawns", 0);
    cJSON *tm = cJSON_GetObjectItem(o, "TimeMods");
    if (tm) {
        m->TimeMods.has = 1;
        m->TimeMods.start = orv(tm, "start", 0);
        m->TimeMods.hpPerMinute = orv(tm, "hpPerMinute", 0);
        m->TimeMods.speedPerMinute = orv(tm, "speedPerMinute", 0);
    }
}
static void StageModifiers_Add(StageModifiers *m, cJSON *o) {  // hyper e inverse sopra i mods dello stage
    if (!o) return;
    m->PlayerPxSpeed += orv(o, "PlayerPxSpeed", 0);
    m->EnemySpeed += orv(o, "EnemySpeed", 0);
    m->ProjectileSpeed += orv(o, "ProjectileSpeed", 0);
    m->GoldMultiplier += orv(o, "GoldMultiplier", 0);
    m->EnemyHealthMultiplier += orv(o, "EnemyHealthMultiplier", 0);
    m->LuckBonus += orv(o, "LuckBonus", 0);
    m->XPBonus += orv(o, "XPBonus", 0);
    m->StartingSpawns += orv(o, "StartingSpawns", 0);
    cJSON *tm = cJSON_GetObjectItem(o, "TimeMods");
    if (tm) {
        m->TimeMods.has = 1;
        m->TimeMods.start = fminf(num(tm, "start", 0), m->TimeMods.start);
        m->TimeMods.hpPerMinute += orv(tm, "hpPerMinute", 0);
        m->TimeMods.speedPerMinute += orv(tm, "speedPerMinute", 0);
    }
}

