    float DEFAULT_SPEED, radius, speed, time, value, feverMS;
    int goToPlayer, isStationary, disableGet, isCullable, isTeleportOnCull, isGem;
    int quiet;  // Silver Wind: volume 0.1 invece di 0.35; come nell'originale resta nel pool
    const char *itemType, *frameName;
    Vector2 currentDirection;
    TweenRef vacuumTween;
    PickupPool *pool;
    const PickupVT *vt;
    // Treasure (0x8af)
    int hasArcana, CurrentTreasureLevel;
    cJSON *CurrentTreasureTypes, *CurrentFixedTreasures;
    Sprite Cursor;
    Animation cursorIdle, cursorNeutral;
    Animation idle;  // Rosary/PocketWatch/Vacuum/Nft/Gilded: 'idle' a 10 fps
    // PickupGuarded (0x15ee2) + pickup arma (0xbf1f)
    const char *weaponType, *enemyType;
    void (*OnPickupCallback)(Pickup *p);  // owner.OnPickupCallback: la classe dello stage che l'ha messo (il formaggio del Dairy Plant)
    float spawnQuantity, spawnAngle, guardRadius, left, right, top, bottom, colorValue, totalTime, particlesInterval;
    int hasSpawned, despawnOnUnavailable;
    Sprite shadow, glow;
    TweenRef floatTween, shadowTween, glowTween;
    int hasFloat;
    struct Enemy *guards[32];  // PickupGuarded.guards
