    po_set("SoundsVolume", 0.5), po_set("MusicVolume", 0.5);  // SoundsEnabled/MusicEnabled ? 0.5 : 0
    po_sets("SelectedBGMMod", "BGM_Forest");                   // (sic) JSON.stringify(BGM_Forest)
    po_set("SelectedRandomEvents", 0);
    po_set("Coins", ceil(po_num("Coins")));
