static void AchievementManager_CheckForStartupAchievements(void);
void SaveSystem_Load(void) {
    cJSON_Delete(PlayerOptions);
    PlayerOptions = cJSON_Parse(PlayerOptions_ctor);
    time_t now = time(NULL);
    char d[32];
    strftime(d, sizeof(d), "%Y-%m-%dT%H:%M:%S.000Z", gmtime(&now));  // new Date()
    po_sets("saveDate", d);
    if (!SaveSystem_LoadType(SAVE_DEFAULT)) PlayerOptions_AsyncLoad();
    po_sets("TwitchUsername", "");
    PlayerOptions_Load_options();
    AchievementManager_CheckForStartupAchievements();  // PreloadScene
}
