// HUD: Phaser.GameObjects.Text/Image/Graphics e NineSlice (sottoinsieme)
// ============================================================================
#define MAX_SAFE_INTEGER 9007199254740991.0
#define ZInGameUI (MAX_SAFE_INTEGER - 0x3e8)
#define ZDamageNumber (MAX_SAFE_INTEGER - 0x2710)
static const char *lang1(const char *key, const char *a0);

// Text: lo stile dell'HUD non ha fontFamily, quindi Phaser usa 'Courier' (Courier New bold su Windows).
// semplificazione: qui ANY.ttf (il sostituto di Courier del gioco) con grassetto sintetico (+1 px); metriche di raylib, non MeasureText di Phaser
// HUD_TEXT_SCALE: scostamento voluto da Federico (2026-10-04), testi piu' leggibili sullo schermo della Vita; 1 = dimensioni originali
#define HUD_TEXT_SCALE 1.25f
typedef struct { Sprite s; char text[32]; float fontSize; } Text;
static void Text_draw(Sprite *s) {
    Text *t = s->owner;
    if (!s->visible || !*t->text) return;
    float size = t->fontSize * HUD_TEXT_SCALE;
    Vector2 m = MeasureTextEx(vs_font, t->text, size, 0);
    Vector2 p = { roundf(s->x - s->originX * (m.x + 1)), roundf(s->y - s->originY * m.y) };
    DrawTextEx(vs_font, t->text, p, size, 0, WHITE);
    DrawTextEx(vs_font, t->text, (Vector2){ p.x + 1, p.y }, size, 0, WHITE);
}
static void Text_setText(Text *t, const char *v) { snprintf(t->text, sizeof(t->text), "%s", v); }
static void add_text(Text *t, float x, float y, const char *v, float fontSize, float ox, float oy) {  // scene.add.text(...).setScrollFactor(0).setOrigin(ox, oy)
    sprite_init(&t->s, NULL, x, y);
    sprite_setOrigin(&t->s, ox, oy);
    t->s.owner = t;
    t->s.draw = Text_draw;
    t->s.scrollFactor0 = 1;
    t->fontSize = fontSize;
    Text_setText(t, v);
    children_add(&t->s);
}
static void add_image(Sprite *s, float x, float y, const char *atlas, const char *frame) {  // scene.add.image(...).setScrollFactor(0)
    sprite_init(s, frame_get(atlas, frame), x, y);
    s->scrollFactor0 = 1;
    children_add(s);
}
static float displayWidth(const Sprite *s) { return s->width * fabsf(s->scaleX); }

// NineSlice (phaser3-nineslice): angoli di sourceLayout.width x sourceLayout.height
static void nine_wh(const char *frame, int cw, int ch, Rectangle r, Color tint) {
    const Frame *f = frame_get("UI", frame);
    if (!f) { DrawRectangleRec(r, (Color){ 40, 40, 80, 230 }); return; }
    NPatchInfo n = { (Rectangle){ f->x, f->y, f->w, f->h }, cw, ch, cw, ch, NPATCH_NINE_PATCH };
    DrawTextureNPatch(*f->tex, n, r, (Vector2){ 0, 0 }, 0, tint);
}
static void nine(const char *frame, int corner, Rectangle r, Color tint) { nine_wh(frame, corner, corner, r, tint); }

