// 0x18645: MainUI (tempo, livello, monete, uccisioni, icone di armi e potenziamenti)
// ============================================================================
typedef struct { Sprite image; const char *weaponType; int level, isWeapon; } WeaponIconUI;
static struct {
    Text SurvivedSecondsText, PlayerLevelText, KillsText, PlayerCoinsText;
    Sprite CoinsIcon, KillsIcon, WeaponSlots, BlockedWeaponSlots[5];
    WeaponIconUI icons[32];  // memoria delle icone: WeaponIcons/PowerUpIcons puntano qui
    WeaponIconUI *WeaponIcons[16], *PowerUpIcons[16], *ExtraIcons[16];
    int n_icons, n_WeaponIcons, n_PowerUpIcons, n_ExtraIcons;
    float xIncrease, yOffset;
    int cols;
} MainUI;

#define HUDK 1.5f  // Vita: l'HUD ingrandito, ancorato ai bordi (il campo di gioco resta quello dell'originale)
static void MainUI_new(void) {
    memset(&MainUI, 0, sizeof(MainUI));
    MainUI.xIncrease = 0x10 * HUDK, MainUI.yOffset = 0x12 + 0x10 * (HUDK - 1) * 0, MainUI.cols = 6;
    MainUI.yOffset = 0x12;
    add_text(&MainUI.SurvivedSecondsText, 0.5f * game_width, 0x16, "0:00", 20 * HUDK, 0.5f, 0);
    add_text(&MainUI.PlayerLevelText, game_width - 4, 9, "LV 99", 15, 1, 0.5f);
    add_image(&MainUI.CoinsIcon, game_width - 4, 0x19 + 6, "UI", "CoinGold.png");
    sprite_setOrigin(&MainUI.CoinsIcon, 1, 0.5f);
    sprite_setScale(&MainUI.CoinsIcon, PixelScale * HUDK);
    MainUI.CoinsIcon.depth = ZInGameUI - 3;
    add_image(&MainUI.KillsIcon, game_width - 4, 0x19 + 6 + 0x12 * HUDK, "UI", "SkullToken.png");  // Vita: sotto le monete
    sprite_setOrigin(&MainUI.KillsIcon, 1, 0.5f);
    sprite_setScale(&MainUI.KillsIcon, PixelScale * HUDK);
    MainUI.KillsIcon.depth = ZInGameUI - 3;
    add_text(&MainUI.KillsText, MainUI.KillsIcon.x - displayWidth(&MainUI.KillsIcon) - 4, MainUI.KillsIcon.y, "9999", 12 * HUDK, 1, 0.5f);
    MainUI.KillsText.s.depth = ZInGameUI - 3;
    add_text(&MainUI.PlayerCoinsText, MainUI.CoinsIcon.x - displayWidth(&MainUI.CoinsIcon) - 4, MainUI.CoinsIcon.y, "9999", 12 * HUDK, 1, 0.5f);
    MainUI.PlayerCoinsText.s.depth = ZInGameUI - 3;
    add_image(&MainUI.WeaponSlots, 1, 0x12, "UI", "weaponSlots.psd");
    sprite_setOrigin(&MainUI.WeaponSlots, 0, 0);
    sprite_setScale(&MainUI.WeaponSlots, PixelScale * HUDK);
    MainUI.WeaponSlots.depth = ZInGameUI - 3;
    for (int i = 1; i < 6; i++) {
        Sprite *b = &MainUI.BlockedWeaponSlots[5 - i];  // push e poi reverse()
        add_image(b, 9 * HUDK + MainUI.xIncrease * i, 9 * HUDK + MainUI.yOffset, "UI", "no16.png");
        b->alpha = 0.5f;
        sprite_setScale(b, PixelScale * HUDK);
        b->depth = ZInGameUI - 2;
        b->visible = 0;
    }
    MainUI.PlayerCoinsText.s.depth = MainUI.CoinsIcon.depth = MainUI.PlayerLevelText.s.depth = MAX_SAFE_INTEGER;
    MainUI.SurvivedSecondsText.s.depth = MainUI.KillsIcon.depth = MainUI.KillsText.s.depth = MAX_SAFE_INTEGER;
    // StatsPanel (0xe199): creato e subito nascosto (setVisible(false)); da tradurre con PauseStatsScene
}
