static void MainUI_RearrangeIcons(void) {
    for (int i = 0; i < MainUI.n_WeaponIcons; i++) {
        Sprite *im = &MainUI.WeaponIcons[i]->image;
        im->x = MainUI.xIncrease * i, im->y = MainUI.yOffset;
    }
    int l = -1, r = -1;  // LEFT e RIGHT in testa ai potenziamenti
    for (int i = 0; i < MainUI.n_PowerUpIcons; i++) {
        if (l < 0 && !strcmp(MainUI.PowerUpIcons[i]->weaponType, "LEFT")) l = i;
        if (r < 0 && !strcmp(MainUI.PowerUpIcons[i]->weaponType, "RIGHT")) r = i;
    }
    if (l >= 0 && r >= 0) {
        WeaponIconUI **a = MainUI.PowerUpIcons, *R = a[r], *L = a[l];
        memmove(&a[1], &a[0], r * sizeof(*a)), a[0] = R;  // splice(r, 1) + unshift
        if (l < r) l++;
        memmove(&a[1], &a[0], l * sizeof(*a)), a[0] = L;
    }
    for (int i = 0; i < MainUI.n_PowerUpIcons; i++) {
        Sprite *im = &MainUI.PowerUpIcons[i]->image;
        im->x = MainUI.xIncrease * (i % MainUI.cols), im->y = MainUI.yOffset + MainUI.xIncrease + MainUI.xIncrease * (i / MainUI.cols);
    }
    for (int i = 0; i < MainUI.n_ExtraIcons; i++) {  // dopo i potenziamenti, nella stessa griglia
        int k = MainUI.n_PowerUpIcons + i;
        Sprite *im = &MainUI.ExtraIcons[i]->image;
        im->x = MainUI.xIncrease * (k % MainUI.cols), im->y = MainUI.yOffset + MainUI.xIncrease + MainUI.xIncrease * (k / MainUI.cols);
    }
}
static void MainUI_AddExtra(const char *type) {  // icone di armi nascoste e arcane: niente slot, solo l'immagine
    for (int i = 0; i < MainUI.n_ExtraIcons; i++)
        if (!strcmp(MainUI.ExtraIcons[i]->weaponType, type)) { MainUI.ExtraIcons[i]->level++; MainUI_RearrangeIcons(); return; }
    if (MainUI.n_icons >= 32 || MainUI.n_ExtraIcons >= 16) return;
    cJSON *base = cJSON_GetArrayItem(cJSON_GetObjectItem(data_get("weapons"), type), 0);
    WeaponIconUI *w = &MainUI.icons[MainUI.n_icons++];
    w->weaponType = type, w->level = 1, w->isWeapon = 0;
    int k = MainUI.n_PowerUpIcons + MainUI.n_ExtraIcons;
    add_image(&w->image, MainUI.xIncrease * (MainUI.n_PowerUpIcons % MainUI.cols), MainUI.yOffset + MainUI.xIncrease + MainUI.xIncrease * (k / MainUI.cols),
              str(base, "texture"), str(base, "frameName"));  // (sic) x dalla sola colonna dei potenziamenti; RearrangeIcons la sistema
    sprite_setOrigin(&w->image, 0, 0);
    w->image.depth = ZInGameUI - 2;
    if (w->image.width) sprite_setScale(&w->image, 0x10 * HUDK / w->image.width);
    MainUI.ExtraIcons[MainUI.n_ExtraIcons++] = w;
    MainUI_RearrangeIcons();
}
static void MainUI_Add(const char *type) {
    cJSON *base = cJSON_GetArrayItem(cJSON_GetObjectItem(data_get("weapons"), type), 0);
    int asPowerUp = cJSON_IsTrue(cJSON_GetObjectItem(base, "isPowerUp")) || MainUI.n_WeaponIcons >= 6;
    WeaponIconUI **arr = asPowerUp ? MainUI.PowerUpIcons : MainUI.WeaponIcons;
    int n = asPowerUp ? MainUI.n_PowerUpIcons : MainUI.n_WeaponIcons;
    for (int i = 0; i < n; i++)
        if (!strcmp(arr[i]->weaponType, type)) { arr[i]->level++; MainUI_RearrangeIcons(); return; }
    if (MainUI.n_icons >= 32 || n >= 16) return;
    WeaponIconUI *w = &MainUI.icons[MainUI.n_icons++];
    w->weaponType = type, w->level = 1, w->isWeapon = !asPowerUp;
    float x = w->isWeapon ? MainUI.xIncrease * MainUI.n_WeaponIcons : MainUI.xIncrease * (MainUI.n_PowerUpIcons % MainUI.cols);
    float y = w->isWeapon ? MainUI.yOffset : MainUI.yOffset + MainUI.xIncrease + MainUI.xIncrease * (MainUI.n_PowerUpIcons / MainUI.cols);
    add_image(&w->image, x, y, str(base, "texture"), str(base, "frameName"));
    sprite_setOrigin(&w->image, 0, 0);
    w->image.depth = ZInGameUI - 2;
    if (w->image.width) sprite_setScale(&w->image, 0x10 * HUDK / w->image.width);
    if (w->isWeapon) MainUI.WeaponIcons[MainUI.n_WeaponIcons++] = w;
    else MainUI.PowerUpIcons[MainUI.n_PowerUpIcons++] = w;
    MainUI_RearrangeIcons();
}
static void MainUI_AddWeaponIcon(const char *type) { if (Players_isLocal()) MainUI_Add(type); }
static void MainUI_ShowWeaponBlocks(int n) { for (int i = 0; i < n && i < 5; i++) MainUI.BlockedWeaponSlots[i].visible = 1; }
static void MainUI_Remove(const char *type) {  // l'icona sparisce dai potenziamenti o dalle armi, poi RearrangeIcons
    if (!Players_isLocal()) return;
    for (int k = 0; k < 2; k++) {
        WeaponIconUI **a = k == 0 ? MainUI.PowerUpIcons : MainUI.WeaponIcons;
        int *n = k == 0 ? &MainUI.n_PowerUpIcons : &MainUI.n_WeaponIcons;
        for (int i = 0; i < *n; i++) {
            if (strcmp(a[i]->weaponType, type)) continue;
            children_remove(&a[i]->image);
            memmove(&a[i], &a[i + 1], (*n - i - 1) * sizeof(*a));
            (*n)--;
            k = 2;
            break;
        }
    }
    MainUI_RearrangeIcons();
}
