    sprite_setFrame(&p->s, frame_get("characters", "Gash_body_i01.png"));
    make_anim(&p->walk2, "characters", "Gash_body_i0", 1, 1, 0, 1, -1);
    anims_play(&p->s, &p->walk2, 0);
    Player_SetMaxHistory(p, 1);
