static void Pickup_DeSpawn(Pickup *p);
static void RunPickups_push(const char *t) { if (Core.n_RunPickups < 512) Core.RunPickups[Core.n_RunPickups++] = t; }
static void json_inc(cJSON *o, const char *k) {  // o[k] += 1 sui dati in memoria
    if (!o) return;
    cJSON *n = cJSON_GetObjectItem(o, k);
    if (n) cJSON_SetNumberValue(n, n->valuedouble + 1);
    else cJSON_AddItemToObject(o, k, cJSON_CreateNumber(1));
}
static void make_anim(Animation *a, const char *atlas, const char *prefix, int start, int end, int pad, float fps, int repeat) {
    a->n = anims_generateFrameNames(atlas, prefix, start, end, pad, a->frames, ANIM_MAX_FRAMES);
    a->frameRate = fps;
    a->msPerFrame = 1000.0f / fps;
    a->repeat = repeat;
}

