static void Rosary_GetTaken(Pickup *p) { if (p->disableGet) return; Core_RosaryDamage(); RunPickups_push(p->itemType); Pickup_SetSeenItem(p->itemType); Pickup_GetTaken(p); }        // 0x608c
static void Orologion_GetTaken(Pickup *p) { if (p->disableGet) return; Core_TimeStop(); RunPickups_push(p->itemType); Pickup_SetSeenItem(p->itemType); Pickup_GetTaken(p); }        // 0x11e6e
static void Vacuum_GetTaken(Pickup *p) { if (p->disableGet) return; Core_TurnOnVacuum(); RunPickups_push(p->itemType); Pickup_SetSeenItem(p->itemType); Pickup_GetTaken(p); Sound_PlaySimple("Vacuum", 0.6f); }  // 0x1386
static Weapon *Core_AddHiddenWeapon(const char *type);
static void Nft_GetTaken(Pickup *p) {  // 0x165ca: Nduja Fritta
    if (p->disableGet) return;
    Weapon *w = NULL;
    for (int i = 0; i < Core.n_HiddenWeapons; i++) if (!strcmp(Core.HiddenWeapons[i]->bulletType, "NDUJA")) w = Core.HiddenWeapons[i];
    if (w) {
        w->totalTime = fmaxf(1, w->totalTime - 0x2710);
        for (int i = 0; i < Core.n_HiddenWeapons; i++)
            if (!strcmp(Core.HiddenWeapons[i]->bulletType, "NDUJA_COUNTER")) Core.HiddenWeapons[i]->totalTime = w->totalTime;
    } else Core_AddHiddenWeapon("NDUJA");
    RunPickups_push(p->itemType);
    Pickup_SetSeenItem(p->itemType);
    Pickup_GetTaken(p);
}
static void Gilded_GetTaken(Pickup *p) {  // 0x17e91: Gold Fever (compare dal livello 30)
    if (p->disableGet) return;
    GoldFever_Start(0x2710);  // Core.TriggerGoldFever(10000)
    Core_TurnOnVacuumForGold();
    RunPickups_push(p->itemType);
    Pickup_SetSeenItem(p->itemType);
    Pickup_GetTaken(p);
}

// --- 0x15ee2 PickupGuarded + 0xbf1f pickup arma: fluttua, bagliore arcobaleno, ombra; le guardie appaiono da vicino --------
static void PickupGuarded_UpdateBounds(Pickup *p) {
    p->left = p->s.x - p->guardRadius, p->right = p->s.x + p->guardRadius, p->top = p->s.y - p->guardRadius, p->bottom = p->s.y + p->guardRadius;
}
static EnemyPool *StageEvent_pool(Stage *st, const char *type);
static Enemy *EnemyPool_SpawnAt(EnemyPool *p, float x, float y);
static void PickupGuarded_TriggerSpawn(Pickup *p) {
    if (p->hasSpawned) return;
    p->hasSpawned = 1;
    if (!p->enemyType || !p->spawnQuantity) return;
    EnemyPool *pool = StageEvent_pool(Core.Stage, p->enemyType);
    if (!pool) return;
    float a = 0;
    for (int i = 0; i < p->spawnQuantity; i++) {
        float x = p->s.x + 0x30 * cosf(a) * 3, y = p->s.y + 0x30 * sinf(a) * 3;
        a += p->spawnAngle / (p->spawnQuantity - 1);
        Enemy *e = EnemyPool_SpawnAt(pool, x, y);
        if (e) e->isCullable = 0;
        if (e && p->n_guards < 32) p->guards[p->n_guards++] = e;
    }
}
static void WeaponPickup_float(Pickup *p) {  // floatTween: y - 8 in yoyo, Sine.easeInOut
    if (p->hasFloat) tween_stop(p->floatTween), tween_remove(p->floatTween);
    p->floatTween = tweens_add((TweenConfig){ .props = { { &p->s.y, NULL, p->s.y - 8 } }, .nprops = 1, .duration = 0x3e8, .ease = Ease_SineInOut, .loop = -1, .yoyo = 1 });
    p->hasFloat = 1;
}
static void WeaponPickup_ctor(Pickup *p) {
    p->weaponType = "VOID";
    p->particlesInterval = 0xc8, p->totalTime = 0x64;
    p->despawnOnUnavailable = 1;
    sprite_setScale(&p->s, PixelScale);
    p->isStationary = 1;
    p->spawnQuantity = 0xc, p->guardRadius = 0xc8, p->spawnAngle = PI;
    sprite_init(&p->shadow, frame_get("items", "ShadowSpot.png"), 0, 0);
    sprite_init(&p->glow, frame_get("vfx", "round.png"), 0, 0);
    // Cursor e CursorIcon: visibili solo con PlayerOptions.ShowPickups, spento di default
}
static void WeaponPickup_OnRecycle(Pickup *p) {
    Pickup_OnRecycle(p);
    p->guardRadius = 0.5f * 0x1c8;  // PickupGuarded.OnRecycle: GAMEPLAY_PIXEL_HEIGHT / 2
    PickupGuarded_UpdateBounds(p);
    p->hasSpawned = 0;
    if (!list_contains(&Core.PickupsWithArrows, &p->s)) list_add(&Core.PickupsWithArrows, &p->s);
    p->colorValue = 0;
    WeaponPickup_float(p);
    p->shadowTween = tweens_add((TweenConfig){ .props = { { &p->shadow.scaleX, &p->shadow.scaleY, 0.75f } }, .nprops = 1, .duration = 0x3e8, .ease = Ease_SineInOut, .loop = -1, .yoyo = 1 });
    children_add(&p->shadow);
    p->shadow.x = p->s.x, p->shadow.y = p->s.y;
    sprite_setScale(&p->shadow, 1);
    p->shadow.alpha = 0.5f;
    children_add(&p->glow);
    p->glow.x = p->s.x, p->glow.y = p->s.y;
    p->glow.blendAdd = 1;
    p->glow.alpha = 0.5f;
    p->glowTween = tweens_add((TweenConfig){ .props = { { &p->glow.alpha, NULL, 0 } }, .nprops = 1, .duration = 0x1f4, .loop = -1, .yoyo = 1 });
}
static void WeaponPickup_DeSpawn(Pickup *p) {
    Pickup_DeSpawn(p);
    tween_remove(p->floatTween), tween_remove(p->shadowTween), tween_remove(p->glowTween);
    p->hasFloat = 0;
    children_remove(&p->shadow);
    children_remove(&p->glow);
}
static void WeaponPickup_SetWeaponType(Pickup *p, const char *t) {
    cJSON *b = cJSON_GetArrayItem(cJSON_GetObjectItem(data_get("weapons"), t), 0);
    p->frameName = str(b, "frameName");
    sprite_setFrame(&p->s, frame_get(str(b, "texture"), p->frameName));
    p->weaponType = t;
}
static int LevelUpFactory_InStore(const char *t);
static void WeaponPickup_Update(Pickup *p) {
    if (p->goToPlayer && !p->isStationary) Pickup_GoToPlayer(p);  // Pickup.Update
    if (!p->hasSpawned && !(Core.Player->s.y > p->bottom || Core.Player->s.y < p->top || Core.Player->s.x > p->right || Core.Player->s.x < p->left))
        PickupGuarded_TriggerSpawn(p);
    p->glow.x = p->s.x, p->glow.y = p->s.y;
    float h = game_height;
    p->s.depth = h, p->shadow.depth = h - 1, p->glow.depth = h;
    p->totalTime += 0x64 / 6.0f;  // semplificazione: Update(delta) riceve ~16.7 ms per frame; qui lo scandisce Core_Update ogni frame
    if (p->totalTime > p->particlesInterval) { p->totalTime = 0; manager_emitParticleAt(Core.PfxEmitter_Pickups, p->s.x, p->s.y); }
    p->colorValue += 0.1f;
    p->glow.tint = (unsigned)(0xff * fabsf(sinf(p->colorValue))) << 16 | (unsigned)(0xff * fabsf(cosf(0.5f * p->colorValue))) << 8 | (unsigned)(0xc8 + 0x37 * fabsf(cosf(p->colorValue)));
    if (p->despawnOnUnavailable && !LevelUpFactory_InStore(p->weaponType)) { WeaponPickup_DeSpawn(p); return; }  // owner.OnPickupCallback: vuoto
    Vector2 sxy = Pickup_safeXY(p, p->s.x, p->s.y);
    if (sxy.x != p->s.x || sxy.y != p->s.y) { p->s.x = sxy.x, p->s.y = sxy.y; WeaponPickup_float(p); p->shadow.x = p->s.x, p->shadow.y = p->s.y; }
}
static void WeaponPickup_GetTaken(Pickup *p) {
    if (p->disableGet) return;
    // triggerOnGet: solo per le maschere GOLD/SILVER/LEFT/RIGHT
    if (Core.n_FoundWeaponQueue < 16) Core.FoundWeaponQueue[Core.n_FoundWeaponQueue++] = p->weaponType;
    Pickup_GetTaken(p);
}

// --- 0x4d2b: la reliquia a terra (PickupGuarded), con la freccia verde verso di lei quando e' fuori schermo ---------
static void Relic_ctor(Pickup *p) {
    WeaponPickup_ctor(p);  // stessi particlesInterval, totalTime, scala, isStationary, ombra e alone
    p->weaponType = NULL, p->despawnOnUnavailable = 0;
    sprite_init(&p->Cursor, frame_get("UI", "arrow_01.png"), p->s.x, p->s.y);
    p->Cursor.depth = 0x270f;
    sprite_setScale(&p->Cursor, 2);
    p->Cursor.alpha = 1;
    sprite_setTint(&p->Cursor, 0xff00);
    children_add(&p->Cursor);
    make_anim(&p->cursorIdle, "UI", "arrow_", 1, 8, 2, 0x10, -1);
    anims_play(&p->Cursor, &p->cursorIdle, 0);
}
static void Relic_OnRecycle(Pickup *p) {
    WeaponPickup_OnRecycle(p);
    p->Cursor.visible = 1;
}
static void Relic_DeSpawn(Pickup *p) {
    WeaponPickup_DeSpawn(p);
    p->Cursor.visible = 0;
}
static void Relic_SetItemType(Pickup *p, const char *t) {
    cJSON *it = cJSON_GetObjectItem(data_get("items"), t);
    sprite_setFrame(&p->s, frame_get(str(it, "texture"), str(it, "frameName")));
    p->itemType = t;  // il pool la ritrova dal tipo della classe (vt->itemType)
}
static void Relic_Update(Pickup *p) {
    if (p->goToPlayer && !p->isStationary) Pickup_GoToPlayer(p);  // PickupGuarded.Update
    if (!p->hasSpawned && !(Core.Player->s.y > p->bottom || Core.Player->s.y < p->top || Core.Player->s.x > p->right || Core.Player->s.x < p->left))
        PickupGuarded_TriggerSpawn(p);
    p->shadow.x = p->s.x, p->shadow.y = p->s.y;
    p->glow.x = p->s.x, p->glow.y = p->s.y;
    float h = game_height;
    p->s.depth = h, p->shadow.depth = h - 1, p->glow.depth = h;
    p->totalTime += 0x64 / 6.0f;  // Update(delta): un frame a 60 FPS, come WeaponPickup_Update
    if (p->totalTime > p->particlesInterval) { p->totalTime = 0; manager_emitParticleAt(Core.PfxEmitter_Pickups, p->s.x, p->s.y); }
    p->colorValue += 0.1f;
    p->glow.tint = (unsigned)(0xff * fabsf(sinf(p->colorValue))) << 16 | (unsigned)(0xff * fabsf(cosf(0.5f * p->colorValue))) << 8 | (unsigned)(0xc8 + 0x37 * fabsf(cosf(p->colorValue)));
    if (fabsf(p->s.x - Core.Player->s.x) < 0.5f * game_width && fabsf(p->s.y - Core.Player->s.y) < 0.5f * game_height) p->Cursor.visible = 0;
    else {
        float a = Pickup_AngleFromTargetRadians(p);
        p->Cursor.angle = a * RAD2DEG;
        p->Cursor.x = Core.Player->s.x + 0.45f * cosf(a) * game_width;
        p->Cursor.y = Core.Player->s.y + 0.45f * sinf(a) * game_height;
        p->Cursor.visible = 1;
    }
}
static void Relic_GetTaken(Pickup *p) {
    if (p->disableGet) return;
    p->Cursor.visible = 0;
    Core.CurrentFoundRelic = p->itemType;
    if (!strcmp(p->itemType, "RELIC_3DGLASSES")) Glasses_fx = 1, Glasses_left = 30;  // la realta' si piega per 30 s; poi Vista 3D dal menu
    if (Core.n_RelicQueue < 16) Core.RelicQueue[Core.n_RelicQueue++] = p->itemType;
    Pickup_SetSeenItem(p->itemType);
    Pickup_GetTaken(p);
}

// --- 0xf623: EggManager, le uova d'oro di ogni personaggio in PlayerOptions.EggData ---------------------------------
static const struct { const char *name; double value; } EggAttr[19] = {
    { "maxHp", 1 }, { "armor", 0.1 }, { "regen", 0.1 }, { "moveSpeed", 0.01 }, { "power", 0.01 }, { "cooldown", -0.005 }, { "area", 0.01 },
    { "speed", 0.01 }, { "duration", 0.01 }, { "amount", 0.1 }, { "luck", 0.01 }, { "growth", 0.01 }, { "greed", 0.01 }, { "curse", 0.01 },
    { "magnet", 0.3 }, { "revivals", 0.1 }, { "rerolls", 0.1 }, { "skips", 0.2 }, { "banish", 0.2 } };
static cJSON *Egg_char(int make) {  // EggData[SelectedCharacter], creato vuoto se serve
    cJSON *d = po("EggData"), *c = cJSON_GetObjectItem(d, po_str("SelectedCharacter"));
    if (!c && make) cJSON_AddItemToObject(d, po_str("SelectedCharacter"), c = cJSON_CreateObject());
    return c;
}
static void json_addnum(cJSON *o, const char *k, double v) {  // o[k] === undefined && (o[k] = 0), o[k] += v
    cJSON *n = cJSON_GetObjectItem(o, k);
    if (!n) cJSON_AddItemToObject(o, k, cJSON_CreateNumber(v));
    else cJSON_SetNumberValue(n, n->valuedouble + v);
}
static int EggManager_AddGoldenEgg(void) {  // restituisce l'indice dell'attributo pescato
    cJSON *c = Egg_char(1);
    int a = RND_between(0, 18);  // PickRandomAttribute
    json_addnum(c, EggAttr[a].name, EggAttr[a].value);
    json_addnum(c, "total", 1);
    json_addnum(po("EggData"), "total", 1);
    if (!po_has("CollectedItems", "RELIC_GOLDENEGG")) {
        obj_set(cJSON_GetObjectItem(data_get("items"), "RELIC_GOLDENEGG"), "seen", cJSON_CreateTrue());
        po_push("CollectedItems", "RELIC_GOLDENEGG");
    }
    return a;
}
static void EggManager_ApplyBonuses(void) {
    cJSON *c = Egg_char(0);
    if (!c) return;
    Player *p = Core.Player;
    p->power += num(c, "power", 0), p->area += num(c, "area", 0), p->speed += num(c, "speed", 0), p->cooldown += num(c, "cooldown", 0);
    p->duration += num(c, "duration", 0), p->moveSpeed += num(c, "moveSpeed", 0), p->growth += num(c, "growth", 0), p->luck += num(c, "luck", 0);
    p->maxHp += num(c, "maxHp", 0), p->regen += num(c, "regen", 0), p->greed += num(c, "greed", 0), p->curse += num(c, "curse", 0);
    Core.Magnet->radius += num(c, "magnet", 0);
    p->amount += floor(num(c, "amount", 0)), p->armor += floor(num(c, "armor", 0)), p->rerolls += floor(num(c, "rerolls", 0));
    p->skips += floor(num(c, "skips", 0)), p->banish += floor(num(c, "banish", 0)), p->revivals += floor(num(c, "revivals", 0));
}
static int EggAttr_find(const char *name) { for (int i = 0; i < 19; i++) if (!strcmp(EggAttr[i].name, name)) return i; return -1; }
static void Egg_dropTotals(cJSON *c, int n) {  // total del personaggio (mai sotto zero) e totale generale
    cJSON *t = cJSON_GetObjectItem(c, "total"), *g = cJSON_GetObjectItem(po("EggData"), "total");
    if (t && t->valuedouble > 0) cJSON_SetNumberValue(t, fmax(0, t->valuedouble - n));
    if (g) cJSON_SetNumberValue(g, g->valuedouble - n);
}
static void EggManager_RemoveAllSpecificEggs(const char *name) {
    cJSON *c = Egg_char(0);
    int a = EggAttr_find(name), n = 0;
    if (!c || a < 0) return;
    cJSON *v = cJSON_GetObjectItem(c, name);
    if (v && v->valuedouble != 0) {
        double x = v->valuedouble;
        if (strcmp(name, "cooldown")) { while (x > 0) x -= EggAttr[a].value, n++; if (x < 0) x = 0; }
        else { while (x < 0) x += EggAttr[a].value, n++; if (x > 0) x = 0; }
        cJSON_SetNumberValue(v, x);
    }
    if (n) Egg_dropTotals(c, n);
}
static int EggManager_RemoveRandomEgg(void) {  // (sic) restituisce sempre l'attributo pescato, tolto o no: vero se il personaggio ha uova
    cJSON *c = Egg_char(0);
    if (!c) return 0;
    int a = RND_between(0, 18);
    cJSON *v = cJSON_GetObjectItem(c, EggAttr[a].name);
    if (v && v->valuedouble != 0) {
        double x = v->valuedouble - EggAttr[a].value;
        if (strcmp(EggAttr[a].name, "cooldown") && x < 0) x = 0;
        cJSON_SetNumberValue(v, x);
        Egg_dropTotals(c, 1);
    }
    return 1;
}
static int EggManager_RemoveBonuses(void) {  // l'inverso di ApplyBonuses (per Astral Stair senza le sue reliquie); restituisce total
    cJSON *c = Egg_char(0);
    if (!c) return 0;
    Player *p = Core.Player;
    p->power -= num(c, "power", 0), p->area -= num(c, "area", 0), p->speed -= num(c, "speed", 0), p->cooldown -= num(c, "cooldown", 0);
    p->duration -= num(c, "duration", 0), p->moveSpeed -= num(c, "moveSpeed", 0), p->growth -= num(c, "growth", 0), p->luck -= num(c, "luck", 0);
    p->maxHp -= num(c, "maxHp", 0), p->regen -= num(c, "regen", 0), p->greed -= num(c, "greed", 0), p->curse -= num(c, "curse", 0);
    Core.Magnet->radius -= num(c, "magnet", 0);
    p->amount -= floor(num(c, "amount", 0)), p->armor -= floor(num(c, "armor", 0)), p->rerolls -= floor(num(c, "rerolls", 0));
    p->skips -= floor(num(c, "skips", 0)), p->banish -= floor(num(c, "banish", 0)), p->revivals -= floor(num(c, "revivals", 0));
    return (int)num(c, "total", 0);
}
static void EggManager_RemoveAllEggs(void) {
    cJSON *c = Egg_char(0);
    if (!c) return;
    cJSON *z = cJSON_CreateObject();
    cJSON_AddNumberToObject(z, "total", 0);
    cJSON_ReplaceItemInObject(po("EggData"), po_str("SelectedCharacter"), z);
}
static const char *EggManager_lookUpFrame(int a) {
    static const char *const F[19] = { "HeartBlack.png", "ArmorIron.png", "HeartRuby.png", "Wing.png", "Leaf.png", "Book2.png", "Candelabra.png", "Gauntlet.png",
        "EmblemEye.png", "Ring.png", "Clover.png", "Crown.png", "Mask.png", "Curse.png", "OrbGlow.png", "Tiramisu.png", "Dice.png", "Skip.png", "Banish.png" };
    return F[a];
}
// ShowResultAt: l'icona dell'attributo e "+valore" (scala 2, tinta a caso, ombra) che salgono di 20 px e svaniscono in 2 s
typedef struct { Sprite icon, txt; char text[24]; } EggResult;
static void EggResult_drawText(Sprite *s) {
    EggResult *r = s->owner;
    if (s->alpha <= 0) return;
    float cx = s->scrollFactor0 ? 0 : camera_scrollX, cy = s->scrollFactor0 ? 0 : camera_scrollY, size = 16 * s->scaleX;
    Vector2 m = MeasureTextEx(vs_font, r->text, size, 0), p = { roundf(s->x - cx), roundf(s->y - cy - 0.5f * m.y) };
    DrawTextEx(vs_font, r->text, (Vector2){ p.x + 2, p.y + 2 }, size, 0, Fade(BLACK, s->alpha));  // setShadow(2, 2, '#000')
    DrawTextEx(vs_font, r->text, p, size, 0, Fade(GetColor(s->tint << 8 | 0xff), s->alpha));
}
static void EggResult_done(void *ctx) { EggResult *r = ctx; children_remove(&r->icon), children_remove(&r->txt); free(r); }
static void EggManager_ShowResultAt(float tx, float ty, int a, float ox, float oy, int tint) {
    EggResult *r = calloc(1, sizeof(EggResult));
    float x = tx + ox + frand() * ox, y = ty + oy + frand() * oy;
    sprite_init(&r->icon, frame_get("items", EggManager_lookUpFrame(a)), x, y);
    sprite_setScale(&r->icon, 2), r->icon.depth = 0xc1c;
    children_add(&r->icon);
    snprintf(r->text, sizeof(r->text), "%s%g", EggAttr[a].value > 0 ? "+" : "", EggAttr[a].value);
    static const unsigned T[3] = { 0xffff00, 0xff00, 0xffff };
    sprite_init(&r->txt, NULL, x + 0x20, y);
    r->txt.owner = r, r->txt.draw = EggResult_drawText, r->txt.scaleX = r->txt.scaleY = 2, r->txt.depth = 0xc1c;
    r->txt.tint = tint >= 0 ? (unsigned)tint : T[RND_between(0, 2)];
    children_add(&r->txt);
    tweens_add((TweenConfig){ .props = { { &r->icon.alpha, NULL, 0 }, { &r->icon.y, NULL, y - 0x14 } }, .nprops = 2, .duration = 0x7d0 });
    tweens_add((TweenConfig){ .props = { { &r->txt.alpha, NULL, 0 }, { &r->txt.y, NULL, y - 0x14 } }, .nprops = 2, .duration = 0x7d0, .onComplete = EggResult_done, .ctx = r });
}

// --- 0xc903 mercante (Pantalone) e 0x11e05 Eggman: toccati aprono il negozio, con le maschere o le uova che salgono ---
static void Merchant_init(Pickup *p, int egg) {
    sprite_setScale(&p->s, PixelScale);
    body_setCircle(&p->s.body, 0x10, p->s.body.offset.x, p->s.body.offset.y);
    p->pfx = particles_add();
    EmitterConfig c = { .lifespan = EOP(0x3e8), .rotate = egg ? ERND(-0x3c, 0x3c) : ERND(-0x14, 0x14), .angle = egg ? ERND(0xc8, 0x154) : ERND(0x104, 0x118),
                        .speed = egg ? ERND(0x32, 0x46) : ERND(0x14, 0x32), .quantity = egg ? 4 : 1, .scale = ERANGE(1, 0.75f), .alpha = ERANGE(1, 0), .frequency = 0x1f4, .on = 1 };
    static const char *const M[5] = { "mask1.png", "mask2.png", "mask3.png", "mask4.png", "mask5.png" };
    for (int i = 0; i < (egg ? 2 : 5); i++) c.frames[i] = egg ? frame_get("items", "goldenegg.png") : frame_get("vfx", M[i]);
    c.nframes = egg ? 2 : 5;
    p->pfxE = particles_createEmitter(p->pfx, c);
}
static void Merchant_ctor(Pickup *p) { Merchant_init(p, 0); }
static void Eggman_ctor(Pickup *p) { Merchant_init(p, 1); }
static void Merchant_OnRecycle(Pickup *p) {
    Pickup_OnRecycle(p);
    p->goToPlayer = 1, p->isStationary = 1;
    sprite_setFrame(&p->s, frame_get("items", p->vt->ctor == Eggman_ctor ? "Eggman.png" : "Pantalone.png"));
}
static void Merchant_Update(Pickup *p) {
    if (p->goToPlayer && !p->isStationary) Pickup_GoToPlayer(p);  // super.Update
    p->s.depth = 9 + p->s.y - Core.Player->s.y, p->pfx->s.depth = p->s.depth - 1;
    Vector2 s = Pickup_safeXY(p, p->s.x, p->s.y);
    p->s.x = s.x, p->s.y = s.y, p->pfxE->x = p->s.x, p->pfxE->y = p->s.y;  // particles.x/y: l'emettitore segue il mercante
}
static void Merchant_GetTaken(Pickup *p) {
    if (p->disableGet) return;
    emitter_stop(p->pfxE);  // (sic) mai riacceso: un mercante riciclato non fa piu' maschere
    Core.MerchantInventory = p->vt->ctor == Eggman_ctor;
    Core.StartShopScene = 1;
    Pickup_GetTaken(p);
}

// --- 0x639b: il guaritore di Moongolow, sette occhi neri in orbita che respirano ------------------------------------
typedef struct { Sprite eye[7]; float r[7], a[7]; } HealerX;
static void Healer_ctor(Pickup *p) {
    HealerX *h = calloc(1, sizeof(HealerX));
    p->ext = h;
    sprite_setScale(&p->s, 4);
    body_setCircle(&p->s.body, 0x10, p->s.body.offset.x, p->s.body.offset.y);
    static const float A[7] = { 0, 0.23f, 0.41f, 0.61f, 0.71f, 0.79f, 0.83f }, S[7] = { 2, 1.75f, 1.5f, 1.25f, 1, 0.75f, 0.5f }, S2[7] = { 0.5f, 0.75f, 1, 1.25f, 1.5f, 1.75f, 2 };
    static const float D[7] = { 0x3f1, 0x4c1, 0x5d1, 0x653, 0x745, 0x833, 0x925 };
    for (int i = 0; i < 7; i++) {
        h->r[i] = 0x6c, h->a[i] = 2 * PI * A[i];
        sprite_init(&h->eye[i], frame_get("vfx", "eyeanim_0.png"), p->s.x, p->s.y);
        sprite_setScale(&h->eye[i], S[i]), sprite_setTintFill(&h->eye[i], 0);
        children_add(&h->eye[i]);
        tweens_add((TweenConfig){ .props = { { &h->r[i], NULL, 0x36 } }, .nprops = 1, .duration = D[i], .yoyo = 1, .repeat = -1 });
        tweens_add((TweenConfig){ .props = { { &h->eye[i].scaleX, &h->eye[i].scaleY, S2[i] } }, .nprops = 1, .duration = D[i], .yoyo = 1, .repeat = -1 });
    }
}
static void Healer_OnRecycle(Pickup *p) {
    Pickup_OnRecycle(p);
    p->goToPlayer = 1, p->isStationary = 1;
    sprite_setFrame(&p->s, frame_get("items", "Healer.png"));
}
static void Healer_Update(Pickup *p) {
    HealerX *h = p->ext;
    if (p->goToPlayer && !p->isStationary) Pickup_GoToPlayer(p);  // super.Update
    p->s.depth = 9 + p->s.y - Core.Player->s.y;
    for (int i = 0; i < 7; i++) h->eye[i].depth = p->s.depth + 2;
    Vector2 s = Pickup_safeXY(p, p->s.x, p->s.y);
    p->s.x = s.x, p->s.y = s.y;
    for (int i = 0; i < 7; i++) h->a[i] += PI / 0xb4 * (0x64 / 6.0f);  // angleUnit * delta (un frame a 60 FPS)
    static const int RX[7] = { 0, 2, 4, 6, 1, 3, 5 }, RY[7] = { 1, 3, 5, 0, 2, 4, 6 };  // eye1: radius1/radius2, eye2: radius3/radius4, ...
    for (int i = 0; i < 7; i++) h->eye[i].x = p->s.x + cosf(h->a[i]) * h->r[RX[i]], h->eye[i].y = p->s.y + sinf(h->a[i]) * h->r[RY[i]];
}
static void Healer_GetTaken(Pickup *p) {
    if (p->disableGet) return;
    HealerX *h = p->ext;
    for (int i = 0; i < 7; i++) h->eye[i].visible = 0;  // (sic) non tornano piu' visibili
    Core.StartHealerScene = 1;
    Pickup_GetTaken(p);
}

// --- 0x301a Teleporter (le porte di Astral Stair) e 0x8504 Moongate (le lune di Gallo Tower), a coppie -------------
static void Guarded_OnRecycle(Pickup *p) {  // PickupGuarded.OnRecycle
    Pickup_OnRecycle(p);
    p->guardRadius = 0.5f * 0x1c8;
    PickupGuarded_UpdateBounds(p);
    p->hasSpawned = 0, p->n_guards = 0;
    if (!list_contains(&Core.PickupsWithArrows, &p->s)) list_add(&Core.PickupsWithArrows, &p->s);
}
static void Guarded_Update(Pickup *p) {  // PickupGuarded.Update
    if (p->goToPlayer && !p->isStationary) Pickup_GoToPlayer(p);
    if (!p->hasSpawned && !(Core.Player->s.y > p->bottom || Core.Player->s.y < p->top || Core.Player->s.x > p->right || Core.Player->s.x < p->left))
        PickupGuarded_TriggerSpawn(p);
}
static void Enemy_Disappear(Enemy *e);
typedef struct { Sprite door, beam, whiteFader; Animation open; } TeleX;
static void Teleporter_ctor(Pickup *p) {
    TeleX *x = calloc(1, sizeof(TeleX));
    p->ext = x;
    p->triggerDelay = 0x1e, p->isStationary = 1;
    sprite_init(&x->door, frame_get("background_Astral", "door01.png"), p->s.x, p->s.y);
    sprite_setOrigin(&x->door, 0.5f, 1), x->door.depth = -0x7cb;
    children_add(&x->door);
    make_anim(&x->open, "background_Astral", "door", 1, 0x10, 2, 0x40, 0);
    sprite_init(&x->beam, frame_get("vfx", "Beam.png"), 0, 0);  // MakeDoorVFX
    x->beam.scaleX = 0, x->beam.scaleY = 1, sprite_setTint(&x->beam, 0xfafafa), x->beam.blendAdd = 1, x->beam.depth = 0x7cc;
    children_add(&x->beam);
    sprite_init(&x->whiteFader, frame_get("vfx", "WhiteDot.png"), 0, 0);
    sprite_setTint(&x->whiteFader, 0xfafafa), sprite_setOrigin(&x->whiteFader, 0, 0), x->whiteFader.scrollFactor0 = 1, x->whiteFader.alpha = 0, x->whiteFader.depth = 0x7cc;
    x->whiteFader.scaleX = game_width / fmaxf(1, x->whiteFader.width), x->whiteFader.scaleY = game_height / fmaxf(1, x->whiteFader.height);
    children_add(&x->whiteFader);
    if (po_is("SelectedInverse") && po_is("VisuallyInvertStages")) x->door.scaleY = -1;  // door.setScale(1, -1)
    p->canTeleport = 1;
}
static void Teleporter_OnRecycle(Pickup *p) {
    Guarded_OnRecycle(p);
    p->colorValue = 0;
    body_setCircle(&p->s.body, 0xc, -6, 6);
    p->s.visible = 0;
}
static void Teleporter_DeSpawn(Pickup *p) { (void)p; }
static void Teleporter_Update(Pickup *p) {
    TeleX *x = p->ext;
    Guarded_Update(p);
    p->s.depth = -0x7cb, p->triggerDelay = 0x2710;
    x->door.x = p->s.x, x->door.y = p->s.y;
}
static void Tele_enable(void *ctx) { Pickup *p = ctx; p->canTeleport = 1, p->s.body.enable = 1; }
static void Teleporter_Disable(Pickup *p) { p->s.body.enable = 0; time_addEvent(p->triggerDelay, 0, 0, Tele_enable, p); }
static void Tele_yoyo(void *ctx) {  // a schermo bianco: il raggio sparisce, la porta si chiude e il giocatore passa
    Pickup *p = ctx;
    TeleX *x = p->ext;
    x->beam.scaleX = x->beam.scaleY = 0;
    anims_stop(&x->door), sprite_setFrame(&x->door, frame_get("background_Astral", "door01.png"));
    Core.Player->s.x = p->destinationX, Core.Player->s.y = p->destinationY;  // DoTeleport
    for (int i = 0; i < Core.Enemies.n; i++) { Enemy *e = Core.Enemies.items[i]->owner; if (!e->res_Rosary) Enemy_Disappear(e); }
}
static void Tele_finished(void *ctx) {  // OnTeleportFinished
    (void)ctx;
    for (int i = 0; i < Core.Enemies.n; i++) { Enemy *e = Core.Enemies.items[i]->owner; if (!e->IsTimeStopped) e->speed = e->defaultSpeed; }
}
static void Teleporter_GetTaken(Pickup *p) {
    if (p->disableGet || !p->canTeleport) return;
    TeleX *x = p->ext;
    p->canTeleport = 0;
    Teleporter_Disable(p), Teleporter_Disable(p->link);
    anims_play(&x->door, &x->open, 0);  // StartTeleport -> OpenDoorAnimation
    x->beam.x = x->door.x, x->beam.y = x->door.y;
    tweens_add((TweenConfig){ .props = { { &x->beam.scaleX, NULL, 3 }, { &x->beam.scaleY, NULL, 0x14 } }, .nprops = 2, .duration = 0xc8 });
    tweens_add((TweenConfig){ .props = { { &x->whiteFader.alpha, NULL, 1 } }, .nprops = 1, .duration = 0x12c, .yoyo = 1, .onYoyo = Tele_yoyo, .onComplete = Tele_finished, .ctx = p });
    for (int i = 0; i < Core.Enemies.n; i++) ((Enemy *)Core.Enemies.items[i]->owner)->speed = 0;
    json_inc(cJSON_GetObjectItem(data_get("items"), p->vt->itemType), "pickedupAmount");
}
static void Tele_LinkTo(Pickup *p, Pickup *l) {
    p->link = l, p->destinationX = l->s.x, p->destinationY = l->s.y + 0x30;
    if (po_is("SelectedInverse") && po_is("VisuallyInvertStages")) p->destinationY = l->s.y - 0x30;
}
static void Moongate_ctor(Pickup *p) {
    p->weaponType = "VOID", p->particlesInterval = 0xc8, p->totalTime = 0x64, p->triggerDelay = 0x1e, p->isStationary = 1;
    sprite_setScale(&p->s, PixelScale);
    sprite_init(&p->glow, frame_get("vfx", "round.png"), p->s.x, p->s.y);
    p->pfx = particles_add();
    static const char *const R[5] = { "_runes_02.png", "_runes_03.png", "_runes_04.png", "_runes_05.png", "_runes_06.png" };
    EmitterConfig c = { .lifespan = EOP(0x7d0), .rotate = ERND(0, 0x168), .angle = ERND(0xf0, 0x12c), .speed = ERND(0xa, 0x32), .quantity = 1, .scale = ERANGE(0.3f, 0.5f),
                        .alpha = ERANGE(1, 0), .frequency = 0x1f4, .tints = { 0xaaffff }, .ntints = 1, .blendAdd = 1, .on = 1 };
    for (int i = 0; i < 5; i++) c.frames[i] = frame_get("vfx", R[i]);
    c.nframes = 5;
    p->pfxE = particles_createEmitter(p->pfx, c);
}
static void Moongate_OnRecycle(Pickup *p) {
    Guarded_OnRecycle(p);
    p->colorValue = 0;
    body_setCircle(&p->s.body, 0x18, -0xc, 0xc);
    p->pfx->s.depth = p->s.depth;
    children_add(&p->glow);
    p->glow.x = p->s.x, p->glow.y = p->s.y, p->glow.blendAdd = 1, p->glow.alpha = 0.5f;
    tween_remove(p->glowTween);
    p->glowTween = tweens_add((TweenConfig){ .props = { { &p->glow.alpha, NULL, 0 } }, .nprops = 1, .duration = 0x1f4, .loop = -1, .yoyo = 1 });
    p->s.visible = 0;
    p->pfxE->x = p->s.x, p->pfxE->y = p->s.y;
}
static void Moongate_Update(Pickup *p) {
    Guarded_Update(p);
    p->s.depth = 9 + p->s.y - Core.Player->s.y, p->pfx->s.depth = p->s.depth;
    p->glow.x = p->s.x, p->glow.y = p->s.y - 0x30, p->glow.depth = p->s.y - Core.Player->s.y;
    p->colorValue += 0.1f;
    p->glow.tint = (unsigned)(0xff * fabsf(sinf(p->colorValue))) << 16 | (unsigned)(0xff * fabsf(cosf(0.5f * p->colorValue))) << 8 | (unsigned)(0xc8 + 0x37 * fabsf(cosf(p->colorValue)));
    p->triggerDelay = 0x4e20, p->canTeleport = 1;  // (sic) torna sempre vero: conta solo il corpo spento
}
static void Moon_enable(void *ctx) { Pickup *p = ctx; p->canTeleport = 1, p->s.body.enable = 1, p->glow.visible = 1, emitter_start(p->pfxE); }
static void Moongate_Disable(Pickup *p) {
    p->s.body.enable = 0, p->glow.visible = 0;
    emitter_stop(p->pfxE);
    time_addEvent(p->triggerDelay, 0, 0, Moon_enable, p);
}
static void Moongate_GetTaken(Pickup *p) {
    if (p->disableGet || !p->canTeleport) return;
    p->canTeleport = 0;
    Moongate_Disable(p), Moongate_Disable(p->link);
    Core.Player->s.x = p->destinationX, Core.Player->s.y = p->destinationY;
}
static void Moon_LinkTo(Pickup *p, Pickup *l) { p->link = l, p->destinationX = l->s.x, p->destinationY = l->s.y; }

// --- 0xf1f6: l'uovo d'oro a terra (Mietitore, maschere) ---------------------------------------------------------
static void Core_RemoveStagePickup(Pickup *p) {  // StagePickups.splice(indexOf(this), 1)
    for (int i = 0; i < Core.n_StagePickups; i++)
        if (Core.StagePickups[i] == p) { memmove(&Core.StagePickups[i], &Core.StagePickups[i + 1], (--Core.n_StagePickups - i) * sizeof(Pickup *)); break; }
}
static void GoldenEgg_ctor(Pickup *p) {
    sprite_setScale(&p->s, PixelScale);
    sprite_init(&p->Cursor, frame_get("UI", "arrow_01.png"), p->s.x, p->s.y);
    p->Cursor.depth = 0x270e, p->Cursor.alpha = 0.75f, p->Cursor.blendAdd = 1;
    sprite_setScale(&p->Cursor, 2);
    children_add(&p->Cursor);
    sprite_init(&p->CursorIcon, frame_get("items", "goldenegg.png"), p->s.x, p->s.y);
    p->CursorIcon.depth = 0x270f;
    children_add(&p->CursorIcon);
    make_anim(&p->cursorIdle, "UI", "arrow_", 1, 8, 2, 0x10, -1);
    anims_play(&p->Cursor, &p->cursorIdle, 0);
    p->Cursor.visible = p->CursorIcon.visible = 0;
}
static void GoldenEgg_Update(Pickup *p) {
    if (p->goToPlayer && !p->isStationary) Pickup_GoToPlayer(p);  // super.Update
    p->s.depth = 9 + p->s.y - Core.Player->s.y;
    if ((fabsf(p->s.x - Core.Player->s.x) < 0.5f * game_width && fabsf(p->s.y - Core.Player->s.y) < 0.5f * game_height) || !po_is("ShowPickups"))
        p->Cursor.visible = p->CursorIcon.visible = 0;
    else {
        float a = Pickup_AngleFromTargetRadians(p);
        p->Cursor.angle = a * RAD2DEG;
        p->Cursor.x = Core.Player->s.x + 0.45f * cosf(a) * game_width;
        p->Cursor.y = Core.Player->s.y + 0.45f * sinf(a) * game_height;
        p->Cursor.alpha = 0.75f, p->Cursor.blendAdd = 1, p->Cursor.visible = 1;
        p->CursorIcon.x = p->Cursor.x, p->CursorIcon.y = p->Cursor.y, p->CursorIcon.visible = 1;
    }
    Vector2 s = Pickup_safeXY(p, p->s.x, p->s.y);
    p->s.x = s.x, p->s.y = s.y;
}
static void GoldenEgg_DeSpawn(Pickup *p) {
    Pickup_DeSpawn(p);
    p->Cursor.visible = p->CursorIcon.visible = 0;
    Core_RemoveStagePickup(p);
}
static void Sigma_eggGone(void *ctx) { children_remove(ctx); free(ctx); }
static void GoldenEgg_GetTaken(Pickup *p) {
    if (p->disableGet) return;
    if (!strcmp(po_str("SelectedCharacter"), "SIGMA")) {  // Sigma non tiene le uova: vola via in alto a sinistra
        Sprite *e = calloc(1, sizeof(Sprite));
        sprite_init(e, frame_get("items", "goldenegg.png"), 0.5f * game_width, 0.5f * game_height);
        e->scrollFactor0 = 1, e->depth = 1;
        children_add(e);
        tweens_add((TweenConfig){ .props = { { &e->x, NULL, -0x64 }, { &e->y, NULL, -0x64 }, { &e->angle, NULL, 0x2d0 } }, .nprops = 3, .duration = 0x1f4 });
        tweens_add((TweenConfig){ .props = { { &e->scaleX, &e->scaleY, 1.4f } }, .nprops = 1, .duration = 0x1f4, .onComplete = Sigma_eggGone, .ctx = e });
        Core_RemoveStagePickup(p);
        GoldenEgg_DeSpawn(p);
        return;
    }
    int a = EggManager_AddGoldenEgg();
    EggManager_ShowResultAt(Core.Player->s.x, Core.Player->s.y, a, -0x10, -0x10, -1);
    RunPickups_push(p->itemType);
    Pickup_SetSeenItem(p->itemType);
    Pickup_GetTaken(p);
    Sound_PlaySound("Roast", 0.5f, 1, 0xc8, 0, 0), Sound_PlaySound("Roast", 0.5f, 1, 0x190, 0, 0), Sound_PlaySound("Roast", 0.5f, 1, 0x258, 0, 0);
    Core_RemoveStagePickup(p);
}

static void LittleHeart_GetTaken(Pickup *p) {  // 0x16fe9: cuoricino, 1 HP
    if (p->disableGet) return;
    Player_RecoverHp(Core.Player, 1, 1, 1);
    Pickup_SetSeenItem(p->itemType);
    Pickup_GetTaken(p);
    Sound_PlaySound("LittleHeart", p->quiet ? 0.1f : 0.35f, 1.2f, 0xc8 * (frand() - 0.5f), 0x32, 3);
}

static int AchievementManager_UnlockSecret(const char *k);
static void Pickup_SetSeenItem(const char *t);
// --- 0x13742 Coffin e 0x444 CoffinX: la bara del personaggio da sbloccare, aperta quando le guardie sono morte --------
static void Coffin_ctor(Pickup *p) {
    p->charCFF = "VOID", p->totalTime = 0x64, p->particlesInterval = 0xc8, p->isStationary = 1;
    sprite_setScale(&p->s, PixelScale);
    sprite_init(&p->Lid, frame_get("items", "CoffinLid.png"), 0, 0);
    sprite_init(&p->CharSprite, NULL, 0, 0);
    sprite_setScale(&p->CharSprite, 0);
    // Cursor e CursorIcon: visibili solo con PlayerOptions.ShowPickups, spento di default
}
static void Coffin_OnRecycle(Pickup *p) {
    Pickup_OnRecycle(p);
    p->guardRadius = 0.5f * 0x1c8;  // PickupGuarded.OnRecycle
    PickupGuarded_UpdateBounds(p);
    p->hasSpawned = 0, p->n_guards = 0, p->opened = 0;
    body_setCircle(&p->s.body, 0x10, 0, 8);
    sprite_setFrame(&p->s, frame_get("items", "Coffin.png"));
    p->Lid.x = p->s.x, p->Lid.y = p->s.y, p->Lid.visible = 1, p->Lid.angle = 0, p->Lid.scaleX = p->Lid.scaleY = 1;
    p->CharSprite.x = p->s.x, p->CharSprite.y = p->s.y, p->CharSprite.visible = 1, p->CharSprite.scaleX = p->CharSprite.scaleY = 0;
    sprite_setTintFill(&p->CharSprite, 0);
    children_add(&p->Lid);
    children_add(&p->CharSprite);
}
static void Coffin_DeSpawn(Pickup *p) { Pickup_DeSpawn(p); }
static int Coffin_guardsAlive(Pickup *p) {
    for (int i = 0; i < p->n_guards; i++) if (!p->guards[i]->isDead) return 1;
    return 0;
}
static void Coffin_Update(Pickup *p) {
    if (!p->hasSpawned && !(Core.Player->s.y > p->bottom || Core.Player->s.y < p->top || Core.Player->s.x > p->right || Core.Player->s.x < p->left))
        PickupGuarded_TriggerSpawn(p);  // PickupGuarded.Update
    p->s.depth = 9 + p->s.y - Core.Player->s.y, p->Lid.depth = 0xa + p->s.y - Core.Player->s.y, p->CharSprite.depth = p->Lid.depth;
    // vicino (o senza ShowPickups): scintille quando le guardie sono morte
    if (Coffin_guardsAlive(p)) return;
    p->totalTime += 0x64 / 6.0f;  // Update(delta): un frame
    if (p->totalTime > p->particlesInterval) { p->totalTime = 0; manager_emitParticleAt(Core.PfxEmitter_Pickups, p->s.x, p->s.y); }
}
static void Coffin_setChar(Pickup *p, const char *ch) {
    p->charCFF = ch;
    cJSON *c = tbl0("characters", ch);
    if (c) sprite_setFrame(&p->CharSprite, frame_get("characters", p->isCoffinX ? "random_00.png" : str(c, "spriteName")));
}
static void Coffin_TriggerCharScene(void *ctx) {
    Pickup *p = ctx;
    p->Lid.visible = 0;
    if (p->isCoffinX) {
        Sound_PlaySound("ThingFound", 1, 0.5f, -0x3e8, 0, 0);
        Pickup_GetTaken(p);
        return;
    }
    if (Core.n_CharQueue < 8) Core.CharQueue[Core.n_CharQueue++] = p->charCFF;
    Pickup_SetSeenItem(p->itemType);
    Pickup_GetTaken(p);
}
static void Coffin_hideChar(void *ctx) { ((Pickup *)ctx)->CharSprite.visible = 0; }
static void Coffin_GetTaken(Pickup *p) {
    if (p->disableGet || p->opened || Coffin_guardsAlive(p)) return;
    p->opened = 1;
    if (p->isCoffinX) AchievementManager_UnlockSecret("UnderTheCoffin");
    else {
        Sound_FadeMusic(0.1f, 0x64);
    }
    Sound_PlaySound("Lid", 2, 1, 0, 0x96, 2);
    if (!p->isCoffinX) Sound_PlaySound("ThingFound", 1.4f, 1, -0x7d0, 0, 0);
    tweens_add((TweenConfig){ .props = { { &p->CharSprite.scaleX, NULL, 2 }, { &p->CharSprite.scaleY, NULL, 4 } }, .nprops = 2, .duration = 0x64 });
    tweens_add((TweenConfig){ .props = { { &p->CharSprite.y, NULL, p->s.y - game_height } }, .nprops = 1, .duration = 0x190, .onComplete = Coffin_hideChar, .ctx = p });
    tweens_add((TweenConfig){ .props = { { &p->Lid.scaleX, NULL, -1 } }, .nprops = 1, .duration = 0x1f4 });  // (piu' di TWEEN_DATA proprieta': due tween)
    tweens_add((TweenConfig){ .props = { { &p->Lid.y, NULL, p->s.y - 0.75f * game_height }, { &p->Lid.x, NULL, p->s.x - 0.75f * game_width }, { &p->Lid.angle, NULL, 0x168 } },
                              .nprops = 3, .duration = 0x1f4, .onComplete = Coffin_TriggerCharScene, .ctx = p });
}
static void CoffinX_ctor(Pickup *p) { Coffin_ctor(p); p->isCoffinX = 1; }

// --- COFFIN_EMPTY (0x1072b): le nove bare del pianoforte; quasi tutte vuote ("Empty"), una con Avatar (OnOpen) -----------------
// itemType resta COFFIN_EMPTY (l'originale passa COFFIN al costruttore): qui il pool dei pickup e' per itemType
static void text_at(const char *s, float x, float y, float size, float ox, float oy, Color c);
static void EmptyText_draw(Sprite *s) {  // scene.add.text(x, y, 'Empty', { align: center }): 16 px, origine 0.5
    if (!s->visible || s->alpha <= 0 || s->scaleX <= 0) return;
    text_at("Empty", roundf(s->x - camera_scrollX), roundf(s->y - camera_scrollY), 16 * s->scaleX, 0.5f, 0.5f, Fade(WHITE, s->alpha));
}
static void EmptyText_gone(void *ctx) { children_remove(ctx); }
static void EmptyText_fade(void *ctx) { Sprite *t = ctx; tweens_add((TweenConfig){ .props = { { &t->alpha, NULL, 0 } }, .nprops = 1, .duration = 0x3e8, .onComplete = EmptyText_gone, .ctx = t }); }
static void EmptyText_rise(void *ctx) { Sprite *t = ctx; tweens_add((TweenConfig){ .props = { { &t->y, NULL, t->y - 0x10 } }, .nprops = 1, .duration = 0x7d0, .onComplete = EmptyText_fade, .ctx = t }); }
static void CoffinEmpty_lidDone(void *ctx) { Pickup *p = ctx; p->Lid.visible = 0; Pickup_GetTaken(p); }
static void CoffinEmpty_GetTaken(Pickup *p) {
    if (p->disableGet || p->opened) return;
    if (p->charCFF && strcmp(p->charCFF, "VOID")) {
        tweens_add((TweenConfig){ .props = { { &p->CharSprite.scaleX, NULL, 2 }, { &p->CharSprite.scaleY, NULL, 4 } }, .nprops = 2, .duration = 0x64 });
        tweens_add((TweenConfig){ .props = { { &p->CharSprite.y, NULL, p->s.y - game_height } }, .nprops = 1, .duration = 0x190, .onComplete = Coffin_hideChar, .ctx = p });
    } else {
        Sprite *t = gmem_calloc(1, sizeof(Sprite));
        sprite_init(t, NULL, p->s.x, p->s.y);
        t->draw = EmptyText_draw, t->scaleX = t->scaleY = 0, t->depth = 0xbba;
        children_add(t);
        tweens_add((TweenConfig){ .props = { { &t->scaleX, &t->scaleY, 1 } }, .nprops = 1, .duration = 0xc8, .onComplete = EmptyText_rise, .ctx = t });
    }
    if (p->OnOpen) p->OnOpen();
    p->opened = 1;
    Sound_PlaySound("Lid", 2, 1, 0, 0x96, 2);
    tweens_add((TweenConfig){ .props = { { &p->Lid.scaleX, NULL, -1 } }, .nprops = 1, .duration = 0x1f4 });  // un tween solo nell'originale (4 proprieta')
    tweens_add((TweenConfig){ .props = { { &p->Lid.y, NULL, p->s.y - 0.75f * game_height }, { &p->Lid.x, NULL, p->s.x - 0.75f * game_width }, { &p->Lid.angle, NULL, 0x168 } },
                              .nprops = 3, .duration = 0x1f4, .onComplete = CoffinEmpty_lidDone, .ctx = p });
}

