static void Core_MakeExplosion(float x, float y, float damage, float radius);
static void Enemy_OnSelfDestruct(void *ctx) {
    Enemy *e = ctx;
    if (e->isDead) return;
    e->alertSprite.visible = 0;
    tween_stop(e->alertTween), e->alertTween = (TweenRef){ -1, 0 };
    Core_MakeExplosion(e->s.x, e->s.y, e->moreX, e->moreY);
    Enemy_Disappear(e);
}
static void Enemy_alertRepeat(void *ctx) {  // l'allarme accelera del 10% a ogni giro
    Enemy *e = ctx;
    Tween *t = tween_get(e->alertTween);
    if (t) t->timeScale *= 1.1f;
    Sound_PlaySound("Alert", 0.2f, 1, 0, 0xfa, 3);
}
static void Enemy_CheckSelfDestruct(Enemy *e) {  // Update / ConditionalUpdate: il ramo SelfDestruct
    e->alertSprite.x = e->s.x, e->alertSprite.y = e->s.y;  // copyPosition
    if (e->isSelfDestructionTriggered) return;
    float dx = Core.Player->s.x - e->s.x, dy = Core.Player->s.y - e->s.y;
    if (dx * dx + dy * dy >= e->SelfDestDistance) return;
    e->isSelfDestructionTriggered = 1;
    children_add(&e->alertSprite);
    e->alertSprite.visible = 1, e->alertSprite.alpha = 1, sprite_setScale(&e->alertSprite, 1);
    tween_stop(e->alertTween);
    e->alertTween = tweens_add((TweenConfig){ .props = { { &e->alertSprite.alpha, NULL, 0 }, { &e->alertSprite.scaleX, &e->alertSprite.scaleY, 0.9f } }, .nprops = 2,
                                              .yoyo = 1, .duration = 0xc8, .repeat = -1, .onRepeat = Enemy_alertRepeat, .ctx = e });
    e->SelfDestructTimer = time_addEvent(0x7d0, 0, 0, Enemy_OnSelfDestruct, e);
}

static void base_EnemyUpdate(Enemy *e);
static int Enemy_beatMode;  // Abyss Foscari (0xba51): Update = ConditionalUpdate sul battito
static void Enemy_Update(Enemy *e) {
    if (Enemy_beatMode && !e->conditional_canMove) {  // ConditionalUpdate col battito fermo: niente passi
        if (!e->isDead) {
            e->s.depth = e->s.y - Core.Player->s.y;
            if (e->SelfDestruct && !e->IsTimeStopped) Enemy_CheckSelfDestruct(e);
        }
        return;
    }
    if (e->vt && e->vt->Update) e->vt->Update(e); else base_EnemyUpdate(e);
}
static void base_EnemyUpdate(Enemy *e) {
    if (e->isDead) return;
    e->s.depth = e->s.y - Core.Player->s.y;
    if (e->IsTimeStopped) return;
    if (!e->FixedDirection || (e->FixedDirection && e->_currentDirection.x == 0 && e->_currentDirection.y == 0)) {
        e->_currentDirection.x = e->target->x - e->s.x;
        e->_currentDirection.y = e->target->y - e->s.y;
        float l = sqrtf(e->_currentDirection.x * e->_currentDirection.x + e->_currentDirection.y * e->_currentDirection.y);
        if (l > 0) { e->_currentDirection.x /= l; e->_currentDirection.y /= l; }
    }
    if (e->Medusa) { e->medusaElapsed += 0.05f; e->_currentDirection.y = cosf(e->medusaElapsed); }
    if (e->SelfDestruct) Enemy_CheckSelfDestruct(e);
    float k = e->receivingDamage ? -e->knockback * e->damageKB : 1;
    e->s.flipX = e->_currentDirection.x > 0;
    float v = EnemySpeed * e->speed * k * e->slow;
    sprite_setVelocity(&e->s, v * e->_currentDirection.x, v * e->_currentDirection.y);
    e->s.angle = TweenAngles[e->moveTweenIndex];
}

static void Enemy_ResumeFromFreeze(void *ctx) {
    Enemy *e = ctx;
    e->IsTimeStopped = 0;
    e->speed = e->defaultSpeed;
    Enemy_restoreTint(e);
    if (e->idleFrameCount) anims_resume(&e->s);
}
static int Enemy_Freeze(void *o, float duration, float chance) {  // Enemy.Freeze (0x1166a)
    Enemy *e = o;
    if (e->res_Freeze > chance || e->IsTimeStopped) return 0;
    time_removeEvent(e->FreezeTimer);  // FreezeTimer.destroy()
    e->FreezeTimer = time_addEvent(duration, 0, 0, Enemy_ResumeFromFreeze, e);
    e->IsTimeStopped = 1;
    e->speed = 0;
    sprite_setVelocity(&e->s, 0, 0);
    sprite_setTint(&e->s, 0xff);
    if (e->idleFrameCount) anims_pause(&e->s);
    return 1;
}
static void Enemy_TimeStop(Enemy *e) {
    time_removeEvent(e->FreezeTimer);
    e->IsTimeStopped = 1;
    e->speed = 0;
    sprite_setVelocity(&e->s, 0, 0);
    sprite_setTint(&e->s, 0xff);
    if (e->idleFrameCount) anims_pause(&e->s);
}

static EnemyPool *EnemyPool_new(const char *type) {
    EnemyPool *p = calloc(1, sizeof(EnemyPool));
    p->enemyType = type;
    p->enabled = 1;
    p->upperLimit = 0x12c;
    return p;
}

static void arr_push(Enemy ***a, int *n, int cap, Enemy *e) { (void)cap; *a = realloc(*a, (*n + 1) * sizeof(Enemy *)); (*a)[(*n)++] = e; }

static Enemy *EnemyPool_Spawn(EnemyPool *p) {
    Enemy *e = p->n_stored ? p->stored[--p->n_stored] : NULL;
    if (!e) { e = Enemy_new(p, p->enemyType); Enemy_Init(e, -1000, -1000); }
    children_add(&e->s);
    Enemy_OnRecycle(e);
    arr_push(&p->spawned, &p->n_spawned, 0, e);
    list_add(&Core.Enemies, &e->s);
    if (!e->passThroughWalls) list_add(&Core.EnemyGroup, &e->s);
    return e;
}

static Enemy *EnemyPool_SpawnAt(EnemyPool *p, float x, float y) {
    if (p->n_spawned >= p->upperLimit && p->isUncapped) {
        int i = 0;
        while (p->spawned[i]->isDespawning && i < p->upperLimit) i++;
        if (p->spawned[i]) Enemy_DeSpawn(p->spawned[i]);
    }
    Enemy *e = EnemyPool_Spawn(p);
    e->s.x = x;
    e->s.y = y;
    if (e->vt && e->vt->setOwner) e->vt->setOwner(e);
    if (Core.IsTimeStopped) Enemy_TimeStop(e);
    return e;
}

static void EnemyPool_Recycle(EnemyPool *p, Enemy *e) {
    children_remove(&e->s);
    for (int i = 0; i < p->n_spawned; i++)
        if (p->spawned[i] == e) { memmove(&p->spawned[i], &p->spawned[i + 1], (p->n_spawned - i - 1) * sizeof(Enemy *)); p->n_spawned--; break; }
    list_remove(&Core.Enemies, &e->s);
    list_remove(&Core.EnemyGroup, &e->s);
    arr_push(&p->stored, &p->n_stored, 0, e);
}

// ============================================================================
// 0x4a9d: BulletPool + 0xa14d: Bullet + 0xe49a: Weapon, e le armi base:
// 0x7e1d/0xb66f Whip, 0xf82d/0x663d MagicMissile, 0x9225/0x1f5a Knife,
// 0x136b1/0xd0f4 Axe, 0x1d36/0x61be HolyBook, 0x1220c/0xe2b7 HolyWater,
// 0x7784/0x11fa3 Laurel, 0x5dba PowerUp
// ============================================================================
struct BulletVT {
    const char *tex, *frame;
    void (*ctor)(Bullet *b);                 // dopo il costruttore di Bullet
    void (*Init)(Bullet *b, float x, float y);
    void (*OnRecycle)(Bullet *b);
    void (*OnHasHitAnObject)(Bullet *b, void *o, int oIsDead);  // o: Enemy o Destructible (si legge solo isDead)
    void (*Update)(Bullet *b, float delta);
    void (*DeSpawn)(Bullet *b);
    void (*SetTarget)(Bullet *b, Vector2 target);  // FireOneBullet: SetTarget(target) / SetNullTarget()
    void (*SetNullTarget)(Bullet *b);
    void (*OnHasHitWall)(Bullet *b, Tile *t);  // NULL: DeSpawn
};
struct WeaponVT {
    const BulletVT *bullet;
    float (*PArea)(Weapon *w);
    float (*PAmount)(Weapon *w);
    float (*PPower)(Weapon *w);
    float (*PBounces)(Weapon *w);
    float (*PInterval)(Weapon *w);
    void (*ctor)(Weapon *w);
    void (*Fire)(Weapon *w);
    void (*OnStart)(Weapon *w);
    void (*Update)(Weapon *w, float delta);
    int (*LevelUp)(Weapon *w);
    void (*MakeLevelOne)(Weapon *w);
    void (*ResetFiringTimer)(Weapon *w);
    void (*onBulletOverlapsEnemy)(Weapon *w, Bullet *b, Enemy *e);
    Bullet *(*FireOneBullet)(Weapon *w, float x, float y, int index);  // NULL: quello della base
    void (*OnWeaponAdded)(Weapon *w);  // NULL: niente (Core.AddWeapon, dopo l'icona)
    void (*CheckArcanas)(Weapon *w);   // MakeLevelOne e Arcanas.CheckOnAllWeapons
    float (*SecondaryPPower)(Weapon *w);  // NULL: quello della base (secondaryPower)
};

// --- Weapon: proprieta' calcolate ------------------------------------------
static float Weapon_PArea(Weapon *w) { return w->vt->PArea(w); }
static float Weapon_PAmount(Weapon *w) { return w->vt->PAmount(w); }
static float Weapon_PPower(Weapon *w) { return w->vt->PPower(w); }
static float base_PArea(Weapon *w) { return fminf(10, Core.Player->area * sinev(Core.Player->sineArea)) * w->area; }
static float base_PAmount(Weapon *w) { return fminf(10, Core.Player->amount) + w->amount; }
static float base_PPower(Weapon *w) { return fminf(10, (Arcanas.silentMight + Core.Player->power) * sinev(Core.Player->sineMight)) * w->power + Arcanas.bloodlineDamage; }
static float base_PBounces(Weapon *w) { return w->bounces; }
// Bloodline: Cross, Garlic, HolyBook, HolyWater, Lightning aggiungono l'armatura; Song, Vento, Victory di nuovo bloodlineDamage
// (super.PPower lo somma gia': conta due volte, sic)
static float armor_PPower(Weapon *w) { return base_PPower(w) + Arcanas.bloodlineArmorValue; }
static float blood2_PPower(Weapon *w) { return base_PPower(w) + Arcanas.bloodlineDamage; }
static float bonus_PBounces(Weapon *w) { return w->bonusBounces + w->bounces; }  // bonusBounces: NaN senza arcana, qui 0 (NaN > 0 e' falso)
static float Weapon_PSpeed(Weapon *w) { return fminf(5, Core.Player->speed) * w->speed * sinev(Core.Player->sineSpeed); }
static float base_PInterval(Weapon *w) { return fmaxf(0.1f, (Arcanas.silentCooldown + Core.Player->cooldown) * sinev(Core.Player->sineCooldown)) * w->interval; }
static float Weapon_PInterval(Weapon *w) { return w->vt->PInterval(w); }
static float Weapon_PDuration(Weapon *w) { return fminf(5, Core.Player->duration * sinev(Core.Player->sineDuration)) * w->duration; }
static float Bullet_TrueSpeed(Bullet *b) { return Weapon_PSpeed(b->weapon) * ProjectileSpeed * b->_speed; }

// --- BulletPool (0x4a9d) ----------------------------------------------------
static void BulletPool_Return(BulletPool *pool, Bullet *b) {
    children_remove(&b->s);
    list_remove(&pool->group, &b->s);
    list_remove(&Core.BulletGroup, &b->s);
    if (pool->n_stored == pool->cap_stored) { pool->cap_stored = pool->cap_stored ? pool->cap_stored * 2 : 16; pool->stored = realloc(pool->stored, pool->cap_stored * sizeof(Bullet *)); }
    pool->stored[pool->n_stored++] = b;
}

// --- Bullet (0xa14d) --------------------------------------------------------
static void Bullet_DeSpawn(Bullet *b) {
    if (b->vt->DeSpawn) { b->vt->DeSpawn(b); return; }
    b->s.active = 0;
    b->s.body.enable = 0;
    BulletPool_Return(b->pool, b);
}
static void base_DeSpawn(Bullet *b) {
    b->s.active = 0;
    b->s.body.enable = 0;
    BulletPool_Return(b->pool, b);
}

static void Bullet_OnRecycle(Bullet *b) {
    b->isDead = 0;
    b->n_hit = 0;
    b->s.active = 1;
    b->s.body.enable = 1;
    b->penetrating = b->weapon->penetrating;
    b->bounces = b->weapon->vt->PBounces(b->weapon);
}
// Rimbalzo sul WorldBoxCollider attivato da weapon.PBounces (Pearls): Cross, HeavenSword, Scythe, Hellfire.
// L'ascoltatore 'worldbounds' resta per sempre (bounceActivated): ai riusi successivi i bordi tornano accesi.
static void Bullet_activateBounce(Bullet *b, void (*Bounce)(void *)) {
    if (b->weapon->vt->PBounces(b->weapon) && !b->bounceActivated) {
        b->bounceActivated = 1;
        b->s.body.customBounds = &Core.Player->WorldBoxCollider;
        b->s.body.onWorldBounds = Bounce, b->s.body.onWorldBoundsCtx = b;
    }
    if (b->bounceActivated) b->s.body.collideWorldBounds = 1, b->s.body.hasWorldBounce = 1, b->s.body.worldBounce = (Vector2){ 1, 1 };
}
static int Bullet_Bounce(Bullet *b) {  // bounces > 0 ? (bounces--, objectsHit = []) : setCollideWorldBounds(false)
    if (b->bounces > 0) { b->bounces--, b->n_hit = 0; return 1; }
    b->s.body.collideWorldBounds = 0;
    return 0;
}
static void B_velocity_Bounce(void *ctx) { Bullet *b = ctx; if (Bullet_Bounce(b)) b->velocity.x *= -1, b->velocity.y *= -1; }  // Cross, HeavenSword
static void B_Scythe_Bounce(void *ctx) { Bullet *b = ctx; if (Bullet_Bounce(b)) b->s.body.velocity.x *= -2, b->s.body.velocity.y *= -2; }
static void B_Hellfire_Bounce(void *ctx) {
    Bullet *b = ctx;
    if (Bullet_Bounce(b)) b->s.body.velocity.x *= -1.5f, b->s.body.velocity.y *= -1.5f, b->s.angle += 0xb4;  // setAngle: il wrap non cambia il disegno
}

static void Bullet_Init(Bullet *b, float x, float y) {
    b->s.x = x;
    b->s.y = y;
    physics_existing(&b->s);
    b->vt->OnRecycle(b);
}

static int Bullet_HasAlreadyHitObject(Bullet *b, void *o, int oIsDead) {
    for (int i = 0; i < b->n_hit; i++)
        if (b->objectsHit[i] == o) return 1;
    if (b->n_hit == b->cap_hit) { b->cap_hit = b->cap_hit ? b->cap_hit * 2 : 16; b->objectsHit = realloc(b->objectsHit, b->cap_hit * sizeof(void *)); }
    b->objectsHit[b->n_hit++] = o;
    if (b->vt->OnHasHitAnObject) b->vt->OnHasHitAnObject(b, o, oIsDead);
    return 0;
}

static float Bullet_AngleFromVelocityRadians(Vector2 v) { return atan2f(v.y - 0, v.x - 1); }  // Vector2.RIGHT sottratto come l'originale

static void Bullet_ApplyInitialVelocity(Bullet *b, Sprite *target) {
    Vector2 d = { target->body.position.x - Core.Player->s.x, target->body.position.y - Core.Player->s.y };
    float l = sqrtf(d.x * d.x + d.y * d.y);
    if (l > 0) { d.x /= l; d.y /= l; }
    sprite_setVelocity(&b->s, Bullet_TrueSpeed(b) * d.x, Bullet_TrueSpeed(b) * d.y);
    b->s.angle = Bullet_AngleFromVelocityRadians(b->s.body.velocity) * (180 / PI);
}

static void Bullet_ApplyPlayerFacingVelocity(Bullet *b) {
    Vector2 *d = &Core.Player->lastFacedDirection;  // normalize() modifica il vettore del giocatore
    float l = sqrtf(d->x * d->x + d->y * d->y);
    if (l > 0) { d->x /= l; d->y /= l; }
    if (d->x == 0 && d->y == 0) d->x = 1;
    sprite_setVelocity(&b->s, Bullet_TrueSpeed(b) * d->x, Bullet_TrueSpeed(b) * d->y);
    b->s.angle = Bullet_AngleFromVelocityRadians(b->s.body.velocity) * (180 / PI);
}

static void Bullet_ApplyInversePlayerFacingVelocity(Bullet *b) {
    Vector2 *d = &Core.Player->lastFacedDirection;  // normalize() modifica il vettore del giocatore
    float l = sqrtf(d->x * d->x + d->y * d->y);
    if (l > 0) { d->x /= l; d->y /= l; }
    if (d->x == 0 && d->y == 0) d->x = 1;
    sprite_setVelocity(&b->s, Bullet_TrueSpeed(b) * -d->x, Bullet_TrueSpeed(b) * -d->y);
    b->s.angle = Bullet_AngleFromVelocityRadians(b->s.body.velocity) * (180 / PI);
}

static int Bullet_AimForNearestEnemy(Bullet *b) {
    Sprite *t = physics_closest(&Core.Player->s, &Core.Enemies);
    if (t) { Bullet_ApplyInitialVelocity(b, t); return 1; }
    Bullet_ApplyPlayerFacingVelocity(b);
    return 0;
}

static Sprite *Bullet_AimForRandomEnemy(Bullet *b) {
    Sprite *t = Core.Enemies.n ? Core.Enemies.items[(int)floorf(frand() * Core.Enemies.n)] : NULL;  // RND.pick
    if (t) { Bullet_ApplyInitialVelocity(b, t); return t; }
    Bullet_ApplyPlayerFacingVelocity(b);
    return NULL;
}

static Bullet *Bullet_new(BulletPool *pool, Weapon *w, int index) {
    const BulletVT *vt = pool->vt ? pool->vt : w->vt->bullet;
    Bullet *b = calloc(1, sizeof(Bullet));
    sprite_init(&b->s, frame_get(vt->tex, vt->frame), 0, 0);
    b->s.owner = b;
    b->vt = vt;
    b->isCullable = 1;
    b->_speed = 1;
    b->pool = pool;
    b->weapon = w;
    b->indexInWeapon = index;
    if (vt->ctor) vt->ctor(b);
    return b;
}

static Bullet *BulletPool_SpawnAt(BulletPool *pool, float x, float y, Weapon *w, int index) {
    if (pool->group.n >= pool->upperLimit) {
        if (!pool->isUncapped) return NULL;
        Bullet *first = pool->group.n ? pool->group.items[0]->owner : NULL;
        if (first) Bullet_DeSpawn(first);
    }
    Bullet *b = pool->n_stored ? pool->stored[--pool->n_stored] : NULL;  // Spawn
    if (!b) { b = Bullet_new(pool, w, index); (b->vt->Init ? b->vt->Init : Bullet_Init)(b, -1000, -1000); }
    list_add(&pool->group, &b->s);
    list_add(&Core.BulletGroup, &b->s);
    b->s.x = x;
    b->s.y = y;
    b->indexInWeapon = index;
    children_add(&b->s);
    b->vt->OnRecycle(b);
    return b;
}

// Fantasmi (scie) di Knife e Axe: immagini con tinta, alpha e scala proprie
static void ghost_init(Bullet *b, float sx, float sy, float alpha) {
    sprite_init(&b->ghost, b->s.frame, 0, 0);
    b->ghost.scaleX = sx;
    b->ghost.scaleY = sy;
    b->ghost.visible = 0;
    b->ghost.tint = 0xff;
    b->ghost.alpha = alpha;
    children_add(&b->ghost);  // scene.add.image
}
static int getHistoryIndex(Bullet *b, int i) { return b->historyIndex + i >= b->maxHistory ? b->historyIndex + i - b->maxHistory : b->historyIndex + i; }

// --- B_Whip (0x7e1d) ----------------------------------------------------------
static void B_Whip_tween2_done(void *ctx) { Bullet_DeSpawn(ctx); }
static void B_Whip_OnRecycle(Bullet *b) {
    Bullet_OnRecycle(b);
    b->s.alpha = 1;
    if (b->hasTween) {
        if (b->previousArea != Weapon_PArea(b->weapon)) {
            tween_stop(b->tween);
            tween_remove(b->tween);
            sprite_setScale(&b->s, 0);
            b->tween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, PixelScale * Weapon_PArea(b->weapon) } }, .nprops = 1, .duration = 0x64, .persist = 1 });
        }
        tween_restart(b->tween);
    }
    if (b->hasTween2) tween_stop(b->tween2);
    b->tween2 = tweens_add((TweenConfig){ .props = { { &b->s.alpha, NULL, 0 } }, .nprops = 1, .duration = 0x64, .delay = 0x64, .onComplete = B_Whip_tween2_done, .ctx = b });
    b->hasTween2 = 1;
    int flip = Core.Player->s.flipX ? b->indexInWeapon % 2 != 1 : b->indexInWeapon % 2 == 1;
    b->s.x += flip ? -0x40 : 0x40;
    b->s.y -= 0x10;
    b->s.y -= 0x10 * b->indexInWeapon;
    b->s.flipY = b->indexInWeapon % 2 == 1;
    b->s.flipX = flip;
    Sound_PlaySound("Whip", 1.7f, 2, -0x64 * b->indexInWeapon, 0, 0);
}
static void B_Whip_Init(Bullet *b, float x, float y) {
    Bullet_Init(b, x, y);
    sprite_setScale(&b->s, 0);
    b->previousArea = Weapon_PArea(b->weapon);
    b->tween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, PixelScale * Weapon_PArea(b->weapon) } }, .nprops = 1, .duration = 0x64, .persist = 1 });
    b->hasTween = 1;
}
static const BulletVT B_Whip = { "vfx", "slash.png", NULL, B_Whip_Init, B_Whip_OnRecycle, NULL, NULL, NULL };

// --- B_MagicMissile (0xf82d) --------------------------------------------------
static void B_MagicMissile_ctor(Bullet *b) {
    b->Pfx = particles_add();
    b->PfxEmitter = particles_createEmitter(b->Pfx, (EmitterConfig){
        .frames = { frame_get("vfx", "PfxHoly1.png"), frame_get("vfx", "PfxHoly2.png") }, .nframes = 2,
        .speed = ERND(0xf, 0x1e), .quantity = 1, .lifespan = EOP(0x12c), .alpha = ERANGE(1, 0), .on = 0 });
}
static void B_MagicMissile_OnRecycle(Bullet *b) {
    Bullet_OnRecycle(b);
    body_setCircle(&b->s.body, 8, b->s.body.offset.x, b->s.body.offset.y);
    sprite_setScale(&b->s, PixelScale * Weapon_PArea(b->weapon));
    b->s.x += (frand() - 0.5f) * b->indexInWeapon * 0xa;
    b->s.y += (frand() - 0.5f) * b->indexInWeapon * 0xa;
    Bullet_AimForNearestEnemy(b);
    Sound_PlaySound("MagicMissile", b->weapon->volume ? b->weapon->volume : 0.15f, 1, -0x64 * b->indexInWeapon, 0xc8, 0xc);
}
static void Bullet_TryFreeze(Bullet *b, void *o);
static void B_MagicMissile_OnHasHitAnObject(Bullet *b, void *o, int isDead) {  // anche Knife, Fireball (Jewels: solo MagicMissile e HolyWand lo accendono)
    if (isDead) return;
    if (b->bounces > 0) { b->bounces--; Bullet_AimForRandomEnemy(b); b->n_hit = 0; return; }
    b->penetrating--;
    if (b->penetrating <= 0) Bullet_DeSpawn(b);
    if (Arcanas_has(14) && b->weapon->freezeChance > 0) Bullet_TryFreeze(b, o);
}
static void B_MagicMissile_Update(Bullet *b, float delta) { (void)delta; emitter_emitParticleAt(b->PfxEmitter, b->s.x, b->s.y, 0); }
static const BulletVT B_MagicMissile = { "vfx", "ProjectileHoly1.png", B_MagicMissile_ctor, NULL, B_MagicMissile_OnRecycle,
                                         B_MagicMissile_OnHasHitAnObject, B_MagicMissile_Update, NULL };

// --- B_Knife (0x9225) ---------------------------------------------------------
static void B_Knife_ctor(Bullet *b) {
    b->maxHistory = 1;
    sprite_setScale(&b->s, PixelScale * Weapon_PArea(b->weapon));
    b->s.angle = -0x5a;
    b->_speed = 2;
    b->posHistory[0] = (Vector2){ 0, 0 };
    ghost_init(b, 1.5f * PixelScale, 0.75f * PixelScale, 0.5f);
}
static void B_Knife_OnRecycle(Bullet *b) {
    Bullet_OnRecycle(b);
    body_setCircle(&b->s.body, 8, b->s.body.offset.x, b->s.body.offset.y);
    b->_speed = 2;
    Weapon *w = b->weapon;
    float c = w->critChancesArray[w->critIndex++ % 1000];
    b->bounces = c >= 0.5f ? w->vt->PBounces(w) : 0;
    sprite_setScale(&b->s, PixelScale * Weapon_PArea(w));
    b->ghost.scaleX = 2 * b->s.scaleX;
    b->ghost.scaleY = 0.75f * b->s.scaleX;
    b->ghost.visible = 1;
    b->ghost.angle = b->s.angle;
    b->ghost.x = b->s.x;
    b->ghost.y = b->s.y;
    for (int i = 0; i < b->maxHistory; i++) b->posHistory[i] = (Vector2){ b->s.x, b->s.y };
    b->s.y -= 0xc;
    b->s.x += (frand() - 0.5f) * (b->indexInWeapon == 0 ? 0 : 0x28) * Weapon_PArea(w);
    b->s.y += (frand() - 0.5f) * (b->indexInWeapon == 0 ? 0 : 0x28) * Weapon_PArea(w);
    Bullet_ApplyPlayerFacingVelocity(b);
    Sound_PlaySound("Shot", w->volume ? w->volume : 0.4f, 1, -0x64 * b->indexInWeapon, 0xc8, 0xa);
}
static void B_Knife_DeSpawn(Bullet *b) { b->ghost.visible = 0; base_DeSpawn(b); }
static void B_Knife_Update(Bullet *b, float delta) {
    (void)delta;
    if (b->historyIndex < b->maxHistory - 1) b->historyIndex++;
    else b->historyIndex = 0;
    Vector2 h = b->posHistory[getHistoryIndex(b, 0)];
    b->ghost.angle = b->s.angle;
    b->ghost.x = h.x;
    b->ghost.y = h.y;
    b->posHistory[b->historyIndex] = (Vector2){ b->s.x, b->s.y };
}
static const BulletVT B_Knife = { "vfx", "ProjectileKnife3.png", B_Knife_ctor, NULL, B_Knife_OnRecycle,
                                  B_MagicMissile_OnHasHitAnObject, B_Knife_Update, B_Knife_DeSpawn };

// --- B_Axe (0x136b1) ----------------------------------------------------------
static void B_Axe_ctor(Bullet *b) {
    b->maxHistory = 1;
    b->grav = 0.625f;
    sprite_setScale(&b->s, PixelScale * Weapon_PArea(b->weapon));
    b->AngleTween = tweens_add((TweenConfig){ .props = { { &b->s.angle, NULL, 0x168 } }, .nprops = 1, .duration = 0x3e8, .repeat = -1 });
    b->MovementTween = tweens_add((TweenConfig){ .props = { { &b->moveAngle, NULL, PI } }, .nprops = 1, .duration = 0x3e8 });
    ghost_init(b, PixelScale, PixelScale, 0.75f);
}
static void B_Axe_OnRecycle(Bullet *b) {
    Bullet_OnRecycle(b);
    body_setCircle(&b->s.body, 0xc, b->s.body.offset.x, b->s.body.offset.y);
    b->_speed = 2;
    b->isCullable = 0;
    sprite_setScale(&b->s, PixelScale * Weapon_PArea(b->weapon));
    int dir = Core.Player->lastFacedDirection.x * 1 + Core.Player->lastFacedDirection.y * 0 < 0 ? -1 : 1;  // dot(RIGHT)
    float a = 0x2d * dir / Weapon_PAmount(b->weapon) * b->indexInWeapon - 0x5a;
    b->startingAngle = a;
    b->s.body.velocity = velocityFromRotation(a * (PI / 180), Bullet_TrueSpeed(b));
    b->initialVelocity.x = b->s.body.velocity.x;
    b->initialVelocity.y = fmaxf(-0x258, b->s.body.velocity.y);
    for (int i = 0; i < b->maxHistory; i++) b->posHistory[i] = (Vector2){ b->s.x, b->s.y };
    b->moveAngle = a * (PI / 180);
    b->MovementTween = tweens_add((TweenConfig){ .props = { { &b->moveAngle, NULL, (a + 0xb4 * dir) * (PI / 180) } }, .nprops = 1, .duration = 0x5dc });
    Sound_PlaySound("Shot", 0.45f, 1, -0x64 * b->indexInWeapon, 0xc8, 0xa);
}
static void B_Axe_DeSpawn(Bullet *b) {
    tween_stop(b->MovementTween);
    tween_stop(b->ScaleTween);
    b->ghost.visible = 0;
    base_DeSpawn(b);
}
static void B_Axe_OnHasHitAnObject(Bullet *b, void *o, int isDead) {
    (void)o;
    if (isDead) return;
    if (b->bounces > 0) {
        b->bounces--;
        b->s.body.velocity = velocityFromRotation(b->startingAngle * (PI / 180), Bullet_TrueSpeed(b));
        b->initialVelocity.x *= -1;
        b->initialVelocity.y = fmaxf(-0x258, b->s.body.velocity.y);
        b->n_hit = 0;
        return;
    }
    b->penetrating--;
    if (b->penetrating <= 0) Bullet_DeSpawn(b);
}
static void B_Axe_Update(Bullet *b, float delta) {
    b->initialVelocity.y += delta * b->grav;
    if (b->historyIndex < b->maxHistory - 1) b->historyIndex++;
    else b->historyIndex = 0;
    Vector2 h = b->posHistory[getHistoryIndex(b, 0)];
    b->ghost.angle = b->s.angle;
    b->ghost.x = h.x;
    b->ghost.y = h.y;
    b->ghost.scaleX = b->ghost.scaleY = b->s.scaleX;
    b->ghost.visible = 1;
    sprite_setVelocity(&b->s, b->initialVelocity.x, b->initialVelocity.y);
    b->posHistory[b->historyIndex] = (Vector2){ b->s.x, b->s.y };
    if (b->s.y > Core.Player->s.y + game_height) { b->isCullable = 1; Bullet_DeSpawn(b); }
}
static const BulletVT B_Axe = { "vfx", "ProjectileAxe1.png", B_Axe_ctor, NULL, B_Axe_OnRecycle, B_Axe_OnHasHitAnObject, B_Axe_Update, B_Axe_DeSpawn };

static void Bullet_explodeMany(Bullet *b);
static Bullet *Weapon_SpawnExplosionAt(Weapon *w, float x, float y, int index);
static BulletPool *BulletPool_new(Weapon *w, const BulletVT *vt);
// --- B_HolyBook (0x1d36) ------------------------------------------------------
static void B_HolyBook_pfxStart(void *ctx) { emitter_start(((Bullet *)ctx)->PfxEmitter); }
static void B_HolyBook_clearHits(void *ctx) { ((Bullet *)ctx)->n_hit = 0; }
static void B_HolyBook_despawn(void *ctx) { Bullet_DeSpawn(ctx); }
static void B_HolyBook_expire(void *ctx) {
    Bullet *b = ctx;
    time_removeEvent(b->HitboxTimer);
    time_removeEvent(b->ExpireTimer);
    emitter_stop(b->PfxEmitter);
    if (b->hasScaleTween) tween_stop(b->scaleTween);
    b->scaleTween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, 0 } }, .nprops = 1, .duration = 0x1f4, .onComplete = B_HolyBook_despawn, .ctx = b });
    b->hasScaleTween = 1;
}
static void B_HolyBook_ctor(Bullet *b) {
    b->radius = 0x32;
    b->perc = 1.0f / 16;
    sprite_setScale(&b->s, PixelScale * (1 + 0.1f * Weapon_PArea(b->weapon)));
    b->Pfx = particles_add();
    b->PfxEmitter = particles_createEmitter(b->Pfx, (EmitterConfig){
        .frames = { frame_get("vfx", "Page.png") }, .nframes = 1, .speed = EOP(0x32), .quantity = 1, .lifespan = EOP(0x12c),
        .alpha = ERANGE(0.7f, 0), .on = 1, .follow = &b->s, .frequency = 0xc8 });
    // requiemRandomOffsets: servono solo con l'arcana Twilight Requiem
}
static void B_HolyBook_OnRecycle(Bullet *b) {
    Bullet_OnRecycle(b);
    body_setCircle(&b->s.body, 8, b->s.body.offset.x, b->s.body.offset.y);
    sprite_setScale(&b->s, 0);
    if (b->hasScaleTween) tween_stop(b->scaleTween);
    b->scaleTween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, PixelScale * (1 + 0.3f * Weapon_PArea(b->weapon)) } }, .nprops = 1, .duration = 0x1f4, .onComplete = B_HolyBook_pfxStart, .ctx = b });
    b->hasScaleTween = 1;
    b->deltaTime = 2 * PI / Weapon_PAmount(b->weapon) * b->indexInWeapon;
    time_removeEvent(b->HitboxTimer);
    time_removeEvent(b->ExpireTimer);
    b->HitboxTimer = time_addEvent(b->weapon->hitBoxDelay, 1, 0, B_HolyBook_clearHits, b);
    b->ExpireTimer = time_addEvent(Weapon_PDuration(b->weapon), 0, 0, B_HolyBook_expire, b);
}
static void B_HolyBook_DeSpawn(Bullet *b) {
    base_DeSpawn(b);
    if (b->hasScaleTween) tween_stop(b->scaleTween);
    time_removeEvent(b->HitboxTimer);
    time_removeEvent(b->ExpireTimer);
    emitter_stop(b->PfxEmitter);
    if (b->weapon->explodeOnExpire) Bullet_explodeMany(b);
}
static void B_HolyBook_Update(Bullet *b, float delta) {
    b->deltaTime += 0.035f * Weapon_PSpeed(b->weapon) * delta * b->perc;
    b->s.x = Core.Player->s.x;
    b->s.y = Core.Player->s.y;
    float r = fminf(4.5f, Weapon_PArea(b->weapon));
    b->s.x += cosf(b->deltaTime) * r * b->radius;
    b->s.y += sinf(b->deltaTime) * r * b->radius;
}
static const BulletVT B_HolyBook = { "vfx", "HolyBook.png", B_HolyBook_ctor, NULL, B_HolyBook_OnRecycle, NULL, B_HolyBook_Update, B_HolyBook_DeSpawn };

// --- B_HolyWater (0x1220c) ----------------------------------------------------
static void GroundFx_draw(Sprite *s) {  // scene.add.circle(16, colore in tint), blend ADD
    BeginBlendMode(BLEND_ADDITIVE);
    DrawCircle((int)roundf(s->x - camera_scrollX), (int)roundf(s->y - camera_scrollY), 16 * s->scaleX,
               (Color){ (s->tint >> 16) & 0xff, (s->tint >> 8) & 0xff, s->tint & 0xff, (unsigned char)(255 * s->alpha) });
    EndBlendMode();
}
static float Weapon_GetAngle(Weapon *w) { int i = (w->lastAngleIndex + 1) % w->maxAngles; w->lastAngleIndex = i; return w->targetAngles[i]; }
static float Weapon_GetRadius(Weapon *w) { int i = (w->lasRadiusIndex + 1) % w->maxAngles; w->lasRadiusIndex = i; return w->targetRadii[i]; }
static void B_HolyWater_Break(void *ctx);
static void B_HolyWater_expire(void *ctx) {
    Bullet *b = ctx;
    b->GroundFx.visible = 0;
    time_removeEvent(b->HitboxTimer);
    time_removeEvent(b->ExpireTimer);
    Bullet_DeSpawn(b);
}
static void B_HolyWater_ctor(Bullet *b) {
    b->radius = 0x10;
    b->exploRadius = 8;
    b->_speed = 2;
    b->explosionRadius = b->exploRadius;
    sprite_init(&b->GroundFx, NULL, 0, 0);
    b->GroundFx.alpha = 0.2f;
    b->GroundFx.tint = 0xff;
    b->GroundFx.visible = 0;
    b->GroundFx.draw = GroundFx_draw;
    children_add(&b->GroundFx);
    b->Pfx = particles_add();
    const Frame *fl[2] = { frame_get("vfx", "ProjectileFlameHoly.png"), frame_get("vfx", "ProjectileFlameBlue.png") };
    b->PfxEmitter1 = particles_createEmitter(b->Pfx, (EmitterConfig){ .frames = { fl[0], fl[1] }, .nframes = 2, .speed = ERND(1, 1), .quantity = 1,
        .rotate = ERND(0x5a, 0x5a), .lifespan = EOP(0x258), .alpha = ERANGE(1, 0), .scale = ERANGE(PixelScale / 4, PixelScale), .hasZone = 1, .zoneRadius = b->exploRadius });
    b->PfxEmitter2 = particles_createEmitter(b->Pfx, (EmitterConfig){ .frames = { fl[0], fl[1] }, .nframes = 2, .speed = ERND(1, 1), .quantity = 1,
        .rotate = ERND(0x5a, 0x5a), .lifespan = EOP(0x258), .alpha = ERANGE(0.2f, 0), .scale = ERANGE(PixelScale / 4, PixelScale / 2), .blendAdd = 1, .hasZone = 1, .zoneRadius = b->exploRadius });
    b->PfxExplosion = particles_add();
    particles_createEmitter(b->PfxExplosion, (EmitterConfig){ .frames = { frame_get("vfx", "HitCloud2.png") }, .nframes = 1, .quantity = 1,
        .rotate = ERND(0, 0x168), .lifespan = EOP(0x96), .alpha = ERANGE(1, 0.5f), .scale = ERANGE(PixelScale / 4, 2 * PixelScale) });
    particles_createEmitter(b->PfxExplosion, (EmitterConfig){ .frames = { frame_get("vfx", "HitCloud1.png") }, .nframes = 1, .quantity = 3,
        .rotate = ERND(0, 0x168), .lifespan = EOP(0x96), .alpha = ERANGE(1, 0.5f), .scale = ERANGE(PixelScale / 4, PixelScale) });
    b->AngleTween = tweens_add((TweenConfig){ .props = { { &b->s.angle, NULL, 0x168 } }, .nprops = 1, .duration = 0x258, .repeat = -1 });
}
static void B_HolyWater_OnRecycle(Bullet *b) {
    Bullet_OnRecycle(b);
    Weapon *w = b->weapon;
    b->_speed = 2;
    body_setCircle(&b->s.body, b->radius, -0.5f * b->radius, -0.5f * b->radius);
    sprite_setScale(&b->s, PixelScale);
    b->s.visible = 1;
    b->isBroken = 0;
    b->s.body.enable = 0;
    b->isCullable = 0;
    time_removeEvent(b->HitboxTimer);
    time_removeEvent(b->ExpireTimer);
    b->explosionRadius = b->exploRadius * Weapon_PArea(w) * 3;
    b->PfxEmitter1->c.zoneRadius = b->PfxEmitter2->c.zoneRadius = b->explosionRadius;
    b->PfxEmitter1->c.quantity = b->PfxEmitter2->c.quantity = 1 + (int)floorf(w->level / 3.0f);
    Vector2 t = { Core.Player->s.x, Core.Player->s.y };
    b->s.x = t.x + (frand() - 0.5f) * game_width * 0.5f;
    b->s.y = t.y - 0.6f * game_height;
    float ang = Weapon_GetAngle(w), rad = Weapon_GetRadius(w);
    t.x += cosf(ang) * rad;
    t.y += sinf(ang) * rad;
    if (Weapon_PAmount(w) < 4 && b->indexInWeapon == 0) {
        Sprite *c = physics_closest(&Core.Player->s, &Core.Enemies);
        if (c) t = (Vector2){ c->x, c->y };
    }
    b->s.depth = b->s.y - Core.Player->s.y + game_height;
    if (b->hasPositionTween) tween_remove(b->PositionTween);
    b->PositionTween = tweens_add((TweenConfig){ .props = { { &b->s.x, NULL, t.x }, { &b->s.y, NULL, t.y } }, .nprops = 2, .duration = 0x2ee, .onComplete = B_HolyWater_Break, .ctx = b });
    b->hasPositionTween = 1;
}
static void B_HolyWater_Break(void *ctx) {
    Bullet *b = ctx;
    if (b->isBroken) return;
    b->isBroken = 1;
    b->s.visible = 0;
    sprite_setVelocity(&b->s, 0, 0);
    b->n_hit = 0;
    b->s.body.enable = 1;
    b->GroundFx.x = b->s.x;
    b->GroundFx.y = b->s.y;
    b->GroundFx.visible = 1;
    sprite_setScale(&b->GroundFx, PixelScale * Weapon_PArea(b->weapon));
    sprite_setScale(&b->s, PixelScale * Weapon_PArea(b->weapon));
    b->HitboxTimer = time_addEvent(b->weapon->hitBoxDelay, 1, 0, B_HolyBook_clearHits, b);
    b->ExpireTimer = time_addEvent(Weapon_PDuration(b->weapon), 0, 0, B_HolyWater_expire, b);
    manager_emitParticleAt(b->PfxExplosion, b->s.x, b->s.y);
    b->Pfx->s.depth = b->s.y - Core.Player->s.y - 0.5f * game_height;
    b->GroundFx.depth = b->s.y - Core.Player->s.y - 0.5f * game_height;
    Sound_PlaySound("Holywater", 0.35f, 2, -0xc8 - -0x32 * b->indexInWeapon, 0xc8, 0xc);
}
static void B_HolyWater_Update(Bullet *b, float delta) { (void)delta; if (b->isBroken) manager_emitParticleAt(b->Pfx, b->s.x, b->s.y); }
static void B_HolyWater_DeSpawn(Bullet *b) {
    b->isCullable = 1;
    time_removeEvent(b->HitboxTimer);
    time_removeEvent(b->ExpireTimer);
    b->GroundFx.visible = 0;
    base_DeSpawn(b);
}
static const BulletVT B_HolyWater = { "items", "HolyWater.png", B_HolyWater_ctor, NULL, B_HolyWater_OnRecycle, NULL, B_HolyWater_Update, B_HolyWater_DeSpawn };

// --- B_Vampirica (0xe4a6): la frusta con due fantasmi, rosso e viola additivo ------------
static TweenRef B_Vampirica_scaleTween(Bullet *b) {  // targets [this, ghost1, ghost2]
    float v = PixelScale * Weapon_PArea(b->weapon);
    return tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, v }, { &b->ghost.scaleX, &b->ghost.scaleY, v }, { &b->ghost2.scaleX, &b->ghost2.scaleY, v } },
                                     .nprops = 3, .duration = 0x64, .persist = 1 });
}
static void B_Vampirica_ctor(Bullet *b) {
    sprite_init(&b->ghost, frame_get("vfx", "slash.png"), b->s.x, b->s.y);
    sprite_setScale(&b->ghost, 0);
    sprite_init(&b->ghost2, frame_get("vfx", "slash.png"), b->s.x, b->s.y);
    sprite_setScale(&b->ghost2, 0);
    b->ghost2.blendAdd = 1;
    children_add(&b->ghost);
    children_add(&b->ghost2);
    sprite_setTint(&b->s, 0x110011);
    sprite_setTint(&b->ghost2, 0x660066);
    sprite_setTint(&b->ghost, 0xff0000);
}
static void B_Vampirica_Init(Bullet *b, float x, float y) {
    Bullet_Init(b, x, y);
    sprite_setScale(&b->s, 0);
    b->previousArea = Weapon_PArea(b->weapon);
    b->tween = B_Vampirica_scaleTween(b);
    b->hasTween = 1;
}
static void B_Vampirica_OnRecycle(Bullet *b) {
    Bullet_OnRecycle(b);
    b->s.alpha = b->ghost.alpha = b->ghost2.alpha = 1;
    if (b->hasTween) {
        if (b->previousArea != Weapon_PArea(b->weapon)) {
            tween_stop(b->tween);
            tween_remove(b->tween);
            sprite_setScale(&b->s, 0);
            b->tween = B_Vampirica_scaleTween(b);
        }
        tween_restart(b->tween);
    }
    if (b->hasTween2) tween_stop(b->tween2);
    b->tween2 = tweens_add((TweenConfig){ .props = { { &b->s.alpha, NULL, 0 }, { &b->ghost.alpha, NULL, 0 }, { &b->ghost2.alpha, NULL, 0 } }, .nprops = 3,
                                          .duration = 0xc8, .delay = 0x64, .onComplete = B_Whip_tween2_done, .ctx = b });
    b->hasTween2 = 1;
    int flip = Core.Player->s.flipX ? b->indexInWeapon % 2 != 1 : b->indexInWeapon % 2 == 1;
    b->s.x += flip ? -0x40 : 0x40;
    b->s.y -= 0x10;
    b->s.y -= 0x10 * b->indexInWeapon;
    int fy = b->indexInWeapon % 2 == 1;
    b->s.flipY = b->ghost.flipY = b->ghost2.flipY = fy;
    b->s.flipX = b->ghost.flipX = b->ghost2.flipX = flip;
    b->ghost.x = b->s.x + 4, b->ghost2.x = b->s.x - 4;
    b->ghost.y = b->s.y + 2, b->ghost2.y = b->s.y - 2;
    Sound_PlaySound("Whip", 1.7f, 2, -0x64 * b->indexInWeapon, 0, 0);
}
static const BulletVT B_Vampirica = { "vfx", "slash.png", B_Vampirica_ctor, B_Vampirica_Init, B_Vampirica_OnRecycle, NULL, NULL, NULL };

// --- B_Scythe (0x1179c): falce che gira, a raggiera, con un fantasma nero ----------------
static void B_Scythe_ctor(Bullet *b) {
    b->maxHistory = 1;
    b->posHistory[0] = (Vector2){ b->s.x, b->s.y };
    b->AngleTween = tweens_add((TweenConfig){ .props = { { &b->s.angle, NULL, 0x168 } }, .nprops = 1, .duration = 0x1f4, .repeat = -1 });
    ghost_init(b, PixelScale, PixelScale, 0.75f);
    b->ghost.tint = 0;
}
static void B_Scythe_OnRecycle(Bullet *b) {
    Bullet_OnRecycle(b);
    body_setCircle(&b->s.body, 0x10, b->s.body.offset.x, b->s.body.offset.y);
    sprite_setScale(&b->s, PixelScale * Weapon_PArea(b->weapon));
    float a = 0x168 / Weapon_PAmount(b->weapon) * b->indexInWeapon - 0x5a;
    b->s.body.velocity = velocityFromRotation(a * (PI / 180), Bullet_TrueSpeed(b));
    for (int i = 0; i < b->maxHistory; i++) b->posHistory[i] = (Vector2){ b->s.x, b->s.y };
    Sound_PlaySound("Shot", 0.4f, 1, -0x64 * b->indexInWeapon, 0xc8, 0xa);
    Bullet_activateBounce(b, B_Scythe_Bounce);
}
static void B_Scythe_Update(Bullet *b, float delta) {
    (void)delta;
    if (b->historyIndex < b->maxHistory - 1) b->historyIndex++;
    else b->historyIndex = 0;
    Vector2 h = b->posHistory[getHistoryIndex(b, 0)];
    b->ghost.angle = b->s.angle;
    b->ghost.x = h.x;
    b->ghost.y = h.y;
    b->ghost.scaleX = b->ghost.scaleY = b->s.scaleX;
    b->ghost.visible = 1;
    b->posHistory[b->historyIndex] = (Vector2){ b->s.x, b->s.y };
}
static const BulletVT B_Scythe = { "vfx", "ProjectileScythe.png", B_Scythe_ctor, NULL, B_Scythe_OnRecycle, NULL, B_Scythe_Update, B_Knife_DeSpawn };

// --- B_Vespers (0x54d4): HolyBook con Page2, scia piu' fitta e l'animazione 'idle' ----------
static Animation VespersIdle;  // anims.create('idle'): g o r g o n z o l a, 2 fps, repeat -1
static void B_Vespers_ctor(Bullet *b) {
    b->radius = 0x32;
    b->perc = 1.0f / 16;
    sprite_setScale(&b->s, PixelScale * (1 + 0.1f * Weapon_PArea(b->weapon)));
    static const char *letters[] = { "g.png", "o.png", "r.png", "g.png", "o.png", "n.png", "z.png", "o.png", "l.png", "a.png" };
    VespersIdle.n = 0;
    for (int i = 0; i < 10; i++) VespersIdle.frames[VespersIdle.n++] = frame_get("vfx", letters[i]);
    VespersIdle.frameRate = 2, VespersIdle.msPerFrame = 1000.0f / 2, VespersIdle.repeat = -1;
    b->Pfx = particles_add();
    b->PfxEmitter = particles_createEmitter(b->Pfx, (EmitterConfig){
        .frames = { frame_get("vfx", "Page2.png") }, .nframes = 1, .speed = EOP(0x32), .quantity = 2, .lifespan = EOP(0x12c),
        .alpha = ERANGE(1, 0), .on = 1, .follow = &b->s, .frequency = 0x64 });
    // requiemRandomOffsets: servono solo con l'arcana Twilight Requiem
}
static void B_Vespers_OnRecycle(Bullet *b) {  // OnRecycle di HolyBook (stessi tween e timer) + anims.play('idle')
    B_HolyBook_OnRecycle(b);
    anims_play(&b->s, &VespersIdle, 0);
}
