static const WeaponVT W_MagicMissile = { BASE, .CheckArcanas = CA_magicMissile, .bullet = &B_MagicMissile, .PBounces = bonus_PBounces };
static const WeaponVT W_Knife = { BASE, .CheckArcanas = CA_knife, .onBulletOverlapsEnemy = W_canCrit_onBulletOverlapsEnemy, .bullet = &B_Knife, .PBounces = bonus_PBounces };
static const WeaponVT W_Axe = { BASE, .CheckArcanas = CA_axe, .onBulletOverlapsEnemy = W_canCrit_onBulletOverlapsEnemy, .bullet = &B_Axe, .PBounces = bonus_PBounces, .PArea = W_Axe_PArea };
static const WeaponVT W_HolyBook = { BASE, .PPower = armor_PPower, .SecondaryPPower = power_noBloodline, .CheckArcanas = CA_twilight, .bullet = &B_HolyBook };
static const WeaponVT W_HolyWater = { BASE, .PPower = armor_PPower, .CheckArcanas = CA_tragic, .bullet = &B_HolyWater, .ctor = W_HolyWater_ctor, .LevelUp = W_HolyWater_LevelUp,
                                      .Update = W_HolyWater_Update, .ResetFiringTimer = noop_ResetFiringTimer };
static const WeaponVT W_Laurel = { BASE, .bullet = &B_Whip, .ctor = W_Laurel_ctor, .PAmount = W_Laurel_PAmount, .Fire = W_Laurel_Fire,
                                   .OnStart = W_Laurel_OnStart, .Update = W_Laurel_Update, .LevelUp = W_Laurel_LevelUp };
// W_HolyWand (0xf87): MagicMissile con PBounces; il suo B_HolyWand (0xf422) estende B_MagicMissile senza cambiare nulla
static const WeaponVT W_HolyWand = { BASE, .CheckArcanas = CA_holyWand, .bullet = &B_MagicMissile, .PBounces = bonus_PBounces };
// THOUSAND: stessa classe di KNIFE (0x1f5a) e stesso bullet (0x9225)
// W_Scythe (0xd99a): PArea con 1.2 invece dell'1.3 dell'ascia
static float W_Scythe_PArea(Weapon *w) { return fminf(10, 1.2f * Core.Player->area) * w->area; }
static const WeaponVT W_Scythe = { BASE, .CheckArcanas = CA_scythe, .onBulletOverlapsEnemy = W_canCrit_onBulletOverlapsEnemy, .bullet = &B_Scythe, .PBounces = bonus_PBounces, .PArea = W_Scythe_PArea };  // canCrit (StandardCritical) solo con l'arcana Mad Groove
// W_Vespers (0x14936): SecondaryPPower/explodeOnExpire servono solo con l'arcana Twilight Requiem
static const WeaponVT W_Vespers = { BASE, .SecondaryPPower = power_noBloodline, .CheckArcanas = CA_twilight, .bullet = &B_Vespers };
// W_Vampirica (0xd684): un critico cura 8 HP, al massimo una volta ogni healDelay
static void W_Vampirica_ctor(Weapon *w) { w->canHeal = 1; w->healDelay = 0x3e8; }
static void W_Vampirica_heal(void *ctx) { ((Weapon *)ctx)->canHeal = 1; }
static void W_Vampirica_onBulletOverlapsEnemy(Weapon *w, Bullet *b, Enemy *e) {
    if (e->isDead) return;
    float crit = frand() < w->critChance * Player_PLuck(Core.Player) ? w->critMul * Arcanas.CritMul : 1;  // PLuck
    if (crit > 1 && w->canHeal) {
        w->canHeal = 0;
        Player_RecoverHp(Core.Player, 8, 1, 0);
        w->healTimer = time_addEvent(w->healDelay, 0, 0, W_Vampirica_heal, w);
    }
    if (!Bullet_HasAlreadyHitObject(b, e, e->isDead)) {
        float p = Weapon_PPower(w) * crit;
        Enemy_GetDamaged(e, p, (int)w->hitVFX, w->knockback, w->bulletType);
        w->stats_inflictedDamage += p;
    }
}
static const WeaponVT W_Vampirica = { BASE, .CheckArcanas = CA_slash, .bullet = &B_Vampirica, .ctor = W_Vampirica_ctor, .onBulletOverlapsEnemy = W_Vampirica_onBulletOverlapsEnemy };
// W_Bora (0x8c61): spara da Update come HolyWater; i bersagli sono i 12 punti di un'ellisse
static void W_Bora_ctor(Weapon *w) {
    w->maxAngles = 0xc;
    w->mul = 1000.0f / 3;
    float r = 0.5f * 0x1c8;  // GAMEPLAY_PIXEL_HEIGHT
    for (int i = 0; i < 0xc; i++) {  // new Ellipse(0, 0, GAMEPLAY_PIXEL_HEIGHT, GAMEPLAY_PIXEL_WIDTH).getPoints(12)
        float a = 2 * PI * ((float)i / 0xc);
        w->targetPoints[i] = (Vector2){ 0.5f * 0x1c8 * cosf(a), 0.5f * 0x156 * sinf(a) };
    }
    for (int i = 0; i < w->maxAngles; i++) w->targetAngles[i] = 2 * PI * i / w->maxAngles, w->targetRadii[i] = r;
    shuffle(w->targetRadii, w->maxAngles);
}
static const WeaponVT W_Bora = { BASE, .CheckArcanas = CA_tragic, .bullet = &B_Bora, .ctor = W_Bora_ctor, .LevelUp = W_HolyWater_LevelUp, .Update = W_HolyWater_Update,
                                 .ResetFiringTimer = noop_ResetFiringTimer };  // cooldownAffectedByMovement: solo con l'arcana Tragic Princess
// W_Cross (0x10856): PPower + bloodlineArmorValue, PBounces con bonusBounces (Pearls)
static const WeaponVT W_Cross = { BASE, .PPower = armor_PPower, .CheckArcanas = CA_cross, .bullet = &B_Cross, .PBounces = bonus_PBounces };
// W_HeavenSword (0x29d2): critico senza StandardCritical
static void W_crit_onBulletOverlapsEnemy(Weapon *w, Bullet *b, Enemy *e) {
    if (e->isDead) return;
    float crit = frand() < w->critChance * Player_PLuck(Core.Player) ? w->critMul * Arcanas.CritMul : 1;
    if (!Bullet_HasAlreadyHitObject(b, e, e->isDead)) {
        float p = Weapon_PPower(w) * crit;
        Enemy_GetDamaged(e, p, (int)w->hitVFX, w->knockback, w->bulletType);
        w->stats_inflictedDamage += p;
    }
}
static const WeaponVT W_HeavenSword = { BASE, .CheckArcanas = CA_cross, .bullet = &B_HeavenSword, .PBounces = bonus_PBounces, .onBulletOverlapsEnemy = W_crit_onBulletOverlapsEnemy };
// W_Fireball (0xa894) / W_Hellfire (0x1e1f): Fire sceglie un nemico a caso (RND.pick: lista vuota = nessun bersaglio)
static void W_Fireball_Fire(Weapon *w) {
    w->target = Core.Enemies.n ? Core.Enemies.items[(int)floorf(frand() * Core.Enemies.n)] : NULL;
    Sound_PlaySound("MagicMissile", 0.2f, 1, 0, 0xc8, 0xa);
    base_Fire(w);
}
static void W_Hellfire_Fire(Weapon *w) {  // EnemyGroup.children.entries
    w->target = Core.EnemyGroup.n ? Core.EnemyGroup.items[(int)floorf(frand() * Core.EnemyGroup.n)] : NULL;
    Sound_PlaySound("MagicMissile", 0.2f, 1, 0, 0xc8, 0xa);
    base_Fire(w);
}
static const WeaponVT W_Fireball = { BASE, .CheckArcanas = CA_fireball, .bullet = &B_Fireball, .PBounces = bonus_PBounces, .Fire = W_Fireball_Fire };
static const WeaponVT W_Hellfire = { BASE, .CheckArcanas = CA_hellfire, .bullet = &B_Hellfire, .PBounces = bonus_PBounces, .Fire = W_Hellfire_Fire };
// W_Garlic (0x4a36): spara da Update ogni PInterval; un anello additivo che pulsa e gira attorno al giocatore
static float one_PAmount(Weapon *w) { (void)w; return 1; }
static void W_Garlic_ctor(Weapon *w) {
    w->mul = 1000.0f / 6;
    sprite_init(&w->image, frame_get("vfx", "Rings3.png"), Core.Player->s.x, Core.Player->s.y);
    w->image.blendAdd = 1;
    w->image.alpha = 0.1f;
    sprite_setScale(&w->image, 2 * PixelScale * fminf(10, Core.Player->area) * 1);  // PArea prima di MakeLevelOne: area = 1
    children_add(&w->image);
    // semplificazione: loopDelay 100 ms del primo tween non tradotto (yoyo continuo)
    tweens_add((TweenConfig){ .props = { { &w->image.alpha, NULL, 0.3f } }, .nprops = 1, .loop = 1, .yoyo = 1, .duration = 0x3e8, .repeat = -1 });
    tweens_add((TweenConfig){ .props = { { &w->image.angle, NULL, 0x168 } }, .nprops = 1, .loop = 1, .duration = 0x1770, .repeat = -1 });
}
static void W_Garlic_Fire(Weapon *w) {
    sprite_setScale(&w->image, 2 * PixelScale * Weapon_PArea(w));
    if (Arcanas.hasAstronomia) Arcanas_TriggerAstronomia(w);
    base_Fire(w);
}
static void W_Garlic_Update(Weapon *w, float delta) {
    base_Update(w, delta);
    w->image.x = Core.Player->s.x, w->image.y = Core.Player->s.y;
    w->image.depth = Core.Player->s.depth - 0.5f * game_height;
    sprite_setScale(&w->image, 2 * PixelScale * Weapon_PArea(w));
    w->totalTime += delta;
    if (w->cooldownAffectedByMovement) w->totalTime += Core.Player->frameWalk * (delta / w->mul);
    if (w->totalTime >= Weapon_PInterval(w)) { w->totalTime -= Weapon_PInterval(w); Weapon_Fire(w); }
}
static const WeaponVT W_Garlic = { BASE, .PPower = armor_PPower, .CheckArcanas = CA_tragic, .bullet = &B_Garlic, .ctor = W_Garlic_ctor, .PAmount = one_PAmount, .Fire = W_Garlic_Fire,
                                   .Update = W_Garlic_Update, .ResetFiringTimer = noop_ResetFiringTimer };
// W_Vortex (0x101f3, Soul Eater): un buco nero che si richiude, potenza dagli HP recuperati, cuoricini dai nemici uccisi
static void W_Vortex_ctor(Weapon *w) {
    w->imageScale = 36.0f / 256;
    w->mul = 1000.0f / 6;
    float sc = 2 * PixelScale * fminf(10, Core.Player->area) * 1 * w->imageScale;
    sprite_init(&w->image2, frame_get("vfx", "circle.png"), Core.Player->s.x, Core.Player->s.y);  // imageBG
    w->image2.alpha = 0.6f, w->image2.tint = 0;
    sprite_setScale(&w->image2, sc);
    children_add(&w->image2);
    sprite_init(&w->image, frame_get("vfx", "circle.png"), Core.Player->s.x, Core.Player->s.y);
    w->image.alpha = 0.1f, w->image.tint = 0;
    sprite_setScale(&w->image, sc);
    children_add(&w->image);
    tweens_add((TweenConfig){ .props = { { &w->image.alpha, NULL, 0.6f } }, .nprops = 1, .loop = 1, .yoyo = 1, .duration = 0x3e8, .repeat = -1 });
    Core.Player->onHPRecovery = w;
    w->vortexPfx = particles_add();
    particles_createEmitter(w->vortexPfx, (EmitterConfig){ .frames = { frame_get("vfx", "PfxColor2.png") }, .nframes = 1, .frameCycle = 1,
        .lifespan = EOP(0x1f4), .speed = EOP(0), .scale = ERANGE(1, 0), .alpha = EOP(0.2f), .blendAdd = 1,
        .rotate = ERANGE(0, 0x168), .hasZone = 1, .zoneRadius = 0x3c, .on = 0 });  // semplificazione: rotate con ease Bounce.easeOut, qui lineare (punti di 3 px)
    w->vortexPfx->hasWell = 1;  // createGravityWell({ power: 0.51, epsilon: 20, gravity: 50 })
    w->vortexPfx->wellPower = 0.51f * 0x32, w->vortexPfx->wellEpsilon = 0x14 * 0x14;
    w->innerDuration = 0x1770;
}
static float W_Vortex_PPower(Weapon *w) { return base_PPower(w) + w->recoveredCalculated; }
static void W_Vortex_Fire(Weapon *w) {
    w->recoveredCalculated = fminf(6, w->recoveredHP / 0x258);
    if (Arcanas.hasAstronomia) Arcanas_TriggerAstronomia(w);
    base_Fire(w);
}
static void W_Vortex_Update(Weapon *w, float delta) {
    base_Update(w, delta);
    w->totalTime += delta;
    Sprite *im = &w->image, *bg = &w->image2;  // VortexUpdate
    im->x = bg->x = Core.Player->s.x, im->y = bg->y = Core.Player->s.y;
    im->depth = bg->depth = Core.Player->s.depth - 0.5f * game_height;
    emitter_emitParticleAt(w->vortexPfx->emitters[0], im->x, im->y, 0);
    w->vortexPfx->wellX = im->x, w->vortexPfx->wellY = im->y;
    sprite_setScale(bg, 2 * PixelScale * Weapon_PArea(w) * w->imageScale);
    w->vfxTime += delta;
    if (w->vfxTime > w->innerDuration) w->vfxTime = 0;
    w->innerScale = Weapon_PArea(w) * ((w->innerDuration - w->vfxTime) / w->innerDuration);
    sprite_setScale(im, 2 * PixelScale * w->innerScale * w->imageScale);
    w->vortexPfx->emitters[0]->c.zoneRadius = 0x10 * Weapon_PArea(w) * 2;  // shape1.radius
    if (w->cooldownAffectedByMovement) w->totalTime += Core.Player->frameWalk * (delta / w->mul);
    if (w->totalTime >= Weapon_PInterval(w)) { w->totalTime -= Weapon_PInterval(w); Weapon_Fire(w); }
}
static void W_Vortex_onBulletOverlapsEnemy(Weapon *w, Bullet *b, Enemy *e) {
    if (e->isDead || Bullet_HasAlreadyHitObject(b, e, e->isDead)) return;
    Enemy_GetDamaged(e, Weapon_PPower(w), (int)w->hitVFX, w->knockback, w->bulletType);
    w->stats_inflictedDamage += Weapon_PPower(w);
    if (!e->isDead) return;
    float r = frand();
    if (Weapon_PPower(w) / 7 * 0.15f > r) {
        float o = 0xa * (r - 0.5f);
        Pickup *h = Core_MakePickup(e->s.x + o, e->s.y - o, "LITTLEHEART");
        if (h) h->goToPlayer = 1, h->time = 1;
    }
}
