static void W_UpdateFire(Weapon *w, float delta) {  // super.Update + totalTime, frameWalk, Fire
    base_Update(w, delta);
    if (!w->mul) w->mul = 1000.0f / 6;
    w->totalTime += delta;
    if (w->cooldownAffectedByMovement) w->totalTime += Core.Player->frameWalk * (delta / w->mul);
    if (w->totalTime >= Weapon_PInterval(w)) { w->totalTime -= Weapon_PInterval(w); Weapon_Fire(w); }
}
