// W_Misspell (0x17685): l'arma nascosta NDUJA, si toglie da sola dopo 10 s * Player.duration
static void Weapon_CleanUp(Weapon *w);
static void W_Misspell_Update(Weapon *w, float delta) {
    base_Update(w, delta);
    w->totalTime += delta;
    if (w->totalTime > 0x2710 * Core.Player->duration) {
        for (int i = 0; i < Core.n_HiddenWeapons; i++)
            if (Core.HiddenWeapons[i] == w) { memmove(&Core.HiddenWeapons[i], &Core.HiddenWeapons[i + 1], (Core.n_HiddenWeapons - i - 1) * sizeof(Weapon *)); Core.n_HiddenWeapons--; break; }
        Weapon_CleanUp(w);
        time_removeEvent(w->firingTimer);
    }
}
