// --- Peachone / Ebony Wings: W_Silf (0x13a8e), W_Silf2 (0x127ba), B_Silf (0x544e), B_Silf2 (0x11c17) -------------
// Un uccello segue il giocatore; i colpi cadono su 12 punti a caso di una zona che gira attorno a lui.
static Vector2 Spline_getPoint(const Vector2 *p, int n, float t);
static void Silf_zoneDraw(Sprite *s) {  // scene.add.circle con solo lo stroke: raggio in scaleX, lineWidth in scaleY
    if (!s->visible || s->alpha <= 0) return;
    Vector2 c = { s->x - camera_scrollX, s->y - camera_scrollY };
    DrawRing(c, s->scaleX - 0.5f * s->scaleY, s->scaleX + 0.5f * s->scaleY, 0, 360, 48, hexc(s->tint, s->alpha));
}
static void Silf_zone(Sprite *s, float radius, float lineWidth, unsigned color) {
    sprite_init(s, NULL, 0, 0);
    s->draw = Silf_zoneDraw;
    s->scaleX = radius, s->scaleY = lineWidth, s->tint = color;
    children_add(s);
}
static void W_Silf_ctor_common(Weapon *w, int silf2) {
    static Animation idle[2];
    w->silf2 = silf2;
    w->ntargets = 12;
    w->damageZoneDistance = 0x1c8 * 0.5f;  // IS_PORTRAIT ? GAMEPLAY_PIXEL_WIDTH : GAMEPLAY_PIXEL_HEIGHT
    w->damageZoneDefaultRadius = 0.25f * w->damageZoneDistance;
    w->damageZoneDistance -= w->damageZoneDefaultRadius;
    w->delayBasedOnDuration = 1;
    w->rayDuration = 0x1f4;
    w->runSpeed = PlayerPxSpeed / 1.178571428571429f;
    Silf_zone(&w->damageZone, w->damageZoneDefaultRadius, 2, 0xffff00);
    w->damageZone.visible = 0;
    Silf_zone(&w->targetZone, w->damageZoneDefaultRadius, 1, silf2 ? 0xff88ff : 0x8888ff);
    w->targetZone.alpha = 0.5f;
    sprite_init(&w->sprite, frame_get("vfx", silf2 ? "ProjectileBird4.png" : "ProjectileBird2.png"), Core.Player->s.x, Core.Player->s.y);
    children_add(&w->sprite);
    physics_existing(&w->sprite);
    if (!idle[silf2].n) make_anim(&idle[silf2], "vfx", "ProjectileBird", silf2 ? 4 : 1, silf2 ? 5 : 2, 0, 6, -1);
    anims_play(&w->sprite, &idle[silf2], 0);
    w->sprite.depth = MAX_SAFE_INTEGER - 0x3e7;
}
static void W_Silf_ctor(Weapon *w) { W_Silf_ctor_common(w, 0); }
static void W_Silf2_ctor(Weapon *w) { W_Silf_ctor_common(w, 1); }
static void W_Silf_Fire(Weapon *w) {
    if (w->blockFire) return;
    w->repeatInterval = w->interval / Weapon_PAmount(w);
    w->damageZone.scaleX = w->damageZoneDefaultRadius;
    float r = w->damageZone.scaleX;  // this.circle
    for (int i = 0; i < 12; i++) {  // Geom.Circle.Random
        float t = 2 * PI * frand(), u = frand() + frand(), k = u > 1 ? 2 - u : u;
        w->targets[i] = (Vector2){ k * cosf(t) * r + w->damageZone.x, k * sinf(t) * r + w->damageZone.y };
    }
    base_Fire(w);
}
static void W_Silf_Update(Weapon *w, float delta) {
    base_Update(w, delta);
    w->totalTime += delta;
    w->angleTime += delta;
    float ox = w->silfCounter ? ((Core.Player->s.flipX != (w->silfCounter == 2)) ? 0x24 : -0x24)
                              : ((Core.Player->s.flipX != w->silf2) ? 0x18 : -0x18);  // OffsetX (Silf2 al contrario)
    float oy = w->silfCounter ? 0x18 : 0;  // OffsetY
    Sprite *s = &w->sprite;
    float dx = Core.Player->s.x + ox - s->x, dy = Core.Player->s.y - s->y;
    if (dx * dx + dy * dy > 0x1388) {
        Vector2 *d = &w->_currentDirection;
        d->x = Core.Player->s.x + ox - s->x, d->y = Core.Player->s.y - 0x18 - s->y + oy;
        float l = sqrtf(d->x * d->x + d->y * d->y);
        if (l > 0) d->x /= l, d->y /= l;
        s->flipX = d->x < 0;
        sprite_setVelocity(s, w->runSpeed * d->x * Core.Player->moveSpeed, w->runSpeed * d->y * Core.Player->moveSpeed);
    } else {
        sprite_setVelocity(s, 0x23 * w->_currentDirection.x, 0x23 * w->_currentDirection.y);
    }
    float sg = (w->silf2 || w->silfCounter == 2) ? -1 : 1, a = 0.001f * (w->angleTime - w->rayDuration) * Weapon_PSpeed(w);
    w->targetZone.x = Core.Player->s.x + cosf(sg * a) * w->damageZoneDistance, w->targetZone.y = Core.Player->s.y + sinf(sg * a) * w->damageZoneDistance;
    a = 0.001f * w->angleTime * Weapon_PSpeed(w);
    w->damageZone.x = Core.Player->s.x + cosf(sg * a) * w->damageZoneDistance, w->damageZone.y = Core.Player->s.y + sinf(sg * a) * w->damageZoneDistance;
    if (w->totalTime >= Weapon_PDuration(w)) {
        w->totalTime = -Weapon_PDuration(w) * w->delayBasedOnDuration * Core.Player->cooldown;
        w->blockFire = 1;
        w->targetZone.alpha = 0.1f;
        if (w->totalTime >= Weapon_PDuration(w)) w->totalTime = 0, w->blockFire = 0, w->targetZone.alpha = 0.5f;
    } else if (w->totalTime > 0) {
        w->blockFire = 0;
        w->targetZone.alpha = 0.5f;
    }
}
// LevelUp / ApplyLimitBreak: counterWeapon solo con l'arcana Aquarius
