// Curve.getPointAt: lunghezza d'arco su 100 divisioni (getLengths + getUtoTmapping)
static void Silf_curveLengths(Bullet *b) {
    Vector2 last = Spline_getPoint(b->curvePts, 3, 0);
    float sum = 0;
    b->arcLengths[0] = 0;
    for (int p = 1; p <= 100; p++) {
        Vector2 c = Spline_getPoint(b->curvePts, 3, p / 100.0f);
        sum += sqrtf((c.x - last.x) * (c.x - last.x) + (c.y - last.y) * (c.y - last.y));
        b->arcLengths[p] = sum;
        last = c;
    }
}
static Vector2 Silf_getPointAt(Bullet *b, float u) {
    const float *L = b->arcLengths;
    float target = u * L[100];
    int low = 0, high = 100, i = 0;
    while (low <= high) {
        i = (int)floorf(low + (high - low) / 2.0f);
        float c = L[i] - target;
        if (c < 0) low = i + 1;
        else if (c > 0) high = i - 1;
        else { high = i; break; }
    }
    i = high;
    float t = L[i] == target ? i / 100.0f : (i + (target - L[i]) / (L[i + 1] - L[i])) / 100.0f;
    return Spline_getPoint(b->curvePts, 3, t);
}
static void Silf_trailDraw(Sprite *s) {  // RibbonTrail di 24 punti, Rope orizzontale
    Bullet *b = s->owner;
    if (s->visible) Rope_drawH(b->ropePts, 0x18, b->trailFrame, 1, s->alpha, b->trailAdd, 0);
}
static void B_Silf_ctor_common(Bullet *b, int silf2) {
    b->isKilled = 1;
    b->trailAlpha = silf2 ? 1 : 0.4f;
    b->s.alpha = silf2 ? 1 : 0.5f;  // startingAlpha
    b->_speed = 0;
    b->duration = b->weapon->rayDuration;
    b->fadeInTween = b->fadeOutTween = b->scaleTween = TWEEN_NONE;
    b->explodeTimer = (Timer){ -1, 0 };
    sprite_init(&b->trail, NULL, 0, 0);  // MakeTrail: Silf la crea al primo OnRecycle, Silf2 nel costruttore
    b->trail.owner = b;
    b->trail.draw = Silf_trailDraw;
    b->trail.depth = MAX_SAFE_INTEGER - 0x3eb;
    b->trail.visible = 0;
    b->trailAdd = !silf2;
    b->trailFrame = frame_get("vfx", silf2 ? "Gradient4_4px.png" : "Gradient3_4px.png");
    children_add(&b->trail);
}
static void B_Silf_ctor(Bullet *b) { B_Silf_ctor_common(b, 0); }
static void B_Silf2_ctor(Bullet *b) { B_Silf_ctor_common(b, 1); }
static void B_Silf_DeSpawn(Bullet *b) {
    if (b->weapon->explodeOnExpire) Weapon_SpawnExplosionAt(b->weapon, b->s.x, b->s.y, 0);
    b->isKilled = 1;
    b->trail.visible = 0, b->trail.alpha = 0;
    b->s.body.enable = 0;
    sprite_setScale(&b->s, 0);
    b->s.visible = 0;
    base_DeSpawn(b);
}
static void B_Silf_despawnCb(void *ctx) { Bullet_DeSpawn(ctx); }
static void B_Silf_explode(void *ctx) {  // explodeTimer 'SILF explode'
    Bullet *b = ctx;
    b->s.body.enable = 1;
    b->fadeOutTween = tweens_add((TweenConfig){ .props = { { &b->trail.alpha, NULL, 0 } }, .nprops = 1, .duration = 0xc8, .onComplete = B_Silf_despawnCb, .ctx = b });
    b->scaleTween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, 1 * PixelScale * Weapon_PArea(b->weapon) }, { &b->s.alpha, NULL, 0 } },
                                              .nprops = 2, .duration = 0x78 });
}
static void B_Silf_OnRecycle(Bullet *b) {
    Weapon *w = b->weapon;
    int silf2 = w->silf2;
    Bullet_OnRecycle(b);
    body_setCircle(&b->s.body, 0x10, b->s.body.offset.x, b->s.body.offset.y);
    b->s.body.enable = 0;
    b->totalTime = 0;
    b->isCullable = 0;
    tween_stop(b->fadeInTween), tween_stop(b->fadeOutTween);  // despawnTween: mai creato
    b->s.visible = 0;
    b->trail.visible = 0, b->trail.alpha = 0;
    b->npos = 0;  // clearPositions
    for (int i = 0; i < 0x18; i++) b->ropePts[i] = (Vector2){ b->s.x, b->s.y };  // reset: punti sul follower
    sprite_setScale(&b->s, 0.5f);
    Vector2 t = w->targets[w->enemyIndex % w->ntargets];
    w->enemyIndex++;
    if (w->silf3) {
        // B_Silf3: niente SetBeamTextureFromArea
    } else if (w->silfCounter == 1) {  // B_Silf_Counter: solo le scie larghe, rovesciate
        float a = Weapon_PArea(w);
        if (a >= 2) b->trailFrame = frame_get("vfx", "Gradient3_8pxReverse.png");
        else if (a >= 1.5f) b->trailFrame = frame_get("vfx", "Gradient3_6pxReverse.png");
    } else if (w->silfCounter == 2) {  // B_Silf2_Counter
        float a = Weapon_PArea(w);
        sprite_setFrame(&b->s, frame_get("vfx", "HitBlack1.png"));
        b->trailFrame = frame_get("vfx", a >= 2 ? "Gradient4_8pxReverse.png" : a >= 1.5f ? "Gradient4_6pxReverse.png" : "Gradient4_4pxReverse.png");
    } else if (!silf2) {  // SetBeamTextureFromArea
        sprite_setFrame(&b->s, frame_get("vfx", "HitWhite1.png"));
        float a = Weapon_PArea(w);
        b->trailFrame = frame_get("vfx", a >= 2 ? "Gradient3_8px.png" : a >= 1.5f ? "Gradient3_6px.png" : "Gradient3_4px.png");
    } else if (!(Weapon_PArea(w) >= 2) && Weapon_PArea(w) >= 1.5f) {  // (sic) PArea >= 2 || ...: oltre 2 resta la 4px
        b->trailFrame = frame_get("vfx", "Gradient4_6px.png");
    }
    // targets ha sempre 12 punti: il ramo DeSpawn dell'originale non scatta mai
    Sound_PlaySound("MagicMissile", 0.15f, 1, -0x64 * b->indexInWeapon, 0xc8, 0xc);
    b->isKilled = 0;
    b->target = NULL;  // SetTarget: this.target = punto
    float sg = w->enemyIndex % 2 == 0 ? 1 : -1, ang = (10 * (PI / 180)) * sg + frand() * (20 * (PI / 180)) * sg;
    b->s.x = w->sprite.x, b->s.y = w->sprite.y;
    float px = b->s.x - t.x, py = b->s.y - t.y, sn = sinf(ang), cs = cosf(ang);  // rotate_point attorno al bersaglio
    b->curvePts[0] = (Vector2){ b->s.x, b->s.y };
    b->curvePts[1] = (Vector2){ px * cs - py * sn + t.x, px * sn + py * cs + t.y };
    b->curvePts[2] = t;
    if (w->silf3) b->curvePts[1] = (Vector2){ Core.Player->s.x + 0x32 * (frand() - 0.5f), Core.Player->s.y - 0x96 };  // B_Silf3: l'arco passa sopra il giocatore
    Silf_curveLengths(b);
    Vector2 p = Silf_getPointAt(b, 0);
    b->s.x = p.x, b->s.y = p.y;
    for (int i = 0; i < 0x18; i++) b->ropePts[i] = p;  // resetPoints
    b->trail.visible = 1;
    b->s.visible = 1;
    b->s.alpha = 1;
    tween_stop(b->fadeInTween), tween_remove(b->fadeInTween);
    tween_stop(b->fadeOutTween), tween_remove(b->fadeOutTween);
    tween_stop(b->scaleTween), tween_remove(b->scaleTween);
    b->fadeInTween = tweens_add((TweenConfig){ .props = { { &b->trail.alpha, NULL, b->trailAlpha } }, .nprops = 1, .duration = 0xc8 });
    b->explodeTimer = time_addEvent(b->duration, 0, 0, B_Silf_explode, b);  // FlashingVFXEnabled
}
static void B_Silf_Update(Bullet *b, float delta) {
    if (b->isKilled) return;
    b->totalTime += delta;
    if (b->totalTime > b->duration) b->totalTime = b->duration;
    Vector2 p = Silf_getPointAt(b, b->totalTime / b->duration);
    b->s.x = p.x, b->s.y = p.y;
    memmove(&b->positions[1], &b->positions[0], 0x17 * sizeof(Vector2));  // RibbonTrail.trailUpdate (active)
    b->positions[0] = p;
    if (b->npos < 0x18) b->npos++;
    for (int i = 0; i < b->npos; i++) b->ropePts[i] = b->positions[i];
}
