// --- Phiera Der Tuphello / Eight The Sparrow: W_Guns (0x140bb), W_Guns2 (0xb0e5), B_Guns (0x15e86), B_Guns2 (0x21ce) --
// Quattro colpi a 30, -30, 210, -210 gradi. Con tutte e due le armi, GUNS prende GUNS2 come secondo set e la fa sparare a meta' repeatInterval.
static Weapon *Core_GetWeapon(const char *type);
static void Guns_OnRecycle(Bullet *b, const float *firingAngles) {
    Bullet_OnRecycle(b);
    sprite_setScale(&b->s, 1);
    body_setCircle(&b->s.body, 8, b->s.body.offset.x, b->s.body.offset.y);
    sprite_setScale(&b->s, 0.5f * Weapon_PArea(b->weapon));
    b->s.y -= 0xc;
    b->s.body.velocity = velocityFromRotation(firingAngles[b->indexInWeapon % 4] * (PI / 180), Bullet_TrueSpeed(b));
    Sound_PlaySound("Guns1", 0.2f, 1, 0x64 * b->indexInWeapon, 0xc8, 0xc);
}
static const float GUNS_ANGLES[4] = { 0x1e, -0x1e, 0xd2, -0xd2 }, GUNS_COUNTER_ANGLES[4] = { 0x2d, -0x2d, 0xe1, -0xe1 };
static void B_Guns_OnRecycle(Bullet *b) { Guns_OnRecycle(b, GUNS_ANGLES); }
static void B_GunsCounter_OnRecycle(Bullet *b) { Guns_OnRecycle(b, GUNS_COUNTER_ANGLES); }  // B_Guns_Counter / B_Guns2_Counter
static void Guns_OnHasHitAnObject(Bullet *b, void *o, int isDead, int guns2) {  // B_Guns: Heart of Fire all'impatto; B_Guns2: gelo Jewels
    if (!isDead) {
        if (!guns2 && Arcanas_has(19)) Weapon_SpawnExplosionAt(b->weapon, b->s.x, b->s.y, 1);
        if (b->bounces > 0) {
            b->bounces--;
            b->s.body.velocity.x *= -1, b->s.body.velocity.y *= -1;
            b->n_hit = 0;  // objectsHit = []
            return;        // B_Guns2: niente gelo sul rimbalzo
        }
        if (--b->penetrating <= 0) Bullet_DeSpawn(b);
    }
    if (guns2 && Arcanas_has(14)) Bullet_TryFreeze(b, o);  // B_Guns2: anche col nemico gia' morto, come l'originale
}
static void B_Guns_OnHasHitAnObject(Bullet *b, void *o, int isDead) { Guns_OnHasHitAnObject(b, o, isDead, 0); }
static void B_Guns2_OnHasHitAnObject(Bullet *b, void *o, int isDead) { Guns_OnHasHitAnObject(b, o, isDead, 1); }
