static const BulletVT B_Guns2 = { "vfx", "BulletBlue.png", NULL, NULL, B_Guns_OnRecycle, B_Guns2_OnHasHitAnObject, NULL, NULL };
static const BulletVT B_Guns_Counter = { "vfx", "BulletRed.png", NULL, NULL, B_GunsCounter_OnRecycle, B_Guns_OnHasHitAnObject, NULL, NULL };
static const BulletVT B_Guns2_Counter = { "vfx", "BulletBlue.png", NULL, NULL, B_GunsCounter_OnRecycle, B_Guns2_OnHasHitAnObject, NULL, NULL };
