// --- Phieraggi: W_Guns3 (0x1665e), B_Guns3 (0x8e78) -----------------------------------------------------------
// Raggi RaggiBeam che girano attorno al giocatore; lungo ognuno una raffica di 9 colpi invisibili che curva col giro.
static void B_Guns3_OnRecycle(Bullet *b) {
    Bullet_OnRecycle(b);
    sprite_setScale(&b->s, 1);
    body_setCircle(&b->s.body, 0xa, b->s.body.offset.x, b->s.body.offset.y);
    b->s.visible = 0;
    sprite_setScale(&b->s, Weapon_PArea(b->weapon));
}
static void B_Guns3_OnHasHitAnObject(Bullet *b, void *o, int isDead) {
    (void)o;
    if (!isDead && --b->penetrating <= 0) Bullet_DeSpawn(b);
}
static const BulletVT B_Guns3 = { "vfx", "HitRed1.png", NULL, NULL, B_Guns3_OnRecycle, B_Guns3_OnHasHitAnObject, NULL, NULL };
static float W_Guns3_PAmount(Weapon *w) { return fminf(10, Core.Player->amount) + w->amount + fminf(10, Core.Player->revivals); }
static float W_Guns3_PPower(Weapon *w) { return fminf(10, Core.Player->power) * (w->power + 0.1f * fminf(10, Core.Player->revivals)); }
static float W_Guns3_PSpeed(Weapon *w) { return fminf(5, Core.Player->speed + 1.5f * (Core.Player->speed - 1)) * w->speed * sinev(Core.Player->sineSpeed); }  // Chaos
static void W_Guns3_ctor(Weapon *w) {
    w->angleUnit = (0.5f / 0x10) * (PI / 180);
    w->pxUnit = 0.5f * sqrtf((float)game_width * game_width + (float)game_height * game_height) / 0xc;
}
static void W_Guns3_FireOneBullet(Weapon *w, float x, float y, int index, float angle) {
    Bullet *b = BulletPool_SpawnAt(w->pool, x, y, w, index);
    if (b) b->s.body.velocity = velocityFromRotation(angle, 0xa * ProjectileSpeed);  // SetTarget
}
typedef struct { Weapon *w; float dx, dy, angle, delay; int index; } Guns3Shot;
static void W_Guns3_DelayedShot(void *ctx) {
    Guns3Shot *c = ctx;
    W_Guns3_FireOneBullet(c->w, Core.Player->s.x + c->dx, Core.Player->s.y + c->dy, c->index, c->angle + 1.66f * c->w->angleUnit * c->delay);
}
static TweenRef W_Guns3_raysTween(Weapon *w, float sx, float alpha, Callback onStart, Callback onComplete) {
    TweenProp pr[3 * 32];
    for (int i = 0; i < w->n_rays; i++) {
        pr[3 * i] = (TweenProp){ &w->rays[i].scaleX, NULL, sx };
        pr[3 * i + 1] = (TweenProp){ &w->rays[i].scaleY, NULL, 6.5f };
        pr[3 * i + 2] = (TweenProp){ &w->rays[i].alpha, NULL, alpha };
    }
    return tweens_add((TweenConfig){ .many = pr, .nmany = 3 * w->n_rays, .duration = 4 * w->repeatInterval, .yoyo = 1,
                                     .ease = Ease_SineInOut, .onStart = onStart, .onComplete = onComplete, .ctx = w });
}
static void W_Guns3_PermaTween(void *ctx);
static void W_Guns3_permaStart(void *ctx) {
    Weapon *w = ctx;
    for (int i = 0; i < w->n_rays; i++) w->rays[i].alpha = 1, w->rays[i].scaleX = 0.5f * Weapon_PArea(w), w->rays[i].scaleY = 6.5f;
}
static void W_Guns3_PermaTween(void *ctx) {
    Weapon *w = ctx;
    w->hasPermaTween = 1;
    W_Guns3_raysTween(w, 0.4f * Weapon_PArea(w), 0.8f, W_Guns3_permaStart, W_Guns3_PermaTween);
}
static void W_Guns3_Fire(Weapon *w) {
    static Guns3Shot shots[1024];
    static int shot_i;
    w->angleUnit = (0.5f / 0x20 * W_Guns3_PSpeed(w)) * (PI / 180);
    int n = (int)ceilf(Weapon_PAmount(w));
    if (n > 32) n = 32;  // semplificazione: tetto a 32 raggi (PAmount arriva a ~30 al massimo)
    for (; w->n_rays < n; w->n_rays++) {
        Sprite *r = &w->rays[w->n_rays];
        sprite_init(r, frame_get("vfx", "RaggiBeam.png"), 0, 0);
        r->visible = 0, r->originX = 0.5f, r->originY = 0, r->alpha = 0.25f;
        children_add(r);
    }
    float step = (360.0f / Weapon_PAmount(w)) * (PI / 180);
    for (int i = 0; i < n; i++) {
        float a = w->rayAngle + step * i, dx = cosf(a) * w->pxUnit, dy = sinf(a) * w->pxUnit;
        Sprite *r = &w->rays[i];
        r->visible = 1, r->x = Core.Player->s.x + dx, r->y = Core.Player->s.y + dy;
        r->scaleX = 0.1f, r->scaleY = 1;
        W_Guns3_FireOneBullet(w, dx, dy, 0, a);  // come l'originale: il primo colpo nasce in (dx, dy), senza la posizione del giocatore
        for (int k = 1; k <= 8; k++) {
            Guns3Shot *c = &shots[shot_i++ & 1023];
            *c = (Guns3Shot){ w, dx, dy, a, w->repeatInterval * k, k };
            w->lastShotTimer = time_addEvent(c->delay, 0, 0, W_Guns3_DelayedShot, c);
        }
    }
    if (Weapon_PInterval(w) > 8 * w->repeatInterval) {
        Sound_PlaySound("Guns2", 0.5f, 1, -0x64, 0xc8, 0xa);
        tween_stop(w->scaleTween);
        w->scaleTween = W_Guns3_raysTween(w, 0.5f * Weapon_PArea(w), 0.9f, NULL, NULL);
    } else {
        Sound_PlaySound("Guns3", 0.3f, 1, -0x64, 0x64, 1);
        if (!w->hasPermaTween) Sound_PlaySound("Guns2", 0.5f, 1, -0x64, 0xc8, 0xa), W_Guns3_PermaTween(w);
    }
    if (w->lastFiringInterval != Weapon_PInterval(w)) {
        w->lastFiringInterval = Weapon_PInterval(w);
        Weapon_ResetFiringTimer(w);
    }
}
static void W_Guns3_Update(Weapon *w, float delta) {
    base_Update(w, delta);
    w->rayAngle += w->angleUnit * delta;
    float step = (360.0f / Weapon_PAmount(w)) * (PI / 180);
    for (int i = 0; i < w->n_rays; i++) {
        float a = w->rayAngle + step * i;
        Sprite *r = &w->rays[i];
        r->visible = 1;
        r->x = Core.Player->s.x + cosf(a) * w->pxUnit, r->y = Core.Player->s.y + sinf(a) * w->pxUnit;
        r->angle = a * (180 / PI) - 0x5a;
        r->depth = -game_height;
    }
}
// critChancesArray(1000), LevelUp / ApplyLimitBreak dei counterWeapon: solo con l'arcana Aquarius
static const WeaponVT W_Guns3 = { BASE, .CheckArcanas = CA_guns3, .bullet = &B_Guns3, .PAmount = W_Guns3_PAmount, .PPower = W_Guns3_PPower, .ctor = W_Guns3_ctor,
                                  .Fire = W_Guns3_Fire, .Update = W_Guns3_Update };

// --- Gatti Amari: W_Gatti (0xab10), B_Gatti (0xbd84), B_Gatti_Scratch (0xfb8b), B_Gatti_Scuffle (0x155f9), B_FireExplosion (0x123bc) ---
// Gatti capricciosi: compaiono attorno al giocatore, graffiano (a volte lui), fanno zuffa tra loro e giocano coi pickup.
static float W_Gatti_GetRandom(Weapon *w) { return w->RANDOMS[w->randomIndex++ % 0x1f4]; }
static float W_Gatti_GetPlusMinus(Weapon *w) { return w->PLUSMINUS[w->plusMinusIndex++ % 0x1f4]; }
static const char *W_Gatti_GetSfx(Weapon *w) { return w->SFXARRAY[w->sfxIndex++ % 0x78]; }
static void Bullet_pushHit(Bullet *b, void *o) {  // objectsHit.push senza OnHasHitAnObject
    if (b->n_hit == b->cap_hit) { b->cap_hit = b->cap_hit ? b->cap_hit * 2 : 16; b->objectsHit = realloc(b->objectsHit, b->cap_hit * sizeof(void *)); }
    b->objectsHit[b->n_hit++] = o;
}

// B_Gatti_Scratch: un graffio (slash..slash4) che si allarga in 120 ms e svanisce in 100
static void B_Scratch_despawn(void *ctx) { Bullet_DeSpawn(ctx); }
static void B_Scratch_OnRecycle(Bullet *b) {
    static const struct { const char *frame; float ox, oy; } configs[4] = { { "slash.png", 0, 0.5f }, { "slash2.png", 0, 1 }, { "slash3.png", 0, 0 }, { "slash4.png", 0, 0.5f } };
    Weapon *w = b->weapon;
    Bullet_OnRecycle(b);
    tween_stop(b->exitTween), tween_stop(b->entryTween);
    sprite_setScale(&b->s, 1);
    body_setCircle(&b->s.body, 0x40, -0x20, -0x20);
    sprite_setScale(&b->s, 0);
    b->s.alpha = 1;
    int k = b->cfgIndex++ % 4;
    b->s.flipX = 0.5f >= w->critChancesArray[w->critIndex++ % 1000];
    sprite_setFrame(&b->s, frame_get("vfx", configs[k].frame));
    sprite_setOrigin(&b->s, configs[k].ox, configs[k].oy);
    b->s.angle = (2 * PI * w->critChancesArray[w->critIndex++ % 1000]) * (180 / PI);
    b->s.x += 0x18 * W_Gatti_GetPlusMinus(w);
    b->s.y += 0x18 * W_Gatti_GetPlusMinus(w);
    b->entryTween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, 0.5f * Weapon_PArea(w) } }, .nprops = 1, .duration = 0x78 });
    b->exitTween = tweens_add((TweenConfig){ .props = { { &b->s.alpha, NULL, 0 } }, .nprops = 1, .delay = 0x78, .duration = 0x64, .onComplete = B_Scratch_despawn, .ctx = b });
}
static void B_Scratch_ctor(Bullet *b) { b->exitTween = b->entryTween = TWEEN_NONE; }
static const BulletVT B_Gatti_Scratch = { "vfx", "Cat.png", B_Scratch_ctor, NULL, B_Scratch_OnRecycle, NULL, NULL, NULL };

// B_Gatti_Scuffle: nuvola di fumo invisibile che genera un graffio ogni 30 ms per tutta la durata
static void B_Scuffle_ctor(Bullet *b) {
    b->exploRadius = 0x40;
    b->Pfx = particles_add();
    b->PfxEmitter1 = particles_createEmitter(b->Pfx, (EmitterConfig){ .frames = { frame_get("vfx", "Smoke1.png"), frame_get("vfx", "Smoke2.png") }, .nframes = 2,
        .speed = ERND(1, 0xa), .quantity = 2, .rotate = ERND(0, 0x168), .lifespan = EOP(0x1f4), .alpha = ERANGE(1, 0), .scale = ERANGE(2, 1),
        .hasZone = 1, .zoneRadius = b->exploRadius, .on = 0 });
    b->PfxEmitter2 = particles_createEmitter(b->Pfx, (EmitterConfig){ .frames = { frame_get("vfx", "Smoke1.png"), frame_get("vfx", "Smoke2.png"),
        frame_get("vfx", "HitStarRed1.png"), frame_get("vfx", "HitStarRed2.png"), frame_get("vfx", "Hit2.png"), frame_get("vfx", "Cat.png") }, .nframes = 6,
        .speed = ERND(1, 0xa), .quantity = 1, .rotate = ERND(0, 0x168), .lifespan = EOP(0xfa), .alpha = ERANGE(1, 0), .scale = ERANGE(0, 2),
        .hasZone = 1, .zoneRadius = b->exploRadius, .on = 0 });
    b->HitboxTimer = b->ExpireTimer = (Timer){ -1, 0 };
}
static void B_Scuffle_despawn(void *ctx) { Bullet_DeSpawn(ctx); }
static void B_Scuffle_hitbox(void *ctx) {
    Bullet *b = ctx;
    b->n_hit = 0;  // objectsHit = []
    BulletPool_SpawnAt(b->weapon->scratchPool, b->s.x, b->s.y, b->weapon, 0);
}
static void B_Scuffle_OnRecycle(Bullet *b) {
    Weapon *w = b->weapon;
    float a = Weapon_PArea(w);
    Bullet_OnRecycle(b);
    b->s.body.enable = 1;
    sprite_setScale(&b->s, 1);
    body_setCircle(&b->s.body, 0x20, -0x10, -0x10);
    b->s.visible = 0;
    sprite_setScale(&b->s, a);
    time_removeEvent(b->HitboxTimer), time_removeEvent(b->ExpireTimer);
    b->PfxEmitter1->c.zoneRadius = b->PfxEmitter2->c.zoneRadius = b->exploRadius * a;  // explosionCircle
    b->PfxEmitter1->c.quantity = b->PfxEmitter2->c.quantity = 1 + (int)floorf(a);
    b->PfxEmitter1->c.scale = ERANGE(1 * a, 1);
    b->PfxEmitter2->c.scale = ERANGE(0, 1 * a);
    b->ExpireTimer = time_addEvent(Weapon_PDuration(w), 0, 0, B_Scuffle_despawn, b);
    b->HitboxTimer = time_addEvent(0x1e, 0, -1, B_Scuffle_hitbox, b);
}
static void B_Scuffle_Update(Bullet *b, float delta) { (void)delta; manager_emitParticleAt(b->Pfx, b->s.x, b->s.y); }
static void B_Scuffle_DeSpawn(Bullet *b) {
    b->isCullable = 1;
    time_removeEvent(b->HitboxTimer), time_removeEvent(b->ExpireTimer);
    base_DeSpawn(b);
}
static const BulletVT B_Gatti_Scuffle = { "vfx", "Cat.png", B_Scuffle_ctor, NULL, B_Scuffle_OnRecycle, NULL, B_Scuffle_Update, B_Scuffle_DeSpawn };

// B_FireExplosion: esplosione rossa (NFT preso da un gatto); OnRecycle non passa dal Bullet base
static void B_FireExplosion_ctor(Bullet *b) {
    b->radius = 0x20, b->exploRadius = 0x10;
    b->s.visible = 0;
    b->Pfx = particles_add();
    b->PfxEmitter2 = particles_createEmitter(b->Pfx, (EmitterConfig){ .frames = { frame_get("vfx", "Smoke1.png"), frame_get("vfx", "Smoke2.png") }, .nframes = 2,
        .lifespan = EOP(0x1f4), .rotate = ERND(0, 0x168), .angle = { 0, 0xb4, 1 }, .angleSteps = 0x10, .speed = ERND(0x64, 0xc8), .quantity = 1,
        .scale = ERANGE(1, 0), .frequency = 1, .alpha = ERANGE(0.5f, 0), .hasZone = 1, .zoneRadius = b->exploRadius, .on = 0 });
    b->PfxEmitter = particles_createEmitter(b->Pfx, (EmitterConfig){ .frames = { frame_get("vfx", "HitSmoke1.png"), frame_get("vfx", "HitSmoke2.png") }, .nframes = 2,
        .lifespan = EOP(0x1f4), .rotate = ERND(0, 0x168), .angle = { 0, 0x168, 1 }, .angleSteps = 0x10, .speed = ERND(0x32, 0x50), .quantity = 1,
        .scale = ERANGE(1, 0), .frequency = 1, .blendAdd = 1, .hasZone = 1, .zoneRadius = b->exploRadius, .on = 0 });
    b->Pfx->hasWell = 1;  // createGravityWell({ power: 1, epsilon: 50, gravity: 20 })
    b->Pfx->wellPower = 1 * 0x14, b->Pfx->wellEpsilon = 0x32 * 0x32;
    sprite_init(&b->GroundFx, NULL, 0, 0);  // scene.add.circle(0, 0, 1, 0xff0000), ADD
    b->GroundFx.draw = MoonGroundFx_draw;
    b->GroundFx.tint = 0xff0000, b->GroundFx.alpha = 0.4f, b->GroundFx.visible = 0, b->GroundFx.scaleX = 1;
    children_add(&b->GroundFx);
    b->despawnTween = TWEEN_NONE;
}
static void B_FireExplosion_despawn(void *ctx) { Bullet_DeSpawn(ctx); }
static void B_FireExplosion_OnRecycle(Bullet *b) {
    float a = Weapon_PArea(b->weapon);
    sprite_setScale(&b->s, b->radius * a);
    body_setCircle(&b->s.body, 1, -0.5f, -0.5f);
    sprite_setScale(&b->s, 1);
    b->n_hit = 0;
    b->PfxEmitter->c.scale = b->PfxEmitter2->c.scale = ERANGE(0.5f * a, 0);
    b->PfxEmitter->c.zoneRadius = b->PfxEmitter2->c.zoneRadius = b->exploRadius * a;
    b->Pfx->wellX = b->s.x, b->Pfx->wellY = b->s.y + 0x14;
    b->PfxEmitter->x = b->s.x, b->PfxEmitter->y = b->s.y;
    emitter_start(b->PfxEmitter);
    b->PfxEmitter2->x = b->s.x, b->PfxEmitter2->y = b->s.y;
    emitter_start(b->PfxEmitter2);
    b->GroundFx.x = b->s.x, b->GroundFx.y = b->s.y;
    b->GroundFx.scaleX = 1, b->GroundFx.alpha = 0.2f, b->GroundFx.visible = 1;  // FlashingVFXEnabled
    tween_stop(b->despawnTween);
    // targets [GroundFx, this]: scale e alpha; onStart: setActive(true), body.enable = true
    b->s.active = 1, b->s.body.enable = 1;
    float sc = b->radius * a;
    b->despawnTween = tweens_add((TweenConfig){ .props = { { &b->GroundFx.scaleX, &b->GroundFx.scaleY, sc }, { &b->GroundFx.alpha, NULL, 0 }, { &b->s.scaleX, &b->s.scaleY, sc } },
                                                .nprops = 3, .duration = 0x78, .onComplete = B_FireExplosion_despawn, .ctx = b });
    tweens_add((TweenConfig){ .props = { { &b->s.alpha, NULL, 0 } }, .nprops = 1, .duration = 0x78 });
    Sound_PlaySound("FireExplosion", 0.5f, 1, 0x1f4 * (frand() - 0.5f), 0x96, 3);
}
static void B_FireExplosion_DeSpawn(Bullet *b) {
    b->s.body.enable = 0;
    b->s.active = 0;
    emitter_stop(b->PfxEmitter), emitter_stop(b->PfxEmitter2);
    BulletPool_Return(b->pool, b);
    tween_stop(b->despawnTween), b->despawnTween = TWEEN_NONE;
    b->GroundFx.visible = 0;
}
static const BulletVT B_FireExplosion = { "vfx", "WhiteDot.png", B_FireExplosion_ctor, NULL, B_FireExplosion_OnRecycle, NULL, NULL, B_FireExplosion_DeSpawn };

