static const WeaponVT W_DivineBloodline = { BASE, .bullet = &B_Sarabande, .ResetFiringTimer = noop_ResetFiringTimer };  // non spara: tiene le statistiche
static void Arcanas_TriggerSarabande(float v) { Arcanas.SarabandeWeapon->healAmount = 0.1f * v; Weapon_Fire(Arcanas.SarabandeWeapon); }
static void Arcanas_IncreaseBloodlineBonus(void) { Arcanas.bloodlineMaxHpBonus += Arcanas.divineBloodlineHPBonusUnit, Core.Player->maxHp += Arcanas.divineBloodlineHPBonusUnit; }
// --- Blood Astronomia: W_BloodAstronomia (0x37ec), B_BloodAstronomia (0x390f), B_Blood_Garlic (0xcdf1), B_Blood_Planet (0x609a),
// B_Blood_Pentagram (0x66dd), B_Blood_Laurel (0x13134), B_Blood_Lancet (0x16764) ---------------------------------------------
// Ogni volta che Garlic/Vortex, Song/Mannaggia, Pentagram/Sire, Laurel o Lancet sparano, l'arma lancia la sua versione di sangue
// con i dati dell'arma di partenza (overrideWeaponData). Esplosioni: MoonExplosion rossa (pool 0x7cb4).
enum { ASTRO_GARLIC, ASTRO_SONG, ASTRO_PENTAGRAM, ASTRO_LANCET, ASTRO_LAUREL };
#define ASTRO_DEPTH (0.5f * -game_height)
static float astro_amount(Weapon *src) { return fminf(10, Core.Player->amount) + src->amount; }
static void astro_despawnCb(void *ctx) { Bullet_DeSpawn(ctx); }
static void astro_stop(TweenRef *t) { tween_stop(*t), *t = TWEEN_NONE; }
static void astro_explosion(Bullet *b, float x, float y, int maxSim) {  // PentagramSFX + moonExplosionPool.SpawnAt(x, y, 0, 10)
    Sound_PlaySound("PentagramSFX", 0.4f, 1.5f, 0, 0xc8, maxSim);
    MoonExplosionPool_SpawnAt(b->weapon->moonExplosionPool, x, y, 0, 0xa);
}
static void astro_FadeOutTo0(Bullet *b, float ms) {  // alphaTween: alpha 0 -> DeSpawn
    astro_stop(&b->alphaTween);
    b->alphaTween = tweens_add((TweenConfig){ .props = { { &b->s.alpha, NULL, 0 } }, .nprops = 1, .duration = ms, .onComplete = astro_despawnCb, .ctx = b });
}
static void astro_expire(Bullet *b, float ms, Callback cb) {
    time_removeEvent(b->ExpireTimer);
    b->ExpireTimer = time_addEvent(ms, 0, 0, cb, b);
}
// B_BloodAstronomia: cerchio invisibile grande quanto il Magnete, vive un intervallo
static void B_BloodAstro_expire(void *ctx) { Bullet *b = ctx; time_removeEvent(b->ExpireTimer); Bullet_DeSpawn(b); }
static void B_BloodAstro_ctor(Bullet *b) { b->radius = 1; b->s.x = Core.Magnet->s.x, b->s.y = Core.Magnet->s.y; }
static void B_BloodAstro_OnRecycle(Bullet *b) {
    Bullet_OnRecycle(b);
    b->radius = Core.Magnet->radius;
    body_setCircle(&b->s.body, b->radius, -b->radius, -b->radius);
    b->s.visible = 0;
    astro_expire(b, Weapon_PInterval(b->weapon), B_BloodAstro_expire);
}
static void B_BloodAstro_Update(Bullet *b, float delta) { (void)delta; b->s.x = Core.Magnet->s.x, b->s.y = Core.Magnet->s.y; }
static const BulletVT B_BloodAstronomia = { "vfx", "WhiteDot.png", B_BloodAstro_ctor, NULL, B_BloodAstro_OnRecycle, NULL, B_BloodAstro_Update, NULL };
// B_Blood_Garlic
static void B_BloodGarlic_FadeOut(void *ctx) { Bullet *b = ctx; time_removeEvent(b->ExpireTimer); astro_FadeOutTo0(b, 0x1f4); }
static void B_BloodGarlic_ctor(Bullet *b) { b->radius = 1; }
static void B_BloodGarlic_OnRecycle(Bullet *b) { Bullet_OnRecycle(b); b->s.visible = 0, b->s.alpha = 0.1f; }
static void B_BloodGarlic_override(Bullet *b, Weapon *src) {
    body_setCircle(&b->s.body, 0x10, b->s.body.offset.x, b->s.body.offset.y);
    b->s.visible = 1;
    sprite_setScale(&b->s, fmaxf(Core.Magnet->radius / 0x20, Weapon_PArea(src)));
    astro_expire(b, Weapon_PDuration(src), B_BloodGarlic_FadeOut);
    astro_stop(&b->alphaTween);
    b->s.alpha = 0.1f;  // onStart; semplificazione: loopDelay 100 ms non tradotto (come Garlic)
    b->alphaTween = tweens_add((TweenConfig){ .props = { { &b->s.alpha, NULL, 0.3f } }, .nprops = 1, .loop = 1, .yoyo = 1, .duration = 0x3e8, .repeat = -1 });
    astro_stop(&b->angleTween);
    b->s.angle = 0;
    b->angleTween = tweens_add((TweenConfig){ .props = { { &b->s.angle, NULL, 0x168 } }, .nprops = 1, .loop = 1, .duration = 0x1770, .repeat = -1 });
    b->s.depth = ASTRO_DEPTH;
}
static const BulletVT B_Blood_Garlic = { "vfx", "Rings6.png", B_BloodGarlic_ctor, NULL, B_BloodGarlic_OnRecycle, NULL, NULL, NULL };
// B_Blood_Planet (Song): nove pianeti animati che girano attorno al punto di partenza
static Animation planetAnims[9];
static const float PLANET_DURATIONS[10] = { 0x95f, 0x989, 0x745, 0x3f1, 0x4c1, 0x925, 0x9a3, 0x833, 0x5d1, 0x653 },
                   PLANET_RADII[9] = { 0x10, 0x18, 0x18, 0x18, 0x20, 0x20, 0x20, 0x8, 0 };  // bodyRadii[8] e' undefined: setCircle non fa nulla
static void B_BloodPlanet_FadeOutCb(void *ctx);
static void B_BloodPlanet_ctor(Bullet *b) {
    b->radius = 1;
    if (!planetAnims[0].n)
        for (int i = 0; i < 9; i++) {
            char pre[8];
            snprintf(pre, sizeof(pre), "p0%d_", i + 1);
            make_anim(&planetAnims[i], "vfx", pre, 1, 0x10, 2, 0x10, -1);
        }
    b->radiusMulX = b->radiusMulY = 1;
}
static void B_BloodPlanet_OnRecycle(Bullet *b) { Bullet_OnRecycle(b); b->s.visible = 0; }
static void B_BloodPlanet_scaleStart(void *ctx) { Bullet *b = ctx; b->radiusMulY = 1; sprite_setScale(&b->s, 1); }
static void B_BloodPlanet_override(Bullet *b, Weapon *src) {
    int i = b->indexInWeapon % 9;
    anims_play(&b->s, &planetAnims[i], 0);
    sprite_setScale(&b->s, 1);
    body_setCircle(&b->s.body, PLANET_RADII[i], b->s.body.offset.x, b->s.body.offset.y);
    sprite_setScale(&b->s, 0);
    b->s.visible = 1;
    float d = PLANET_DURATIONS[i];
    b->radius = 0, b->radiusMulX = b->radiusMulY = 1;
    sprite_setScale(&b->s, 1);  // this.scale = 1
    astro_stop(&b->scaleTween);
    B_BloodPlanet_scaleStart(b);
    b->scaleTween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, NULL, 0.25f }, { &b->s.scaleY, NULL, 0.25f }, { &b->radiusMulY, NULL, 0.1f } }, .nprops = 3,
                                              .duration = d, .yoyo = 1, .repeat = -1, .onStart = B_BloodPlanet_scaleStart, .ctx = b });
    astro_expire(b, Weapon_PInterval(src) + Weapon_PDuration(src), B_BloodPlanet_FadeOutCb);
    b->s.alpha = 0.1f;
    tweens_add((TweenConfig){ .props = { { &b->s.alpha, NULL, 0.6f }, { &b->radius, NULL, Core.Magnet->radius } }, .nprops = 2, .duration = 0xc8 });
    b->groundX = b->s.x, b->groundY = b->s.y;
    b->myRotationAngle = 2 * PI / 9 * i;
    b->angleRotUnit = PI / (8 * Core.Magnet->radius);
    b->amount = astro_amount(src);
}
static void B_BloodPlanet_FadeOut(Bullet *b) {
    astro_stop(&b->scaleTween), astro_stop(&b->alphaTween);
    b->alphaTween = tweens_add((TweenConfig){ .props = { { &b->s.alpha, NULL, 0 }, { &b->s.scaleX, NULL, 0 }, { &b->s.scaleY, NULL, 0 } }, .nprops = 3,
                                              .duration = 0xc8, .onComplete = astro_despawnCb, .ctx = b });
}
static void B_BloodPlanet_FadeOutCb(void *ctx) { Bullet *b = ctx; time_removeEvent(b->ExpireTimer); B_BloodPlanet_FadeOut(b); }
static void B_BloodPlanet_explode(Bullet *b) {
    astro_explosion(b, b->s.x, b->s.y, 3);
    if (--b->amount <= 0) b->s.body.enable = 0, B_BloodPlanet_FadeOut(b);
}
static void B_BloodPlanet_DeSpawn(Bullet *b) {
    astro_stop(&b->scaleTween), astro_stop(&b->alphaTween);
    base_DeSpawn(b);
    b->s.visible = 0;
    time_removeEvent(b->ExpireTimer);
}
static void B_BloodPlanet_Update(Bullet *b, float delta) {
    b->myRotationAngle += b->angleRotUnit * delta;
    b->s.x = b->groundX + cosf(b->myRotationAngle) * (b->radiusMulX * b->radius);
    b->s.y = b->groundY + sinf(b->myRotationAngle) * (b->radiusMulY * b->radius);
}
static const BulletVT B_Blood_Planet = { "vfx", "p01_01.png", B_BloodPlanet_ctor, NULL, B_BloodPlanet_OnRecycle, NULL, B_BloodPlanet_Update, B_BloodPlanet_DeSpawn };
// B_Blood_Pentagram / B_Blood_Laurel / B_Blood_Lancet: stessa uscita (alpha a 0 in 500 ms) e stesso DeSpawn
static void B_BloodRing_DeSpawn(Bullet *b) {
    base_DeSpawn(b);
    b->s.visible = 0;
    time_removeEvent(b->ExpireTimer);
    astro_stop(&b->alphaTween);
}
static void B_BloodPentagram_FadeOut(void *ctx) { Bullet *b = ctx; time_removeEvent(b->ExpireTimer); astro_FadeOutTo0(b, 0x1f4); }
static void B_BloodPentagram_ctor(Bullet *b) { b->s.visible = 0; }
static void B_BloodPentagram_override(Bullet *b, Weapon *src) {
    b->s.body.enable = 1, b->s.visible = 1;
    body_setCircle(&b->s.body, 0x10, b->s.body.offset.x, b->s.body.offset.y);
    b->isCullable = 0, b->s.alpha = 1;
    b->amount = astro_amount(src);
    astro_expire(b, Weapon_PInterval(src) + Weapon_PDuration(src), B_BloodPentagram_FadeOut);
    b->s.depth = ASTRO_DEPTH;
}
static void B_BloodPentagram_explode(Bullet *b) {
    astro_explosion(b, b->s.x, b->s.y, 6);
    if (--b->amount <= 0) b->s.body.enable = 0, astro_FadeOutTo0(b, 0x1f4);
}
static const BulletVT B_Blood_Pentagram = { "vfx", "Rings5.png", B_BloodPentagram_ctor, NULL, Bullet_OnRecycle, NULL, NULL, B_BloodRing_DeSpawn };
static void B_BloodLaurel_FadeOut(Bullet *b) { astro_stop(&b->scaleTween), astro_stop(&b->imageTween); astro_FadeOutTo0(b, 0x1f4); }
static void B_BloodLaurel_FadeOutCb(void *ctx) { Bullet *b = ctx; time_removeEvent(b->ExpireTimer); B_BloodLaurel_FadeOut(b); }
static void B_BloodLaurel_ctor(Bullet *b) { b->s.visible = 0, b->s.tint = 0xff0000; }
static void B_BloodLaurel_override(Bullet *b, Weapon *src) {
    b->s.body.enable = 1, b->s.visible = 1;
    body_setCircle(&b->s.body, 0x40, b->s.body.offset.x, b->s.body.offset.y);
    b->isCullable = 0, b->s.alpha = 0.2f;
    b->amount = astro_amount(src), b->amount *= b->amount;
    sprite_setScale(&b->s, 0);
    astro_expire(b, Weapon_PInterval(src) + Weapon_PDuration(src), B_BloodLaurel_FadeOutCb);
    astro_stop(&b->imageTween);
    b->imageTween = tweens_add((TweenConfig){ .props = { { &b->s.alpha, NULL, 0.5f } }, .nprops = 1, .loop = 1, .yoyo = 1, .duration = 0x3e8, .repeat = -1 });
    astro_stop(&b->scaleTween);
    b->scaleTween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, fmaxf(1, Core.Magnet->radius / 0x40) } }, .nprops = 1, .duration = 0x12c });
    b->s.depth = ASTRO_DEPTH;
}
static void B_BloodLaurel_explode(Bullet *b, float x, float y) {
    astro_explosion(b, x, y, 3);
    if (--b->amount <= 0) b->s.body.enable = 0, B_BloodLaurel_FadeOut(b);
}
static const BulletVT B_Blood_Laurel = { "vfx", "bloodMin.png", B_BloodLaurel_ctor, NULL, Bullet_OnRecycle, NULL, NULL, B_BloodRing_DeSpawn };
// B_Blood_Lancet: un orologio di 12 numeri che rallenta i nemici
static void B_BloodLancet_FadeOut(Bullet *b) {
    astro_stop(&b->scaleTween), astro_stop(&b->imageTween), astro_stop(&b->alphaTween);
    static TweenProp props[12];
    for (int i = 0; i < 12; i++) props[i] = (TweenProp){ .t = &b->numbers[i].alpha, .end = 0 };
    b->alphaTween = tweens_add((TweenConfig){ .many = props, .nmany = 12, .duration = 0x1f4, .onComplete = astro_despawnCb, .ctx = b });
    astro_stop(&b->radiusTween);
    // semplificazione: il secondo tween (radius -> 0, onComplete DeSpawn) non tradotto: radius non e' usato e DeSpawn partirebbe due volte
}
static void B_BloodLancet_FadeOutCb(void *ctx) { Bullet *b = ctx; time_removeEvent(b->ExpireTimer); B_BloodLancet_FadeOut(b); }
static void B_BloodLancet_ctor(Bullet *b) {
    b->s.visible = 0, b->s.tint = 0xff0000;
    b->numbers = calloc(12, sizeof(Sprite)), b->radii = calloc(12, sizeof(float));
    for (int i = 0; i < 12; i++) {
        char f[8];
        snprintf(f, sizeof(f), "%02d.png", i + 1);
        sprite_init(&b->numbers[i], frame_get("items", f), b->s.x, b->s.y);
        b->numbers[i].tint = 0xff0000, b->numbers[i].alpha = 0, b->numbers[i].depth = ASTRO_DEPTH;
        children_add(&b->numbers[i]);
    }
}
static void B_BloodLancet_override(Bullet *b, Weapon *src) {
    b->s.body.enable = 1, b->s.visible = 1;
    body_setCircle(&b->s.body, 0x40, b->s.body.offset.x, b->s.body.offset.y);
    b->isCullable = 0, b->s.alpha = 0.5f;
    b->amount = astro_amount(src), b->amount *= b->amount;
    sprite_setScale(&b->s, 0);
    b->slowPower = src->amount;
    astro_expire(b, Weapon_PDuration(src), B_BloodLancet_FadeOutCb);
    astro_stop(&b->imageTween);
    b->s.angle = 0;  // onStart
    for (int i = 0; i < 12; i++) b->numbers[i].alpha = 0.5f;
    // stagger(20, { start: 1000 }): un tween per numero; il riferimento tiene l'ultimo (semplificazione: gli altri si fermano col loro sprite nascosto)
    for (int i = 0; i < 12; i++)
        b->imageTween = tweens_add((TweenConfig){ .props = { { &b->numbers[i].alpha, NULL, 0.8f } }, .nprops = 1, .loop = 1, .yoyo = 1, .duration = 0x3e8 + 0x14 * i, .repeat = -1 });
    astro_stop(&b->angleTween);
    b->angleTween = tweens_add((TweenConfig){ .props = { { &b->s.angle, NULL, 0x168 } }, .nprops = 1, .loop = 1, .duration = 0xfa0, .repeat = -1 });
    float sc = fmaxf(1, Core.Magnet->radius / 0x40);
    astro_stop(&b->scaleTween);
    b->scaleTween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, sc } }, .nprops = 1, .duration = 0x12c });
    astro_stop(&b->radiusTween);
    for (int i = 0; i < 12; i++) b->radii[i] = 0xa;
    for (int i = 0; i < 12; i++)
        b->radiusTween = tweens_add((TweenConfig){ .props = { { &b->radii[i], NULL, Core.Magnet->radius - 0xc } }, .nprops = 1, .duration = 0x3e8 * sc + 0x32 * i,
                                                   .ease = Ease_SineInOut, .yoyo = 1, .repeat = -1 });
    b->s.depth = ASTRO_DEPTH;
}
// explode (amount--): nessuno lo chiama, onLancetOverlapsEnemy non esplode; l'orologio dura PDuration
static void B_BloodLancet_Update(Bullet *b, float delta) {
    (void)delta;
    float u = 2 * PI / 12, a = b->s.angle * (PI / 180);
    for (int i = 0; i < 12; i++) b->numbers[i].x = b->s.x + cosf(u * i + a) * b->radii[i], b->numbers[i].y = b->s.y + sinf(u * i + a) * b->radii[i];
}
static void B_BloodLancet_OnHasHitAnObject(Bullet *b, void *o, int isDead) {
    if (isDead || !(((Sprite *)o)->groups & Core.Enemies.bit)) return;
    Enemy *e = ((Sprite *)o)->owner;
    if (e->res_Debuffs >= 1) return;
    if (e->slow > 0.2f) e->slow -= 0.01f * b->slowPower;
}
static const BulletVT B_Blood_Lancet = { "vfx", "outer0.png", B_BloodLancet_ctor, NULL, Bullet_OnRecycle, B_BloodLancet_OnHasHitAnObject, B_BloodLancet_Update, B_BloodRing_DeSpawn };
// W_BloodAstronomia
static float W_Astro_PPower(Weapon *w) { return w->power * Core.Player->amount; }
static float W_Astro_PArea(Weapon *w) { (void)w; return Core.Magnet->radius; }
static void W_Astro_ctor(Weapon *w) {
    sprite_init(&w->image, frame_get("vfx", "Rings3.png"), Core.Magnet->s.x, Core.Magnet->s.y);
    w->image.blendAdd = 1, w->image.alpha = 0.6f, w->image.tint = 0xff0000;
    sprite_setScale(&w->image, Core.Magnet->radius / 0x10);
    children_add(&w->image);
    tweens_add((TweenConfig){ .props = { { &w->image.alpha, NULL, 0.3f } }, .nprops = 1, .loop = 1, .yoyo = 1, .duration = 0x3e8, .repeat = -1 });
    tweens_add((TweenConfig){ .props = { { &w->image.angle, NULL, -0x168 } }, .nprops = 1, .loop = 1, .duration = 0x1770, .repeat = -1 });
}
static void W_Astro_Fire(Weapon *w) { sprite_setScale(&w->image, Weapon_PArea(w) / 0x10); base_Fire(w); }
static void W_Astro_Update(Weapon *w, float delta) { base_Update(w, delta); w->image.x = Core.Magnet->s.x, w->image.y = Core.Magnet->s.y; }
static void W_Astro_hit(Weapon *w, Enemy *e, float p, float kb) { Enemy_GetDamaged(e, p, (int)w->hitVFX, kb, w->bulletType); w->stats_inflictedDamage += p; }
static void W_Astro_onGarlic(void *ctx, Sprite *bs, Sprite *es) {
    Weapon *w = ctx; Enemy *e = es->owner;
    if (!e->isDead && !Bullet_HasAlreadyHitObject(bs->owner, e, e->isDead)) W_Astro_hit(w, e, Weapon_PPower(w->astroSrc[ASTRO_GARLIC]), w->knockback);
}
static void W_Astro_onSong(void *ctx, Sprite *bs, Sprite *es) {
    Weapon *w = ctx; Enemy *e = es->owner;
    if (e->isDead) return;
    if (!Bullet_HasAlreadyHitObject(bs->owner, e, e->isDead)) W_Astro_hit(w, e, Weapon_PPower(w->astroSrc[ASTRO_SONG]), w->knockback);
    B_BloodPlanet_explode(bs->owner);  // explode(x, y): i pianeti ignorano gli argomenti
}
static void W_Astro_onPentagram(void *ctx, Sprite *bs, Sprite *es) {
    Weapon *w = ctx; Enemy *e = es->owner;
    if (e->isDead || Bullet_HasAlreadyHitObject(bs->owner, e, e->isDead)) return;
    if (!e->res_Rosary) W_Astro_hit(w, e, fmaxf(0x42, e->maxHp - e->hp), 0);
    B_BloodPentagram_explode(bs->owner);
}
static void W_Astro_onLaurel(void *ctx, Sprite *bs, Sprite *es) {  // niente HasAlreadyHitObject: colpisce a ogni passo finche' ha cariche
    Weapon *w = ctx; Enemy *e = es->owner;
    if (e->isDead) return;
    Weapon *l = w->astroSrc[ASTRO_LAUREL];
    W_Astro_hit(w, e, Weapon_PPower(l) * (fminf(10, Core.Player->amount) + l->amount), 0xa);
    B_BloodLaurel_explode(bs->owner, e->s.x, e->s.y);
}
static void W_Astro_onLancet(void *ctx, Sprite *bs, Sprite *es) {
    Weapon *w = ctx; Enemy *e = es->owner;
    if (!e->isDead && !Bullet_HasAlreadyHitObject(bs->owner, e, e->isDead)) W_Astro_hit(w, e, Weapon_PPower(w->astroSrc[ASTRO_LANCET]) + 0.5f, w->knockback);
}
static void W_Astro_OnStart(Weapon *w) {
    static const BulletVT *const vts[5] = { &B_Blood_Garlic, &B_Blood_Planet, &B_Blood_Pentagram, &B_Blood_Lancet, &B_Blood_Laurel };
    static void (*const cbs[5])(void *, Sprite *, Sprite *) = { W_Astro_onGarlic, W_Astro_onSong, W_Astro_onPentagram, W_Astro_onLancet, W_Astro_onLaurel };
    Weapon_ResetFiringTimer(w);
    for (int i = 0; i < 5; i++) w->bloodPools[i] = BulletPool_new(w, vts[i]);
    w->moonExplosionPool = calloc(1, sizeof(MoonExplosionPool)), w->moonExplosionPool->blood = 1;
    physics_addOverlap(&w->pool->group, &Core.Enemies, Weapon_onBulletOverlapsEnemy, w);
    physics_addOverlap(&w->pool->group, &Core.Destructibles, Weapon_onBulletOverlapsDestuctible, w);
    for (int i = 0; i < 5; i++) physics_addOverlap(&w->bloodPools[i]->group, &Core.Enemies, cbs[i], w);
}
static const WeaponVT W_BloodAstronomia = { BASE, .PPower = W_Astro_PPower, .PAmount = one_PAmount, .PArea = W_Astro_PArea, .bullet = &B_BloodAstronomia,
                                            .ctor = W_Astro_ctor, .Fire = W_Astro_Fire, .Update = W_Astro_Update, .OnStart = W_Astro_OnStart };
static Bullet *astro_spawn(Weapon *w, int k, float x, float y, int i) {
    Bullet *b = BulletPool_SpawnAt(w->bloodPools[k], x, y, w, i);
    if (!b) return NULL;
    switch (k) {  // overrideWeaponData
    case ASTRO_GARLIC: B_BloodGarlic_override(b, w->astroSrc[k]); break;
    case ASTRO_SONG: B_BloodPlanet_override(b, w->astroSrc[k]); break;
    case ASTRO_PENTAGRAM: B_BloodPentagram_override(b, w->astroSrc[k]); break;
    case ASTRO_LANCET: B_BloodLancet_override(b, w->astroSrc[k]); break;
    case ASTRO_LAUREL: B_BloodLaurel_override(b, w->astroSrc[k]); break;
    }
    return b;
}
static void W_Astro_FirePentagramLater(void *ctx) {
    Weapon *w = ctx;
    int n = (int)(fminf(10, Core.Player->amount) + 3 * w->astroSrc[ASTRO_PENTAGRAM]->amount);
    float u = 2 * PI / n, r = fminf(0.45f * game_height, 0.75f * Core.Magnet->radius), x = Core.Player->s.x, y = Core.Player->s.y;
    for (int i = 0; i < n; i++) astro_spawn(w, ASTRO_PENTAGRAM, x + cosf(u * i) * r, y + sinf(u * i) * r, i);
}
static void Arcanas_TriggerAstronomia(Weapon *src) {
    Weapon *w = Arcanas.BloodAstronomiaWeapon;
    const char *t = src->bulletType;
    float x = Core.Player->s.x, y = Core.Player->s.y;
    if (!strcmp(t, "VORTEX") || !strcmp(t, "GARLIC")) {  // FireGarlic
        w->astroSrc[ASTRO_GARLIC] = src;
        int n = (int)astro_amount(src);
        float r = 8 * fmaxf(Core.Magnet->radius / 0x20, Weapon_PArea(src)), u = 2 * PI / n;
        for (int i = 0; i < n; i++) astro_spawn(w, ASTRO_GARLIC, x + cosf(u * i) * r, y + sinf(u * i) * r, i);
    } else if (!strcmp(t, "MANNAGGIA") || !strcmp(t, "SONG")) {  // FireSong
        w->astroSrc[ASTRO_SONG] = src;
        int n = (int)(fminf(10, Core.Player->amount) + 3 * src->amount);
        for (int i = 0; i < n; i++) astro_spawn(w, ASTRO_SONG, x, y, i);
    } else if (!strcmp(t, "SIRE") || !strcmp(t, "PENTAGRAM")) {  // FirePentagram: dopo 200 ms
        w->astroSrc[ASTRO_PENTAGRAM] = src;
        time_addEvent(0xc8, 0, 0, W_Astro_FirePentagramLater, w);
    } else if (!strcmp(t, "LAUREL")) {  // FireLaurel
        w->astroSrc[ASTRO_LAUREL] = src;
        astro_spawn(w, ASTRO_LAUREL, Core.Magnet->s.x, Core.Magnet->s.y, 0);
    } else if (!strcmp(t, "LANCET")) {  // FireLancet
        w->astroSrc[ASTRO_LANCET] = src;
        astro_spawn(w, ASTRO_LANCET, Core.Magnet->s.x, Core.Magnet->s.y, 0);
    }
}
// --- Game Killer: W_GemCannon (0x184c1), B_GemCannon (0x12103), B_Window (0x620b) -----------------------------------------
// Ogni gemma raccolta parte verso un nemico a caso; dove colpisce si apre una "finestra" verticale che ferisce tutto cio' che tocca.
static void B_GemCannon_ctor(Bullet *b) {
    b->Pfx = particles_add();
    b->PfxEmitter = particles_createEmitter(b->Pfx, (EmitterConfig){ .frames = { frame_get("vfx", "PfxColor1.png"), frame_get("vfx", "PfxColor2.png") }, .nframes = 2,
        .speed = ERND(0xf, 0x1e), .quantity = 1, .lifespan = EOP(0x12c), .alpha = ERANGE(1, 0), .on = 0 });
}
static void B_GemCannon_OnHasHitAnObject(Bullet *b, void *o, int isDead) { (void)o; if (!isDead && --b->penetrating <= 0) Bullet_DeSpawn(b); }
static void B_GemCannon_OnRecycle(Bullet *b) {
    Bullet_OnRecycle(b);
    body_setCircle(&b->s.body, 8, b->s.body.offset.x, b->s.body.offset.y);
    sprite_setScale(&b->s, 1);
    b->s.x += (frand() - 0.5f) * b->indexInWeapon * 0xa;
    b->s.y += (frand() - 0.5f) * b->indexInWeapon * 0xa;
    Bullet_AimForRandomEnemy(b);
    b->s.angle -= 0x5a;
    Sound_PlaySound("MagicMissile", b->weapon->volume ? b->weapon->volume : 0.15f, 1, -0x64 * b->indexInWeapon, 0xc8, 0xc);
    if (b->weapon->gemFrame) sprite_setFrame(&b->s, b->weapon->gemFrame);
}
static void B_GemCannon_Update(Bullet *b, float delta) { (void)delta; emitter_emitParticleAt(b->PfxEmitter, b->s.x, b->s.y, 0); }
static const BulletVT B_GemCannon = { "items", "GemBlue.png", B_GemCannon_ctor, NULL, B_GemCannon_OnRecycle, B_GemCannon_OnHasHitAnObject, B_GemCannon_Update, NULL };
static Animation windowStrike;
static void B_Window_ctor(Bullet *b) {
    static const unsigned TINTS[6] = { 0xefe70d, 0xefc3ca, 0xe57714, 0xafcb09, 0x9fc4e0, 0x9e58fd };
    b->s.scaleX = 0x60, b->s.scaleY = 0;
    if (!windowStrike.n) make_anim(&windowStrike, "vfx", "window_", 0, 0x1d, 0, 0x18, 0);
    sprite_init(&b->windowVfx, frame_get("vfx", "window_0.png"), b->s.x, b->s.y);
    b->windowVfx.visible = 0, b->windowVfx.depth = 0x2329;
    children_add(&b->windowVfx);
    sprite_init(&b->exploSprite, frame_get("vfx", "s_pfx_rainbow_64.png"), b->s.x, b->s.y);
    b->exploSprite.visible = 0, b->exploSprite.blendAdd = 1;
    children_add(&b->exploSprite);
    b->Pfx = particles_add();
    EmitterConfig c = { .frames = { frame_get("vfx", "PfxLine2.png") }, .nframes = 1, .lifespan = EOP(0x1f4), .rotate = EOP(0), .angle = { 0, 0x168, 1 },
                        .angleSteps = 0x10, .speed = ERND(0x50, 0x64), .scale = ERANGE(4, 0), .scaleY = ERANGE(4, 0xc), .hasScaleY = 1,
                        .alpha = ERANGE(0.75f, 0), .quantity = 1, .frequency = 1, .ntints = 6, .on = 0 };
    for (int i = 0; i < 6; i++) c.tints[i] = TINTS[i];
    b->PfxEmitter = particles_createEmitter(b->Pfx, c);
    c.speed = ERND(0xa0, 0xc8), c.scale = ERANGE(4, 6), c.blendAdd = 1;
    b->PfxEmitter2 = particles_createEmitter(b->Pfx, c);
    b->Pfx->hasWell = 1;  // createGravityWell({ power: 1, epsilon: 50, gravity: 20 })
    b->Pfx->wellPower = 1 * 0x14, b->Pfx->wellEpsilon = 0x32 * 0x32;
    b->Pfx->s.depth = 0x2328;
}
static void B_Window_done(void *ctx) { Bullet *b = ctx; emitter_stop(b->PfxEmitter), emitter_stop(b->PfxEmitter2); Bullet_DeSpawn(b); }
static void B_Window_exploHide(void *ctx) { ((Bullet *)ctx)->exploSprite.visible = 0; }
static void B_Window_OnRecycle(Bullet *b) {
    Bullet_OnRecycle(b);
    b->windowVfx.visible = 0;
    float a = Weapon_PArea(b->weapon), d = 0x3e8 * (frand() - 0.5f);
    b->s.scaleX = 0x60 * a, b->s.scaleY = 0, b->s.alpha = 0;
    for (int i = 0; i < 3; i++) Sound_PlaySound("Window", 0.5f, 1, d - 0x190 * i, 0x96, 6);
    b->windowVfx.x = b->s.x, b->windowVfx.y = b->s.y, b->windowVfx.visible = 1;
    anims_play(&b->windowVfx, &windowStrike, 0);
    b->Pfx->wellX = b->s.x, b->Pfx->wellY = b->s.y - 0x14;
    b->PfxEmitter->x = b->PfxEmitter2->x = b->s.x, b->PfxEmitter->y = b->PfxEmitter2->y = b->s.y;
    b->PfxEmitter->c.scaleY = b->PfxEmitter2->c.scaleY = ERANGE(4, 0xc * a);
    emitter_start(b->PfxEmitter), emitter_start(b->PfxEmitter2);
    tween_stop(b->scaleTween);
    b->scaleTween = tweens_add((TweenConfig){ .props = { { &b->s.scaleY, NULL, 0.5f * game_height * a } }, .nprops = 1, .duration = 0x78, .onComplete = B_Window_done, .ctx = b });
    b->exploSprite.x = b->s.x, b->exploSprite.y = b->s.y;  // FlashingVFXEnabled
    sprite_setScale(&b->exploSprite, 0), b->exploSprite.visible = 1, b->exploSprite.depth = 0x2328;
    tween_stop(b->exploTween);
    b->exploTween = tweens_add((TweenConfig){ .props = { { &b->exploSprite.scaleX, NULL, 0x60 * a / 0x40 }, { &b->exploSprite.scaleY, NULL, 0.5f * game_height * a / 0x40 } },
                                              .nprops = 2, .duration = 0xfa, .onComplete = B_Window_exploHide, .ctx = b });
    tween_stop(b->tween2);
    sprite_setScale(&b->windowVfx, 1);  // onStart
    b->tween2 = tweens_add((TweenConfig){ .props = { { &b->windowVfx.scaleX, &b->windowVfx.scaleY, 1.5f } }, .nprops = 1, .duration = 0x12c });
}
static const BulletVT B_Window = { "vfx", "blackDot.png", B_Window_ctor, NULL, B_Window_OnRecycle, NULL, NULL, NULL };
static float W_GemCannon_PPower(Weapon *w) { return w->gemValue; }
static void W_GemCannon_ctor(Weapon *w) { w->gemValue = 1, w->gemFrame = frame_get("items", "GemBlue.png"); }
static void W_GemCannon_onBulletOverlapsEnemy(Weapon *w, Bullet *b, Enemy *e) {
    if (e->isDead || Bullet_HasAlreadyHitObject(b, e, e->isDead)) return;
    Enemy_GetDamaged(e, Weapon_PPower(w), (int)w->hitVFX, w->knockback, w->bulletType);
    w->stats_inflictedDamage += Weapon_PPower(w);
    BulletPool_SpawnAt(w->secondaryPool, e->s.x, e->s.y, w, 0);
}
static void W_GemCannon_onExplosionOverlapsEnemy(void *ctx, Sprite *bs, Sprite *es) {
    Weapon *w = ctx; Enemy *e = es->owner;
    if (e->isDead || Bullet_HasAlreadyHitObject(bs->owner, e, e->isDead)) return;
    Enemy_GetDamaged(e, Weapon_PPower(w), (int)w->hitVFX, w->knockback, w->bulletType);
    w->stats_inflictedDamage += Weapon_PPower(w);
}
static void W_GemCannon_OnStart(Weapon *w) {
    base_OnStart(w);
    w->secondaryPool = BulletPool_new(w, &B_Window);
    physics_addOverlap(&w->secondaryPool->group, &Core.Enemies, W_GemCannon_onExplosionOverlapsEnemy, w);
    physics_addOverlap(&w->secondaryPool->group, &Core.Destructibles, Weapon_onBulletOverlapsDestuctible, w);
}
static const WeaponVT W_GemCannon = { BASE, .PPower = W_GemCannon_PPower, .PAmount = one_PAmount, .bullet = &B_GemCannon, .ctor = W_GemCannon_ctor,
                                      .ResetFiringTimer = noop_ResetFiringTimer, .onBulletOverlapsEnemy = W_GemCannon_onBulletOverlapsEnemy, .OnStart = W_GemCannon_OnStart };
// W_Window (0xbc47): l'arma delle vetrate della Cappella, un colpo alla volta e mai da sola
static const WeaponVT W_WindowW = { BASE, .PAmount = one_PAmount, .bullet = &B_Window, .ResetFiringTimer = noop_ResetFiringTimer };
static void Arcanas_TriggerGemCannon(float value, const Frame *frame) {
    Weapon *w = Arcanas.GemCannonWeapon;
    w->gemValue = value, w->gemFrame = frame;
    Weapon_Fire(w);
}
static void Arcanas_TriggerFire(float x, float y) { Weapon *w = Arcanas.FireExplosionWeapon; BulletPool_SpawnAt(w->pool, x, y, w, 0); }
static void Arcanas_TriggerCold(float x, float y) { Weapon *w = Arcanas.ColdExplosionWeapon; BulletPool_SpawnAt(w->pool, x, y, w, 0); }

// B_Gatti: il gatto
static void B_Gatti_ctor(Bullet *b) {
    b->defaultSpeed = b->_speed;
    sprite_init(&b->summon, frame_get("vfx", "summon.png"), 0, 0);
    b->summon.visible = 0;
    children_add(&b->summon);
    b->summonTween = b->entryTween = b->onExpireAlphaTween = TWEEN_NONE;
    b->chooseTimer = b->ExpireTimer = (Timer){ -1, 0 };
    // PfxEmitter (PfxHoly): creato ma mai emesso dall'originale, non tradotto
}
static void B_Gatti_TargetPlayer(Bullet *b) {
    float dx = Core.Player->s.x - b->s.x, dy = Core.Player->s.y - b->s.y, l = sqrtf(dx * dx + dy * dy);
    if (l > 0) dx /= l, dy /= l;
    b->aimVec = (Vector2){ Bullet_TrueSpeed(b) * dx, Bullet_TrueSpeed(b) * dy };
}
static void B_Gatti_ChooseTarget(void *ctx) {
    Bullet *b = ctx;
    Weapon *w = b->weapon;
    Vector2 t;
    Sprite *best = NULL;
    float bd = 1e30f;
    for (int i = 0; i < Core.PickupGroup.n; i++) {  // filter(ROAST || NFT) + physics.closest(this, ...)
        Pickup *p = Core.PickupGroup.items[i]->owner;
        if (strcmp(p->itemType, "ROAST") && strcmp(p->itemType, "NFT")) continue;
        float dx = b->s.x - p->s.body.center.x, dy = b->s.y - p->s.body.center.y, d = dx * dx + dy * dy;
        if (d < bd) bd = d, best = &p->s;
    }
    if (!best) {
        float r = w->critChancesArray[w->critIndex++ % 1000];
        if (r < 0.2f) { B_Gatti_TargetPlayer(b); return; }
        float px = Core.Player->s.x, py = Core.Player->s.y;
        t = r < 0.25f ? (Vector2){ px + 0xc8, py } : r < 0.5f ? (Vector2){ px - 0xc8, py } : r < 0.75f ? (Vector2){ px, py + 0xc8 } : (Vector2){ px, py - 0xc8 };
    } else {
        t = (Vector2){ best->x, best->y };
    }
    float dx = b->s.x - t.x, dy = b->s.y - t.y, l = sqrtf(dx * dx + dy * dy);  // (sic) this - bersaglio: il gatto se ne allontana
    if (l > 0) dx /= l, dy /= l;
    b->aimVec = (Vector2){ Bullet_TrueSpeed(b) * dx, Bullet_TrueSpeed(b) * dy };
}
static void B_Gatti_despawn(void *ctx) { Bullet_DeSpawn(ctx); }
static void B_Gatti_onExpire(void *ctx) {
    Bullet *b = ctx;
    b->onExpireAlphaTween = tweens_add((TweenConfig){ .props = { { &b->s.alpha, NULL, 0 } }, .nprops = 1, .duration = 0x12c, .onComplete = B_Gatti_despawn, .ctx = b });
}
static void B_Gatti_OnRecycle(Bullet *b) {
    static const char *const catBaseFrames[3] = { "cat_i0", "cat3_i0", "cat2_i0" };
    Weapon *w = b->weapon;
    Bullet_OnRecycle(b);
    if (!b->isInitialised) {
        const char *const *cf = w->catBaseFrames ? w->catBaseFrames : catBaseFrames;  // trueWeapon.catBaseFrames
        int nc = w->catBaseFrames ? w->nCatBaseFrames : 3;
        make_anim(&b->idleAnim, "vfx", cf[(int)floorf(frand() * nc)], 1, 4, 0, 8, -1);  // RND.pick
        anims_play(&b->s, &b->idleAnim, 0);
        b->isInitialised = 1;
    }
    tween_stop(b->summonTween), tween_stop(b->entryTween), tween_stop(b->onExpireAlphaTween);
    b->s.visible = 1;
    b->isCullable = 0;
    b->idleAnim.frameRate = 0xc * Weapon_PSpeed(w), b->idleAnim.msPerFrame = 1000 / b->idleAnim.frameRate;  // play({ key, frameRate })
    anims_play(&b->s, &b->idleAnim, 0);
    sprite_setScale(&b->s, 1);
    body_setCircle(&b->s.body, 8, b->s.body.offset.x, b->s.body.offset.y);
    sprite_setScale(&b->s, Weapon_PArea(w));
    b->s.alpha = 1;
    sprite_setScale(&b->summon, 0);
    b->summon.visible = 1, b->summon.alpha = 1;
    b->s.tint = 0xffffff;
    b->_speed = b->defaultSpeed;
    b->summonTween = tweens_add((TweenConfig){ .props = { { &b->summon.scaleX, &b->summon.scaleY, Weapon_PArea(w) }, { &b->summon.alpha, NULL, 0 } }, .nprops = 2, .duration = 0x3e8 });
    sprite_setScale(&b->s, 0);  // entryTween onStart: scaleX = scaleY = 0
    b->entryTween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, Weapon_PArea(w) } }, .nprops = 1, .duration = 0x12c });
    float a = 2 * PI * frand();
    b->s.x += cosf(a) * game_width * 0.45f, b->s.y += sinf(a) * game_height * 0.45f;
    b->summon.x = b->s.x, b->summon.y = b->s.y + 0x18;
    b->save_vel_x = b->save_vel_y = 1;
    B_Gatti_TargetPlayer(b);
    time_removeEvent(b->chooseTimer);  // l'originale lo ferma solo qui: dopo il DeSpawn continua a girare
    b->chooseTimer = time_addEvent(0x5dc / Weapon_PSpeed(w), 0, -1, B_Gatti_ChooseTarget, b);
    time_removeEvent(b->ExpireTimer);
    b->ExpireTimer = time_addEvent(Weapon_PDuration(w), 0, 0, B_Gatti_onExpire, b);
    Sound_PlaySound("MagicMissile", 0.2f, 1, 0x3e8, 0xc8, 0xc);
}
static void B_Gatti_OnHasHitWall(Bullet *b, Tile *t) {
    b->save_vel_x *= t && (t->faceRight || t->faceLeft) ? -1 : 1;
    b->save_vel_y *= t && (t->faceTop || t->faceBottom) ? -1 : 1;
}
static void B_Gatti_Update(Bullet *b, float delta) {
    (void)delta;
    sprite_setVelocity(&b->s, b->aimVec.x * b->save_vel_x, b->aimVec.y * b->save_vel_y);
    b->s.flipX = b->s.body.velocity.x < 0;
    b->summon.x = b->s.x, b->summon.y = b->s.y + 0x18;
}
static void B_Gatti_DeSpawn(Bullet *b) { b->s.visible = 0; base_DeSpawn(b); }
static const BulletVT B_Gatti = { "vfx", "Cat.png", B_Gatti_ctor, NULL, B_Gatti_OnRecycle, NULL, B_Gatti_Update, B_Gatti_DeSpawn, NULL, NULL, B_Gatti_OnHasHitWall };

// W_Gatti
static void W_Gatti_ctor(Weapon *w) {
    static const char *const cats[4] = { "CAT1", "CAT2", "CAT3", "CAT5" };
    w->full = 1, w->chickens = 0;
    for (int i = 0; i < 0x1f4; i++) w->RANDOMS[i] = i / 500.0f;
    shuffle(w->RANDOMS, 0x1f4);  // RND.shuffle
    for (int i = 0; i < 0x1f4; i++) w->PLUSMINUS[i] = (i - 0xfa) / 500.0f;
    shuffle(w->PLUSMINUS, 0x1f4);
    for (int i = 0; i < 0x78; i++) w->SFXARRAY[i] = cats[(int)floorf(frand() * 4)];
}
static int W_Gatti_tryChance(Weapon *w) { return w->chance * Player_PLuck(Core.Player) < W_Gatti_GetRandom(w); }  // PLuck; vero = il colpo NON riesce
static void W_Gatti_onCatOverlapsEnemy(void *ctx, Sprite *bs, Sprite *es) {
    Weapon *w = ctx;
    Bullet *b = bs->owner;
    Enemy *e = es->owner;
    if (e->isDead || Bullet_HasAlreadyHitObject(b, e, e->isDead)) return;
    if (W_Gatti_tryChance(w)) { Bullet_pushHit(b, e); return; }
    BulletPool_SpawnAt(w->scratchPool, b->s.x, b->s.y, w, 0);
    Sound_PlaySound(W_Gatti_GetSfx(w), 0.2f, 1, 0x190 * W_Gatti_GetPlusMinus(w), 0xc8, 2);
    Enemy_GetDamaged(e, Weapon_PPower(w), (int)w->hitVFX, w->knockback, w->bulletType);
    w->stats_inflictedDamage += Weapon_PPower(w);
}
static void W_Gatti_onCatOverlapsPlayer(void *ctx, Sprite *bs, Sprite *ps) {
    Weapon *w = ctx;
    Bullet *b = bs->owner;
    (void)ps;
    if (Core.Player->isDead || Bullet_HasAlreadyHitObject(b, Core.Player, Core.Player->isDead)) return;
    if (W_Gatti_tryChance(w)) {  // (sic) il graffio che non riesce sui nemici qui colpisce il giocatore
        BulletPool_SpawnAt(w->scratchPool, b->s.x, b->s.y, w, 0);
        Sound_PlaySound(W_Gatti_GetSfx(w), 0.2f, 1, 0, 0xc8, 2);
        w->stats_inflictedDamage += Weapon_PPower(w);
        Player_GetDamaged(Core.Player, 2 * Weapon_PPower(w));
        return;
    }
    Bullet_pushHit(b, Core.Player);
}
static void W_Gatti_OnBulletOverlapsBullet(void *ctx, Sprite *as, Sprite *bs) {
    Weapon *w = ctx;
    Bullet *a = as->owner, *b = bs->owner;
    if (Bullet_HasAlreadyHitObject(a, b, 0)) return;
    Bullet_pushHit(b, a), Bullet_pushHit(a, b);
    if (w->chance * Player_PLuck(Core.Player) > W_Gatti_GetRandom(w)) {
        Sound_PlaySound("CAT3", 0.8f, 1, 0x190 * W_Gatti_GetRandom(w), 0xc8, 2);
        Sound_PlaySound("CATE", 1, 1, 0x190 * W_Gatti_GetRandom(w), 0xc8, 2);
        BulletPool_SpawnAt(w->scufflePool, b->s.x, b->s.y, w, 0);
        Bullet_DeSpawn(a);
        Bullet_DeSpawn(b);
    }
}
static void W_Gatti_OnBulletOverlapsPickup(void *ctx, Sprite *cs, Sprite *ps) {
    Weapon *w = ctx;
    Bullet *c = cs->owner;
    Pickup *p = ps->owner;
    const char *t = p->itemType;
    if (!strcmp(t, "ROAST")) {
        Sound_PlaySound(W_Gatti_GetSfx(w), 0.2f, 2, 0x3e8, 0xc8, 2);
        Sound_PlaySound("Roast", 0.6f, 1.7f, 0x1f4, 0, 0);
        w->chickens++;
        w->chance *= 1.1f;
        w->full = 1 - fminf(0.95f, w->chickens / 108.0f);
        w->power += 0.1f * w->full;
        Pickup_DeSpawn(p);
    }
    if (!strcmp(t, "NFT")) {
        Sound_PlaySound(W_Gatti_GetSfx(w), 0.2f, 2, 1, 0xc8, 2);
        BulletPool_SpawnAt(w->secondaryPool, p->s.x, p->s.y, w, 0);
        Bullet_DeSpawn(c);
        Pickup_DeSpawn(p);
    }
    if (!strcmp(t, "CLOVER") || !strcmp(t, "GILDED")) {
        Sound_PlaySound(W_Gatti_GetSfx(w), 0.2f, 2, 0x3e8, 0xc8, 2);
        c->_speed *= 2;
        Pickup_DeSpawn(p);
    }
    if (!strcmp(t, "ROSARY") || !strcmp(t, "VACUUM")) {
        if (W_Gatti_tryChance(w)) { Sound_PlaySound(W_Gatti_GetSfx(w), 0.2f, 2, -0x3e8, 0xc8, 2); Pickup_DeSpawn(p); }
        else Pickup_DoGetTaken(p);
    }
    if (!strcmp(t, "OROLOGION")) {
        if (W_Gatti_tryChance(w)) {
            Sound_PlaySound(W_Gatti_GetSfx(w), 0.2f, 2, -0x3e8, 0xc8, 2);
            sprite_setTint(&c->s, 0xff);
            Sound_PlaySound("Orologion", 1.5f, 4, 0, 0, 0);
            c->_speed = 0;
            Pickup_DeSpawn(p);
        } else {
            Pickup_DoGetTaken(p);
        }
    }
}
static void W_Gatti_OnBulletOverlapsEnemyNoKB(void *ctx, Sprite *bs, Sprite *es) {  // GetDamaged(..., false): senza respinta
    Weapon *w = ctx;
    Bullet *b = bs->owner;
    Enemy *e = es->owner;
    if (e->isDead || Bullet_HasAlreadyHitObject(b, e, e->isDead)) return;
    Enemy_GetDamaged(e, Weapon_PPower(w), (int)w->hitVFX, 0, w->bulletType);
    w->stats_inflictedDamage += Weapon_PPower(w);
}
static void W_Gatti_OnStart(Weapon *w) {
    Weapon_ResetFiringTimer(w);
    physics_addOverlap(&w->pool->group, &Core.Enemies, W_Gatti_onCatOverlapsEnemy, w);
    physics_addOverlap(&w->pool->group, &Core.playerGroup, W_Gatti_onCatOverlapsPlayer, w);
    physics_addOverlap(&w->pool->group, &Core.Destructibles, Weapon_onBulletOverlapsDestuctible, w);
    physics_addOverlapSelf(&w->pool->group, W_Gatti_OnBulletOverlapsBullet, w);
    physics_addOverlap(&w->pool->group, &Core.PickupGroup, W_Gatti_OnBulletOverlapsPickup, w);
    if (w->hitsWalls && Core.Stage && Core.Stage->hasTileset)
        for (int i = 0; i < n_CollisionLayers; i++) w->wallsColliders[w->n_wallsColliders++] = physics_addColliderLayerCb(&w->pool->group, CollisionLayers[i], Weapon_onBulletOverlapsWall, w);
    w->secondaryPool = BulletPool_new(w, &B_FireExplosion);
    w->scratchPool = BulletPool_new(w, &B_Gatti_Scratch);
    w->scufflePool = BulletPool_new(w, &B_Gatti_Scuffle);
    physics_addOverlap(&w->secondaryPool->group, &Core.Enemies, Weapon_onBulletOverlapsEnemy, w);
    physics_addOverlap(&w->secondaryPool->group, &Core.Destructibles, Weapon_onBulletOverlapsDestuctible, w);
    physics_addOverlap(&w->scratchPool->group, &Core.Enemies, Weapon_onBulletOverlapsEnemy, w);
    physics_addOverlap(&w->scufflePool->group, &Core.Enemies, W_Gatti_OnBulletOverlapsEnemyNoKB, w);
}
// LevelUp/MakeLevelOne: ChangeBGMRate agisce solo con BGM_Gatti in riproduzione (non nella Foresta)
static const WeaponVT W_Gatti = { BASE, .CheckArcanas = CA_gatti, .bullet = &B_Gatti, .ctor = W_Gatti_ctor, .OnStart = W_Gatti_OnStart };
// Gemini: W_Gatti_Counter (0x27c6): altri gatti, PLUSMINUS spostato di -2, niente CheckArcanas ne' BGM
static void W_GattiCounter_ctor(Weapon *w) {
    static const char *const cats[3] = { "cat4_i0", "cat6_i0", "cat5_i0" };
    W_Gatti_ctor(w);
    w->catBaseFrames = cats, w->nCatBaseFrames = 3;
    for (int i = 0; i < 0x1f4; i++) w->PLUSMINUS[i] -= 2;
}
static const WeaponVT W_Gatti_Counter = { BASE, .CheckArcanas = CA_none, .bullet = &B_Gatti, .ctor = W_GattiCounter_ctor, .OnStart = W_Gatti_OnStart };

// --- Stigrangatti: W_Grangatti (0xa914), B_Grangatti (0x1446c) -------------------------------------------------
// Occhi evocati attorno al giocatore che inseguono i pickup: l'oro va al giocatore, il cibo e i nemici uccisi diventano monete.
static Vector2 Grangatti_ellipse[5], Grangatti_edge[0x30];
static void B_Grangatti_ctor(Bullet *b) {
    static Animation idle;
    static const char *const smoke[6] = { "SmokeB1.png", "SmokeB2.png", "SmokeB3.png", "SmokeB4.png", "SmokeB5.png", "SmokeB6.png" };
    if (!idle.n) {
        make_anim(&idle, "vfx", "eyeanim_", 0, 0x1d, 0, 0x10, -1);
        for (int i = 0; i < 5; i++) Grangatti_ellipse[i] = (Vector2){ 0.5f * game_width * cosf(2 * PI * i / 5), 0.5f * game_height * sinf(2 * PI * i / 5) };  // Ellipse.getPoints(5)
        for (int i = 0; i < 0x30; i++) Grangatti_edge[i] = (Vector2){ 0x18 * cosf(2 * PI * i / 0x30), 0x18 * sinf(2 * PI * i / 0x30) };  // explosionCircle, edge quantity 48
    }
    EmitterConfig c = { .nframes = 6, .angle = ERND(0, 0x168), .speed = ERND(0xf, 0x1e), .quantity = 1, .lifespan = EOP(0x2ee),
                        .alpha = ERANGE(1, 0), .scale = ERANGE(1, 0), .on = 0 };
    for (int i = 0; i < 6; i++) c.frames[i] = frame_get("vfx", smoke[i]);
    b->Pfx = particles_add();
    c.hasZone = 1, c.zoneRadius = 0x18;
    b->PfxEmitter = particles_createEmitter(b->Pfx, c);
    b->PfxExplosion = particles_add();
    c.hasZone = 0, c.edge = Grangatti_edge, c.nEdge = 0x30;
    b->PfxEmitter2 = particles_createEmitter(b->PfxExplosion, c);
    b->defaultSpeed = b->_speed;
    sprite_init(&b->summon, frame_get("vfx", "summon.png"), 0, 0);
    b->summon.visible = 0;
    children_add(&b->summon);
    anims_play(&b->s, &idle, 0);
    b->summonTween = b->entryTween = b->onExpireAlphaTween = TWEEN_NONE;
    b->chooseTimer = b->ExpireTimer = b->HitboxTimer = (Timer){ -1, 0 };
}
static void B_Grangatti_ChooseTarget(void *ctx) {
    Bullet *b = ctx;
    Vector2 t;
    Sprite *best = NULL;
    float bd = 1e30f;
    for (int i = 0; i < Core.PickupGroup.n; i++) {  // physics.closest(this, PickupGroup.children.entries)
        Pickup *p = Core.PickupGroup.items[i]->owner;
        float dx = b->s.x - p->s.body.center.x, dy = b->s.y - p->s.body.center.y, d = dx * dx + dy * dy;
        if (d < bd) bd = d, best = &p->s;
    }
    if (!best) {
        Vector2 e = Grangatti_ellipse[(int)floorf(frand() * 5)];  // RND.pick
        t = (Vector2){ Core.Player->s.x + e.x, Core.Player->s.y + e.y };
    } else {
        t = (Vector2){ best->x, best->y };
    }
    float dx = t.x - b->s.x, dy = t.y - b->s.y, l = sqrtf(dx * dx + dy * dy);
    if (l > 0) dx /= l, dy /= l;
    b->aimVec = (Vector2){ Bullet_TrueSpeed(b) * dx, Bullet_TrueSpeed(b) * dy };
}
static void B_Grangatti_hitbox(void *ctx) { ((Bullet *)ctx)->n_hit = 0; }  // objectsHit = []
static void B_Grangatti_OnRecycle(Bullet *b) {
    Weapon *w = b->weapon;
    Bullet_OnRecycle(b);
    tween_stop(b->summonTween), tween_stop(b->entryTween), tween_stop(b->onExpireAlphaTween);
    b->s.visible = 1;
    b->isCullable = 0;
    sprite_setOrigin(&b->s, 0.5f, 0.5f);
    sprite_setScale(&b->s, 1);
    body_setCircle(&b->s.body, 0xe, b->s.body.offset.x, b->s.body.offset.y);
    sprite_setScale(&b->s, Weapon_PArea(w));
    b->s.alpha = 0.7f;
    sprite_setScale(&b->summon, 0);
    b->summon.visible = 1, b->summon.alpha = 1;
    b->s.tint = 0xffffff;
    b->_speed = b->defaultSpeed;
    b->summonTween = tweens_add((TweenConfig){ .props = { { &b->summon.scaleX, &b->summon.scaleY, Weapon_PArea(w) }, { &b->summon.alpha, NULL, 0 } }, .nprops = 2, .duration = 0x3e8 });
    sprite_setScale(&b->s, 0);  // entryTween onStart: scaleX = scaleY = 0
    b->entryTween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, Weapon_PArea(w) } }, .nprops = 1, .duration = 0x12c });
    float a = 2 * PI * frand();
    b->s.x += cosf(a) * game_width * 0.45f, b->s.y += sinf(a) * game_height * 0.45f;
    b->summon.x = b->s.x, b->summon.y = b->s.y + 0x18;
    b->save_vel_x = b->save_vel_y = 1;
    B_Gatti_TargetPlayer(b);
    time_removeEvent(b->chooseTimer);  // come in B_Gatti: dopo il DeSpawn continua a girare
    b->chooseTimer = time_addEvent(0x5dc / Weapon_PSpeed(w), 0, -1, B_Grangatti_ChooseTarget, b);
    time_removeEvent(b->ExpireTimer);
    b->ExpireTimer = time_addEvent(Weapon_PDuration(w), 0, 0, B_Gatti_onExpire, b);
    time_removeEvent(b->HitboxTimer);
    b->HitboxTimer = time_addEvent(w->hitBoxDelay, 1, 0, B_Grangatti_hitbox, b);
    Sound_PlaySound("MagicMissile", 0.2f, 1, -0x3e8, 0xc8, 0xc);
}
static void B_Grangatti_Update(Bullet *b, float delta) {
    (void)delta;
    if (b->indexInWeapon < 6) manager_emitParticleAt(b->Pfx, b->s.x, b->s.y), manager_emitParticleAt(b->PfxExplosion, b->s.x, b->s.y);
    b->s.depth = b->s.y - Core.Player->s.y - 0x20;
    b->Pfx->s.depth = b->s.depth - 1, b->PfxExplosion->s.depth = b->s.depth + 1;
    sprite_setVelocity(&b->s, b->aimVec.x * b->save_vel_x, b->aimVec.y * b->save_vel_y);
    b->s.flipX = b->s.body.velocity.x < 0;
    b->summon.x = b->s.x, b->summon.y = b->s.y + 0x18;
}
static void B_Grangatti_DeSpawn(Bullet *b) { time_removeEvent(b->HitboxTimer); b->s.visible = 0; base_DeSpawn(b); }
// OnHasHitWall rimbalza, ma W_Grangatti.OnStart non aggiunge i collider dei muri: non scatta mai
static const BulletVT B_Grangatti = { "vfx", "eye.png", B_Grangatti_ctor, NULL, B_Grangatti_OnRecycle, NULL, B_Grangatti_Update, B_Grangatti_DeSpawn };

static void W_Grangatti_ctor(Weapon *w) {
    w->goldChance = 0.005f;
    for (int i = 0; i < 0x3e8; i++) w->RANDOMS[i] = w->PLUSMINUS[i] = i / 1000.0f;
    shuffle(w->RANDOMS, 0x3e8), shuffle(w->PLUSMINUS, 0x3e8);
}
static int W_Grangatti_TurnToGold(Weapon *w, float x, float y) {
    if (!(w->RANDOMS[w->randomIndex++ % 0x3e8] < w->goldChance * Player_PLuck(Core.Player))) return 0;  // PLuck
    Pickup *p = Core_MakePickup(x, y, "COIN");
    if (p) p->time = 1, p->goToPlayer = 1, p->value = 1, p->feverMS = 0x32;
    if (p) po_add("RunHunger", p->value * GoldMultiplier * Player_PGreed(Core.Player));
    return 1;
}
static void W_Grangatti_OnBulletOverlapsPickup(void *ctx, Sprite *bs, Sprite *ps) {
    static const char *const gold[] = { "COIN", "COINBAG1", "COINBAGMAX" }, *const edible[] = { "ROAST", "CLOVER", "OROLOGION", "ROSARY", "NFT", "GEM", "VACUUM" };
    Weapon *w = ctx;
    Pickup *p = ps->owner;
    if (Bullet_HasAlreadyHitObject(bs->owner, p, 0)) return;
    for (int i = 0; i < 3; i++)
        if (!strcmp(p->itemType, gold[i])) { p->time = 1, p->goToPlayer = 1; return; }
    for (int i = 0; i < 7; i++)
        if (!strcmp(p->itemType, edible[i])) {
            if ((p->value <= 2 && w->PLUSMINUS[w->plusMinusIndex++ % 0x3e8] >= 0.25f) || W_Grangatti_TurnToGold(w, p->s.x, p->s.y)) {
                Sound_PlaySound("Roast", 0.1f, 2, -0x3e8, 0xc8, 2);
                Pickup_DeSpawn(p);
            }
            return;
        }
}
static void W_Grangatti_OnBulletOverlapsEnemyNoKB(void *ctx, Sprite *bs, Sprite *es) {
    Weapon *w = ctx;
    Enemy *e = es->owner;
    if (e->isDead || Bullet_HasAlreadyHitObject(bs->owner, e, e->isDead)) return;
    Enemy_GetDamaged(e, Weapon_PPower(w), (int)w->hitVFX, 0, w->bulletType);
    w->stats_inflictedDamage += Weapon_PPower(w);
    if (e->isDead) W_Grangatti_TurnToGold(w, e->s.x, e->s.y);
}
static void W_Grangatti_OnStart(Weapon *w) {  // niente collider dei muri
    Weapon_ResetFiringTimer(w);
    physics_addOverlap(&w->pool->group, &Core.Enemies, W_Grangatti_OnBulletOverlapsEnemyNoKB, w);
    physics_addOverlap(&w->pool->group, &Core.Destructibles, Weapon_onBulletOverlapsDestuctible, w);
    physics_addOverlap(&w->pool->group, &Core.PickupGroup, W_Grangatti_OnBulletOverlapsPickup, w);
}
// MakeLevelOne: il power di GATTI rimosso alza il proprio (e goldChance) solo se supera 3, cioe' col limit break; counterWeapon: arcana Aquarius
static const WeaponVT W_Grangatti = { BASE, .CheckArcanas = CA_grangatti, .bullet = &B_Grangatti, .ctor = W_Grangatti_ctor, .OnStart = W_Grangatti_OnStart };

// --- Song of Mana: W_Song (0x144b9), B_Song (0x9ab5) ---------------------------------------------------------
// Colonna verticale che segue il giocatore; a schermo due Blitter di particelle additive che rimbalzano nella colonna.
typedef struct { float x, y, alpha, vx, vy, bounce; const Frame *f; float defaultBounce; } Bob;  // defaultBounce: B_Song2
typedef struct Blitter { Sprite s; Bob *bobs; int n, cap; } Blitter;  // GameObjects.Blitter (scrollFactor 0, ADD)
static void Blitter_draw(Sprite *s) {
    Blitter *bl = s->owner;
    if (!s->visible || s->alpha <= 0) return;
    float cx = s->scrollFactor0 ? 0 : camera_scrollX, cy = s->scrollFactor0 ? 0 : camera_scrollY;
    if (s->blendAdd) BeginBlendMode(BLEND_ADDITIVE);
    for (int i = 0; i < bl->n; i++) {  // Bob: origine in alto a sinistra, alpha del bob per quella del blitter
        Bob *b = &bl->bobs[i];
        const Frame *f = b->f;
        DrawTexturePro(*f->tex, (Rectangle){ f->x, f->y, f->w, f->h }, (Rectangle){ roundf(b->x + f->ox - cx), roundf(b->y + f->oy - cy), f->w, f->h }, (Vector2){ 0, 0 }, 0,
                       (Color){ 255, 255, 255, (unsigned char)(255 * fminf(1, b->alpha * s->alpha)) });
    }
    if (s->blendAdd) EndBlendMode();
}
static Blitter *Blitter_add(void) {  // scene.add.blitter(0, 0, 'vfx')
    Blitter *bl = calloc(1, sizeof(Blitter));
    sprite_init(&bl->s, NULL, 0, 0);
    bl->s.owner = bl;
    bl->s.draw = Blitter_draw;
    bl->s.scrollFactor0 = 1;
    bl->s.blendAdd = 1;
    children_add(&bl->s);
    return bl;
}
static void B_Song_AddBobs(Blitter *bl, int n) {
    static const char *const fr[3] = { "PfxPink.png", "PfxYellow.png", "PfxBlue.png" };
    for (int i = 0; i < n; i++) {
        float a = frand() * PI;
        if (bl->n == bl->cap) bl->bobs = realloc(bl->bobs, (bl->cap = bl->cap ? bl->cap * 2 : 128) * sizeof(Bob));
        bl->bobs[bl->n++] = (Bob){ 0.5f * game_width, 0.5f * game_height, 0.5f, 2 * sinf(a), 0xa * cosf(a), 1 + 0.2f * frand(), frame_get("vfx", fr[i % 3]) };
    }
}
static void B_Song_ctor(Bullet *b) {  // MakeBlitters
    b->blitter = Blitter_add();
    B_Song_AddBobs(b->blitter, 0x64);
    b->blitter->s.alpha = 0;
    b->blitterBG = Blitter_add();
    B_Song_AddBobs(b->blitterBG, 0x64);
    b->blitterBG->s.alpha = 0;
    b->HitboxTimer = b->ExpireTimer = b->FadeOutTimer = (Timer){ -1, 0 };
    b->ScaleTween = b->FadeOutTween = TWEEN_NONE;
}
static void B_Song_UpdateBlitter(Blitter *bl, float mul) {
    for (int i = 0; i < bl->n; i++) {
        Bob *o = &bl->bobs[i];
        float a = frand() * PI * 2;
        o->vx = 0.5f * (1 + i % 7) * sinf(a) * mul, o->vy = 5 * cosf(a) * mul, o->bounce = 0.8f + 0.2f * frand();
        o->x = 0.5f * game_width, o->y = 0.5f * game_height;
    }
}
static void B_Song_despawn(void *ctx) { Bullet_DeSpawn(ctx); }  // CheckExplodeOnExpire: vuota
static void B_Song_fadeOut(void *ctx) {
    Bullet *b = ctx;
    b->isBroken = 1;
    b->s.body.enable = 0;
    tween_stop(b->FadeOutTween);
    b->FadeOutTween = tweens_add((TweenConfig){ .props = { { &b->blitter->s.alpha, NULL, 0 }, { &b->blitterBG->s.alpha, NULL, 0 } }, .nprops = 2, .duration = 0x3e8,
                                                .onComplete = B_Song_despawn, .ctx = b });
}
static void B_Song_Shoot(Bullet *b) {
    b->blitter->s.depth = Core.Player->s.depth + game_height;
    b->blitterBG->s.depth = Core.Player->s.depth - game_height;
    b->blitter->s.alpha = b->blitterBG->s.alpha = 1;
    B_Song_UpdateBlitter(b->blitter, 1);
    B_Song_UpdateBlitter(b->blitterBG, 1);
    time_removeEvent(b->FadeOutTimer);
    b->FadeOutTimer = time_addEvent(Weapon_PDuration(b->weapon), 0, 0, B_Song_fadeOut, b);
}
static void B_Song_resetHits(void *ctx) { ((Bullet *)ctx)->n_hit = 0; }  // 'SM Hitbox'
static void B_Song_OnRecycle(Bullet *b) {
    Weapon *w = b->weapon;
    float a = Weapon_PArea(w);
    b->s.visible = 0;
    Bullet_OnRecycle(b);
    sprite_setScale(&b->s, 0);
    b->s.body.enable = 1;
    b->isCullable = 0;
    time_removeEvent(b->HitboxTimer), time_removeEvent(b->ExpireTimer);
    b->HitboxTimer = time_addEvent(w->hitBoxDelay, 1, 0, B_Song_resetHits, b);
    tween_stop(b->ScaleTween);
    b->ScaleTween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, NULL, 0x20 * a }, { &b->s.scaleY, NULL, 0x1c8 } }, .nprops = 2, .duration = 0x1f4 });  // GAMEPLAY_PIXEL_HEIGHT
    if (a >= 1.5f && b->blitter->n < 0xc8) B_Song_AddBobs(b->blitter, 0x64), B_Song_AddBobs(b->blitterBG, 0x64);
    if (a >= 2 && b->blitter->n < 0x12c) B_Song_AddBobs(b->blitter, 0x64), B_Song_AddBobs(b->blitterBG, 0x64);
    if (a >= 2.5f && b->blitter->n < 0x1f4) B_Song_AddBobs(b->blitter, 0xc8), B_Song_AddBobs(b->blitterBG, 0xc8);
    if (a >= 3 && b->blitter->n < 0x3e8) B_Song_AddBobs(b->blitter, 0x64), B_Song_AddBobs(b->blitterBG, 0x64);
    b->isBroken = 0;
    B_Song_Shoot(b);
    Sound_PlaySound("Song", 0.4f, 1, 0x1f4 * frand(), 0x96, 3);
}
static void B_Song_BlitterBounce(Blitter *bl, float right, float left, float top, float bottom) {
    for (int i = 0; i < bl->n; i++) {
        Bob *o = &bl->bobs[i];
        o->y += o->vy, o->x += o->vx;
        if (o->x > right) o->x = right, o->vx *= -o->bounce;
        else if (o->x < left) o->x = left, o->vx *= -o->bounce;
        if (o->y > bottom) o->y = bottom, o->vy *= -o->bounce;
        if (o->y < top) o->y = top, o->vy *= -o->bounce;
    }
}
static void B_Song_Update(Bullet *b, float delta) {
    (void)delta;
    b->s.x = Core.Player->s.x, b->s.y = Core.Player->s.y;
    float a = Weapon_PArea(b->weapon), right = 0.5f * game_width + 0x10 * a, left = 0.5f * game_width - 0x10 * a, top = -0.25f * game_height, bottom = 1.25f * game_height;
    if (b->isBroken) right = game_width, left = 0;
    B_Song_BlitterBounce(b->blitter, right, left, top, bottom);
    B_Song_BlitterBounce(b->blitterBG, right, left, top, bottom);
}
static void B_Song_DeSpawn(Bullet *b) {
    b->isCullable = 1;
    time_removeEvent(b->HitboxTimer), time_removeEvent(b->ExpireTimer);
    base_DeSpawn(b);
}
static const BulletVT B_Song = { "vfx", "WhiteDot.png", B_Song_ctor, NULL, B_Song_OnRecycle, NULL, B_Song_Update, B_Song_DeSpawn };
// W_Song: PAmount 1 (amount -> SecondaryPAmount, non usato)
static void W_SongAstro_Fire(Weapon *w) { base_Fire(w); if (Arcanas.hasAstronomia) Arcanas_TriggerAstronomia(w); }  // Song, Song2
static const WeaponVT W_Song = { BASE, .PPower = blood2_PPower, .CheckArcanas = CA_twilight, .bullet = &B_Song, .PAmount = one_PAmount, .Fire = W_SongAstro_Fire };

// --- Mannajja: W_Song2 (0x9e66), B_Song2 (0x10bd9) ------------------------------------------------------------
// Song of Mana evoluta: 800 bob per Blitter dentro lo schermo, dissolvenza a meta' durata, rallenta chi colpisce.
static void B_Song2_ctor(Bullet *b) {
    B_Song_ctor(b);
    b->blitter->n = b->blitterBG->n = 0;
    B_Song_AddBobs(b->blitter, 0x320), B_Song_AddBobs(b->blitterBG, 0x320);
    for (int k = 0; k < 2; k++) {
        Blitter *bl = k ? b->blitterBG : b->blitter;
        for (int i = 0; i < bl->n; i++) bl->bobs[i].bounce = bl->bobs[i].defaultBounce = 0.8f + 0.2f * frand();
    }
}
static void B_Song2_UpdateBlitter(Blitter *bl) {
    for (int i = 0; i < bl->n; i++) {
        Bob *o = &bl->bobs[i];
        float a = frand() * PI * 2;
        o->vx = 0.125f * (1 + i % 5) * sinf(a) * 5, o->vy = 0.125f * (1 + i % 5) * cosf(a) * 5, o->bounce = o->defaultBounce;
        o->x = 0.5f * game_width, o->y = 0.5f * game_height;
    }
}
static void B_Song2_broken(void *ctx) { Bullet *b = ctx; b->isBroken = 1, b->s.body.enable = 0; }
static void B_Song2_OnRecycle(Bullet *b) {
    Weapon *w = b->weapon;
    b->s.visible = 0;
    Bullet_OnRecycle(b);
    sprite_setScale(&b->s, 0);
    b->s.body.enable = 1;
    b->isCullable = 0;
    time_removeEvent(b->HitboxTimer), time_removeEvent(b->ExpireTimer);
    b->HitboxTimer = time_addEvent(w->hitBoxDelay, 1, 0, B_Song_resetHits, b);  // 'MN Hitbox'
    tween_stop(b->ScaleTween);
    b->ScaleTween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, NULL, 0x20 * Weapon_PArea(w) }, { &b->s.scaleY, NULL, 0x1c8 } }, .nprops = 2, .duration = 0x1f4 });
    b->isBroken = 0;
    // Shoot
    b->blitter->s.depth = Core.Player->s.depth + game_height;
    b->blitterBG->s.depth = Core.Player->s.depth - game_height;
    b->blitter->s.alpha = b->blitterBG->s.alpha = 1;
    B_Song2_UpdateBlitter(b->blitter), B_Song2_UpdateBlitter(b->blitterBG);
    time_removeEvent(b->FadeOutTimer);
    b->FadeOutTimer = time_addEvent(Weapon_PDuration(w), 0, 0, B_Song2_broken, b);
    tween_stop(b->FadeOutTween);
    b->FadeOutTween = tweens_add((TweenConfig){ .props = { { &b->blitter->s.alpha, NULL, 0 }, { &b->blitterBG->s.alpha, NULL, 0 } }, .nprops = 2,
                                                .delay = 0.5f * Weapon_PDuration(w), .duration = 0.5f * Weapon_PDuration(w), .onComplete = B_Song_despawn, .ctx = b });
    for (int i = 0; i < 3; i++) Sound_PlaySound("Song", 0.4f, 1, 0x3e8 * frand(), 0x96, 3);
}
static void B_Song2_Update(Bullet *b, float delta) {
    (void)delta;
    b->s.x = Core.Player->s.x, b->s.y = Core.Player->s.y;  // copyPosition
    float a = Weapon_PArea(b->weapon), right = 0.5f * game_width + 0x10 * a, left = 0.5f * game_width - 0x10 * a;
    if (b->isBroken) right = game_width, left = 0;
    B_Song_BlitterBounce(b->blitter, right, left, 0, game_height);
    B_Song_BlitterBounce(b->blitterBG, right, left, 0, game_height);
}
static void B_Song2_OnHasHitAnObject(Bullet *b, void *o, int isDead) {  // sui Destructible res_Debuffs e slow sono undefined: niente
    (void)b;
    if (isDead || !(((Sprite *)o)->groups & Core.Enemies.bit)) return;
    Enemy *e = o;
    if (e->res_Debuffs >= 1) return;
    if (e->slow > 0.2f) e->slow -= 0.05f;
}
// DamageAllEnemies: solo con le arcane
static const BulletVT B_Song2 = { "vfx", "WhiteDot.png", B_Song2_ctor, NULL, B_Song2_OnRecycle, B_Song2_OnHasHitAnObject, B_Song2_Update, B_Song_DeSpawn };
