static const WeaponVT W_Song2 = { BASE, .CheckArcanas = CA_twilight, .bullet = &B_Song2, .PAmount = one_PAmount, .Fire = W_SongAstro_Fire };

// --- Shadow Pinion: W_Trapano (0x8cbc), B_Trapano (0x4906) --------------------------------------------------
// Zone a terra lasciate camminando; quando il giocatore si ferma scattano nella direzione dell'ultimo passo.
static void Trapano_groundDraw(Sprite *s) {  // scene.add.circle(0, 0, 8, 0x440000), ADD: raggio 8 * scala
    Bullet *b = s->owner;
    if (!s->visible || s->alpha <= 0 || s->scaleX <= 0) return;
    BeginBlendMode(BLEND_ADDITIVE);
    DrawCircle((int)roundf(s->x - camera_scrollX), (int)roundf(s->y - camera_scrollY), b->radius * s->scaleX, hexc(s->tint, s->alpha));
    EndBlendMode();
}
static void Trapano_trailDraw(Sprite *s) {  // Graphics: ogni passata usa l'ultimo lineStyle per tutti i segmenti
    Bullet *b = s->owner;
    if (b->npos < 2 || s->alpha <= 0) return;
    float w = ceilf(Weapon_PArea(b->weapon)), ox = s->x - camera_scrollX, oy = s->y - camera_scrollY;
    for (int i = 1; i < b->npos; i++)
        DrawLineEx((Vector2){ ox + b->positions[i - 1].x, oy + b->positions[i - 1].y }, (Vector2){ ox + b->positions[i].x, oy + b->positions[i].y }, w, hexc(0, s->alpha));
    int last = 0;
    for (int i = 1; i < 0x32 && i < b->npos; i++) last = i;
    float a = fminf(1, 1.0f / (last / 20.0f)) * s->alpha;
    for (int i = 1; i <= last; i++)
        DrawLineEx((Vector2){ ox + b->positions[i - 1].x, oy + b->positions[i - 1].y }, (Vector2){ ox + b->positions[i].x, oy + b->positions[i].y }, 0.5f * w, hexc(0x444444, a));
}
static void B_Trapano_ctor(Bullet *b) {
    static Animation idle;
    b->radius = 8;
    sprite_init(&b->trail, NULL, 0, 0);
    b->trail.owner = b;
    b->trail.draw = Trapano_trailDraw;
    children_add(&b->trail);
    sprite_init(&b->GroundFx, NULL, 0, 0);
    b->GroundFx.owner = b;
    b->GroundFx.draw = Trapano_groundDraw;
    b->GroundFx.tint = 0x440000, b->GroundFx.alpha = 0.5f, b->GroundFx.visible = 1;
    children_add(&b->GroundFx);
    b->s.visible = 0;
    sprite_init(&b->spikeSprite, frame_get("items", "trapano.png"), b->s.x, b->s.x);  // (sic) x, x
    sprite_setScale(&b->spikeSprite, 0);
    sprite_setOrigin(&b->spikeSprite, 0.5f, 1);
    b->spikeSprite.angle = -0x2d;
    children_add(&b->spikeSprite);
    b->AngleTween = tweens_add((TweenConfig){ .props = { { &b->spikeSprite.angle, NULL, 0x2d } }, .nprops = 1, .duration = 0x3e8, .repeat = -1, .yoyo = 1,
                                              .delay = 0x1f4 * frand() + 0xef * b->indexInWeapon, .persist = 1 });
    if (!idle.n) make_anim(&idle, "vfx", "trapano", 1, 0xa, 0, 0x10, -1);
    anims_play(&b->spikeSprite, &idle, 0);
    b->tween1 = TWEEN_NONE;
    b->HitboxTimer = b->ExpireTimer = (Timer){ -1, 0 };
}
static void B_Trapano_resetHits(void *ctx) { ((Bullet *)ctx)->n_hit = 0; }
static void B_Trapano_despawn(void *ctx) { Bullet_DeSpawn(ctx); }
static void B_Trapano_FadeOut(void *ctx) {
    Bullet *b = ctx;
    if (b->isFading) return;
    b->isFading = 1;
    tweens_add((TweenConfig){ .props = { { &b->spikeSprite.alpha, NULL, 0 }, { &b->s.alpha, NULL, 0 }, { &b->GroundFx.alpha, NULL, 0 } }, .nprops = 3, .duration = 0xc8,
                              .onComplete = B_Trapano_despawn, .ctx = b });
    tweens_add((TweenConfig){ .props = { { &b->trail.alpha, NULL, 0 } }, .nprops = 1, .duration = 0xc8 });  // 4 target: il trail nel secondo tween
    if (b->weapon->explodeOnExpire) Weapon_SpawnExplosionAt(b->weapon, b->s.x, b->s.y, 0);
}
static void B_Trapano_OnRecycle(Bullet *b) {
    Weapon *w = b->weapon;
    float a = Weapon_PArea(w);
    Bullet_OnRecycle(b);
    b->isCullable = 0;
    b->isFading = 0;
    b->npos = 0;  // trail.clear()
    b->trail.alpha = 1;
    b->spikeSprite.angle = -0x2d;
    tween_play(b->AngleTween);
    b->trail.x = b->s.x - Core.Player->s.x, b->trail.y = b->s.y - Core.Player->s.y;
    sprite_setScale(&b->s, 1);
    body_setCircle(&b->s.body, 8, -4, -4);
    b->s.body.enable = 1;
    b->n_hit = 0;
    b->isYeeted = 0;
    b->spikeSprite.visible = 1, b->GroundFx.visible = 1, b->s.visible = 0;
    b->s.alpha = 1, b->spikeSprite.alpha = 1, b->GroundFx.alpha = 0.5f;
    b->save_vel_x = b->save_vel_y = 1;
    b->aimVec = (Vector2){ 0, 0 };
    Vector2 pv = Core.Player->s.body.velocity;
    float l = sqrtf(pv.x * pv.x + pv.y * pv.y);
    b->previousVector = l > 0 ? (Vector2){ pv.x / l, pv.y / l } : pv;
    sprite_setVelocity(&b->s, 0, 0);
    b->spikeSprite.x = b->s.x, b->spikeSprite.y = b->s.y + 8;
    b->spikeSprite.angle = 0;
    b->GroundFx.x = b->s.x, b->GroundFx.y = b->s.y;
    b->s.scaleX = b->s.scaleY = b->GroundFx.scaleX = b->GroundFx.scaleY = 0;
    tween_stop(b->tween1);
    b->spikeSprite.scaleX = b->spikeSprite.scaleY = 0;  // tween1 onStart
    b->tween1 = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, a }, { &b->spikeSprite.scaleX, &b->spikeSprite.scaleY, a } }, .nprops = 2, .duration = 0x12c });
    tweens_add((TweenConfig){ .props = { { &b->GroundFx.scaleX, &b->GroundFx.scaleY, 1.1f * a } }, .nprops = 1, .duration = 0x12c, .yoyo = 1 });
    time_removeEvent(b->HitboxTimer);
    b->HitboxTimer = time_addEvent(w->hitBoxDelay, 1, 0, B_Trapano_resetHits, b);
    b->durata = 0;
    time_removeEvent(b->ExpireTimer);
    b->ExpireTimer = time_addEvent(Weapon_PDuration(w), 1, 0, B_Trapano_FadeOut, b);
}
static void B_Trapano_yeetStart(void *ctx) {  // onStart del tween dello scatto (dopo il suo delay)
    Bullet *b = ctx;
    tween_stop(b->AngleTween);
    b->spikeSprite.angle = b->s.angle + 0x5a;
    Sound_PlaySound("Shot", 0.45f, 1, -0xc8 - -0xc8 * b->indexInWeapon, 0xc8, 0xa);
}
static void B_Trapano2_yeetStart(void *ctx);
static void B_Trapano2_FadeOut(void *ctx);
static const BulletVT B_Trapano2;
static void B_Trapano_Yeet(Bullet *b) {
    int v2 = b->vt == &B_Trapano2;  // B_Trapano2: 450 invece di 150, suono MagicMissile, AngleTween assente
    float a = Bullet_AngleFromVelocityRadians(b->previousVector);
    b->s.angle = a * (180 / PI);
    sprite_setVelocity(&b->s, 0, 0);
    float d = (v2 ? 0x1c2 : 0x96) * Weapon_PArea(b->weapon), delay = 0x32 * b->indexInWeapon;
    time_addEvent(delay, 0, 0, v2 ? B_Trapano2_yeetStart : B_Trapano_yeetStart, b);
    tweens_add((TweenConfig){ .props = { { &b->s.x, NULL, b->s.x + d * cosf(a) }, { &b->s.y, NULL, b->s.y + d * sinf(a) } }, .nprops = 2, .duration = 0x96,
                              .delay = delay, .ease = Ease_SineInOut, .onComplete = v2 ? B_Trapano2_FadeOut : B_Trapano_FadeOut, .ctx = b });
}
static void B_Trapano_Update(Bullet *b, float delta) {
    b->s.depth = b->GroundFx.depth = -game_height;
    b->spikeSprite.depth = b->s.y - Core.Player->s.y - 1;
    b->spikeSprite.x = b->s.x, b->spikeSprite.y = b->s.y;
    if (b->isYeeted) {
        b->trail.depth = b->s.y - Core.Player->s.y + 0.5f * game_height;
        int n = (int)ceilf(delta / 0x10);
        for (int i = 0; i < n; i++) {  // trailUpdate (attivo): positions.unshift, al massimo 50
            memmove(&b->positions[1], &b->positions[0], 49 * sizeof(Vector2));
            b->positions[0] = (Vector2){ b->s.x, b->s.y };
            if (b->npos < 50) b->npos++;
        }
        return;
    }
    b->durata += delta;
    Vector2 pv = Core.Player->s.body.velocity;
    if (pv.x == 0 && pv.y == 0) {
        if (b->previousVector.x == 0 && b->previousVector.y == 0) return;
        B_Trapano_Yeet(b);
        b->isYeeted = 1;
    } else {
        b->previousVector = pv;
        float sp = Weapon_PSpeed(b->weapon);
        if (sp > 1) {
            b->aimVec.x = b->aimVec.x - 0.002f * (pv.x - b->aimVec.x), b->aimVec.y = b->aimVec.y - 0.002f * (pv.y - b->aimVec.y);
            sprite_setVelocity(&b->s, b->aimVec.x * sp, b->aimVec.y * sp);
        }
    }
}
static void B_Trapano_DeSpawn(Bullet *b) {
    time_removeEvent(b->ExpireTimer), time_removeEvent(b->HitboxTimer);
    tween_stop(b->tween1);  // SpeedTween, tween2: mai creati
    b->spikeSprite.visible = 0;
    b->s.scaleX = b->s.scaleY = 0;
    b->GroundFx.visible = 0;
    b->s.visible = 0;
    b->s.body.enable = 0;
    base_DeSpawn(b);
}
static const BulletVT B_Trapano = { "vfx", "circle8.png", B_Trapano_ctor, NULL, B_Trapano_OnRecycle, NULL, B_Trapano_Update, B_Trapano_DeSpawn };
static void W_Trapano_MakeLevelOne(Weapon *w) { base_MakeLevelOne(w); w->pool->isUncapped = 1; }  // Init: pool.isUncapped
static void W_Trapano_Update(Weapon *w, float delta) {
    base_Update(w, delta);
    w->totalTime += delta;
    w->totalTime += Core.Player->frameWalk * (delta / (1000.0f / 60));
    if (w->totalTime >= Weapon_PInterval(w)) { w->totalTime = 0; Weapon_Fire(w); }
}
static void W_Trapano_onBulletOverlapsEnemy(Weapon *w, Bullet *b, Enemy *e) {
    if (e->isDead || Bullet_HasAlreadyHitObject(b, e, e->isDead)) return;
    float p = Weapon_PPower(w) + (b->isYeeted ? b->durata / 1000 * Weapon_PPower(w) : 0);
    Enemy_GetDamaged(e, p, (int)w->hitVFX, w->knockback, w->bulletType);
    w->stats_inflictedDamage += p;
}
// pfxEmitter della Weapon: creato e mai emesso, non tradotto
static const WeaponVT W_Trapano = { BASE, .CheckArcanas = CA_twilight, .bullet = &B_Trapano, .MakeLevelOne = W_Trapano_MakeLevelOne, .Update = W_Trapano_Update,
                                    .ResetFiringTimer = noop_ResetFiringTimer, .onBulletOverlapsEnemy = W_Trapano_onBulletOverlapsEnemy };

