static const WeaponVT W_Corridor_vt;
// --- Clock Lancet / Infinite Corridor: W_Lancet (0x16b3a), W_Corridor (0x7819), B_Lancet (0x10da9), B_SpaceTime (0x6caa) ---
// Sei colpi istantanei in fila lungo una delle 12 ore dell'orologio, che avanza di uno scatto a ogni sparo; congelano i nemici.
static void B_Lancet_despawn(void *ctx) { Bullet_DeSpawn(ctx); }  // 'Lancet Expire'
static void B_Lancet_OnRecycle(Bullet *b) {
    Bullet_OnRecycle(b);
    body_setCircle(&b->s.body, 0x10, b->s.body.offset.x, b->s.body.offset.y);
    sprite_setScale(&b->s, 2 * PixelScale);
    b->s.visible = 0;
    time_removeEvent(b->ExpireTimer);
    b->ExpireTimer = time_addEvent(0x14, 0, 0, B_Lancet_despawn, b);
}
static void B_Lancet_OnHasHitAnObject(Bullet *b, void *o, int isDead) {  // solo i nemici hanno Freeze
    if (isDead || !(((Sprite *)o)->groups & Core.Enemies.bit)) return;
    Enemy_Freeze(o, Weapon_PDuration(b->weapon), 1);
    if (Arcanas_has(12)) Arcanas_TriggerCold(((Sprite *)o)->x, ((Sprite *)o)->y);  // Out of Time
}
static const BulletVT B_Lancet = { "vfx", "Rings3.png", NULL, NULL, B_Lancet_OnRecycle, B_Lancet_OnHasHitAnObject, NULL, NULL };
static void W_Lancet_imageStart(void *ctx) { ((Weapon *)ctx)->image.alpha = 1; }
static void W_Lancet_ctor(Weapon *w) {
    static Animation pierce;
    w->ticks = 8;
    for (int i = 0; i < 0xc; i++) {
        float a = i / 12.0f * (2 * PI);
        w->lancetTargets[i] = (Vector2){ cosf(a), sinf(a) };
        w->lancetAngles[i] = a;
    }
    sprite_init(&w->image, frame_get("vfx", "Pierce1.png"), Core.Player->s.x, Core.Player->s.y);
    sprite_setOrigin(&w->image, 0, 0.5f);
    w->image.visible = 0;
    sprite_setTint(&w->image, 0xcceeff);
    w->image.scaleX = 2, w->image.scaleY = 1;
    children_add(&w->image);
    w->imageTween = tweens_add((TweenConfig){ .props = { { &w->image.alpha, NULL, 0 } }, .nprops = 1, .delay = 0xc8, .duration = 0x1f4,
                                              .onStart = W_Lancet_imageStart, .ctx = w, .persist = 1 });
    if (!pierce.n) make_anim(&pierce, "vfx", "Pierce", 1, 5, 0, 0x1e, 0);
    w->pierceAnim = &pierce;
}
static float six_PAmount(Weapon *w) { (void)w; return 6; }
static void W_Lancet_Fire(Weapon *w) {
    if (++w->ticks >= 0xc) w->ticks = 0;
    if (w->vt == &W_Corridor_vt && w->ticks == 9)  // FireCorridor
        BulletPool_SpawnAt(w->corridorPool, Core.Player->s.x, Core.Player->s.y, w, 0);
    Vector2 t = w->lancetTargets[w->ticks];
    tween_restart(w->imageTween);
    w->image.x = Core.Player->s.x, w->image.y = Core.Player->s.y;
    w->image.angle = w->lancetAngles[w->ticks] * (180 / PI);
    w->image.visible = 1;
    w->image.depth = Core.Player->s.depth + game_height;
    anims_play(&w->image, w->pierceAnim, 0);
    for (int i = 0; i < Weapon_PAmount(w); i++) {  // FireOneLancet: FireOneBullet + SetTarget + setAngle
        Bullet *b = BulletPool_SpawnAt(w->pool, Core.Player->s.x, Core.Player->s.y, w, i);
        if (!b) continue;
        b->s.x += 0x32 * t.x * (1 + b->indexInWeapon), b->s.y += 0x32 * t.y * (1 + b->indexInWeapon);
        b->s.angle = w->lancetAngles[w->ticks] * (180 / PI);
    }
    if (w->lastFiringInterval != Weapon_PInterval(w)) {
        w->lastFiringInterval = Weapon_PInterval(w);
        Weapon_ResetFiringTimer(w);
    }
    if (Arcanas.hasAstronomia) Arcanas_TriggerAstronomia(w);
}
// B_SpaceTime: il corridoio che si apre attorno al giocatore e dimezza gli HP
static void B_SpaceTime_ctor(Bullet *b) {
    sprite_setScale(&b->s, 1);
    sprite_init(&b->corridorLight, frame_get("vfx", "corridor_light.png"), 0, 0);
    children_add(&b->corridorLight);
}
static void B_SpaceTime_despawn(void *ctx) { Bullet_DeSpawn(ctx); }
static void B_SpaceTime_OnRecycle(Bullet *b) {
    Bullet_OnRecycle(b);
    sprite_setScale(&b->s, 1);
    body_setCircle(&b->s.body, 0x40, b->s.body.offset.x, b->s.body.offset.y);
    float a = 1, la = 0.75f;  // FlashingVFXEnabled
    sprite_setScale(&b->s, 0);
    b->s.alpha = 0;
    sprite_setScale(&b->corridorLight, 0);
    b->corridorLight.alpha = la;
    tween_stop(b->scaleTween);
    float sc = game_width / 128.0f;
    b->scaleTween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, sc }, { &b->s.alpha, NULL, a } }, .nprops = 2, .duration = 0x3e8, .yoyo = 1,
                                              .ease = Ease_SineInOut, .onComplete = B_SpaceTime_despawn, .ctx = b });
    Sound_PlaySound("Corridor", 0.9f, 1, 0x1f4, 0x190, 1);
    tween_stop(b->AngleTween);
    b->AngleTween = tweens_add((TweenConfig){ .props = { { &b->s.angle, NULL, -0x5a0 } }, .nprops = 1, .duration = 0x7d0 });  // dal secondo in poi parte gia' da -1440
    tween_stop(b->lightTween);
    b->lightTween = tweens_add((TweenConfig){ .props = { { &b->corridorLight.scaleX, &b->corridorLight.scaleY, sc }, { &b->corridorLight.alpha, NULL, a } }, .nprops = 2,
                                              .duration = 0x3e8, .yoyo = 1, .ease = Ease_SineInOut });
}
static void B_SpaceTime_Update(Bullet *b, float delta) {
    (void)delta;
    b->s.x = Core.Player->s.x, b->s.y = Core.Player->s.y;
    b->s.depth = -game_height;
    b->corridorLight.x = b->s.x, b->corridorLight.y = b->s.y;
    b->corridorLight.depth = b->s.depth + 1;
}
static const BulletVT B_SpaceTime = { "vfx", "corridor_bg.png", B_SpaceTime_ctor, NULL, B_SpaceTime_OnRecycle, NULL, B_SpaceTime_Update, NULL };
static void W_Corridor_onCorridorOverlapsEnemy(void *ctx, Sprite *bs, Sprite *es) {
    Weapon *w = ctx;
    Bullet *b = bs->owner;
    Enemy *e = es->owner;
    if (e->isDead || e->res_Corridor || Bullet_HasAlreadyHitObject(b, e, e->isDead)) return;
    float d = 0.5f * e->hp;
    Enemy_GetDamaged(e, d, (int)w->hitVFX, w->knockback, w->bulletType);
    w->stats_inflictedDamage += d;
}
static void W_Corridor_OnStart(Weapon *w) {
    base_OnStart(w);
    w->corridorPool = BulletPool_new(w, &B_SpaceTime);
    physics_addOverlap(&w->corridorPool->group, &Core.Enemies, W_Corridor_onCorridorOverlapsEnemy, w);
}
static const WeaponVT W_Lancet = { BASE, .bullet = &B_Lancet, .ctor = W_Lancet_ctor, .PAmount = six_PAmount, .Fire = W_Lancet_Fire };
static const WeaponVT W_Corridor_vt = { BASE, .bullet = &B_Lancet, .ctor = W_Lancet_ctor, .PAmount = six_PAmount, .Fire = W_Lancet_Fire, .OnStart = W_Corridor_OnStart };

// --- Vento Sacro: W_Vento (0x11f65), B_Vento (0xe4d) ------------------------------------------------------------
// Colpi di petali davanti al giocatore, piu' frequenti camminando; pBonus (camminata continua) regola solo le particelle.
static Animation VentoStrike;
static const WeaponVT W_Vento2;
static float B_Vento_TrueSpeed(Bullet *b) {
    float s = Weapon_PSpeed(b->weapon);
    return s <= 1 ? 0 : (s - 1) * ProjectileSpeed * b->_speed;
}
static void B_Vento_ctor(Bullet *b) {
    if (!VentoStrike.n) make_anim(&VentoStrike, "vfx", "petal", 1, 5, 0, 0x3c, 0);
    sprite_setOrigin(&b->s, 0, 0.5f);
}
static void B_Vento_despawn(void *ctx) { Bullet_DeSpawn(ctx); }
static void B_Vento_OnRecycle(Bullet *b) {
    static const unsigned color[3] = { 0xccffff, 0xfffff, 0x44ccff };  // (sic) 0xfffff
    static const float off[13] = { 0, 5, -5, 1.5f, -2.5f, 0xa, -0xa, 7.5f, -7.5f, 0xf, -0xf, 12.5f, -12.5f };
    Weapon *w = b->weapon;
    int i = b->indexInWeapon;
    Bullet_OnRecycle(b);
    b->s.alpha = 0.5f;
    anims_play(&b->s, &VentoStrike, 0);
    b->s.tint = color[i % 3];
    if (b->hasTween) tween_stop(b->tween);
    sprite_setScale(&b->s, 0);
    b->tween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, Weapon_PArea(w) } }, .nprops = 1, .duration = 0xc8, .yoyo = 1 });
    b->hasTween = 1;
    if (b->hasTween2) tween_stop(b->tween2);
    b->tween2 = tweens_add((TweenConfig){ .props = { { &b->s.alpha, NULL, 0 } }, .nprops = 1, .duration = Weapon_PDuration(w), .delay = 0x64,
                                          .onComplete = B_Vento_despawn, .ctx = b });
    b->hasTween2 = 1;
    int flip = Core.Player->s.flipX;
    b->s.flipX = flip;
    float ox = -8 * (flip ? 1 : -1);
    b->s.originX = flip ? 1 : 0;
    b->s.flipY = i % 2 == (flip ? 0 : 1);
    float oy = -0x10 - off[i % 13];
    b->s.angle = off[i % 6];
    b->_speed = 1;
    b->s.body.velocity.x = (flip ? -1 : 1) * B_Vento_TrueSpeed(b) + Core.Player->s.body.velocity.x;
    b->s.x = Core.Player->s.x + ox, b->s.y = Core.Player->s.y + oy;
    Sound_PlaySound("Whip", b->weapon->vt == &W_Vento2 ? 1 : 1.7f, 2, 0x64 * i, 0, 0);  // B_Vento2: volume 1
}
static void B_Vento_Init(Bullet *b, float x, float y) {
    Bullet_Init(b, x, y);  // super.Init chiama gia' OnRecycle
    sprite_setScale(&b->s, 0);
    b->previousArea = Weapon_PArea(b->weapon);
    b->tween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, PixelScale * Weapon_PArea(b->weapon) } }, .nprops = 1, .duration = 0x64 });
    b->hasTween = 1;
}
static void B_Vento_Update(Bullet *b, float delta) { (void)b, (void)delta; }  // vuoto: niente scia, niente Update della base
static const BulletVT B_Vento = { "vfx", "petal5.png", B_Vento_ctor, B_Vento_Init, B_Vento_OnRecycle, NULL, B_Vento_Update, NULL };
static void W_Vento_ctor(Weapon *w) {
    w->mul = 1000.0f / 6;
    w->ventoPfx = particles_add();
    particles_createEmitter(w->ventoPfx, (EmitterConfig){ .frames = { frame_get("vfx", "PfxHoly1.png"), frame_get("vfx", "PfxHoly2.png") }, .nframes = 2,
        .angle = ERND(0, 0xb4), .speed = ERND(0x19, 0x32), .quantity = 1, .lifespan = ERND(0x32, 0x64), .alpha = ERANGE(1, 0), .blendAdd = 1, .gravityY = -0x1f4, .on = 0 });
    w->ventoPfx->s.depth = -1;
    w->walkedTimer = (Timer){ -1, 0 };
}
static void W_Vento_walkedCheck(void *ctx) {
    Weapon *w = ctx;
    if (Core.Player->walked <= 0) w->walkedW = 0, w->hasWalkedTimer = 0, w->pBonus = 0;  // altrimenti il riferimento resta (sic)
}
static void W_Vento_Update(Weapon *w, float delta) {
    base_Update(w, delta);
    if (Core.Player->walked <= 0) {
        if (!w->hasWalkedTimer) w->walkedTimer = time_addEvent(0x1f4, 0, 0, W_Vento_walkedCheck, w), w->hasWalkedTimer = 1;
    } else {
        time_removeEvent(w->walkedTimer);
        w->hasWalkedTimer = 0;
        w->walkedW += Core.Player->frameWalk;
        w->pBonus = fminf(0.5f * w->level, w->walkedW / 0x30d40);
        w->ventoPfx->emitters[0]->c.lifespan = EOP(0x64 + 0x28 * w->pBonus);  // setLifespan
        for (int i = 0; i < w->pBonus; i++) manager_emitParticleAt(w->ventoPfx, Core.Player->s.x, Core.Player->s.y - 0x18);
    }
    w->totalTime += delta;
    w->totalTime += Core.Player->frameWalk * (delta / w->mul);
    if (w->totalTime >= Weapon_PInterval(w)) { w->totalTime = 0; Weapon_Fire(w); }
}
// canCrit (StandardCritical): solo con l'arcana Slash
static const WeaponVT W_Vento = { BASE, .PPower = blood2_PPower, .CheckArcanas = CA_slash, .onBulletOverlapsEnemy = W_canCrit_onBulletOverlapsEnemy, .bullet = &B_Vento, .ctor = W_Vento_ctor, .Update = W_Vento_Update, .ResetFiringTimer = noop_ResetFiringTimer };

// --- Fuwalafuwaloo: W_Vento2 (0x7051), B_Vento2 (0x5eb8), B_Vento2extra (0xfb3d), B_Vento2explo (0x132ca) --------------
// Vento Sacro + Vampirica: tagli scuri con due fantasmi, un petalo in piu' a raggiera per colpo; i critici curano ed esplodono.
static void Vento2_ghosts(Bullet *b, float ox) {  // ghost1/ghost2: rosso e viola additivo, origine e verso del colpo
    b->ghost.originX = b->ghost2.originX = ox, b->ghost.originY = b->ghost2.originY = 0.5f;
    b->ghost.angle = b->ghost2.angle = b->s.angle;
    b->ghost.flipX = b->ghost2.flipX = b->s.flipX, b->ghost.flipY = b->ghost2.flipY = b->s.flipY;
}
static void Vento2_ghostsInit(Bullet *b, float ox) {
    sprite_init(&b->ghost, frame_get("vfx", "petal5.png"), b->s.x, b->s.y);
    sprite_init(&b->ghost2, frame_get("vfx", "petal5.png"), b->s.x, b->s.y);
    sprite_setOrigin(&b->ghost, ox, 0.5f), sprite_setOrigin(&b->ghost2, ox, 0.5f);
    b->ghost.tint = 0xff0000, b->ghost2.tint = 0x660066, b->ghost2.blendAdd = 1;  // le loro anims 'strike' non partono mai
    children_add(&b->ghost), children_add(&b->ghost2);
    b->s.tint = 0x110011;
}
static void Vento2_ghostsUpdate(Bullet *b) {
    b->ghost.scaleX = b->ghost2.scaleX = b->s.scaleX, b->ghost.scaleY = b->ghost2.scaleY = b->s.scaleY;
    b->ghost.x = b->s.x + 4, b->ghost2.x = b->s.x - 4, b->ghost.y = b->s.y + 2, b->ghost2.y = b->s.y - 2;
    b->ghost.alpha = b->ghost2.alpha = b->s.alpha;
}
static void B_Vento2_ctor(Bullet *b) { B_Vento_ctor(b); Vento2_ghostsInit(b, 0); }
static void B_Vento2_OnRecycle(Bullet *b) {
    unsigned tint = b->s.tint;
    B_Vento_OnRecycle(b);  // il tint per indice di B_Vento non c'e': resta 0x110011
    b->s.tint = tint;
    Vento2_ghosts(b, b->s.originX);
}
static void B_Vento2_Update(Bullet *b, float delta) { (void)delta; Vento2_ghostsUpdate(b); }
static const BulletVT B_Vento2 = { "vfx", "petal5.png", B_Vento2_ctor, B_Vento_Init, B_Vento2_OnRecycle, NULL, B_Vento2_Update, NULL };

static Animation Vento2Strike;
static void B_Vento2extra_ctor(Bullet *b) {
    if (!Vento2Strike.n) make_anim(&Vento2Strike, "vfx", "petal", 1, 5, 0, 0x1e, 0);
    sprite_setOrigin(&b->s, 0.5f, 0.5f);
    Vento2_ghostsInit(b, 0.5f);
    b->hasTween = b->hasTween2 = 0;
}
static void B_Vento2extra_OnRecycle(Bullet *b) {
    Weapon *w = b->weapon;
    Bullet_OnRecycle(b);
    b->s.alpha = 0.75f;
    anims_play(&b->s, &Vento2Strike, 0);
    body_setCircle(&b->s.body, 0x18, b->s.body.offset.x, b->s.body.offset.y);
    if (b->hasTween) tween_stop(b->tween);
    sprite_setScale(&b->s, 0);
    b->tween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, 0.7f * Weapon_PArea(w) } }, .nprops = 1, .duration = 0xc8, .yoyo = 1 });
    if (b->hasTween2) tween_stop(b->tween2);
    // (sic) 400 * PDuration ms: a scala 0 dopo 400 ms, il petalo resta nel pool per minuti
    b->tween2 = tweens_add((TweenConfig){ .props = { { &b->s.alpha, NULL, 0 } }, .nprops = 1, .duration = 0x190 * Weapon_PDuration(w), .delay = 0x64,
                                          .onComplete = B_Vento_despawn, .ctx = b });
    b->hasTween = b->hasTween2 = 1;
    b->s.flipY = b->indexInWeapon % 2 == (b->s.flipX ? 0 : 1);
    float a = 360.0f / Weapon_PAmount(w) * b->indexInWeapon;
    b->s.body.velocity = velocityFromRotation(a * (PI / 180), B_Vento_TrueSpeed(b));
    b->s.angle = a;
    b->s.x = Core.Player->s.x, b->s.y = Core.Player->s.y;
    Vento2_ghosts(b, b->s.originX);
}
static void B_Vento2extra_Update(Bullet *b, float delta) {
    (void)delta;
    b->s.depth = b->ghost.depth = b->ghost2.depth = -1;
    Vento2_ghostsUpdate(b);
}
static const BulletVT B_Vento2extra = { "vfx", "petal5.png", B_Vento2extra_ctor, NULL, B_Vento2extra_OnRecycle, NULL, B_Vento2extra_Update, NULL };

static int Vento2_detunesIndex;
static void B_Vento2explo_ctor(Bullet *b) {
    Weapon *w = b->weapon;
    static const unsigned colors[3] = { 0x220022, 0x660066, 0xee0000 };
    sprite_setOrigin(&b->s, 0.5f, 0.5f);
    b->s.blendAdd = 1;
    b->Pfx = particles_add();  // particles('castoro0'): la foglia animata della RenderTexture
    EmitterConfig c = { .frameRef = &w->leafSprite.frame, .lifespan = EOP(0x1f4), .angle = { 0, 0x168, 1 }, .angleSteps = 0x1e, .rotate = ERND(0, 0x168),
                        .alpha = ERANGE(1, 0), .speed = ERND(0x15e, 0x1c2), .quantity = 2, .ntints = 3, .scale = EOP(4), .on = 0 };  // 'Expo.easIn' non esiste: Linear
    for (int i = 0; i < 3; i++) c.tints[i] = colors[i];
    b->PfxEmitter1 = particles_createEmitter(b->Pfx, c);
    c.lifespan = EOP(0x3e8), c.angle = (EmitterOp){ 0x5a, 0x1c2, 1 }, c.speed = ERND(0x96, 0xfa);
    b->PfxEmitter2 = particles_createEmitter(b->Pfx, c);
    b->tween = TWEEN_NONE;
}
static void B_Vento2explo_Init(Bullet *b, float x, float y) {
    static const unsigned colorss[3] = { 0xff00ff, 0x660066, 0xff0000 };
    Bullet_Init(b, x, y);
    body_setCircle(&b->s.body, 0x1c, 4, 4);
    b->s.tint = colorss[b->colorCount++ % 3];
}
static void B_Vento2explo_onStart(void *ctx) {
    Bullet *b = ctx;
    b->s.alpha = 1, b->s.scaleX = b->s.scaleY = 0;
    emitter_start(b->PfxEmitter1), emitter_start(b->PfxEmitter2);
    b->s.body.enable = 1;
}
static void B_Vento2explo_onRepeat(void *ctx) {
    static const unsigned colorss[3] = { 0xff00ff, 0x660066, 0xff0000 };
    Bullet *b = ctx;
    b->n_hit = 0;
    b->s.tint = colorss[b->colorCount++ % 3];
    if (++b->repeatCount > 1) emitter_stop(b->PfxEmitter1), emitter_stop(b->PfxEmitter2);
}
static void B_Vento2explo_onComplete(void *ctx) {
    Bullet *b = ctx;
    emitter_stop(b->PfxEmitter1), emitter_stop(b->PfxEmitter2);
    Bullet_DeSpawn(b);
    b->s.body.enable = 0;
}
static void B_Vento2explo_OnRecycle(Bullet *b) {
    static const float detunes[4] = { 0, 0x190, 0x320, 0x4b0 }, mul[4] = { 0.4f, 0.6f, 0.8f, 1 };
    Bullet_OnRecycle(b);
    b->s.depth = -game_height;
    b->PfxEmitter1->x = b->PfxEmitter2->x = b->s.x, b->PfxEmitter1->y = b->PfxEmitter2->y = b->s.y;
    b->Pfx->s.depth = b->s.depth + 1;
    b->repeatCount = 0;
    int k = Vento2_detunesIndex++ % 4;
    float m = mul[k];
    b->PfxEmitter1->c.speed = ERND(0x15e * m, 0x1c2 * m), b->PfxEmitter2->c.speed = ERND(0x96 * m, 0xfa * m);
    b->PfxEmitter1->c.scale = b->PfxEmitter2->c.scale = EOP(4 * m);
    Sound_PlaySound("Rose", 1, 1, detunes[k], 0, 0);
    b->s.body.enable = 0;
    tween_stop(b->tween);
    sprite_setScale(&b->s, 0);
    b->tween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, m * (game_height / 64.0f) }, { &b->s.alpha, NULL, 0 } }, .nprops = 2, .duration = 0x15e,
                                         .repeat = 2, .onStart = B_Vento2explo_onStart, .onRepeat = B_Vento2explo_onRepeat, .onComplete = B_Vento2explo_onComplete, .ctx = b });
}
static void B_Vento2explo_Update(Bullet *b, float delta) { (void)b, (void)delta; }
static const BulletVT B_Vento2explo = { "vfx", "sPFX_ring_64.png", B_Vento2explo_ctor, B_Vento2explo_Init, B_Vento2explo_OnRecycle, NULL, B_Vento2explo_Update, NULL };

static void W_Vento2_ctor(Weapon *w) {
    static Animation spin;
    w->mul = 1000.0f / 6;
    w->canHeal = 1, w->healDelay = 0x1f4, w->canExplodeV2 = 1, w->explodeDelay = 0x1f4;
    w->walkedTimer = w->healTimer = w->explodeTimerV2 = (Timer){ -1, 0 };
    if (!spin.n) make_anim(&spin, "vfx", "leaf", 0, 0x13, 4, 0x1e, -1);  // leaf0000..leaf0019, frameRate [30,20,24,14][0]
    sprite_init(&w->leafSprite, frame_get("vfx", "leaf0000.png"), -1e9f, -1e9f);
    sprite_setOrigin(&w->leafSprite, 0, 0);
    children_add(&w->leafSprite);
    anims_play(&w->leafSprite, &spin, 0);
}
static float W_Vento2_PPower(Weapon *w) { return base_PPower(w) + w->pBonus; }  // pBonus = walkBonus
static void W_Vento2_canHeal(void *ctx) { ((Weapon *)ctx)->canHeal = 1; }
static void W_Vento2_canExplode(void *ctx) { ((Weapon *)ctx)->canExplodeV2 = 1; }
static float W_Vento2_crit(Weapon *w) {  // critico: cura 8 (al massimo ogni healDelay)
    float crit = frand() < w->critChance * Player_PLuck(Core.Player) ? w->critMul * Arcanas.CritMul : 1;  // PLuck
    if (crit > 1 && w->canHeal) {
        w->canHeal = 0;
        Player_RecoverHp(Core.Player, 8, 1, 0);
        w->healTimer = time_addEvent(w->healDelay, 0, 0, W_Vento2_canHeal, w);
    }
    return crit;
}
static void W_Vento2_onBulletOverlapsEnemy(Weapon *w, Bullet *b, Enemy *e) {
    if (e->isDead) return;
    float crit = W_Vento2_crit(w);
    if (crit > 1 && w->canExplodeV2) {
        w->canExplodeV2 = 0;
        w->explodeTimerV2 = time_addEvent(w->explodeDelay, 0, 0, W_Vento2_canExplode, w);
        BulletPool_SpawnAt(w->secondaryPool, e->s.x, e->s.y, w, 0);
    }
    if (Bullet_HasAlreadyHitObject(b, e, e->isDead)) return;
    Enemy_GetDamaged(e, Weapon_PPower(w) * crit, (int)w->hitVFX, w->knockback, w->bulletType);
    w->stats_inflictedDamage += Weapon_PPower(w) * crit;
}
static void W_Vento2_onExplosionOverlapsEnemy(void *ctx, Sprite *bs, Sprite *es) {
    Weapon *w = ctx;
    Bullet *b = bs->owner;
    Enemy *e = es->owner;
    if (e->isDead) return;
    float crit = W_Vento2_crit(w);
    if (Bullet_HasAlreadyHitObject(b, e, e->isDead)) return;
    Enemy_GetDamaged(e, Weapon_PPower(w) * crit, (int)w->hitVFX, w->knockback, w->bulletType);
    w->stats_inflictedDamage += Weapon_PPower(w) * crit;
}
static void W_Vento2_OnStart(Weapon *w) {
    base_OnStart(w);
    w->secondaryPool = BulletPool_new(w, &B_Vento2explo);
    w->extraPool = BulletPool_new(w, &B_Vento2extra);
    w->canCrit = 1;
    physics_addOverlap(&w->secondaryPool->group, &Core.Enemies, W_Vento2_onExplosionOverlapsEnemy, w);
    physics_addOverlap(&w->secondaryPool->group, &Core.Destructibles, Weapon_onBulletOverlapsDestuctible, w);
    physics_addOverlap(&w->extraPool->group, &Core.Enemies, Weapon_onBulletOverlapsEnemy, w);
    physics_addOverlap(&w->extraPool->group, &Core.Destructibles, Weapon_onBulletOverlapsDestuctible, w);
}
static Bullet *W_Vento2_FireOneBullet(Weapon *w, float x, float y, int index) {  // target: sempre vuoto per quest'arma
    Bullet *b = BulletPool_SpawnAt(w->pool, x, y, w, index);
    BulletPool_SpawnAt(w->extraPool, x, y, w, index);
    return b;
}
static void W_Vento2_walkedCheck(void *ctx) {
    Weapon *w = ctx;
    if (Core.Player->walked <= 0) w->walkedW = 0, w->hasWalkedTimer = 0, w->pBonus = 0;
}
static void W_Vento2_Update(Weapon *w, float delta) {
    base_Update(w, delta);
    if (Core.Player->walked <= 0) {
        if (!w->hasWalkedTimer) w->walkedTimer = time_addEvent(0x1f4, 0, 0, W_Vento2_walkedCheck, w), w->hasWalkedTimer = 1;
    } else {
        time_removeEvent(w->walkedTimer);
        w->hasWalkedTimer = 0;
        w->walkedW += Core.Player->frameWalk;
        w->pBonus = fminf(4, w->walkedW / 0x30d40);
    }
    w->totalTime += delta;
    w->totalTime += Core.Player->frameWalk * (delta / w->mul);
    if (w->totalTime >= Weapon_PInterval(w)) { w->totalTime = 0; Weapon_Fire(w); }
    // _coinRT: la RenderTexture si ridisegna col fotogramma corrente di leafSprite (frameRef)
}
static const WeaponVT W_Vento2 = { BASE, .CheckArcanas = CA_slash, .bullet = &B_Vento2, .ctor = W_Vento2_ctor, .PPower = W_Vento2_PPower, .OnStart = W_Vento2_OnStart,
                                   .Update = W_Vento2_Update, .ResetFiringTimer = noop_ResetFiringTimer, .onBulletOverlapsEnemy = W_Vento2_onBulletOverlapsEnemy,
                                   .FireOneBullet = W_Vento2_FireOneBullet };

// --- Bone: W_Bone (0x41b2), B_Bone (0x6cd3) ---------------------------------------------------------------------
// Osso che rimbalza sui bordi dello schermo e sui nemici. BONE2 (Anima of Mortaccio): sotto, W_BoneGiant.
static void B_Bone_BounceMore(Bullet *b) { if (b->accelOnBounce) b->physBounce = 0.1f; }  // setBounce: il rimbalzo sui bordi usa worldBounce (1, 1)
static void B_Bone_Bounce(void *ctx) { Bullet *b = ctx; B_Bone_BounceMore(b); b->n_hit = 0; }  // 'worldbounds'
static void B_Bone_ctor(Bullet *b) {
    tweens_add((TweenConfig){ .props = { { &b->s.angle, NULL, 0x168 } }, .nprops = 1, .duration = 0x3e8, .repeat = -1 });  // AngleTween: gira per sempre
    b->BounceTimer = b->ExpireTimer = (Timer){ -1, 0 };
}
static void B_Bone_despawn(void *ctx) { Bullet_DeSpawn(ctx); }
static void B_Bone_OnRecycle(Bullet *b) {
    Weapon *w = b->weapon;
    Bullet_OnRecycle(b);
    body_setCircle(&b->s.body, 8, b->s.body.offset.x, b->s.body.offset.y);
    b->canBounce = 1;
    sprite_setScale(&b->s, 0.5f * PixelScale * Weapon_PArea(w));
    b->physBounce = 0;
    if (IsHalloween) sprite_setFrame(&b->s, frame_get("items", "pumpkin.png"));
    b->isCullable = 0;
    time_removeEvent(b->ExpireTimer);
    b->s.body.collideWorldBounds = 1, b->s.body.hasWorldBounce = 1, b->s.body.worldBounce = (Vector2){ 1, 1 };
    b->s.body.customBounds = &Core.Player->WorldBoxCollider;
    b->s.body.onWorldBounds = B_Bone_Bounce, b->s.body.onWorldBoundsCtx = b;
    Bullet_AimForRandomEnemy(b);
    b->s.angle = 0x168 * frand();
    tween_stop(b->ScaleTween);
    b->ScaleTween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, 0 } }, .nprops = 1, .duration = 0x1f4, .delay = Weapon_PDuration(w),
                                              .onComplete = B_Bone_despawn, .ctx = b });
    Sound_PlaySound("Shot", 0.45f, 1, -0x64 * b->indexInWeapon, 0xc8, 0xa);
}
static void B_Bone_canBounce(void *ctx) { ((Bullet *)ctx)->canBounce = 1; }
static void B_Bone_OnHasHitAnObject(Bullet *b, void *o, int isDead) {
    (void)o;
    if (isDead || !b->canBounce) return;
    B_Bone_BounceMore(b);
    b->canBounce = 0;
    time_removeEvent(b->BounceTimer);
    b->BounceTimer = time_addEvent(0x1e, 0, 0, B_Bone_canBounce, b);
    sprite_setVelocity(&b->s, b->s.body.velocity.x * -(1 + b->physBounce), b->s.body.velocity.y * -(1 + b->physBounce));
    b->n_hit = 0;
}
static void B_Bone_OnHasHitWall(Bullet *b, Tile *t) {
    b->save_vel_x *= t && (t->faceRight || t->faceLeft) ? -1 : 1;
    b->save_vel_y *= t && (t->faceTop || t->faceBottom) ? -1 : 1;
    sprite_setVelocity(&b->s, b->save_vel_x, b->save_vel_y);
    b->n_hit = 0;
}
static void B_Bone_Update(Bullet *b, float delta) {
    (void)delta;
    b->save_vel_x = b->s.body.velocity.x == 0 ? b->save_vel_x : b->s.body.velocity.x;
    b->save_vel_y = b->s.body.velocity.y == 0 ? b->save_vel_y : b->s.body.velocity.y;
}
static void B_Bone_DeSpawn(Bullet *b) {
    b->isCullable = 1;
    time_removeEvent(b->ExpireTimer);
    base_DeSpawn(b);
    if (b->weapon->explodeOnExpire) Weapon_SpawnExplosionAt(b->weapon, b->s.x, b->s.y, 0);  // trueWeapon
}
static const BulletVT B_Bone = { "vfx", "ProjectileBone2.png", B_Bone_ctor, NULL, B_Bone_OnRecycle, B_Bone_OnHasHitAnObject, B_Bone_Update, B_Bone_DeSpawn,
                                 NULL, NULL, B_Bone_OnHasHitWall };
// CheckArcanas (beginning, Twilight Requiem): arcane; SecondaryPPower: non usato
static const WeaponVT W_Bone = { BASE, .SecondaryPPower = power_noBloodline, .CheckArcanas = CA_inverseBeginning, .bullet = &B_Bone };

// --- Anima of Mortaccio: W_BoneGiant (0x1df7, BONE2) con B_Bone; braccia B_BoneGiant (0x8343, BONE_ARM) -------
// Lo scheletro fantasma di Mortaccio (testa, torso, aureola) segue il giocatore; ogni 6 colpi le due braccia girano e poi si staccano.
static void B_BoneArm_OnAttached(Bullet *b) {
    tween_stop(b->AngleTween);
    b->display.angle = 0;
    sprite_setOrigin(&b->display, 11.0f / 60, 13.0f / 60);
    b->display.x = b->anchor.x, b->display.y = b->anchor.y;
    b->s.x = b->display.x, b->s.y = b->display.y;
    b->isSpinning = 0, b->isAttached = 1;
    tween_stop(b->ScaleTween);
    sprite_setScale(&b->s, 1);
    sprite_setVelocity(&b->s, 0, 0);
    b->s.angle = 0;
}
static void B_BoneArm_attachDone(void *ctx) { B_BoneArm_OnAttached(ctx); }
static void B_BoneArm_Attach(Bullet *b) {
    Sound_PlaySound("Shot", 0.45f, 0.3f + 0.1f * b->indexInWeapon, 0, 0xc8, 0xa);
    tween_stop(b->attachTween);
    b->attachTween = tweens_add((TweenConfig){ .props = { { &b->s.x, NULL, b->anchor.x }, { &b->s.y, NULL, b->anchor.y } }, .nprops = 2, .duration = 0xc8,
                                               .onComplete = B_BoneArm_attachDone, .ctx = b });
}
static void B_BoneArm_Detach(Bullet *b, float spin) {
    Sound_PlaySound("Shot", 0.45f, 1, -0x64 * (0xa + b->indexInWeapon), 0xc8, 0xa);
    tween_stop(b->AngleTween);
    b->AngleTween = tweens_add((TweenConfig){ .props = { { &b->display.angle, NULL, b->s.angle + spin } }, .nprops = 1, .duration = 0x3e8, .repeat = -1 });
    b->isSpinning = 0, b->isAttached = 0;
    sprite_setOrigin(&b->display, 0.5f, 0.5f);
    b->n_hit = 0;
    Bullet_AimForRandomEnemy(b);
}
static void B_BoneArm_shot(void *ctx) { (void)ctx; Sound_PlaySound("Shot", 0.2f, 0.2f, 0, 0xc8, 0xa); }
static void B_BoneArm_Spinnn(Bullet *b, float spin, float duration, int repeat) {
    b->isSpinning = 1, b->isAttached = 0;
    B_BoneArm_shot(NULL);
    tween_stop(b->AngleTween);
    b->AngleTween = tweens_add((TweenConfig){ .props = { { &b->display.angle, NULL, b->s.angle + spin } }, .nprops = 1, .duration = duration, .repeat = repeat,
                                              .onRepeat = B_BoneArm_shot, .ctx = b });
}
static void B_BoneArm_ctor(Bullet *b) {
    static Animation idle;
    b->s.visible = 0;
    b->maxHistory = 2;
    b->BounceTimer = (Timer){ -1, 0 };
    b->AngleTween = b->ScaleTween = b->attachTween = (TweenRef){ -1, 0 };
    sprite_init(&b->display, frame_get("characters", "Gash_arm_i01.png"), b->s.x, b->s.y);
    sprite_setOrigin(&b->display, 11.0f / 60, 13.0f / 60);
    children_add(&b->display);
    if (!idle.n) make_anim(&idle, "characters", "Gash_arm_i", 1, 5, 2, 0x18, -1);
    anims_play(&b->display, &idle, 0);
    for (int i = 0; i < b->maxHistory; i++) {
        Sprite *g = &b->ghosts[i];
        b->posHistory[i] = (Vector2){ b->s.x, b->s.y };
        sprite_init(g, b->s.frame, 0, 0), g->visible = 0, g->alpha = 0.65f - 0.25f * i;
        g->tint = 0xe0e0ff;  // semplificazione: setTint a 4 angoli (e0e0ff, ff, e0e0ff, ff): qui il primo
        children_add(g);
    }
}
static void B_BoneArm_Bounce(void *ctx) { ((Bullet *)ctx)->n_hit = 0; }  // 'worldbounds'
static void B_BoneArm_despawn(void *ctx) { Bullet_DeSpawn(ctx); }
static void B_BoneArm_scaleStart(void *ctx) { sprite_setScale(&((Bullet *)ctx)->display, 1); }
static void B_BoneArm_OnRecycle(Bullet *b) {
    Bullet_OnRecycle(b);
    body_setCircle(&b->s.body, 0xe, 0xe, 0xe);
    b->s.visible = 0;
    b->canBounce = 1;
    sprite_setScale(&b->s, 1);  // setBounce(1.1): sui bordi vale worldBounce (1, 1), come B_Bone
    b->isCullable = 0, b->isAttached = b->isSpinning = 0;
    b->s.body.collideWorldBounds = 1, b->s.body.hasWorldBounce = 1, b->s.body.worldBounce = (Vector2){ 1, 1 };
    b->s.body.customBounds = &Core.Player->WorldBoxCollider;
    b->s.body.onWorldBounds = B_BoneArm_Bounce, b->s.body.onWorldBoundsCtx = b;
    sprite_setScale(&b->display, 1);
    Bullet_AimForRandomEnemy(b);
    tween_stop(b->ScaleTween);
    b->ScaleTween = tweens_add((TweenConfig){ .props = { { &b->display.scaleX, &b->display.scaleY, 0 } }, .nprops = 1, .duration = 0x64, .delay = Weapon_PDuration(b->weapon),
                                              .onStart = B_BoneArm_scaleStart, .onComplete = B_BoneArm_despawn, .ctx = b });
}
static void B_BoneArm_OnHasHitAnObject(Bullet *b, void *o, int isDead) {
    (void)o;
    if (isDead || !b->canBounce || b->isAttached) return;
    b->canBounce = 0;
    time_removeEvent(b->BounceTimer);
    b->BounceTimer = time_addEvent(0x1e, 0, 0, B_Bone_canBounce, b);
    sprite_setVelocity(&b->s, -1.1f * b->s.body.velocity.x, -1.1f * b->s.body.velocity.y);
    b->n_hit = 0;
}
static void B_BoneArm_UpdateGhosts(Bullet *b, int visible) {
    b->historyIndex = b->historyIndex < b->maxHistory - 1 ? b->historyIndex + 1 : 0;
    float sc = 0.5f * (b->display.scaleX + b->display.scaleY);  // displaySprite.scale
    for (int i = 0; i < b->maxHistory; i++) {
        Vector2 h = b->posHistory[getHistoryIndex(b, i)];
        Sprite *g = &b->ghosts[i];
        g->angle = b->display.angle, g->x = h.x, g->y = h.y, g->scaleX = g->scaleY = sc, g->visible = visible;
    }
    b->posHistory[b->historyIndex] = (Vector2){ b->s.x, b->s.y };
}
static void B_BoneArm_AdjustBodyOffset(Bullet *b) {  // il corpo sta sulla mano, non sul perno
    float sc = 0.5f * (b->display.scaleX + b->display.scaleY);
    float r = (sc > 0 ? b->display.angle : b->display.angle + 0xb4) * DEG2RAD, c = cosf(r), s = sinf(r);
    if (sc > 0) b->s.x = b->display.x - 0x1c * s + 0x24 * c, b->s.y = b->display.y + 0x1c * c + 0x24 * s;
    else b->s.x = b->display.x + (0x1c * s + 0x24 * c), b->s.y = b->display.y - (0x1c * c - 0x24 * s);
}
static void B_BoneArm_Update(Bullet *b, float delta) {
    (void)delta;
    if (b->isSpinning || b->isAttached) {
        b->display.x = b->anchor.x, b->display.y = b->anchor.y;
        b->s.x = b->display.x, b->s.y = b->display.y;
        B_BoneArm_AdjustBodyOffset(b);
        B_BoneArm_UpdateGhosts(b, 0);
        return;
    }
    b->save_vel_x = b->s.body.velocity.x == 0 ? b->save_vel_x : b->s.body.velocity.x;
    b->save_vel_y = b->s.body.velocity.y == 0 ? b->save_vel_y : b->s.body.velocity.y;
    b->display.x = b->s.x, b->display.y = b->s.y;  // copyPosition
    B_BoneArm_UpdateGhosts(b, 1);
}
static void B_BoneArm_DeSpawn(Bullet *b) {
    b->isCullable = 1;
    for (int i = 0; i < b->maxHistory; i++) b->ghosts[i].visible = 0;
    base_DeSpawn(b);
}
// OnHasHitWall: il pool delle braccia non ha collider coi muri
static const BulletVT B_BoneGiant = { "vfx", "Gash_arm_i01.png", B_BoneArm_ctor, NULL, B_BoneArm_OnRecycle, B_BoneArm_OnHasHitAnObject, B_BoneArm_Update, B_BoneArm_DeSpawn };

static Bullet *W_BoneGiant_FireOneBullet(Weapon *w, float x, float y, int index) {
    Bullet *b = BulletPool_SpawnAt(w->pool, x, y, w, index);
    if (b) b->accelOnBounce = 1;
    return b;
}
static void W_BoneGiant_attachBack(void *ctx) { B_BoneArm_Attach(((Weapon *)ctx)->backArm); }
static void W_BoneGiant_AttachArms(void *ctx) {
    Weapon *w = ctx;
    w->AreArmsAttached = 1;
    B_BoneArm_Attach(w->frontArm);
    time_addEvent(0x64, 0, 0, W_BoneGiant_attachBack, w);  // semplificazione: setTimeout va col tempo reale, qui col Clock della scena
    w->isAttacking = 0;
}
static void W_BoneGiant_detachBack(void *ctx) { B_BoneArm_Detach(((Weapon *)ctx)->backArm, -0x168); }
static void W_BoneGiant_DetachArms(void *ctx) {
    Weapon *w = ctx;
    w->AreArmsAttached = 0;
    B_BoneArm_Detach(w->frontArm, 0x168);
    time_addEvent(0x64, 0, 0, W_BoneGiant_detachBack, w);  // setTimeout, come sopra
    time_addEvent(fmaxf(0xfa0, floorf(Weapon_PDuration(w))), 0, 0, W_BoneGiant_AttachArms, w);
}
static void W_BoneGiant_SpinArms(Weapon *w) {
    w->isAttacking = 1, w->AreArmsAttached = 1;
    int n = (int)fmaxf(8, floorf(Weapon_PDuration(w) / 0x1f4));
    B_BoneArm_Spinnn(w->frontArm, -0x167, 0x1f4, n), B_BoneArm_Spinnn(w->backArm, 0x167, 0x1f4, n);
    time_addEvent(0x1f4 * n, 0, 0, W_BoneGiant_DetachArms, w);
}
static void W_BoneGiant_Fire(Weapon *w) {
    base_Fire(w);
    if (++w->firedTimes >= 6 && !w->isAttacking) w->firedTimes = 0, W_BoneGiant_SpinArms(w);  // secondaryFireCounter
}
static void W_BoneGiant_onGiantArmOverlapsEnemy(void *ctx, Sprite *bs, Sprite *es) {
    Weapon *w = ctx;
    Enemy *e = es->owner;
    if (e->isDead || Bullet_HasAlreadyHitObject(bs->owner, e, e->isDead)) return;
    float p = Weapon_PPower(w) * (0.5f * Weapon_PAmount(w));
    Enemy_GetDamaged(e, p, (int)w->hitVFX, w->knockback, w->bulletType);
    w->stats_inflictedDamage += p;
}
static void W_BoneGiant_InitSkeleton(Weapon *w) {
    static Animation idle;
    w->topDepth = game_height;
    w->frontArm = BulletPool_SpawnAt(w->armPool, 0, 0, w, 0), B_BoneArm_Attach(w->frontArm);
    w->backArm = BulletPool_SpawnAt(w->armPool, 0, 0, w, 1), B_BoneArm_Attach(w->backArm);
    sprite_init(&w->head, frame_get("characters", "Gash_head_i01.png"), 0, 0), children_add(&w->head);
    if (!idle.n) make_anim(&idle, "characters", "Gash_head_i", 1, 5, 2, 0x18, -1);
    anims_play(&w->head, &idle, 0);
    sprite_init(&w->torso, frame_get("characters", "Gash_body_i01.png"), 0, 0), children_add(&w->torso);
    sprite_init(&w->halo, frame_get("characters", "Halo.png"), 0, 0), w->halo.depth = -1, sprite_setOrigin(&w->halo, 0.5f, 1), children_add(&w->halo);
    w->head.tint = w->torso.tint = 0xe0e0ff;  // semplificazione: setTint a 4 angoli (e0e0ff, ff, e0e0ff, ff): qui il primo
    w->head.alpha = 0.65f, w->head.depth = -1, sprite_setOrigin(&w->head, 0, 0);
    w->torso.alpha = 0.65f, w->torso.depth = -2, sprite_setOrigin(&w->torso, 0.5f, 1);
    physics_addOverlap(&w->armPool->group, &Core.Enemies, W_BoneGiant_onGiantArmOverlapsEnemy, w);
    physics_addOverlap(&w->armPool->group, &Core.Destructibles, Weapon_onBulletOverlapsDestuctible, w);
}
static void W_BoneGiant_UpdateSkeleton(Weapon *w) {
    Sprite *P = &Core.Player->s;
    w->torso.x = P->x, w->torso.y = P->y, w->torso.flipX = P->flipX;  // copyPosition
    float x0 = w->torso.x - 0x1f, y0 = w->torso.y - 0x31;
    int fx = w->torso.flipX;
    w->head.flipX = fx;
    w->head.x = x0 + (fx ? -0x1a : 0x34), w->head.y = y0 - 0x15;
    w->halo.x = w->head.x + (fx ? 0x1e : 0xc), w->halo.y = w->head.y - 1;
    Bullet *f = w->frontArm, *k = w->backArm;
    if (w->AreArmsAttached) {
        f->display.scaleX = k->display.scaleX = fx ? -1 : 1, f->display.scaleY = k->display.scaleY = 1;
        f->display.depth = 1, k->display.depth = -3;
    } else f->display.depth = k->display.depth = w->topDepth;
    f->anchor = (Vector2){ x0 + (fx ? 0x15 : 0x2c), y0 + 0xa };
    k->anchor = (Vector2){ x0 + (fx ? 0x4 : 0x3d), y0 + 0x16 };
}
static void W_BoneGiant_Update(Weapon *w, float delta) {
    base_Update(w, delta);
    if (!w->hasSkeleton) W_BoneGiant_InitSkeleton(w), w->hasSkeleton = 1;
    W_BoneGiant_UpdateSkeleton(w);
}
static void W_BoneGiant_ctor(Weapon *w) { w->AreArmsAttached = 1, w->armPool = BulletPool_new(w, &B_BoneGiant); }
static const WeaponVT W_BoneGiant = { BASE, .SecondaryPPower = power_noBloodline, .CheckArcanas = CA_inverseBeginning, .bullet = &B_Bone, .ctor = W_BoneGiant_ctor,
                                      .Fire = W_BoneGiant_Fire, .Update = W_BoneGiant_Update, .FireOneBullet = W_BoneGiant_FireOneBullet };

// --- Cherry Bomb: W_Cherry (0x3e35), B_Cherry (0xe3ce) -----------------------------------------------------------
// Bomba che rimbalza sui nemici, rallenta e poi esplode con probabilita' chance * Luck (fuochi d'artificio), altrimenti sparisce.
// CHERRY2 (Yatta Daikarin, 0xf01f): arma speciale del personaggio, con i personaggi; isStars (SetToStars): idem.
static void B_Cherry_ctor(Bullet *b) {
    static const unsigned TINTS[4] = { 0xff8888, 0xff88ff, 0xff88ff, 0xffff88 };
    static const char *const blur[3] = { "_blur.png", "_blur2.png", "_blur3.png" };
    Weapon *w = b->weapon;
    b->bombDeceleration = 1;
    b->canBounce = 1;
    sprite_init(&b->ring, frame_get("vfx", "sPFX_ring_64.png"), 0, 0), b->ring.visible = 0, children_add(&b->ring);
    sprite_init(&b->rainbow, frame_get("vfx", "s_pfx_rainbow_64.png"), 0, 0), b->rainbow.visible = 0, children_add(&b->rainbow);
    sprite_init(&b->rays, frame_get("vfx", "fuzzA.png"), 0, 0), b->rays.visible = 0, children_add(&b->rays);
    tweens_add((TweenConfig){ .props = { { &b->s.angle, NULL, 0x167 } }, .nprops = 1, .duration = 0x3e8, .repeat = -1 });  // AngleTween
    b->Pfx = particles_add();  // particles('vfx')
    b->PfxEmitter = particles_createEmitter(b->Pfx, (EmitterConfig){ .frames = { frame_get("vfx", blur[b->indexInWeapon % 3]) }, .nframes = 1,
        .lifespan = EOP(0x320), .rotate = ERND(0, 0x168), .alpha = { 0, 1, 2, Ease_ExpoOut }, .angle = { 0, 0x168, 1 }, .angleSteps = 0x10,
        .speed = ERND(0x32, 0x64), .quantity = 0x40, .scale = ERANGE(2, 0), .frequency = 0x40, .blendAdd = 1, .on = 0 });
    b->Pfx2 = particles_add();  // particles('cherryBomb0'): la RenderTexture con la foglia animata
    b->PfxEmitter2 = particles_createEmitter(b->Pfx2, (EmitterConfig){ .frameRef = &w->leafSprite.frame,
        .lifespan = EOP(0x4b0), .rotate = ERND(0, 0x168), .alpha = { 0, 1, 2, Ease_ExpoOut }, .angle = { 0, 0x168, 1 }, .angleSteps = 0x1f,
        .speed = ERND(0x32, 0x64), .quantity = 0x40, .scale = ERANGE(2, 0.1f), .frequency = 0x40, .tints = { TINTS[0], TINTS[1], TINTS[2], TINTS[3] }, .ntints = 4,
        .blendAdd = 1, .on = 0 });
    b->BounceTimer = b->ExpireTimer = (Timer){ -1, 0 };
    b->SpeedTween = b->ScaleTween = TWEEN_NONE;
}
static void B_Cherry_despawn(void *ctx) { Bullet_DeSpawn(ctx); }
static void B_Cherry_tween5Done(void *ctx) { Bullet *b = ctx; emitter_stop(b->PfxEmitter), emitter_stop(b->PfxEmitter2); b->s.body.enable = 0; }
static void B_Cherry_tween6Start(void *ctx) { Bullet *b = ctx; b->PfxEmitter->x = b->s.x, b->PfxEmitter->y = b->s.y; emitter_start(b->PfxEmitter); }  // FlashingVFXEnabled
static void B_Cherry_tween6Done(void *ctx) { Bullet *b = ctx; emitter_stop(b->PfxEmitter), emitter_stop(b->PfxEmitter2); Bullet_DeSpawn(b); }
static void B_Cherry_TryDetonate(void *ctx) {
    Bullet *b = ctx;
    Weapon *w = b->weapon;
    if (frand() < w->chance * Player_PLuck(Core.Player)) {  // PLuck
        b->s.visible = 1;  // FlashingVFXEnabled
        sprite_setFrame(&b->s, frame_get("items", "blurBlack.png"));
        b->PfxEmitter2->x = b->s.x, b->PfxEmitter2->y = b->s.y;
        emitter_start(b->PfxEmitter2);
        b->ring.visible = 1, sprite_setScale(&b->ring, 0), b->ring.alpha = 1, b->ring.angle = 0, b->ring.x = b->s.x, b->ring.y = b->s.y;
        b->rainbow.visible = 1, sprite_setScale(&b->rainbow, 0), b->rainbow.alpha = 0.75f, b->rainbow.angle = 0, b->rainbow.x = b->s.x, b->rainbow.y = b->s.y, b->rainbow.blendAdd = 1;
        b->rays.visible = 1, sprite_setScale(&b->rays, 0), b->rays.alpha = 1, b->rays.angle = 0, b->rays.x = b->s.x, b->rays.y = b->s.y;
        float k = fmaxf(3, w->level) / 8;
        tweens_add((TweenConfig){ .props = { { &b->ring.scaleX, &b->ring.scaleY, 4 * k }, { &b->ring.angle, NULL, 0x168 } }, .nprops = 2, .duration = 0x64 });
        tweens_add((TweenConfig){ .props = { { &b->ring.alpha, NULL, 0 }, { &b->rays.alpha, NULL, 0 } }, .nprops = 2, .delay = 0x64, .duration = 0x64 });
        tweens_add((TweenConfig){ .props = { { &b->rays.scaleX, &b->rays.scaleY, 3 * k } }, .nprops = 1, .duration = 0x64 });
        tweens_add((TweenConfig){ .props = { { &b->rainbow.scaleX, &b->rainbow.scaleY, 5 * k }, { &b->rainbow.alpha, NULL, 0 }, { &b->rainbow.angle, NULL, 0x168 } },
                                  .nprops = 3, .duration = 0x1f4 });
        Sound_PlaySound("Explosion2", 0.5f, 1, 0x64 * b->indexInWeapon - 0x1f4, 0x96, 3);
        Sound_PlaySound("Whistle", 0.1f, 1.5f, 0x64 * b->indexInWeapon, 0x96, 3);
        tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, 8 * Weapon_PArea(w) }, { &b->s.alpha, NULL, 0.1f } }, .nprops = 2, .duration = 0x78,
                                  .onComplete = B_Cherry_tween5Done, .ctx = b });
        tweens_add((TweenConfig){ .props = { { &b->s.alpha, NULL, 0.1f } }, .nprops = 1, .duration = 0x64, .delay = 0xc8,
                                  .onStart = B_Cherry_tween6Start, .onComplete = B_Cherry_tween6Done, .ctx = b });
    } else {
        tween_stop(b->ScaleTween);
        b->ScaleTween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, 0 } }, .nprops = 1, .duration = 0x12c, .onComplete = B_Cherry_despawn, .ctx = b });
    }
}
static void B_Cherry_OnRecycle(Bullet *b) {
    Weapon *w = b->weapon;
    float a = Weapon_PArea(w);
    Bullet_OnRecycle(b);
    body_setCircle(&b->s.body, 8, b->s.body.offset.x, b->s.body.offset.y);
    b->s.body.enable = 1;
    b->canBounce = 1;
    b->s.visible = 1;
    sprite_setFrame(&b->s, frame_get("items", IsHalloween ? "pumpkin.png" : "Cherry.png"));
    b->s.alpha = 1;
    sprite_setScale(&b->s, PixelScale * a * 0.5f);
    // setBounce(1, 1): senza collideWorldBounds ne' collider, nessun effetto
    b->PfxEmitter->c.quantity = 8 + 4 * (int)floorf(w->level / 3.0f);
    b->PfxEmitter->c.speed = ERND(0x32 * a, 0x64 * a);
    b->PfxEmitter2->c.quantity = 8 + 8 * (int)floorf(w->level / 3.0f);
    b->PfxEmitter2->c.speed = ERND(5 * a, 0xa * a);
    b->PfxEmitter2->c.hasZone = 1, b->PfxEmitter2->c.zoneRadius = 8 * a * 8;
    if (w->isStars) {  // TrueWeapon.isStars: fuochi a stelle colorate, stelle al posto delle foglie
        static const char *const C3[3] = { "Blue", "Purple", "Red" };
        static const unsigned T2[4] = { 0x4444ff, 0xff44ff, 0xff44ff, 0xff4444 };
        char f1[32], f2[32];
        snprintf(f1, sizeof(f1), "2Spell3%s.png", C3[b->indexInWeapon % 3]), snprintf(f2, sizeof(f2), "2Spell4%s.png", C3[b->indexInWeapon % 3]);
        b->PfxEmitter->c.frames[0] = frame_get("vfx", f1), b->PfxEmitter->c.frames[1] = frame_get("vfx", f2), b->PfxEmitter->c.nframes = 2;
        b->PfxEmitter->c.scale = ERANGE(3, 0);
        for (int i = 0; i < 4; i++) b->PfxEmitter2->c.tints[i] = T2[i];
        b->PfxEmitter2->c.scale = ERANGE(1, 0.05f);  // la stella e' disegnata a scala 0.5 nella RenderTexture 16x16: qui il fotogramma intero a meta' scala
    }
    b->isCullable = 0;
    time_removeEvent(b->ExpireTimer);
    b->save_vel_x = b->save_vel_y = 1;
    Sprite *t = physics_closest(&Core.Player->s, &Core.Enemies);  // SetForNearestEnemy(aimVec)
    float dx, dy;
    if (!t) {
        Vector2 *d = &Core.Player->lastFacedDirection;
        float l = sqrtf(d->x * d->x + d->y * d->y);
        if (l > 0) d->x /= l, d->y /= l;
        if (d->x == 0 && d->y == 0) d->x = 1;
        dx = d->x, dy = d->y;
    } else {
        dx = t->body.position.x - Core.Player->s.x, dy = t->body.position.y - Core.Player->s.y;
        float l = sqrtf(dx * dx + dy * dy);
        if (l > 0) dx /= l, dy /= l;
    }
    b->aimVec = (Vector2){ Bullet_TrueSpeed(b) * dx, Bullet_TrueSpeed(b) * dy };
    sprite_setVelocity(&b->s, b->aimVec.x, b->aimVec.y);
    tween_stop(b->SpeedTween);
    b->bombDeceleration = 1;
    b->SpeedTween = tweens_add((TweenConfig){ .props = { { &b->bombDeceleration, NULL, 0 } }, .nprops = 1, .delay = 0.25f * Weapon_PDuration(w),
                                              .duration = 0.75f * Weapon_PDuration(w), .onComplete = B_Cherry_TryDetonate, .ctx = b });
    Sound_PlaySound("Shot", 0.45f, 1, -0x64 * b->indexInWeapon, 0xc8, 0xa);
}
static void B_Cherry_canBounce(void *ctx) { ((Bullet *)ctx)->canBounce = 1; }
static void B_Cherry_OnHasHitAnObject(Bullet *b, void *o, int isDead) {
    (void)o;
    if (isDead || !b->canBounce) return;
    b->save_vel_x *= -1, b->save_vel_y *= -1;
    b->n_hit = 0;
    b->canBounce = 0;
    time_removeEvent(b->BounceTimer);
    b->BounceTimer = time_addEvent(0x3c, 0, 0, B_Cherry_canBounce, b);
}
static void B_Cherry_OnHasHitWall(Bullet *b, Tile *t) {
    b->save_vel_x *= t && (t->faceRight || t->faceLeft) ? -1 : 1;
    b->save_vel_y *= t && (t->faceTop || t->faceBottom) ? -1 : 1;
    b->n_hit = 0;
}
static void B_Cherry_Update(Bullet *b, float delta) {
    (void)delta;
    sprite_setVelocity(&b->s, b->aimVec.x * b->save_vel_x * b->bombDeceleration, b->aimVec.y * b->save_vel_y * b->bombDeceleration);
}
static void B_Cherry_DeSpawn(Bullet *b) {
    b->isCullable = 1;
    time_removeEvent(b->ExpireTimer);
    emitter_stop(b->PfxEmitter), emitter_stop(b->PfxEmitter2);
    base_DeSpawn(b);
}
static const BulletVT B_Cherry = { "items", "Cherry.png", B_Cherry_ctor, NULL, B_Cherry_OnRecycle, B_Cherry_OnHasHitAnObject, B_Cherry_Update, B_Cherry_DeSpawn,
                                   NULL, NULL, B_Cherry_OnHasHitWall };
