    static Animation spin;
    if (!spin.n) make_anim(&spin, "vfx", "leaf", 0, 0x13, 4, 0x1e, -1);  // leaf0000..leaf0019, frameRate [30,20,24,14][0]
    sprite_init(&w->leafSprite, frame_get("vfx", "leaf0000.png"), -1e9f, -1e9f);
