static const WeaponVT W_Cherry = { BASE, .CheckArcanas = CA_inverseBeginning, .bullet = &B_Cherry, .ctor = W_Cherry_ctor };

// --- Cherry Stars / Yatta Daikarin: W_CherryStars (0xf01f, CHERRY2), B_CherryStar (0x1438f), B_CherryStarExplosion (0x139b8) ---------
// La bomba fa stelle invece di foglie; un "disegnatore" corre tra 7 punti vicini al giocatore lasciando stelle e scia, poi le fa esplodere.
static void W_Cherry_SetToStars(Weapon *w) {
    static Animation star;
    w->isStars = 1;
    if (!star.n) make_anim(&star, "vfx", "image_004_", 0, 0x16, 4, 0x10, -1);
    anims_play(&w->leafSprite, &star, 0);
    sprite_setScale(&w->leafSprite, 0.5f);
}
static void CherryStar_trailDraw(Sprite *s) {  // come Diamond: ogni passata col lineStyle dell'ultimo segmento; spessori 3 e 1.5
    Bullet *b = s->owner;
    if (b->nStarTrail < 2 || b->trailAlpha <= 0) return;
    float ox = b->trail.x - camera_scrollX, oy = b->trail.y - camera_scrollY, al = fminf(1, b->trailAlpha);
    Vector2 *P = b->starTrail;
    BeginBlendMode(BLEND_ADDITIVE);
    float a = fminf(1, 1.0f / ((b->nStarTrail - 1) / 20.0f)) * al;
    for (int i = 1; i < b->nStarTrail; i++) DrawLineEx((Vector2){ ox + P[i - 1].x, oy + P[i - 1].y }, (Vector2){ ox + P[i].x, oy + P[i].y }, 3, hexc(b->color, a));
    int last = 0;
    for (int i = 1; i < 0xc8 && i < b->nStarTrail; i++) last = i;
    if (last) {
        a = fminf(1, 0.8f / (last / 20.0f)) * al;
        for (int i = 1; i <= last; i++) DrawLineEx((Vector2){ ox + P[i - 1].x, oy + P[i - 1].y }, (Vector2){ ox + P[i].x, oy + P[i].y }, 1.5f, hexc(0xffffff, a));
    }
    EndBlendMode();
}
static void B_CherryStar_ctor(Bullet *b) {
    b->color = 0xff0000;
    sprite_init(&b->trail, NULL, 0, 0);
    b->trail.owner = b, b->trail.draw = CherryStar_trailDraw;
    children_add(&b->trail);
    b->isCullable = 0;
    b->stars1 = gmem_calloc(7, sizeof(Sprite)), b->stars2 = gmem_calloc(7, sizeof(Sprite)), b->starTrail = gmem_calloc(0x190, sizeof(Vector2));
    for (int i = 0; i < 7; i++) {
        Sprite *a = &b->stars1[i], *c = &b->stars2[i];
        sprite_init(a, frame_get("vfx", "2Spell4Blue.png"), 0, 0), a->scaleX = 1, a->scaleY = 4, a->visible = 0, a->alpha = 0.65f, children_add(a);
        sprite_init(c, frame_get("vfx", "2Spell4Red.png"), 0, 0), c->scaleX = 1, c->scaleY = 4, c->angle = 0x2d, c->visible = 0, c->alpha = 0.65f, children_add(c);
        tweens_add((TweenConfig){ .props = { { &a->angle, NULL, 0x2d0 }, { &a->scaleX, NULL, 4 }, { &a->scaleY, NULL, 1 } }, .nprops = 3, .duration = 0x3e8, .yoyo = 1, .repeat = -1 });
        tweens_add((TweenConfig){ .props = { { &c->angle, NULL, 0x2fd }, { &c->scaleX, NULL, 1 }, { &c->scaleY, NULL, 4 } }, .nprops = 3, .duration = 0x40f, .yoyo = 1, .repeat = -1 });
    }
    tweens_add((TweenConfig){ .props = { { &b->s.angle, NULL, 0x2d0 }, { &b->s.scaleX, NULL, 4 }, { &b->s.scaleY, NULL, 1 } }, .nprops = 3, .duration = 0x3e8, .yoyo = 1, .repeat = -1 });
    b->BounceTimer = (Timer){ -1, 0 };
}
static void B_CherryStar_PickNewTarget(Bullet *b) {
    b->n_hit = 0;
    float m = fminf(game_width, game_height);
    Vector2 t = { Core.Player->s.x - (frand() - 0.5f) * m, Core.Player->s.y - (frand() - 0.5f) * m };
    b->lastTargets[0] = b->lastTargets[1], b->lastTargets[1] = b->lastTargets[2], b->lastTargets[2] = t;  // targets.push: servono gli ultimi tre
    b->nTargets++;
    if (frand() < 0.3f && b->nTargets > 2) {  // a volte riparte da uno dei due bersagli precedenti
        Vector2 o = b->lastTargets[frand() >= 0.5f ? 1 : 0];
        b->s.x = o.x, b->s.y = o.y;
    }
    b->starTarget = t;
    float a = atan2f(b->s.y - t.y, b->s.x - t.x);
    b->starSin = fabsf(sinf(a)), b->starCos = fabsf(cosf(a));
}
static void B_CherryStar_OnRecycle(Bullet *b) {
    Bullet_OnRecycle(b);
    body_setCircle(&b->s.body, 9, -4.5f, -4.5f);
    b->isCullable = 0;
    sprite_setScale(&b->s, 2);
    b->trail.x = b->s.x - Core.Player->s.x, b->trail.y = b->s.y - Core.Player->s.y;  // (sic) come Diamond
    b->color = 0xffffff, b->trailAlpha = 1, b->s.alpha = 1;
    b->nStarTrail = 0;
    B_CherryStar_PickNewTarget(b);
    b->canUpdate = 1;
}
static void B_CherryStar_DeSpawn(Bullet *b) { (void)b; }  // il disegnatore non sparisce mai
static void B_CherryStar_resume(void *ctx) { Bullet *b = ctx; b->trailAlpha = 1, b->canUpdate = 1; }
static void B_CherryStar_StartTimer(void *ctx) { Bullet *b = ctx; b->BounceTimer = time_addEvent(0x1f4, 0, 0, B_CherryStar_resume, b); }
static void B_CherryStar_ExplodeAll(Bullet *b) {
    Weapon *w = b->weapon;
    for (int i = 0; i < 7; i++) BulletPool_SpawnAt(w->explosionPool, b->stars1[i].x, b->stars1[i].y, w, i);  // ShootStarAt
    tweens_add((TweenConfig){ .props = { { &b->trailAlpha, NULL, 2 } }, .nprops = 1, .duration = 0x1f4 });
    tweens_add((TweenConfig){ .props = { { &b->trailAlpha, NULL, 0 } }, .nprops = 1, .duration = 0x1f4, .delay = 0x1f4 });
    for (int i = 0; i < 7; i++) {
        tweens_add((TweenConfig){ .props = { { &b->stars1[i].alpha, NULL, 0 } }, .nprops = 1, .duration = 0x1f4, .delay = 0x1f4 });
        tweens_add((TweenConfig){ .props = { { &b->stars2[i].alpha, NULL, 0 } }, .nprops = 1, .duration = 0x1f4, .delay = 0x1f4 });
    }
    time_addEvent(0x1f4 + 0x32 * 7, 0, 0, B_CherryStar_StartTimer, b);
}
static float Approach(float v, float to, float d);
static void B_CherryStar_Update(Bullet *b, float delta) {
    if (!b->canUpdate) return;
    b->trail.depth = b->s.y - Core.Player->s.y + 0.5f * game_height;
    for (int k = 0, n = (int)ceilf(delta / 16); k < n; k++) {  // trailUpdate (sempre attivo): unshift, al massimo 400
        int m = b->nStarTrail < 0x190 ? b->nStarTrail : 0x18f;
        memmove(&b->starTrail[1], &b->starTrail[0], m * sizeof(Vector2));
        b->starTrail[0] = (Vector2){ b->s.x, b->s.y };
        b->nStarTrail = m + 1;
    }
    float step = 0.5f * Weapon_PSpeed(b->weapon) * delta;
    b->s.x = Approach(b->s.x, b->starTarget.x, step * b->starCos);
    b->s.y = Approach(b->s.y, b->starTarget.y, step * b->starSin);
    if (b->s.x == b->starTarget.x && b->s.y == b->starTarget.y) {
        Sprite *a = &b->stars1[b->starIndex], *c = &b->stars2[b->starIndex];  // MakeStar
        a->x = c->x = b->starTarget.x, a->y = c->y = b->starTarget.y;
        a->visible = c->visible = 1, a->alpha = c->alpha = 0.65f;
        b->starIndex++;
        B_CherryStar_PickNewTarget(b);
        b->canUpdate = 0;
        time_removeEvent(b->BounceTimer);  // CheckTimer
        if (++b->bouncedTimes >= 7) b->starIndex = 0, B_CherryStar_ExplodeAll(b), b->bouncedTimes = 0, b->nStarTrail = 0;
        else B_CherryStar_StartTimer(b);
    }
}
