static float W_CherryStars_SecondaryPPower(Weapon *w) {
    float c = w->critChancesArray[w->critIndex % 1000];
    w->critIndex++;
    float crit = c < w->critChance * Player_PLuck(Core.Player) ? Player_PLuck(Core.Player) * Arcanas.CritMul : 1;
    return fminf(10, (Arcanas.silentMight + Core.Player->power) * sinev(Core.Player->sineMight)) * (w->power * Weapon_PAmount(w) * crit) + Arcanas.bloodlineDamage;
}
static void W_CherryStars_ctor(Weapon *w) { W_Cherry_ctor(w); w->critChance = 0.05f; }
static void W_CherryStars_Fire(Weapon *w) {
    base_Fire(w);
    if (w->hasBullets) return;
    w->hasBullets = 1;  // InitBullets
    w->drawerPool = BulletPool_new(w, &B_CherryStar);
    physics_addOverlap(&w->drawerPool->group, &Core.Enemies, Weapon_onSecondaryBulletOverlapsEnemy, w);
    physics_addOverlap(&w->drawerPool->group, &Core.Destructibles, Weapon_onBulletOverlapsDestuctible, w);
    w->explosionPool = BulletPool_new(w, &B_CherryStarExplosion);
    physics_addOverlap(&w->explosionPool->group, &Core.Enemies, Weapon_onSecondaryBulletOverlapsEnemy, w);
    physics_addOverlap(&w->explosionPool->group, &Core.Destructibles, Weapon_onBulletOverlapsDestuctible, w);
    BulletPool_SpawnAt(w->drawerPool, Core.Player->s.x, Core.Player->s.y, w, 0);  // BulletA
}
static void W_CherryStars_Update(Weapon *w, float delta) {
    base_Update(w, delta);
    if (!w->hasImage) {  // InitImage: la mucca fantasma dietro al giocatore
        static Animation idle;
        w->hasImage = 1;
        if (!idle.n) make_anim(&idle, "characters", "yattaCowi0", 1, 4, 0, 8, -1);
        sprite_init(&w->cow, frame_get("characters", "yattaCowi01.png"), 0, 0);
        children_add(&w->cow);
        anims_play(&w->cow, &idle, 0);
        w->cow.alpha = 0.65f, w->cow.depth = -2;
        sprite_setOrigin(&w->cow, 0.5f, 1);
    }
    w->cow.x = Core.Player->s.x, w->cow.y = Core.Player->s.y, w->cow.flipX = Core.Player->s.flipX;  // UpdateImage
}
static const WeaponVT W_CherryStars = { BASE, .CheckArcanas = CA_inverseBeginning, .bullet = &B_Cherry, .ctor = W_CherryStars_ctor, .SecondaryPPower = W_CherryStars_SecondaryPPower,
                                        .Fire = W_CherryStars_Fire, .Update = W_CherryStars_Update };

// --- Carréllo: W_Cart2 (0x13a01), B_Cart2 (0x9494) --------------------------------------------------------------
// Carrello che corre in orizzontale e rimbalza sui bordi dello schermo (rimbalzi = Amount), con le scintille.
static Animation Cart_end, Cart_idle;
static void B_Cart2_ctor(Bullet *b) {
    if (!Cart_end.n) make_anim(&Cart_end, "vfx", "CartEnd_", 0, 0x1d, 0, 0x1e, 0), make_anim(&Cart_idle, "vfx", "CartEnd_", 0, 0, 0, 0x1e, 0);
    b->makeSparks = 1;
    b->Pfx = particles_add();
    b->PfxEmitter = particles_createEmitter(b->Pfx, (EmitterConfig){ .frames = { frame_get("vfx", "PfxYellow.png") }, .nframes = 1, .rotate = ERND(0, 0x168),
        .speed = ERND(0x32, 0x64), .quantity = 1, .lifespan = EOP(0xc8), .scale = ERANGE(1, 0), .on = 0 });
    b->defaultSpeed = b->_speed;
    b->disappearTween = b->enterTween = TWEEN_NONE;
}
static void B_Cart2_vanish(void *ctx) { Bullet *b = ctx; b->s.visible = 0; Bullet_DeSpawn(b); }
static void B_Cart2_FadeOut(Bullet *b) {
    b->isFadingOut = 1;
    b->s.body.velocity = (Vector2){ 0, 0 };
    b->makeSparks = 0;
    Sound_PlaySound("Carrello", 1, 2, -0xc8 * frand(), 0x96, 2);
    tween_stop(b->disappearTween);
    b->disappearTween = tweens_add((TweenConfig){ .props = { { &b->s.x, NULL, b->s.x + -0.5f * b->save_vel_x }, { &b->s.scaleX, &b->s.scaleY, 1.5f * b->s.scaleX } },
                                                  .nprops = 2, .duration = 0x1f4, .onComplete = B_Cart2_vanish, .ctx = b });
}
static void B_Cart2_OnBounce(Bullet *b) {
    if (--b->bounces <= 0) {
        if (!b->isFadingOut) { anims_play(&b->s, &Cart_end, 0); B_Cart2_FadeOut(b); }
    } else {
        b->n_hit = 0;
        Sound_PlaySound("Brakes", 0.3f, 1, 0xc8 * frand(), 0x96, 2);
    }
}
static void B_Cart2_Bounce(void *ctx) { B_Cart2_OnBounce(ctx); }  // 'worldbounds'
static void B_Cart2_OnHasHitWall(Bullet *b, Tile *t) {
    if (b->bounces > 0) {
        b->save_vel_x *= t && (t->faceRight || t->faceLeft) ? -1 : 1;
        b->save_vel_y *= t && (t->faceTop || t->faceBottom) ? -1 : 1;
    }
    sprite_setVelocity(&b->s, b->save_vel_x, b->save_vel_y);
    B_Cart2_OnBounce(b);
}
static void B_Cart2_enterDone(void *ctx) { ((Bullet *)ctx)->enterTweenCompleted = 1; }
static void B_Cart2_OnRecycle(Bullet *b) {
    Weapon *w = b->weapon;
    Bullet_OnRecycle(b);
    sprite_setScale(&b->s, 1);
    sprite_setOrigin(&b->s, 0.5f, 1);
    body_setCircle(&b->s.body, 0x18, b->s.body.offset.x, b->s.body.offset.y);
    b->s.alpha = 1;
    b->_speed = b->defaultSpeed;
    b->makeSparks = 1;
    b->s.visible = 1;
    b->n_hit = 0;
    anims_play(&b->s, &Cart_idle, 0);
    if (IsHalloween) sprite_setFrame(&b->s, frame_get("vfx", "hCartEnd_0.png"));  // (sic) l'animazione resta quella normale
    b->isFadingOut = 0;
    tween_stop(b->disappearTween);
    b->enterTweenCompleted = 0;
    sprite_setScale(&b->s, 0);
    tween_stop(b->enterTween);
    b->enterTween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, Weapon_PArea(w) } }, .nprops = 1, .duration = 0xc8, .onComplete = B_Cart2_enterDone, .ctx = b });
    b->s.body.collideWorldBounds = 1, b->s.body.hasWorldBounce = 1, b->s.body.worldBounce = (Vector2){ 1, 1 };
    b->s.body.customBounds = &Core.Player->WorldBoxCollider;
    b->s.body.onWorldBounds = B_Cart2_Bounce, b->s.body.onWorldBoundsCtx = b;
    int goingRight = Core.Player->lastFacedDirection.x * 1 + Core.Player->lastFacedDirection.y * 0 < 0;  // (sic) dot(RIGHT) < 0 -> 180 gradi
    b->s.depth = Core.Player->s.depth + 1;
    b->Pfx->s.depth = b->s.depth - 1;
    b->s.body.velocity = velocityFromRotation((goingRight ? 0xb4 : 0) * (PI / 180), Bullet_TrueSpeed(b));
    Sound_PlaySound("Brakes", 0.3f, 1, 0xc8 * frand(), 0x96, 2);
}
static void B_Cart2_Update(Bullet *b, float delta) {
    float a = Weapon_PArea(b->weapon);
    b->_speed += 1 * delta;  // (sic) la velocita' si calcola solo in OnRecycle
    if (b->enterTweenCompleted) sprite_setScale(&b->s, a);
    if (b->makeSparks) {
        float o = b->save_vel_x < 0 ? 0xc : -0xc;
        manager_emitParticleAt(b->Pfx, b->s.x + o, b->s.y - 2 * a);
        manager_emitParticleAt(b->Pfx, b->s.x + o, b->s.y - 0x16 * a);
    }
    b->save_vel_x = b->s.body.velocity.x == 0 ? b->save_vel_x : b->s.body.velocity.x;
    b->save_vel_y = b->s.body.velocity.y == 0 ? b->save_vel_y : b->s.body.velocity.y;
}
static const BulletVT B_Cart2 = { "vfx", "CartEnd_0.png", B_Cart2_ctor, NULL, B_Cart2_OnRecycle, NULL, B_Cart2_Update, NULL, NULL, NULL, B_Cart2_OnHasHitWall };
static float W_Cart2_PBounces(Weapon *w) { return floorf(Weapon_PAmount(w)) + w->bonusBounces + w->bounces; }
static void W_Cart2_Fire(Weapon *w) {
    Weapon_FireOneBullet(w, Core.Player->s.x, Core.Player->s.y + 0xc, 0);
    if (w->lastFiringInterval != Weapon_PInterval(w)) {
        w->lastFiringInterval = Weapon_PInterval(w);
        Weapon_ResetFiringTimer(w);
    }
}
static void W_Cart2_ctor(Weapon *w) { w->mul = 1000.0f / 12; }
static void W_Cart2_Update(Weapon *w, float delta) {
    base_Update(w, delta);
    w->totalTime += delta;
    if (w->cooldownAffectedByMovement) w->totalTime += Core.Player->frameWalk * (delta / w->mul);
    if (w->totalTime >= Weapon_PInterval(w)) { w->totalTime -= Weapon_PInterval(w); Weapon_Fire(w); }
}
// CheckArcanas (Tragic Princess, Pearls, Iron Blue, Twilight): arcane
static const WeaponVT W_Cart2 = { BASE, .CheckArcanas = CA_cart2, .bullet = &B_Cart2, .ctor = W_Cart2_ctor, .PBounces = W_Cart2_PBounces, .Fire = W_Cart2_Fire, .Update = W_Cart2_Update,
                                  .ResetFiringTimer = noop_ResetFiringTimer };

// --- Celestial Dusting: W_Flower (0xa698), B_Flower (0xa60b) ----------------------------------------------------
// Un fiore che si allontana nella direzione opposta al passo del giocatore, rallenta e svanisce; l'area verde a terra fa danno.
static float B_Flower_MyScale(Bullet *b) { return Weapon_PArea(b->weapon) * b->bounceAreaMod * b->scaleAfterBounceMod; }
static void B_Flower_ctor(Bullet *b) {
    static const unsigned TINTS[4] = { 0xff8888, 0x88ff88, 0x88ff88, 0xffff88 };
    static const char *const blur[2] = { "_blur.png", "_blur2.png" };
    Weapon *w = b->weapon;
    b->bombDeceleration = 1;
    b->canBounce = 1;
    b->bounceAreaMod = 1, b->maxBounceAreaMod = 1.5f;
    b->radius = 8;
    sprite_init(&b->GroundFx, NULL, 0, 0);  // scene.add.circle(0, 0, 8, 0x00ff00), ADD, alpha 0.1
    b->GroundFx.owner = b;
    b->GroundFx.draw = Trapano_groundDraw;
    b->GroundFx.tint = 0xff00, b->GroundFx.alpha = 0.1f, b->GroundFx.visible = 1;
    children_add(&b->GroundFx);
    b->s.visible = 0;
    b->Pfx = particles_add();  // particles('vfx'): fwEmitter (mai avviato) e fwEmitterK (mai usato)
    b->PfxEmitter = particles_createEmitter(b->Pfx, (EmitterConfig){ .frames = { frame_get("vfx", blur[b->indexInWeapon % 2]) }, .nframes = 1,
        .lifespan = EOP(0x320), .rotate = ERND(0, 0x168), .alpha = { 0, 1, 2, Ease_ExpoOut }, .angle = { 0, 0x168, 1 }, .angleSteps = 0x10,
        .speed = ERND(0x32, 0x64), .quantity = 0x10, .scale = ERANGE(1, 0), .frequency = 0x10, .blendAdd = 1, .on = 0 });
    b->Pfx2 = particles_add();  // particles('dusting0'): la foglia animata della Weapon
    b->PfxEmitter2 = particles_createEmitter(b->Pfx2, (EmitterConfig){ .frameRef = &w->leafSprite.frame,
        .lifespan = EOP(0x258), .rotate = ERND(0, 0x168), .alpha = { 0, 1, 2, Ease_ExpoOut }, .angle = { 0, 0x168, 1 }, .angleSteps = 0x1f,
        .speed = ERND(0x96, 0xc8), .quantity = 1, .scale = ERANGE(2, 0.1f), .frequency = 1, .tints = { TINTS[0], TINTS[1], TINTS[2], TINTS[3] }, .ntints = 4,
        .blendAdd = 1, .on = 0 });
    char nm[16];
    if (IsHalloween) snprintf(nm, sizeof(nm), "Ecto%d.png", 1 + (int)floorf(frand() * 6));
    else snprintf(nm, sizeof(nm), "fl%02d.png", (int)floorf(frand() * 0x59));  // RND.pick(flowerNames)
    sprite_init(&b->flowerSprite, frame_get("vfx", nm), b->s.x, b->s.x);  // (sic) x, x
    sprite_setScale(&b->flowerSprite, 0);
    sprite_setOrigin(&b->flowerSprite, 0.5f, 1);
    b->flowerSprite.angle = -0x2d;
    children_add(&b->flowerSprite);
    tweens_add((TweenConfig){ .props = { { &b->flowerSprite.angle, NULL, 0x2d } }, .nprops = 1, .duration = 0x3e8, .repeat = -1, .yoyo = 1 });  // AngleTween
    b->BounceTimer = b->HitboxTimer = (Timer){ -1, 0 };
    b->SpeedTween = b->tween1 = b->tween2 = TWEEN_NONE;
}
static void B_Flower_despawn(void *ctx) { Bullet_DeSpawn(ctx); }
static void B_Flower_FadeOut(void *ctx) {
    Bullet *b = ctx;
    tweens_add((TweenConfig){ .props = { { &b->flowerSprite.alpha, NULL, 0 }, { &b->s.alpha, NULL, 0 }, { &b->GroundFx.alpha, NULL, 0 } }, .nprops = 3, .duration = 0x1f4,
                              .onComplete = B_Flower_despawn, .ctx = b });
}
static void B_Flower_tween1Start(void *ctx) {
    Bullet *b = ctx;
    b->s.scaleX = b->s.scaleY = 0;
    b->flowerSprite.scaleX = b->flowerSprite.scaleY = 0;
}
static void B_Flower_tween2Done(void *ctx) {
    Bullet *b = ctx;
    b->canBounce = 1;
    tweens_add((TweenConfig){ .props = { { &b->scaleAfterBounceMod, NULL, fmaxf(1, Core.Player->moveSpeed) } }, .nprops = 1,
                              .duration = fmaxf(0x1f4, Weapon_PDuration(b->weapon) - 0x258) });
}
static void B_Flower_resetHits(void *ctx) { ((Bullet *)ctx)->n_hit = 0; }
static void B_Flower_OnRecycle(Bullet *b) {
    static const char *const steps[4] = { "STEP1", "STEP2", "STEP3", "STEP4" };
    Weapon *w = b->weapon;
    float a = Weapon_PArea(w);
    Bullet_OnRecycle(b);
    b->isCullable = 0;
    sprite_setScale(&b->s, 1);
    body_setCircle(&b->s.body, 8, -4, -4);
    b->s.body.enable = 1;
    b->totalTime = 0;
    b->n_hit = 0;
    b->PfxEmitter2->c.hasZone = 1, b->PfxEmitter2->c.zoneRadius = 8 * a;
    b->flowerSprite.visible = 1, b->GroundFx.visible = 1, b->s.visible = 0;
    b->bounceAreaMod = 1;
    b->s.alpha = 1;
    b->GroundFx.alpha = 0.1f;
    b->canBounce = 0;  // setBounce(1.1, 1.1): le velocita' si riscrivono a ogni Update
    b->PfxEmitter->c.speed = ERND(0x32 * a, 0x64 * a);
    b->isCullable = 1;
    b->save_vel_x = b->save_vel_y = 1;
    b->aimVec = (Vector2){ -1 * Core.Player->s.body.velocity.x, -1 * Core.Player->s.body.velocity.y };
    sprite_setVelocity(&b->s, b->aimVec.x * Weapon_PSpeed(w), b->aimVec.y * Weapon_PSpeed(w));  // (sic) Update la riscrive senza PSpeed
    tween_stop(b->SpeedTween);
    b->bombDeceleration = 1;
    b->SpeedTween = tweens_add((TweenConfig){ .props = { { &b->bombDeceleration, NULL, 0 } }, .nprops = 1, .delay = 0.25f * Weapon_PDuration(w),
                                              .duration = 0.75f * Weapon_PDuration(w), .onComplete = B_Flower_FadeOut, .ctx = b });
    if (b->indexInWeapon < 4) Sound_PlaySound(steps[b->indexInWeapon % 4], 0.05f - 0.01f * b->indexInWeapon, 1, 0xc8 * b->indexInWeapon, 0xc8, 0xa);
    b->flowerSprite.scaleX = b->flowerSprite.scaleY = 0;
    b->flowerSprite.alpha = 1, b->flowerSprite.visible = 1;
    b->scaleAfterBounceMod = 1;
    b->flowerSprite.x = b->s.x, b->flowerSprite.y = b->s.y + 8 * B_Flower_MyScale(b);
    float sc = B_Flower_MyScale(b);
    b->s.scaleX = b->s.scaleY = 0;
    tween_stop(b->tween1);
    b->tween1 = tweens_add((TweenConfig){ .props = { { &b->s.scaleY, NULL, sc } }, .nprops = 1, .duration = 0x1f4, .ease = Ease_BackOut,
                                          .onStart = B_Flower_tween1Start, .ctx = b });
    tween_stop(b->tween2);
    b->tween2 = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, NULL, sc } }, .nprops = 1, .duration = 0x258, .ease = Ease_BackOut,
                                          .onComplete = B_Flower_tween2Done, .ctx = b });
    time_removeEvent(b->HitboxTimer);
    b->HitboxTimer = time_addEvent(w->hitBoxDelay, 1, 0, B_Flower_resetHits, b);
}
static void B_Flower_canBounce(void *ctx) { ((Bullet *)ctx)->canBounce = 1; }
static void B_Flower_SizeUp(Bullet *b) {  // (sic) non cambia bounceAreaMod: solo le foglie
    if (!b->canBounce) return;
    b->canBounce = 0;
    emitter_emitParticleAt(b->PfxEmitter2, b->s.x, b->s.y, 0);
    time_removeEvent(b->BounceTimer);
    b->BounceTimer = time_addEvent(0x3c, 0, 0, B_Flower_canBounce, b);
}
static void B_Flower_OnHasHitWall(Bullet *b, Tile *t) {
    b->save_vel_x *= t && (t->faceRight || t->faceLeft) ? -1 : 1;
    b->save_vel_y *= t && (t->faceTop || t->faceBottom) ? -1 : 1;
    b->n_hit = 0;
}
static void B_Flower_Update(Bullet *b, float delta) {
    (void)delta;
    sprite_setVelocity(&b->s, b->aimVec.x * b->save_vel_x * b->bombDeceleration, b->aimVec.y * b->save_vel_y * b->bombDeceleration);
    if (b->canBounce) { float sc = B_Flower_MyScale(b); b->s.scaleX = b->s.scaleY = sc; }
    b->s.depth = b->GroundFx.depth = -game_height;
    b->flowerSprite.depth = b->s.y - Core.Player->s.y - 1;
    b->Pfx->s.depth = b->s.depth - 1;
    b->GroundFx.x = b->flowerSprite.x = b->s.x;
    b->GroundFx.y = b->flowerSprite.y = b->s.y;
    b->GroundFx.scaleX = b->s.scaleX, b->GroundFx.scaleY = b->s.scaleY;
    b->flowerSprite.scaleX = 0.65f * b->s.scaleX, b->flowerSprite.scaleY = 0.65f * b->s.scaleY;
    b->flowerSprite.y = b->s.y + 8 * b->s.scaleY;
}
static void B_Flower_DeSpawn(Bullet *b) {
    tween_stop(b->SpeedTween);
    emitter_stop(b->PfxEmitter);
    tween_stop(b->tween1), tween_stop(b->tween2);
    b->flowerSprite.visible = 0;
    b->s.scaleX = b->s.scaleY = 0;
    b->GroundFx.visible = 0;
    b->s.visible = 0;
    b->s.body.enable = 0;
    if (b->weapon->explodeOnExpire) Weapon_SpawnExplosionAt(b->weapon, b->s.x, b->s.y, 0);
    base_DeSpawn(b);
}
static const BulletVT B_Flower = { "vfx", "circle8.png", B_Flower_ctor, NULL, B_Flower_OnRecycle, NULL, B_Flower_Update, B_Flower_DeSpawn, NULL, NULL, B_Flower_OnHasHitWall };
static void W_Flower_ctor(Weapon *w) {
    w->mul = 1000.0f / 60;
    W_Cherry_ctor(w);  // la stessa foglia animata ('dusting0'), frameRate 30
}
static void W_Flower_Update(Weapon *w, float delta) {
    base_Update(w, delta);
    w->totalTime += delta;
    w->totalTime += Core.Player->frameWalk * (delta / w->mul);
    if (w->totalTime >= Weapon_PInterval(w)) { w->totalTime = 0; Weapon_Fire(w); }
}
static void W_Flower_OnBulletOverlapsBullet(void *ctx, Sprite *as, Sprite *bs) {
    (void)ctx;
    Bullet *a = as->owner, *b = bs->owner;
    if (Bullet_HasAlreadyHitObject(a, b, 0)) return;
    Bullet_pushHit(b, a), Bullet_pushHit(a, b);
    B_Flower_SizeUp(b), B_Flower_SizeUp(a);
}
static void W_Flower_OnStart(Weapon *w) {
    base_OnStart(w);
    physics_addColliderSelf(&w->pool->group, W_Flower_OnBulletOverlapsBullet, w);
}
static void W_Flower_onBulletOverlapsEnemy(Weapon *w, Bullet *b, Enemy *e) {
    if (e->isDead || Bullet_HasAlreadyHitObject(b, e, e->isDead)) return;
    Enemy_GetDamaged(e, Weapon_PPower(w), (int)w->hitVFX, w->knockback, w->bulletType);
    w->stats_inflictedDamage += Weapon_PPower(w);
    if (!e->isDead || w->level < 8) return;
    float r = w->critChancesArray[w->critIndex % 1000];
    w->critIndex++;
    if (r >= 0.33f) {
        Pickup *h = Core_MakePickup(e->s.x, e->s.y, "LITTLEHEART");
        if (h) h->goToPlayer = 1, h->time = 1;  // volume = 0.1: solo il suono
    }
}
static const WeaponVT W_Flower = { BASE, .CheckArcanas = CA_inverseBeginning, .bullet = &B_Flower, .ctor = W_Flower_ctor, .Update = W_Flower_Update, .OnStart = W_Flower_OnStart,
                                   .ResetFiringTimer = noop_ResetFiringTimer, .onBulletOverlapsEnemy = W_Flower_onBulletOverlapsEnemy };

static void GizmoManager_ShowHighlightAt(float x, float y);
static void Core_debug_destructibles(float mul);
// --- Greatest Jubilee: W_Jubilee (0x185ad), B_Jubilee (0x10079) -------------------------------------------------
// Fuochi d'artificio: il primo sul nemico piu' vicino, gli altri a caso sopra il giocatore; a volte fonti di luce.
// MakeRays / SpawnExplosionAt (JUBILEE_RAYS): dal livello 9 (RaysLevel), che i dati non raggiungono senza limit break.
static void B_Jubilee_counterStart(void *ctx) {
    Bullet *b = ctx;
    ParticleEmitter *e = b->jubEmitter;
    e->c.scale = ERANGE(fminf(4, Weapon_PArea(b->weapon)), 0);
    e->c.quantity = 0x40;
    e->x = b->jubX, e->y = b->jubY;
    if (!isnan(b->jubX)) emitter_start(e);  // senza nemici la posizione e' undefined (NaN): niente da vedere, ne' da disegnare
}
static void B_Jubilee_counterDone(void *ctx) { emitter_stop(((Bullet *)ctx)->jubEmitter); }
static void B_Jubilee_despawn(void *ctx) { Bullet_DeSpawn(ctx); }
static void B_Jubilee_OnRecycle(Bullet *b) {
    Weapon *w = b->weapon;
    Bullet_OnRecycle(b);
    sprite_setScale(&b->s, 1);
    body_setCircle(&b->s.body, 1, -0.5f, -0.5f);
    sprite_setScale(&b->s, 0);
    ParticleEmitter *e = w->fwEmitters[b->indexInWeapon % 5];
    float x = NAN, y = NAN;
    if (Weapon_PAmount(w) < 4 && b->indexInWeapon == 0) {
        Sprite *t = physics_closest(&Core.Player->s, &Core.Enemies);
        if (t) x = t->x, y = t->y;
    } else {
        x = b->s.x + (frand() - 0.5f) * (0.75f * game_width), y = b->s.y - 0x40 - 0x80 * frand();
    }
    b->s.x = x, b->s.y = y;
    tween_stop(b->scaleTween);
    b->scaleTween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, 0x30 * Weapon_PArea(w) } }, .nprops = 1, .duration = Weapon_PDuration(w), .yoyo = 1,
                                              .onComplete = B_Jubilee_despawn, .ctx = b });
    if (tween_get(b->emitterCounter) && b->jubEmitter) emitter_stop(b->jubEmitter);  // stop() -> onStop
    tween_stop(b->emitterCounter);
    b->jubEmitter = e, b->jubX = x, b->jubY = y;
    b->counterVal = 0;
    b->emitterCounter = tweens_add((TweenConfig){ .props = { { &b->counterVal, NULL, 1 } }, .nprops = 1, .duration = 0.3f * Weapon_PDuration(w),
                                                  .onStart = B_Jubilee_counterStart, .onComplete = B_Jubilee_counterDone, .ctx = b });
}
static void B_Jubilee_ctor(Bullet *b) { b->s.visible = 0; b->scaleTween = b->emitterCounter = TWEEN_NONE; }
static const BulletVT B_Jubilee = { "vfx", "WhiteDot.png", B_Jubilee_ctor, NULL, B_Jubilee_OnRecycle, NULL, NULL, NULL };
static void W_Jubilee_ctor(Weapon *w) {
    static const char *const fr[5] = { "PfxYellow.png", "PfxPink.png", "PfxRed.png", "PfxGreen.png", "PfxBlue.png" };
    w->canPlaySounds = 1;
    w->fwManager = particles_add();  // MakeFireworks
    for (int i = 0; i < 5; i++)
        w->fwEmitters[i] = particles_createEmitter(w->fwManager, (EmitterConfig){ .frames = { frame_get("vfx", fr[i]) }, .nframes = 1, .lifespan = EOP(0x5dc),
            .rotate = ERND(0, 0x168), .angle = { 0, 0x168, 1 }, .angleSteps = 0x10, .speed = ERND(0x32, 0x64), .quantity = 0x40, .scale = ERANGE(1, 0),
            .frequency = 0x40, .blendAdd = 1, .on = 0 });
    w->fwManager->hasWell = 1;  // createGravityWell({ power: 0.5, epsilon: 25, gravity: 100 })
    w->fwManager->wellPower = 0.5f * 0x64, w->fwManager->wellEpsilon = 0x19 * 0x19;
    w->soundTimer = (Timer){ -1, 0 };
}
static void W_Jubilee_step(void *ctx) {
    static const char *const steps[4] = { "STEP1", "STEP2", "STEP3", "STEP4" };
    Weapon *w = ctx;
    w->jubSoundN++;
    Sound_PlaySound(steps[w->jubSoundIdx % 4], 0.3f, 1, 0xc8 * w->jubSoundN, 0x32, 5);
    TimerEvent *t = time_get(w->soundTimer);
    if (t && t->repeatCount == 0) w->canPlaySounds = 1;
}
static void W_Jubilee_Fire(Weapon *w) {
    static const char *const steps[4] = { "STEP1", "STEP2", "STEP3", "STEP4" };
    base_Fire(w);
    if (frand() < w->chance * Player_PLuck(Core.Player)) Core_debug_destructibles(0.25f * Player_PLuck(Core.Player));  // PLuck
    if (!w->canPlaySounds) return;
    w->canPlaySounds = 0;
    w->jubSoundN = 0, w->jubSoundIdx = w->soundIndex;
    Sound_PlaySound(steps[w->soundIndex % 4], 0.3f, 1, 0, 0x32, 5);
    if (Weapon_PAmount(w) > 1) w->soundTimer = time_addEvent(w->repeatInterval, 0, (int)Weapon_PAmount(w) - 1, W_Jubilee_step, w);
    else w->canPlaySounds = 1;
    w->soundIndex++;
}
static void W_Jubilee_Update(Weapon *w, float delta) {
    base_Update(w, delta);
    w->fwManager->wellX = Core.Player->s.x, w->fwManager->wellY = Core.Player->s.y;
}
// onSecondaryBulletOverlapsEnemy (critico con la Luck): solo per i raggi del livello 9
static const WeaponVT W_Jubilee = { BASE, .bullet = &B_Jubilee, .ctor = W_Jubilee_ctor, .Fire = W_Jubilee_Fire, .Update = W_Jubilee_Update };

// --- Vandalier: W_Silf3 (0xa7cc), B_Silf3 (0x500f) ---------------------------------------------------------------
// Peachone ed Ebony Wings insieme: due zone speculari, 24 bersagli, archi sopra la testa del giocatore.
static void W_Silf3_ctor(Weapon *w) {
    static Animation idle;
    w->silf3 = 1;
    w->ntargets = 24;
    w->rayDuration = 0x190;
    w->runSpeed = PlayerPxSpeed;
    w->damageZoneDistance = 0x1c8 * 0.5f;  // IS_PORTRAIT ? GAMEPLAY_PIXEL_WIDTH : GAMEPLAY_PIXEL_HEIGHT
    w->damageZoneDefaultRadius = 0.25f * w->damageZoneDistance;
    w->damageZoneDistance -= w->damageZoneDefaultRadius;
    Silf_zone(&w->damageZone, w->damageZoneDefaultRadius, 2, 0xffff00), w->damageZone.visible = 0;
    Silf_zone(&w->targetZone, w->damageZoneDefaultRadius, 1, 0xffffff), w->targetZone.alpha = 0.5f;
    Silf_zone(&w->damageZone2, w->damageZoneDefaultRadius, 2, 0xffff00), w->damageZone2.visible = 0;
    Silf_zone(&w->targetZone2, w->damageZoneDefaultRadius, 1, 0xffffff), w->targetZone2.alpha = 0.5f;
    sprite_init(&w->sprite, frame_get("vfx", "ProjectileBird2.png"), Core.Player->s.x, Core.Player->s.y);
    children_add(&w->sprite);
    physics_existing(&w->sprite);
    if (!idle.n) make_anim(&idle, "vfx", "ProjectileBird", 7, 8, 0, 6, -1);
    anims_play(&w->sprite, &idle, 0);
    w->sprite.depth = MAX_SAFE_INTEGER - 0x3e7;
}
static void Silf_randomIn(Vector2 *out, const Sprite *zone) {  // Geom.Circle.Random
    float t = 2 * PI * frand(), u = frand() + frand(), k = u > 1 ? 2 - u : u;
    *out = (Vector2){ k * cosf(t) * zone->scaleX + zone->x, k * sinf(t) * zone->scaleX + zone->y };
}
static void W_Silf3_Fire(Weapon *w) {
    if (w->blockFire) return;
    w->repeatInterval = w->interval / Weapon_PAmount(w);
    w->damageZone.scaleX = w->damageZone2.scaleX = w->damageZoneDefaultRadius;
    for (int i = 0; i < 12; i++) Silf_randomIn(&w->targets[i], &w->damageZone);
    for (int i = 0; i < 12; i++) Silf_randomIn(&w->targets[12 + i], &w->damageZone2);
    base_Fire(w);
}
static void W_Silf3_Update(Weapon *w, float delta) {
    base_Update(w, delta);
    w->totalTime += delta;
    w->angleTime += delta;
    float ox = Core.Player->s.flipX ? 0x18 : -0x18;
    Sprite *s = &w->sprite;
    float dx = Core.Player->s.x + ox - s->x, dy = Core.Player->s.y - s->y;
    if (dx * dx + dy * dy > 0x1388) {
        Vector2 *d = &w->_currentDirection;
        d->x = Core.Player->s.x + ox - s->x, d->y = Core.Player->s.y - 0x18 - s->y;
        float l = sqrtf(d->x * d->x + d->y * d->y);
        if (l > 0) d->x /= l, d->y /= l;
        s->flipX = d->x < 0;
        sprite_setVelocity(s, w->runSpeed * d->x * Core.Player->moveSpeed, w->runSpeed * d->y * Core.Player->moveSpeed);
    } else {
        sprite_setVelocity(s, 0x23 * w->_currentDirection.x, 0x23 * w->_currentDirection.y);
    }
    float px = Core.Player->s.x, py = Core.Player->s.y, r = w->damageZoneDistance, a = 0.001f * (w->angleTime - w->rayDuration) * Weapon_PSpeed(w);
    w->targetZone.x = px + cosf(a) * r, w->targetZone.y = py + sinf(a) * r;
    w->targetZone2.x = px + cosf(-a) * r, w->targetZone2.y = py + sinf(-a) * r;
    a = 0.001f * w->angleTime * Weapon_PSpeed(w);
    w->damageZone.x = px + cosf(a) * r, w->damageZone.y = py + sinf(a) * r;
    w->damageZone2.x = px + cosf(-a) * r, w->damageZone2.y = py + sinf(-a) * r;
    if (w->totalTime >= Weapon_PDuration(w)) {
        w->totalTime = -Weapon_PDuration(w) * (w->interval / 1000) * Core.Player->cooldown;
        w->blockFire = 1;
        w->targetZone.alpha = w->targetZone2.alpha = 0.1f;
        if (w->totalTime >= Weapon_PDuration(w)) w->totalTime = 0, w->blockFire = 0, w->targetZone.alpha = w->targetZone2.alpha = 0.5f;
    } else if (w->totalTime > 0) {
        w->blockFire = 0;
        w->targetZone.alpha = w->targetZone2.alpha = 0.5f;
    }
}
// LevelUp / ApplyLimitBreak: counterWeapon1/2 solo con l'arcana Aquarius
static const WeaponVT W_Silf3 = { BASE, .CheckArcanas = CA_silf3, .bullet = &B_Silf3, .ctor = W_Silf3_ctor, .Fire = W_Silf3_Fire, .Update = W_Silf3_Update };

static const WeaponVT W_PowerUp = { BASE, .bullet = &B_Whip, .LevelUp = PowerUp_LevelUp, .MakeLevelOne = PowerUp_MakeLevelOne,
                                    .ResetFiringTimer = noop_ResetFiringTimer };

// --- Bracelet / Bi-Bracelet / Tri-Bracelet: W_Triace (0x1071b), B_Triace (0x40b6) --------------------------------
// Sfere a ventaglio (0, -15, +15 gradi) verso un nemico a caso, che si allargano fino a 16 * area dentro lo schermo.
static void B_Triace_ctor(Bullet *b) {
    static const unsigned colors[3] = { 0xffff, 0x66ff, 0xffff66 };
    b->radius = 0x10;
    b->color = colors[(int)floorf(frand() * 3)];  // myColor: RND.pick
    sprite_init(&b->GroundFx, NULL, 0, 0);  // scene.add.circle(0, 0, 1, myColor), ADD: raggio = scala
    b->GroundFx.draw = MoonGroundFx_draw;
    b->GroundFx.tint = b->color, b->GroundFx.alpha = 0.2f, b->GroundFx.visible = 1;
    children_add(&b->GroundFx);
    b->s.visible = 0;  // la sfera vera resta invisibile: si vedono il cerchio e le particelle
    b->Pfx = particles_add();
    b->PfxEmitter1 = particles_createEmitter(b->Pfx, (EmitterConfig){ .frames = { frame_get("vfx", "PfxGreen.png"), frame_get("vfx", "PfxYellow.png") }, .nframes = 2,
        .angle = ERND(0, 0x168), .speed = ERND(0xf, 0x1e), .quantity = 1, .lifespan = EOP(0x64), .alpha = ERANGE(1, 0), .scale = ERANGE(1, 0), .on = 0 });
    b->PfxEmitter2 = particles_createEmitter(b->Pfx, (EmitterConfig){ .frames = { frame_get("vfx", "ProjectileBlue1.png"), frame_get("vfx", "ProjectileBlue2.png"),
        frame_get("vfx", "PfxLightGreen.png") }, .nframes = 3, .speed = ERND(0xf, 0x1e), .rotate = ERND(0, 0x168), .angle = { 0, 0xb4, 1 }, .angleSteps = 0x10,
        .quantity = 1, .lifespan = EOP(0x64), .alpha = ERANGE(1, 0), .scale = ERANGE(0, 2), .on = 0 });  // projEmitter
    b->ScaleTween = TWEEN_NONE;
}
static void B_Triace_despawn(void *ctx) { Bullet_DeSpawn(ctx); }
static void B_Triace_OnRecycle(Bullet *b) {
    Weapon *w = b->weapon;
    Bullet_OnRecycle(b);
    body_setCircle(&b->s.body, 1, b->s.body.offset.x, b->s.body.offset.y);
    sprite_setScale(&b->s, PixelScale * Weapon_PArea(w));
    sprite_setTintFill(&b->s, b->color);
    b->s.y -= 0x18;
    Sound_PlaySound("Fireloop", 1, 2.5f, -0x64 * b->indexInWeapon, 0xc8, 1);
    b->GroundFx.alpha = 0.4f, b->GroundFx.scaleX = b->GroundFx.scaleY = 0, b->GroundFx.visible = 1;
    b->s.alpha = 0, sprite_setScale(&b->s, 0);
    b->PfxEmitter2->c.scale = ERANGE(0, fmaxf(2, Weapon_PArea(w)));
    tween_stop(b->ScaleTween);
    float sc = b->radius * Weapon_PArea(w);
    TweenProp pr[4] = { { &b->GroundFx.alpha, NULL, 0 }, { &b->GroundFx.scaleX, &b->GroundFx.scaleY, sc }, { &b->s.alpha, NULL, 0 }, { &b->s.scaleX, &b->s.scaleY, sc } };
    b->ScaleTween = tweens_add((TweenConfig){ .many = pr, .nmany = 4, .duration = Weapon_PDuration(w), .onComplete = B_Triace_despawn, .ctx = b });
    b->s.body.collideWorldBounds = 1, b->s.body.hasWorldBounce = 1, b->s.body.worldBounce = (Vector2){ 0.1f, 0.1f };
    b->s.body.customBounds = &Core.Player->WorldBoxCollider;
    b->s.body.onWorldBounds = NULL;  // onWorldBounds = true: solo l'evento 'worldbounds', che nessuno ascolta
}
static void B_Triace_Update(Bullet *b, float delta) {
    (void)delta;
    b->GroundFx.x = b->s.x, b->GroundFx.y = b->s.y;
    manager_emitParticleAt(b->Pfx, b->s.x, b->s.y);
    b->s.depth = -2, b->Pfx->s.depth = -1;
}
static void B_Triace_DeSpawn(Bullet *b) {
    tween_stop(b->ScaleTween);
    b->GroundFx.visible = 0;
    if (b->weapon->explodeOnExpire && strcmp(b->weapon->bulletType, "TRIASSO1")) Weapon_SpawnExplosionAt(b->weapon, b->s.x, b->s.y, 0);
    b->s.body.collideWorldBounds = 0;
    base_DeSpawn(b);
}
static void B_Triace_OnHasHitAnObject(Bullet *b, void *o, int isDead) {
    if (isDead) return;
    if (Arcanas_has(19) && !strcmp(b->weapon->bulletType, "TRIASSO3")) Weapon_SpawnExplosionAt(b->weapon, b->s.x, b->s.y, 1);  // RAYEXPLOSION (sic)
    if (Arcanas_has(14)) Bullet_TryFreeze(b, o);
    if (--b->penetrating <= 0) Bullet_DeSpawn(b);
}
static const float TriaceFan[3] = { 0, -0xf, 0xf };
static void B_Triace_SetTarget(Bullet *b, Vector2 t) { Bullet_SetTargetFan(b, t, TriaceFan, 3); }
static void B_Triace_SetNullTarget(Bullet *b) { B_Triace_SetTarget(b, Bullet_NullTargetPoint()); }
static const BulletVT B_Triace = { "vfx", "WhiteDot.png", B_Triace_ctor, NULL, B_Triace_OnRecycle, B_Triace_OnHasHitAnObject, B_Triace_Update, B_Triace_DeSpawn,
                                   B_Triace_SetTarget, B_Triace_SetNullTarget };
static void W_Triace_Fire(Weapon *w) {
    w->target = Core.Enemies.n ? Core.Enemies.items[(int)floorf(frand() * Core.Enemies.n)] : NULL;  // RND.pick(Core.Enemies)
    Sound_PlaySound("MagicMissile", 0.2f, 1, 0, 0xc8, 0xa);
    base_Fire(w);
}
static const WeaponVT W_Triace = { BASE, .CheckArcanas = CA_triace, .bullet = &B_Triace, .Fire = W_Triace_Fire };  // CheckArcanas: Jewels, Twilight, Fire

// --- Victory Sword: W_Victory (0x1721f), B_Victory (0xdb09) ------------------------------------------------------
// Fendenti sul nemico scelto, sei angoli a rotazione; dal livello 8 critici e colpo finale (Victory2, scintille blu).
// Quando il giocatore viene colpito: sei fendenti su di lui (ritorsione), al massimo ogni 6 * repeatInterval.
static void Weapon_StandardCritical(Weapon *w, Bullet *b, Enemy *e) {  // Weapon.StandardCritical (0xe49a): legge in ordine la tabella mescolata
    if (e->isDead) return;
    float r = w->critChancesArray[w->critIndex++ % 1000];
    float crit = r < w->critChance * Player_PLuck(Core.Player) ? w->critMul * Arcanas.CritMul : 1;  // PLuck
    if (Bullet_HasAlreadyHitObject(b, e, e->isDead)) return;
    Enemy_GetDamaged(e, Weapon_PPower(w) * crit, (int)w->hitVFX, w->knockback, w->bulletType);
    w->stats_inflictedDamage += Weapon_PPower(w) * crit;
}
static const float VictoryAngles[6] = { 0x14, -0x14, -0x46, 0x1e, -0x1e, 0 }, VictoryX[6] = { -0x10, 0x10, 0, 0x10, -0x10, 0 };
static void B_Victory_ctor(Bullet *b) {
    b->Pfx = particles_add();
    b->PfxEmitter = particles_createEmitter(b->Pfx, (EmitterConfig){ .frames = { frame_get("vfx", "WhiteDot.png") }, .nframes = 1, .quantity = 0xa,
        .lifespan = EOP(0x1f4), .alpha = ERANGE(1, 0), .angle = ERND(0xe1, 0x13b), .blendAdd = 1, .speed = ERND(0x4b, 0x7d),
        .scale = ERANGE(2 * PixelScale, 0), .gravityY = -0x258, .tint = 0x88ff, .hasZoneRect = 1, .zoneRect = { -0x10, -0x80, 0x20, 0x100 },
        .flowEveryFrame = 1, .on = 0 });
    b->tween = b->tween2 = TWEEN_NONE;
}
static void B_Victory_Init(Bullet *b, float x, float y) {
    Bullet_Init(b, x, y);
    sprite_setScale(&b->s, 0);
    b->s.blendAdd = 1;
    b->s.depth = 0xf0;
}
static void B_Victory_OnRecycle(Bullet *b) { Bullet_OnRecycle(b); emitter_stop(b->PfxEmitter); }
static void B_Victory_DeSpawn(Bullet *b) { base_DeSpawn(b); emitter_stop(b->PfxEmitter); }
static void B_Victory_SetNullTarget(Bullet *b) { Bullet_DeSpawn(b); }
static void B_Victory_onStart(void *ctx) {
    Bullet *b = ctx;
    int f = b->victoryFinish;
    b->s.scaleX = 0.5f * (f ? 2 : 1), b->s.scaleY = Weapon_PArea(b->weapon) * (f ? 2 : 1);
    if (f) b->PfxEmitter->x = b->s.x, b->PfxEmitter->y = b->s.y, emitter_start(b->PfxEmitter);
}
static void B_Victory_onComplete(void *ctx) { Bullet *b = ctx; if (b->victoryFinish) emitter_stop(b->PfxEmitter); }
static void B_Victory_despawn(void *ctx) { Bullet_DeSpawn(ctx); }
static void B_Victory_SetTarget(Bullet *b, Vector2 t) {
    int k = b->indexInWeapon % 6, f = b->weapon->canFinish && k == 5;
    b->victoryFinish = f;
    if (k < 5) Sound_PlaySound("Victory1", 0.4f, 1, 0xc8 * k, 0x64, 5);
    else if (f) Sound_PlaySound("Victory2", 1, 1, 0x4b0, 0x12c, 1);
    b->s.x = t.x + VictoryX[k], b->s.y = t.y;
    sprite_setFrame(&b->s, frame_get("vfx", f ? "victoryCrit.png" : "victory.png"));
    b->s.alpha = f ? 0.5f : 0.75f;
    b->s.angle = VictoryAngles[k];
    b->s.depth = game_height;
    tween_stop(b->tween);
    b->tween = tweens_add((TweenConfig){ .props = { { &b->s.scaleY, NULL, 0 }, { &b->s.scaleX, NULL, 0.5f } }, .nprops = 2, .duration = f ? 0x96 : 0x64,
                                         .onStart = B_Victory_onStart, .onComplete = B_Victory_onComplete, .ctx = b });
    tween_stop(b->tween2);
    b->tween2 = tweens_add((TweenConfig){ .props = { { &b->s.alpha, NULL, 0 } }, .nprops = 1, .duration = 0x64, .delay = 0x64, .onComplete = B_Victory_despawn, .ctx = b });
}
static const BulletVT B_Victory = { "vfx", "victory.png", B_Victory_ctor, B_Victory_Init, B_Victory_OnRecycle, NULL, NULL, B_Victory_DeSpawn,
                                    B_Victory_SetTarget, B_Victory_SetNullTarget };
static Bullet *W_Victory_SpawnExplosionAt(Weapon *w, float x, float y, int index) {
    if (!w->secondaryPool) {  // explosionType VICTORY: le esplosioni sono altri fendenti
        w->secondaryPool = BulletPool_new(w, &B_Victory);
        physics_addOverlap(&w->secondaryPool->group, &Core.Enemies, Weapon_onBulletOverlapsEnemy_Retaliation, w);
        physics_addOverlap(&w->secondaryPool->group, &Core.Destructibles, Weapon_onBulletOverlapsDestuctible, w);
    }
    Bullet *b = BulletPool_SpawnAt(w->secondaryPool, x, y, w, index);
    if (b) B_Victory_SetTarget(b, (Vector2){ Core.Player->s.x, Core.Player->s.y });
    return b;
}
typedef struct { Weapon *w; int index; } VictoryShot;
static void W_Victory_explodeLater(void *ctx) { VictoryShot *c = ctx; W_Victory_SpawnExplosionAt(c->w, Core.Player->s.x, Core.Player->s.y, c->index); }
static void W_Victory_canExplode(void *ctx) { ((Weapon *)ctx)->canExplode = 1; }
static void W_Victory_ExplodeOnPlayer(void *ctx) {
    static VictoryShot shots[64];
    static int shot_i;
    Weapon *w = ctx;
    if (!w->canExplode) return;
    w->canExplode = 0;
    time_removeEvent(w->ExplodeTimer);
    w->ExplodeTimer = time_addEvent(6 * w->repeatInterval, 0, 0, W_Victory_canExplode, w);
    W_Victory_SpawnExplosionAt(w, Core.Player->s.x, Core.Player->s.y, 0);
    for (int i = 1; i < 6; i++) {
        VictoryShot *c = &shots[shot_i++ & 63];
        *c = (VictoryShot){ w, i };
        time_addEvent(w->repeatInterval * i, 0, 0, W_Victory_explodeLater, c);
    }
}
static void W_Victory_ctor(Weapon *w) {
    w->canExplode = 1;
    w->ExplodeTimer = (Timer){ -1, 0 };
    PlayerEvents_add(EV_PLAYER_RECEIVEDDAMAGE, W_Victory_ExplodeOnPlayer, w);  // explodeEvent
    PlayerEvents_add(EV_PLAYER_LOSTSHIELD, W_Victory_ExplodeOnPlayer, w);
}
static int W_Victory_LevelUp(Weapon *w) {
    int r = base_LevelUp(w);
    if (w->level >= 8) w->canCrit = 1, w->canFinish = 1;
    return r;
}
static void W_Victory_Fire(Weapon *w) {
    // closest(): la lista dei nemici vivi che via via si avvicinano al giocatore; l'ultimo e' il piu' vicino.
    // Bersaglio a caso nella meta' piu' vicina della lista. I colpi ritardati rileggono this.target allo scatto, come base_Fire.
    static Sprite *list[1024];
    int n = 0;
    float best = 3.4e38f, px = Core.Player->s.x, py = Core.Player->s.y;
    for (int i = 0; i < Core.Enemies.n; i++) {
        Sprite *s = Core.Enemies.items[i];
        if (((Enemy *)s->owner)->isDead) continue;
        float d = hypotf(s->body.center.x - px, s->body.center.y - py);  // Distance.Between
        if (d < best && n < 1024) best = d, list[n++] = s;
    }
    w->target = n > 1 ? list[n - 1 - (int)floorf(frand() * n * 0.5f)] : n ? list[0] : NULL;
    base_Fire(w);
}
static void W_Victory_onBulletOverlapsEnemy(Weapon *w, Bullet *b, Enemy *e) {
    if (w->canCrit) Weapon_StandardCritical(w, b, e);
    else base_onBulletOverlapsEnemy(w, b, e);
}
// CleanUp toglie i due listener (Weapon_CleanUp generico)
static const WeaponVT W_Victory = { BASE, .PPower = blood2_PPower, .bullet = &B_Victory, .ctor = W_Victory_ctor, .LevelUp = W_Victory_LevelUp, .Fire = W_Victory_Fire,
                                    .onBulletOverlapsEnemy = W_Victory_onBulletOverlapsEnemy };

// --- La Robba: W_Larobba (0xdf2e), B_Larobba (0xce07) --------------------------------------------------------
// Oggetti a caso che piovono dall'alto ruotando, con un fantasma scuro; rimbalzano sui nemici e ricadono dall'alto.
static void B_Larobba_ctor(Bullet *b) {
    b->maxHistory = 1;
    b->grav = 10.0f / 48;
    sprite_setScale(&b->s, PixelScale * Weapon_PArea(b->weapon));
    b->AngleTween = tweens_add((TweenConfig){ .props = { { &b->s.angle, NULL, 0x168 } }, .nprops = 1, .duration = 0x3e8, .repeat = -1 });
    // MovementTween su moveAngle: l'originale lo anima ma non lo legge mai
    ghost_init(b, PixelScale, PixelScale, 0.55f);
    sprite_setTintFill(&b->ghost, 0x111111);  // semplificazione: tintFill a quattro angoli (0, 0x222222, 0, 0x222222) reso col colore medio
    b->ScaleTween = TWEEN_NONE;
    b->BounceTimer = (Timer){ -1, 0 };
}
static void B_Larobba_despawn(void *ctx) { Bullet_DeSpawn(ctx); }
static void B_Larobba_OnRecycle(Bullet *b) {
    Weapon *w = b->weapon;
    Bullet_OnRecycle(b);
    b->canBounce = 1;
    w->lastRobbaIndex = (w->lastRobbaIndex + 1) % 0x14;  // GetRobbaFrame: maxFrames 20 su 23 nomi
    const Frame *f = frame_get("items", w->robbaFrames[w->lastRobbaIndex]);
    sprite_setFrame(&b->s, f), sprite_setFrame(&b->ghost, f);
    b->s.tint = 0xffffff, b->s.tintFill = 0;
    sprite_setScale(&b->s, PixelScale * Weapon_PArea(w));
    float r = 0.5f * fmaxf(b->s.width, b->s.height);
    body_setCircle(&b->s.body, r, 0, 0);
    b->isCullable = 0;
    tween_stop(b->ScaleTween);  // onUpdate copia la scala sul fantasma: lo fa gia' Update
    b->ScaleTween = tweens_add((TweenConfig){ .props = { { &b->s.scaleX, &b->s.scaleY, 0 } }, .nprops = 1, .duration = 0x1f4, .delay = Weapon_PDuration(w),
                                              .onComplete = B_Larobba_despawn, .ctx = b });
    float px = Core.Player->s.x, py = Core.Player->s.y;
    b->s.x = px + (frand() - 0.5f) * game_width * 0.25f, b->s.y = py - 0.6f * game_height - r;
    w->lastAngleIndex = (w->lastAngleIndex + 1) % w->maxAngles;  // GetAngle
    float a = w->targetAngles[w->lastAngleIndex];
    b->startingAngle = a;  // in radianti (vedi OnHasHitAnObject)
    b->s.body.velocity = velocityFromRotation(a, Bullet_TrueSpeed(b));
    b->initialVelocity = (Vector2){ 1.5f * b->s.body.velocity.x, b->s.body.velocity.y };
    b->defaultVelocityY = b->initialVelocity.y;
    for (int i = 0; i < b->maxHistory; i++) b->posHistory[i] = (Vector2){ b->s.x, b->s.y };
    Sound_PlaySound("Shot", 0.45f, 1, -0x64 * b->indexInWeapon, 0xc8, 0xa);
}
static void B_Larobba_DeSpawn(Bullet *b) {
    tween_stop(b->ScaleTween);
    b->ghost.visible = 0;
    base_DeSpawn(b);
}
static void B_Larobba_canBounce(void *ctx) { ((Bullet *)ctx)->canBounce = 1; }
static void B_Larobba_OnHasHitAnObject(Bullet *b, void *o, int isDead) {
    (void)o;
    if (isDead || !b->canBounce) return;
    b->canBounce = 0;
    time_removeEvent(b->BounceTimer);
    b->BounceTimer = time_addEvent(0x1e, 0, 0, B_Larobba_canBounce, b);
    b->s.body.velocity = velocityFromRotation(b->startingAngle * (PI / 180), Bullet_TrueSpeed(b));  // (sic) DegToRad di un angolo gia' in radianti
    b->initialVelocity.x *= -1;
    b->initialVelocity.y = fmaxf(-0x258, b->s.body.velocity.y);
    b->n_hit = 0;
}
static void B_Larobba_Update(Bullet *b, float delta) {
    b->initialVelocity.y += delta * b->grav;
    if (b->historyIndex < b->maxHistory - 1) b->historyIndex++;
    else b->historyIndex = 0;
    Vector2 h = b->posHistory[getHistoryIndex(b, 0)];
    b->ghost.angle = b->s.angle, b->ghost.x = h.x, b->ghost.y = h.y;
    b->ghost.scaleX = b->s.scaleX, b->ghost.scaleY = b->s.scaleY, b->ghost.visible = 1;
    sprite_setVelocity(&b->s, b->initialVelocity.x, b->initialVelocity.y);
    b->posHistory[b->historyIndex] = (Vector2){ b->s.x, b->s.y };
    if (b->s.y > Core.Player->s.y + game_height) {  // ricade dall'alto
        b->s.x = Core.Player->s.x + (frand() - 0.5f) * game_width * 0.25f;
        b->s.y = Core.Player->s.y - game_height;
        b->initialVelocity.y = b->defaultVelocityY;
    }
}
static const BulletVT B_Larobba = { "items", "Larobba01.png", B_Larobba_ctor, NULL, B_Larobba_OnRecycle, B_Larobba_OnHasHitAnObject, B_Larobba_Update, B_Larobba_DeSpawn };
static void W_Larobba_shuffle(Weapon *w) {
    shuffle(w->targetAngles, w->maxAngles);
    for (int i = 22; i > 0; i--) { int j = (int)floorf(frand() * (i + 1)); const char *t = w->robbaFrames[i]; w->robbaFrames[i] = w->robbaFrames[j]; w->robbaFrames[j] = t; }
}
static void W_Larobba_ctor(Weapon *w) {
    static const char *const names[23] = { "Larobba01.png", "Larobba02.png", "Larobba03.png", "Larobba04.png", "Larobba05.png", "Larobba06.png", "Larobba07.png",
        "Larobba08.png", "Larobba09.png", "Larobba10.png", "Larobba11.png", "Larobba12.png", "Larobba13.png", "Larobba14.png", "Larobba15.png", "Larobba16.png",
        "Larobba17.png", "Larobba18.png", "Larobba19.png", "Larobba20.png", "Larobba21.png", "Larobba22.png", "Larobba23.png" };
    w->maxAngles = 0xc;
    for (int i = 0; i < w->maxAngles; i++) w->targetAngles[i] = 0.25f * PI + 0.5f * PI * i / w->maxAngles;
    for (int i = 0; i < 23; i++) w->robbaFrames[i] = names[i];
    W_Larobba_shuffle(w);
}
static int W_Larobba_LevelUp(Weapon *w) { W_Larobba_shuffle(w); return base_LevelUp(w); }
// CheckArcanas: beginning (amount + 1) e Twilight: arcane
static const WeaponVT W_Larobba = { BASE, .CheckArcanas = CA_inverseBeginning, .bullet = &B_Larobba, .ctor = W_Larobba_ctor, .PBounces = bonus_PBounces, .LevelUp = W_Larobba_LevelUp };

// --- Dairy Cart: W_Cart (0xa23f), B_Cart (0x3717) ------------------------------------------------------------
// Un carretto che sfreccia verso destra dal punto in cui e' stato rotto un distruttibile (sottoclasse di 0x13fb9,
// OnDestroyed: AddHiddenWeapon(CART), Location, RemoveHiddenWeapon dopo 5 s). Quel distruttibile arriva con il suo stage.
static void B_Cart_ctor(Bullet *b) {
    b->Pfx = particles_add();
    particles_createEmitter(b->Pfx, (EmitterConfig){ .frames = { frame_get("vfx", "PfxYellow.png") }, .nframes = 1, .rotate = ERND(0, 0x168),
        .angle = ERND(0, 0x168), .speed = ERND(0x32, 0x64), .quantity = 1, .lifespan = EOP(0xc8), .scale = ERANGE(1, 0), .on = 0 });
    b->defaultSpeed = b->_speed;
}
static void B_Cart_OnRecycle(Bullet *b) {
    Weapon *w = b->weapon;
    Bullet_OnRecycle(b);
    sprite_setScale(&b->s, 1);
    sprite_setOrigin(&b->s, 0.5f, 1);
    body_setCircle(&b->s.body, 0x30, b->s.body.offset.x, b->s.body.offset.y);
    b->_speed = b->defaultSpeed;
    b->s.x = w->hasLocation ? w->Location.x : Core.Player->s.x, b->s.y = w->hasLocation ? w->Location.y : Core.Player->s.y;
    b->s.depth = b->s.y - Core.Player->s.y + game_height;
    b->Pfx->s.depth = b->s.depth - 1;
    b->s.body.velocity = velocityFromRotation(0, Bullet_TrueSpeed(b));
    Sound_PlaySound("Hit", 0.7f, 1, 0x1f4 * (-1 - frand()), 0x96, 2);
    Sound_PlaySound("Brakes", 0.3f, 1, 0xc8 * frand(), 0x96, 2);
}
static void B_Cart_Update(Bullet *b, float delta) {
    b->_speed += 1 * delta;  // (sic) la velocita' si e' gia' fissata in OnRecycle: non accelera
    manager_emitParticleAt(b->Pfx, b->s.x, b->s.y - 2);
    manager_emitParticleAt(b->Pfx, b->s.x, b->s.y - 0x16);
}
static const BulletVT B_Cart = { "items", "Cart1.png", B_Cart_ctor, NULL, B_Cart_OnRecycle, NULL, B_Cart_Update, NULL };
static float W_Cart_PPower(Weapon *w) { return Core.Player->power * w->power * (1 + 2 * frand()); }
static float W_Cart_PInterval(Weapon *w) { return fmaxf(fmaxf(0.1f, Core.Player->cooldown) * w->interval, 0x2710); }
// onBulletOverlapsEnemy: come la base (GetDamaged con il tipo CART); ResetFiringTimer: solo destroy, parte su richiesta
static const WeaponVT W_Cart = { BASE, .bullet = &B_Cart, .PAmount = one_PAmount, .PPower = W_Cart_PPower, .PInterval = W_Cart_PInterval,
                                 .ResetFiringTimer = noop_ResetFiringTimer };

// --- Crimson Shroud: W_Shroud (0xe905), B_Shroud (0x16767) ---------------------------------------------------
// Alloro evoluto: danno subito al massimo 10, e ogni scudo perso restituisce il colpo con un'onda (10% del danno assorbito).
static void Shroud_inverseDraw(Sprite *s) {  // inverseFilter: colori invertiti in un cerchio attorno al centro dello schermo
    Weapon *w = s->owner;
    if (w->invRadius <= 0 || Core.weaponWithShader) return;  // MakeInverseCameraPlugin non crea il filtro con SOLES
    rlSetBlendFactorsSeparate(RL_ONE_MINUS_DST_COLOR, RL_ZERO, RL_ZERO, RL_ONE, RL_FUNC_ADD, RL_FUNC_ADD);  // rgb = 1 - sotto; alpha della render texture intatto
    BeginBlendMode(BLEND_CUSTOM_SEPARATE);
    DrawCircleV((Vector2){ s->x, s->y }, w->invRadius, WHITE);
    EndBlendMode();
}
static void W_Shroud_CheckColor(Weapon *w, float dmg) {
    w->image.visible = 1;
    switch ((int)Core.Player->shields) {
    default:
    case 0: w->image.visible = 0; break;
    case 1: w->image.tint = 0xffff00; break;
    case 2: w->image.tint = 0xff8800; break;
    case 3: w->image.tint = 0xff0000; break;
    }
    if (dmg <= 0) return;
    w->lastReceivedDamage = 0.1f * fminf(dmg, 0x64);
    base_Fire(w);
}
static void W_Shroud_onLostShield(void *ctx) { W_Shroud_CheckColor(ctx, PlayerEvents_arg); }
static void W_Shroud_ctor(Weapon *w) {
    W_Laurel_ctor(w);  // maxCharges, image Shockwave2 coi suoi due tween
    PlayerEvents_remove(w), laurel = NULL;  // il colorEvent di Shroud passa il danno
    PlayerEvents_add(EV_PLAYER_LOSTSHIELD, W_Shroud_onLostShield, w);
    sprite_init(&w->inverse, NULL, 0, 0);  // Core.MakeInverseCameraPlugin (rexInversePostFx); nessun filtro negli stage BATCOUNTRY e FOSCARI, ne' con SOLES
    w->inverse.owner = w, w->inverse.draw = Shroud_inverseDraw, w->inverse.scrollFactor0 = 1, w->inverse.depth = MAX_SAFE_INTEGER;
    children_add(&w->inverse);
}
static void W_Shroud_OnStart(Weapon *w) {  // niente collider dei muri
    Weapon_ResetFiringTimer(w);
    time_addEvent(1, 0, 0, Weapon_FireCb, w);
    Core.Player->shroud = 0xa;
    physics_addOverlap(&w->pool->group, &Core.Enemies, Weapon_onBulletOverlapsEnemy_Retaliation, w);
    physics_addOverlap(&w->pool->group, &Core.Destructibles, Weapon_onBulletOverlapsDestuctible, w);
    w->canPlayInversionVFX = 1;
}
static void W_Shroud_Fire(Weapon *w) {
    Player *p = Core.Player;
    if (p->shields < w->charges && p->shields < w->maxCharges) p->shields += 1;
    W_Shroud_CheckColor(w, 0);
    if (w->lastFiringInterval != Weapon_PInterval(w)) {
        w->lastFiringInterval = Weapon_PInterval(w);
        Weapon_ResetFiringTimer(w);
    }
}
static float W_Shroud_PPower(Weapon *w) { return fminf(10, (Arcanas.silentMight + Core.Player->power) * sinev(Core.Player->sineMight)) * (w->power + w->lastReceivedDamage) * Player_PCurse(Core.Player) + Arcanas.bloodlineDamage; }
static void W_Shroud_canPlay(void *ctx) { ((Weapon *)ctx)->canPlayInversionVFX = 1; }
static void W_Shroud_InversionVFX(Weapon *w, float radius, float duration, float offY) {
    if (!w->canPlayInversionVFX) return;  // weaponWithShader: nessuna arma tradotta lo imposta
    w->canPlayInversionVFX = 0;
    Sound_PlaySound("Shroud", 1, fmaxf(1, 2 - 0.25f * Weapon_PAmount(w)), 0, 0x190, 1);
    float d = Weapon_PAmount(w) * duration * 0.5f;
    w->inverse.x = 0.5f * game_width, w->inverse.y = 0.5f * game_height - offY;  // setCenter
    w->invRadius = 0;  // onStart
    tweens_add((TweenConfig){ .props = { { &w->invRadius, NULL, radius } }, .nprops = 1, .duration = d, .yoyo = 1, .onComplete = W_Shroud_canPlay, .ctx = w });
}
static void B_Shroud_ctor(Bullet *b) {
    b->radius = 0x10;
    b->s.x = Core.Player->s.x, b->s.y = Core.Player->s.y;
    sprite_init(&b->summon, frame_get("vfx", "bubblevb.png"), 0, 0);  // bubble
    sprite_setOrigin(&b->summon, 0.5f, 0.75f);
    b->summon.alpha = 0;
    children_add(&b->summon);
    sprite_setOrigin(&b->s, 0.5f, 0.75f);
    b->ScaleTween = TWEEN_NONE;
    b->ExpireTimer = (Timer){ -1, 0 };
}
static void B_Shroud_despawn(void *ctx) { Bullet_DeSpawn(ctx); }
static void B_Shroud_OnRecycle(Bullet *b) {
    Weapon *w = b->weapon;
    Bullet_OnRecycle(b);
    sprite_setScale(&b->s, 1);
    body_setCircle(&b->s.body, b->radius, b->s.body.offset.x, b->s.body.offset.y);
    sprite_setScale(&b->s, 0);
    b->s.alpha = 0.5f;
    b->s.visible = 0;
    b->summon.blendAdd = 1;
    time_removeEvent(b->ExpireTimer);
    b->summon.alpha = 1;
    sprite_setScale(&b->summon, 0);
    tween_stop(b->ScaleTween);
    float sc = 2 * PixelScale * Weapon_PArea(w);
    TweenProp pr[4] = { { &b->s.scaleX, &b->s.scaleY, sc }, { &b->s.alpha, NULL, 0 }, { &b->summon.scaleX, &b->summon.scaleY, sc }, { &b->summon.alpha, NULL, 0 } };
    b->ScaleTween = tweens_add((TweenConfig){ .many = pr, .nmany = 4, .duration = 0x190, .onComplete = B_Shroud_despawn, .ctx = b });
    float r = 2 * b->radius * Weapon_PArea(w);
    W_Shroud_InversionVFX(w, r, 0xc8, r * (1 - 0.75f));
}
static void B_Shroud_Update(Bullet *b, float delta) {
    (void)delta;
    b->s.x = Core.Player->s.x, b->s.y = Core.Player->s.y;
    b->summon.x = b->s.x, b->summon.y = b->s.y;
}
static const BulletVT B_Shroud = { "vfx", "Rings4.png", B_Shroud_ctor, NULL, B_Shroud_OnRecycle, NULL, B_Shroud_Update, NULL };
// hasThorns: sempre falso (il costruttore lo riceve dalla factory a false); TriggerAstronomia(SHROUD) non fa nulla
static const WeaponVT W_Shroud = { BASE, .bullet = &B_Shroud, .ctor = W_Shroud_ctor, .PPower = W_Shroud_PPower, .Fire = W_Shroud_Fire,
                                   .OnStart = W_Shroud_OnStart, .Update = W_Laurel_Update, .LevelUp = W_Laurel_LevelUp };

