static const WeaponVT W_Insatiable = { BASE, .bullet = &B_BloodAstronomia, .ctor = W_Insat_ctor, .PPower = W_Insat_PPower, .PAmount = one_PAmount, .PArea = W_Astro_PArea, .Fire = W_Insat_Fire, .Update = W_Insat_Update };

