static struct { float restored; } Molise;
static void Molise_Create(void) { memset(&Molise, 0, sizeof(Molise)); }
static void Molise_RestoreHp(float v) {
    Molise.restored += v;
    if (Molise.restored > 0x2710 && Char_found("PEPPINO", 1, 1)) Sound_PlaySound("ThingFound", 1, 0.5f, -0x3e8, 0, 0);
}
