// --- MOLISANO_* (0x2037): fermi, crescono e poi diventano immobili (fuori da EnemyGroup); FLOWER li cura e da' esperienza ---------
static void Molisano_entered(void *ctx) { Enemy *e = ctx; e->s.body.immovable = 1; list_remove(&Core.EnemyGroup, &e->s); }
static void E_Molisano_OnRecycle(Enemy *e) {
    base_EnemyOnRecycle(e);
    e->speed = 0, sprite_setScale(&e->s, 0), e->s.body.immovable = 0;
    e->s.flipX = frand() >= 0.5f;
    if (po_is("SelectedInverse")) {
        if (po_is("VisuallyInvertStages")) e->s.flipY = 1, sprite_setOrigin(&e->s, 0.5f, 0);
        else e->s.flipY = 0, sprite_setOrigin(&e->s, 0.5f, 1);
        e->saveTint = 0xff88ff, sprite_setTint(&e->s, e->saveTint);
    } else e->s.flipY = 0, sprite_setOrigin(&e->s, 0.5f, 1), e->saveTint = 0xffffff;
    tween_restartOrAdd(&e->OnEnterTween, (TweenConfig){ .props = { { &e->s.scaleX, &e->s.scaleY, e->scaleMul }, { &e->speed, NULL, 0 } }, .nprops = 2, .duration = 0x12c,
                                                       .onComplete = Molisano_entered, .ctx = e });
}
static void E_Molisano_Die(Enemy *e) { base_EnemyDie(e); e->s.body.enable = 0; }
static void E_Molisano_Update(Enemy *e) {
    if (e->isDead) return;
    e->s.depth = e->s.y - Core.Player->s.y;
    if (!e->IsTimeStopped) e->s.angle = TweenAngles[e->moveTweenIndex];
}
static void E_Molisano_GetDamaged(Enemy *e, float amount, int hitVFX, float kb, const char *t) {
    if (!t || strcmp(t, "FLOWER")) { base_EnemyGetDamaged(e, amount, hitVFX, kb, t); return; }
    e->hp += amount;
    Player_AddXP(Core.Player, 0.005f * Core.Player->level);
    Core_ShowRecoveryAt(e->s.x, e->s.y, amount);
    if (!strcmp(Core.Stage->stageType, "MOLISE") && Core.Stage->fancyBG == &FB_Molise) Molise_RestoreHp(amount);
}
static const EnemyVT E_Molisano = { .OnRecycle = E_Molisano_OnRecycle, .Die = E_Molisano_Die, .GetDamaged = E_Molisano_GetDamaged, .Update = E_Molisano_Update };

// --- MOLISANO_ANFORA (0x4e61): un molisano mai specchiato; rotto, lascia una moneta che vola dal giocatore ---------------------------
