static void E_FAngel_Disappear(Enemy *e) { base_EnemyDisappear(e); if (Core.Stage->fancyBG == &FB_Chapel && Chapel.alias) anims_play(&e->s, &((BridgeX *)e->x)->aliasDie, 0); }
