// --- TRINACRIA / BOSS_TRINACRIA (0x154be): corpo, ali, serpenti e gambe che girano; ferma finche' il giocatore non arriva a 1024 px ---
typedef struct { Sprite wings, snakes, legs; Animation aw, as, al; } TrinaX;
static void Trina_UpdateSprites(Enemy *e) {
    TrinaX *t = e->x;
    Sprite *w = &t->wings, *sn = &t->snakes, *l = &t->legs;
    w->flipX = sn->flipX = l->flipX = e->s.flipX;
    w->scaleX = sn->scaleX = l->scaleX = e->s.scaleX, w->scaleY = sn->scaleY = l->scaleY = e->s.scaleY;
    w->angle = sn->angle = e->s.angle;
    w->originX = sn->originX = e->s.originX, w->originY = sn->originY = e->s.originY;
    w->x = sn->x = l->x = e->s.x;
    w->y = e->s.y, sn->y = e->s.y + 4 * e->s.scaleY, l->y = e->s.y - 0xc * e->s.scaleY;
    sn->depth = e->s.depth - 1, l->depth = e->s.depth - 2, w->depth = e->s.depth - 3;
    l->angle *= e->s.flipX ? 1 : -1;  // sul valore del tween: senza flip le gambe girano al contrario a ogni frame (sic)
}
static void Trina_ctor(Enemy *e, TrinaX *t) {  // costruttore: ali, serpenti e gambe
    struct { Sprite *s; Animation *a; const char *p; } P[3] = { { &t->wings, &t->aw, "trinaW_" }, { &t->snakes, &t->as, "trinaS_" }, { &t->legs, &t->al, "trinaL_" } };
    for (int i = 0; i < 3; i++) {
        sprite_init(P[i].s, frame_get("enemies2", TextFormat("%s01.png", P[i].p)), e->s.x, e->s.y);
        P[i].a->n = anims_generateFrameNames("enemies2", P[i].p, 1, 4, 2, P[i].a->frames, ANIM_MAX_FRAMES);
        P[i].a->frameRate = 0xa, P[i].a->msPerFrame = 100, P[i].a->repeat = -1;
        anims_play(P[i].s, P[i].a, 0);
        children_add(P[i].s);
    }
    tweens_add((TweenConfig){ .props = { { &t->legs.angle, NULL, 0x167 } }, .nprops = 1, .duration = 0x3e8, .repeat = -1 });
    e->isCullable = 0, e->activated = 0;
}
static void E_Trina_OnRecycle(Enemy *e) {
    if (!e->x) Trina_ctor(e, e->x = calloc(1, sizeof(TrinaX)));
    base_EnemyOnRecycle(e);
    TrinaX *t = e->x;
    Trina_UpdateSprites(e);
    t->wings.visible = t->snakes.visible = t->legs.visible = 1;
    e->defaultSpeed = num(enemy_data(e), "speed", 0);  // _defaultSpeed
}
static void E_Trina_Update(Enemy *e) {
    e->speed = e->defaultSpeed * e->activated;
    float dx = e->s.x - Core.Player->s.x, dy = e->s.y - Core.Player->s.y;
    if (sqrtf(dx * dx + dy * dy) < 0x400) e->activated = 1;
    base_EnemyUpdate(e);
    Trina_UpdateSprites(e);
}
static void Trina_hide(Enemy *e) { TrinaX *t = e->x; t->wings.visible = t->snakes.visible = t->legs.visible = 0; }
static void E_Trina_Disappear(Enemy *e) { base_EnemyDisappear(e); Trina_hide(e); }
static void E_Trina_Die(Enemy *e) { base_EnemyDie(e); Trina_hide(e); }
static void E_Trina_DeSpawn(Enemy *e) { base_EnemyDeSpawn(e); Trina_hide(e); }
static const EnemyVT E_Trina = { .OnRecycle = E_Trina_OnRecycle, .Die = E_Trina_Die, .Update = E_Trina_Update, .DeSpawn = E_Trina_DeSpawn, .Disappear = E_Trina_Disappear };

// --- MOON_SNEK / MOON_SNEK_GREEN (0x1026f), MOON_SNEK_RED (0x14ccb): serpenti tinti a caso, il muso nella direzione di marcia -----------
static void Snake_angle(Enemy *e) { e->s.angle = -0x5a + atan2f(e->s.body.velocity.y, e->s.body.velocity.x - 1) * RAD2DEG; }  // Vector2.RIGHT
static void E_Snake_recycle(Enemy *e, const unsigned *tints) {
    base_EnemyOnRecycle(e);
    sprite_setOrigin(&e->s, 0.5f, 0.5f);
    e->saveTint = tints[(int)floorf(frand() * 3)], sprite_setTint(&e->s, e->saveTint);
}
static void E_Snake_OnRecycle(Enemy *e) { static const unsigned T[3] = { 0x44bbff, 0x88ffff, 0x44ffbb }; E_Snake_recycle(e, T); }
static void E_SnakeRed_OnRecycle(Enemy *e) { static const unsigned T[3] = { 0xff8844, 0xff8888, 0xff4444 }; E_Snake_recycle(e, T); }
static void E_Snake_Update(Enemy *e) { base_EnemyUpdate(e); Snake_angle(e); }
static const EnemyVT E_Snake = { .OnRecycle = E_Snake_OnRecycle, .Update = E_Snake_Update };
static const EnemyVT E_SnakeRed = { .OnRecycle = E_SnakeRed_OnRecycle, .Update = E_Snake_Update };

// --- MOON_CRABBINO / MOON_BOSS_CRABBINO (0xf2ec): due chele come sprite a parte, che spariscono rimpicciolendo ----------------------
typedef struct { Sprite L, R; Animation idle; TweenRef fade; } CrabbinoX;
static void Crabbino_place(Enemy *e) {
    CrabbinoX *c = e->x;
    c->L.x = e->s.x - 0x1b * e->s.scaleX, c->L.y = e->s.y - 0x1c * e->s.scaleY, c->L.depth = e->s.depth + 1, c->L.angle = e->s.angle;
    c->R.x = e->s.x + 0x1b * e->s.scaleX, c->R.y = e->s.y - 0x1c * e->s.scaleY, c->R.depth = e->s.depth + 1, c->R.angle = e->s.angle;
}
static void E_Crabbino_OnRecycle(Enemy *e) {
    if (!e->x) {
        CrabbinoX *c = e->x = calloc(1, sizeof(CrabbinoX));
        c->idle.n = anims_generateFrameNames("enemies2", "XLPincer_i", 1, 4, 2, c->idle.frames, ANIM_MAX_FRAMES);
        c->idle.frameRate = 8, c->idle.msPerFrame = 125, c->idle.repeat = -1, c->fade = (TweenRef){ -1, 0 };
        Sprite *p[2] = { &c->L, &c->R };
        for (int i = 0; i < 2; i++) sprite_init(p[i], frame_get("enemies2", "XLPincer_i01.png"), e->s.x, e->s.y), sprite_setOrigin(p[i], 0.5f, 1), anims_play(p[i], &c->idle, 0), children_add(p[i]);
    }
    CrabbinoX *c = e->x;
    base_EnemyOnRecycle(e);
    c->R.flipX = 1, c->L.flipX = 0;
    tween_stop(c->fade);
    sprite_setScale(&c->R, e->s.scaleX), sprite_setScale(&c->L, e->s.scaleX);
    sprite_setTint(&c->R, e->saveTint), sprite_setTint(&c->L, e->saveTint);
    Crabbino_place(e);
}
static void Crabbino_fade(Enemy *e) {
    CrabbinoX *c = e->x;
    tween_stop(c->fade);
    c->fade = tweens_add((TweenConfig){ .props = { { &c->L.scaleX, &c->L.scaleY, 0 }, { &c->R.scaleX, &c->R.scaleY, 0 } }, .nprops = 2, .duration = 0xc8 });
}
static void E_Crabbino_Die(Enemy *e) { base_EnemyDie(e); Crabbino_fade(e); }
static void E_Crabbino_Disappear(Enemy *e) { base_EnemyDisappear(e); Crabbino_fade(e); }
static void E_Crabbino_DeSpawn(Enemy *e) { Crabbino_fade(e); base_EnemyDeSpawn(e); }
static void E_Crabbino_Update(Enemy *e) { base_EnemyUpdate(e); Crabbino_place(e); }
static const EnemyVT E_Crabbino = { .OnRecycle = E_Crabbino_OnRecycle, .Die = E_Crabbino_Die, .Update = E_Crabbino_Update, .DeSpawn = E_Crabbino_DeSpawn, .Disappear = E_Crabbino_Disappear };

// --- MOON_EYE1-3 (0xe682): occhi che perdono sangue e lettere (h a s, t u r) da un cerchio attorno ---------------------------------
typedef struct { ParticleManager *m1, *m2; ParticleEmitter *e1, *e2; Vector2 edge[0x30]; float totalTime; } MoonEyeX;
static void E_MoonEye_OnRecycle(Enemy *e) {
    if (!e->x) {
        MoonEyeX *m = e->x = calloc(1, sizeof(MoonEyeX));
        static const char *const F1[6] = { "Blood1.png", "Blood2.png", "Blood3.png", "h.png", "a.png", "s.png" }, *const F2[6] = { "Blood1.png", "Blood2.png", "Blood3.png", "t.png", "u.png", "r.png" };
        EmitterConfig c = { .nframes = 6, .angle = ERND(0, 0x168), .speed = ERND(0xf, 0x1e), .quantity = 1, .lifespan = EOP(0x226), .alpha = ERANGE(1, 0), .scale = ERANGE(0.5f, 0), .on = 0 };
        for (int i = 0; i < 6; i++) c.frames[i] = frame_get("vfx", F1[i]);
        c.hasZone = 1, c.zoneRadius = 0x10;
        m->m1 = particles_add(), m->e1 = particles_createEmitter(m->m1, c);
        for (int i = 0; i < 6; i++) c.frames[i] = frame_get("vfx", F2[i]);
        c.hasZone = 0, c.edge = m->edge, c.nEdge = 0x30;
        m->m2 = particles_add(), m->e2 = particles_createEmitter(m->m2, c);
    }
    MoonEyeX *m = e->x;
    base_EnemyOnRecycle(e);
    m->totalTime = 0;
    float r = 0x10 * e->s.scaleX;  // explosionCircle (0, 0, 16 * scale): zona casuale e bordo (48 punti)
    m->e1->c.zoneRadius = r;
    for (int i = 0; i < 0x30; i++) m->edge[i] = (Vector2){ r * cosf(2 * PI * i / 0x30), r * sinf(2 * PI * i / 0x30) };
    m->e1->c.scale = m->e2->c.scale = ERANGE(0.5f * e->s.scaleX, 0);
}
static void E_MoonEye_Update(Enemy *e) {
    MoonEyeX *m = e->x;
    base_EnemyUpdate(e);
    if (e->s.scaleX < 1) return;
    m->totalTime += Enemies_delta;
    if (m->totalTime > 0x1e) {
        m->totalTime -= 0x1e;
        emitter_emitParticleAt(m->e1, e->s.x, e->s.y - 0xc * e->s.scaleX, 0), emitter_emitParticleAt(m->e2, e->s.x, e->s.y - 0xc * e->s.scaleX, 0);
    }
    m->m1->s.depth = e->s.depth - 1, m->m2->s.depth = e->s.depth + 1;
}
static const EnemyVT E_MoonEye = { .OnRecycle = E_MoonEye_OnRecycle, .Update = E_MoonEye_Update };

// --- MOON_EYE1S-3S (0x150c1): girano attorno al giocatore su un'ellisse che respira -------------------------------------------------
typedef struct { float spinAngle, radius; TweenRef rt, st; } EyeSpinX;
static void E_EyeSpin_OnRecycle(Enemy *e) {
    if (!e->x) { EyeSpinX *k = e->x = calloc(1, sizeof(EyeSpinX)); k->spinAngle = 2 * frand() * PI, k->radius = 1, k->rt = k->st = (TweenRef){ -1, 0 }; }
    EyeSpinX *k = e->x;
    base_EnemyOnRecycle(e);
    k->radius = 1;
    tween_stop(k->rt);
    k->rt = tweens_add((TweenConfig){ .props = { { &k->radius, NULL, 0.65f } }, .nprops = 1, .duration = 0x7d0 + 0x7d0 * frand(), .yoyo = 1, .repeat = -1, .ease = Ease_SineInOut });
    sprite_setScale(&e->s, 0);
    tween_stop(k->st);
    k->st = tweens_add((TweenConfig){ .props = { { &e->s.scaleX, &e->s.scaleY, e->scaleMul } }, .nprops = 1, .duration = 0x12c + 0x3e8 * frand() });
}
static void E_EyeSpin_Update(Enemy *e) {
    EyeSpinX *k = e->x;
    base_EnemyUpdate(e);  // depthOverride = 0: mai usato
    e->s.flipX = 0;
    k->spinAngle += -0.001f * Enemies_delta;
    e->s.x = Core.Player->s.x + cosf(k->spinAngle) * game_width * 0.475f * k->radius;
    e->s.y = Core.Player->s.y + 0x10 + sinf(k->spinAngle) * game_height * 0.45f * k->radius;
    e->s.angle = -0xb4 + atan2f(e->s.body.velocity.y, e->s.body.velocity.x - 1) * RAD2DEG;
}
static const EnemyVT E_EyeSpin = { .OnRecycle = E_EyeSpin_OnRecycle, .Update = E_EyeSpin_Update };

// --- MOON_ANFORA (0x13f3): l'anfora del Molise tinta d'azzurro; sparisce rimpicciolendo (ma dopo la morte va via subito) ------------
static void MoonAnfora_deathDone(void *ctx) { base_EnemyDeSpawn(ctx); }  // OnDeathAnimationComplete: super.DeSpawn, senza tween
static void MoonAnfora_scaledOut(void *ctx) { base_EnemyDeSpawn(ctx); }
static void E_MoonAnfora_OnRecycle(Enemy *e) {
    tween_stop(e->ScaleTween);  // despawnTween
    E_Molisano_OnRecycle(e);
    e->s.flipX = 0;
    static const unsigned T[3] = { 0x44bbff, 0x88ffff, 0x44ffff };
    e->saveTint = T[(int)floorf(frand() * 3)], sprite_setTint(&e->s, e->saveTint);
    e->isCullable = 0, e->isTeleportOnCull = 1;
    e->s.onAnimationComplete = MoonAnfora_deathDone;
}
static void E_MoonAnfora_Update(Enemy *e) { E_Molisano_Update(e); e->s.angle = 0; }
static void E_MoonAnfora_DeSpawn(Enemy *e) {
    e->isDespawning = 1;
    tween_stop(e->ScaleTween);
    e->ScaleTween = tweens_add((TweenConfig){ .props = { { &e->s.scaleX, &e->s.scaleY, 0 } }, .nprops = 1, .duration = 0xc8, .onComplete = MoonAnfora_scaledOut, .ctx = e });
}
static const EnemyVT E_MoonAnfora = { .OnRecycle = E_MoonAnfora_OnRecycle, .Die = E_Anfora_Die, .GetDamaged = E_Molisano_GetDamaged, .Update = E_MoonAnfora_Update, .DeSpawn = E_MoonAnfora_DeSpawn };

// --- MOON_TRINACRIA / _X (0x5cfa): la Trinacria con 20 s di scudo (il danno si accumula e arriva tutto allo scadere) -------------------
typedef struct { TrinaX t; int hasShield; float shieldDamage; Timer shieldTimer; } MoonTrinaX;
static void MoonTrina_shieldOff(void *ctx) { Enemy *e = ctx; MoonTrinaX *m = e->x; m->hasShield = 0, e->hp -= m->shieldDamage; }
static void E_MoonTrina_OnRecycle(Enemy *e) {
    if (!e->x) { MoonTrinaX *m = e->x = calloc(1, sizeof(MoonTrinaX)); m->shieldTimer = (Timer){ -1, 0 }; Trina_ctor(e, &m->t); }  // TrinaX in testa
    MoonTrinaX *m = e->x;
    E_Trina_OnRecycle(e);
    e->isTeleportOnCull = 1, m->shieldDamage = 0, m->hasShield = 1;
    time_removeEvent(m->shieldTimer);
    m->shieldTimer = time_addEvent(0x4e20, 0, 0, MoonTrina_shieldOff, e);
}
static void E_MoonTrina_GetDamaged(Enemy *e, float amount, int hitVFX, float kb, const char *t) {
    (void)t;
    MoonTrinaX *m = e->x;
    if (amount > 0) Core_ShowDamageAt(e->s.x, e->s.y, amount);
    if (m->hasShield) m->shieldDamage += amount; else e->hp -= amount;
    if (e->hp <= 0) Enemy_Die(e); else e->damageKB = kb;
    Sound_PlaySound("Hit", 0.5f, 1, 0x1f4 * (frand() - 0.5f), 0x96, 3);
    if (hitVFX != HIT_NONE) Core_ShowHitVFXAt(e->s.x, e->s.y, hitVFX);
    Enemy_OnGetDamaged(e, hitVFX);
}
static void E_MoonTrina_Die(Enemy *e) { E_Trina_Die(e); if (e->onDefeat) e->onDefeat(e); }
static const EnemyVT E_MoonTrina = { .OnRecycle = E_MoonTrina_OnRecycle, .Die = E_MoonTrina_Die, .GetDamaged = E_MoonTrina_GetDamaged, .Update = E_Trina_Update,
                                     .DeSpawn = E_Trina_DeSpawn, .Disappear = E_Trina_Disappear };

// --- MOON_MASK1-5, MASK_GOLD/SILVER/LEFT/RIGHT (0x862e): una maschera sopra il corpo; battuta, sbianca e svanisce -----------------------
static void E_Mask_place(Enemy *e) {
    Sprite *m = e->x;
    e->s.angle = 0, m->depth = e->s.depth + 1, m->x = e->s.x + (e->s.flipX ? 2 : -2), m->y = e->s.y - 0x2a * e->s.scaleY;
    m->scaleX = e->s.scaleX, m->scaleY = e->s.scaleY, m->flipX = e->s.flipX;
}
static void E_Mask_OnRecycle(Enemy *e) {
    if (!e->x) {
        static const char *const P[5] = { "mask1.png", "mask2.png", "mask3.png", "mask4.png", "mask5.png" };
        const char *t = e->enemyType, *f = !strcmp(t, "MASK_GOLD") ? "mask1.png" : !strcmp(t, "MASK_SILVER") ? "mask2.png" : !strcmp(t, "MASK_LEFT") ? "mask4.png"
                                         : !strcmp(t, "MASK_RIGHT") ? "mask5.png" : P[(int)floorf(frand() * 5)];
        Sprite *m = e->x = calloc(1, sizeof(Sprite));
        sprite_init(m, frame_get("enemies2", f), e->s.x, e->s.y);
        children_add(m);
    }
    Sprite *m = e->x;
    base_EnemyOnRecycle(e);
    e->s.flipX = 0, e->isTeleportOnCull = 1;
    if (e->HPxLevel) e->maxHp = 0x3e8 + e->dataMaxHp * Core.Player->level * EnemyHealthMultiplier * Core.Stage->EnemyHealthMultiplier;
    e->hp = e->maxHp;
    m->alpha = 1, m->tintFill = 0, m->tint = 0xffffff;
}
static void E_Mask_Die(Enemy *e) {
    Sprite *m = e->x;
    base_EnemyDie(e);
    Core_MakeStagePickup(e->s.x, e->s.y, "RELIC_GOLDENEGG", NULL);
    sprite_setTintFill(m, 0xffffff);
    tweens_add((TweenConfig){ .props = { { &m->alpha, NULL, 0 } }, .nprops = 1, .duration = 0x1f4 });
}
static void E_Mask_Update(Enemy *e) { base_EnemyUpdate(e); E_Mask_place(e); }
static const EnemyVT E_Mask = { .OnRecycle = E_Mask_OnRecycle, .Die = E_Mask_Die, .Update = E_Mask_Update };

// --- SINKING (0x545e): Moongolow. L'acqua in sovraimpressione e, per 14 minuti, l'eclissi: luce rossa, buio, la musica che rallenta,
// poi la camera a occhio di pesce (rexFishEyePostFx) e arrivano gli occhi e la Trinacria. Battuta lei: Holy Forbidden (sblocco: F3).
static struct { int on, mode; float intensity, radius; Shader sh; int locMode, locTex, locCenter, locRadius, locInt; } FishEye;
static struct {
    int canTriggerEclipse;
    TileSprite bgtile;
    Sprite moonpresence, fader, sDarkness;
    EnemyPool *pool_Anfora, *pool_Eyespin1, *pool_Eyespin2, *pool_Eyespin3, *pool_Trinacria;
    float rate, detune;
    int waterBGM;
    Timer anforaTimer;
} Moon;
static int Moon_validCharacter(void) {  // StageX.GetValidCharacters: i 20 personaggi del gioco base senza segreti
    static const char *const V[20] = { "ANTONIO", "IMELDA", "PASQUALINA", "GENNARO", "PAESANO", "ARCA", "PORTA", "LAMA", "CROCI", "CRISTINA",
                                       "DOMMARIO", "GERMANA", "MORTACCIO", "CAVALLO", "TATANKA", "MARIA", "PUGNALA", "CONCETTA", "POPPEA", "GIOVANNA" };
    for (int i = 0; i < 20; i++) if (Player_is(Core.Player, V[i])) return 1;
    return 0;
}
static void Moon_setMinute(int m, int minimum, const char *const *en, int nen, const char *const *bo, int nbo) {  // StageData.SINKING[m]: cambia i dati
    cJSON *d = cJSON_GetArrayItem(cJSON_GetObjectItem(data_get("stages"), "SINKING"), m);
    if (minimum) cJSON_ReplaceItemInObject(d, "minimum", cJSON_CreateNumber(minimum));
    cJSON_ReplaceItemInObject(d, "enemies", cJSON_CreateStringArray(en, nen));
    cJSON_ReplaceItemInObject(d, "bosses", cJSON_CreateStringArray(bo, nbo));
}
static void Moon_RestoreEclipse(void) {
    static const char *const E1[1] = { "MOON_EYE1" }, *const B1[2] = { "MOON_EYE2", "MOON_EYE2" }, *const E2[2] = { "MOON_EYE2", "MOON_EYE1" }, *const B2[2] = { "MOON_EYE3", "MOON_EYE3" }, *const E3[1] = { "MOON_SNEK_RED" };
    Moon_setMinute(0xc, 0xc8, E1, 1, B1, 2), Moon_setMinute(0xd, 0x78, E2, 2, B2, 2), Moon_setMinute(0xe, 0xc8, E3, 1, NULL, 0);
}
static void Moon_RemoveEclipse(void) {
    static const char *const G[1] = { "MOON_SNEK_GREEN" }, *const GB[1] = { "MOON_BOSS_GARLIC" }, *const GR[2] = { "MOON_SNEK_GREEN", "MOON_SNEK_RED" }, *const R[1] = { "MOON_SNEK_RED" },
                      *const M[3] = { "MOON_MASK1", "MOON_MASK2", "MOON_MASK3" };
    Moon_setMinute(0xc, 0xc8, G, 1, GB, 1), Moon_setMinute(0xd, 0xc8, GR, 2, GB, 1), Moon_setMinute(0xe, 0, R, 1, M, 3);
}
static void Moon_SendToHiddenGround(Enemy *e) {  // la Trinacria lunare battuta: si va a Holy Forbidden
    (void)e;
    if (Collected("RELIC_YELLOW") || !Moon_validCharacter()) return;
    Core.canInterrupt = 0;
    Sound_FadeMusic(0, 0x1388);
    Sound_PlaySound("BGM_Intro", 0.7f, 1, -0x76c, 0, 0);
    tweens_add((TweenConfig){ .props = { { &FishEye.radius, NULL, 1 }, { &FishEye.intensity, NULL, 0.2f } }, .nprops = 2, .ease = Ease_SineInOut, .duration = 0x2710 });  // Sine.easeIn
    // onStart: UnlockedStages + STAGEX, Save; onComplete: SelectedStage = STAGEX, BGM_Chapet, RestartMainScene. Sblocchi e cambio scena: F3
}
static void Moon_Cry(void *ctx) {
    (void)ctx;
    if (!Moon_validCharacter()) return;
    for (int i = 0; i < 0x3c; i++) EnemyPool_SpawnAt(Moon.pool_Eyespin1, 0, 0);
    for (int i = 0; i < 0x28; i++) EnemyPool_SpawnAt(Moon.pool_Eyespin2, 0, 0);
    for (int i = 0; i < 0x14; i++) EnemyPool_SpawnAt(Moon.pool_Eyespin3, 0, 0);
    Vector2 p = Stage_GetBossyPosition(Core.Stage);
    Enemy *t = EnemyPool_SpawnAt(Moon.pool_Trinacria, p.x, p.y);
    if (t) t->onDefeat = Moon_SendToHiddenGround;
}
static void Moon_waterBGM(void *ctx) {  // BGM_Water (mod Normal): rate 1.125 e detune -1000 in 13 minuti
    (void)ctx;
    if (BGM.idx != Sound_index("BGM_Water")) return;
    Moon.waterBGM = 1, Moon.rate = 1, Moon.detune = 0;
    tweens_add((TweenConfig){ .props = { { &Moon.rate, NULL, 1.125f }, { &Moon.detune, NULL, -0x3e8 } }, .nprops = 2, .duration = 0xea60 * 0xd });
}
static Vector2 Moon_GetPositionOutOfSight(float range) {
    Player *p = Core.Player;
    float a = p->s.body.velocity.x == 0 && p->s.body.velocity.y == 0 ? 2 * PI * frand() : atan2f(p->s.body.velocity.y, p->s.body.velocity.x) + (frand() - 0.5f) * range * DEG2RAD;
    return (Vector2){ p->s.x + 0.75f * cosf(a) * game_width, p->s.y + 0.75f * sinf(a) * game_height };
}
static void Moon_SpawnAnforaCluster(void *ctx) {
    (void)ctx;
    int n = (int)fminf(6 * Player_PLuck(Core.Player), 0x12);
    Vector2 p = Moon_GetPositionOutOfSight(0xf);
    for (int i = 0; i < n; i++) EnemyPool_SpawnAt(Moon.pool_Anfora, p.x, p.y);
}
static void Moon_Create(void) {  // costruttore + Create
    memset(&Moon, 0, sizeof(Moon));
    FishEye.on = 0;
    Moon.canTriggerEclipse = !Collected("RELIC_YELLOW") && Moon_validCharacter();
    if (Moon.canTriggerEclipse) FishEye.on = 1, FishEye.mode = 1, FishEye.radius = 0.5f * game_height, FishEye.intensity = 0;
    Moon.pool_Anfora = EnemyPool_new("MOON_ANFORA"), Moon.pool_Anfora->upperLimit = 0x64, Moon.pool_Anfora->isUncapped = 1;
    Moon.pool_Eyespin1 = EnemyPool_new("MOON_EYE1S"), Moon.pool_Eyespin2 = EnemyPool_new("MOON_EYE2S"), Moon.pool_Eyespin3 = EnemyPool_new("MOON_EYE3S");
    Moon.pool_Trinacria = EnemyPool_new("MOON_TRINACRIA");
    // spawnEggman: con la reliquia gialla, un milione di monete e 5000 uova (tranne Sigma); spawnHealer: reliquia gialla e 5000 uova del personaggio
    if (Collected("RELIC_YELLOW") && num(Egg_char(0), "total", 0) >= 0x1388) Core_MakeStagePickup(0x400, 0x800, "HEALER", NULL);
    if (strcmp(po_str("SelectedCharacter"), "SIGMA") && Collected("RELIC_YELLOW") && po_num("Coins") >= 0xf4240 && num(po("EggData"), "total", 0) >= 0x1388) {
        Pickup *eg = Core_MakeStagePickup(0x3f8, -0x410, "EGGMAN", NULL);
        if (eg) eg->s.flipX = 1;
    }
    float W = game_width, H = game_height, k = W / 0x200, hurry = 1;  // SelectedHurry: F3
    sprite_init(&Moon.moonpresence, frame_get("backgroundW", "whiteDot.png"), 0.5f * W, 0.5f * H);
    sprite_setScale(&Moon.moonpresence, W), Moon.moonpresence.depth = -0x7b2, Moon.moonpresence.scrollFactor0 = 1, Moon.moonpresence.alpha = 0, Moon.moonpresence.blendAdd = 1, sprite_setTint(&Moon.moonpresence, 0xff0000);
    sprite_init(&Moon.fader, frame_get("backgroundW", "blackDot.png"), 0.5f * W, 0.5f * H);
    sprite_setScale(&Moon.fader, W), Moon.fader.depth = -0x7bc, Moon.fader.scrollFactor0 = 1, Moon.fader.alpha = 0;
    children_add(&Moon.moonpresence), children_add(&Moon.fader);
    sprite_init(&Moon.bgtile.s, NULL, 0.5f * W, 0.5f * H);
    Moon.bgtile.s.draw = TileSprite_draw, Moon.bgtile.s.scrollFactor0 = 1, Moon.bgtile.s.depth = -0x7c6, Moon.bgtile.s.blendAdd = 1, Moon.bgtile.s.alpha = 0.25f, Moon.bgtile.s.tint = 0xffffff;
    Moon.bgtile.tex = frame_texture("backgroundW", "spr_water_0.png"), Moon.bgtile.w = W, Moon.bgtile.h = H;
    sprite_setScale(&Moon.bgtile.s, k);
    children_add(&Moon.bgtile.s);
    sprite_init(&Moon.sDarkness, frame_get("vfx", "blackDot.png"), 0, 0);
    sprite_setOrigin(&Moon.sDarkness, 0, 0), Moon.sDarkness.scrollFactor0 = 1, Moon.sDarkness.scaleX = W, Moon.sDarkness.scaleY = H, Moon.sDarkness.alpha = 0, Moon.sDarkness.depth = 0x2710;
    children_add(&Moon.sDarkness);
    if (Moon.canTriggerEclipse) {
        Moon_RestoreEclipse();
        float m = getenv("VS_MOONFAST") ? 0x3e8 : 0xea60;  // StartEclipse (sviluppo: VS_MOONFAST=1, minuti da un secondo)
        tweens_add((TweenConfig){ .props = { { &Moon.moonpresence.alpha, NULL, 0.6f }, { &Moon.fader.alpha, NULL, 0.6f } }, .nprops = 2, .duration = m * hurry * 0xe });
        tweens_add((TweenConfig){ .props = { { &FishEye.intensity, NULL, 0.2f } }, .nprops = 1, .ease = Ease_SineInOut, .duration = 0x2710, .delay = m * hurry * 0xe, .onStart = Moon_Cry });  // Sine.easeIn
        time_addEvent(0x3e8, 0, 0, Moon_waterBGM, NULL);
    } else Moon_RemoveEclipse();
    tweens_add((TweenConfig){ .props = { { &Moon.bgtile.s.scaleX, NULL, 1.25f * k } }, .nprops = 1, .ease = Ease_SineInOut, .duration = 0x1388, .yoyo = 1, .repeat = -1 });  // Sine.easeIn
    tweens_add((TweenConfig){ .props = { { &Moon.bgtile.s.scaleY, NULL, 1.25f * k } }, .nprops = 1, .ease = Ease_SineOut, .duration = 0x1770, .yoyo = 1, .repeat = -1 });
    tweens_add((TweenConfig){ .props = { { &Moon.bgtile.s.alpha, NULL, 0.15f } }, .nprops = 1, .ease = Ease_SineInOut, .duration = 0x1b58, .yoyo = 1, .repeat = -1 });
    Moon.anforaTimer = time_addEvent(0x2710 * hurry, 1, 0, Moon_SpawnAnforaCluster, NULL);  // 'Desct Timer' del fancyBG: i bracieri dello stage restano
}
static void Moon_Update(float delta) {
    (void)delta;
    Moon.bgtile.tilePositionX = Core.Player->s.x, Moon.bgtile.tilePositionY = Core.Player->s.y;  // visible = FlashingVFXEnabled
    if (Moon.waterBGM && BGM.playing) SetMusicPitch(BGM.music, Moon.rate * powf(2, Moon.detune / 1200));
}
static const FancyBG FB_Moon = { Moon_Create, Moon_Update, NULL, NULL };
static void FishEye_Begin(void) {  // fisheye.js (rex): fuori dal raggio la distanza si piega con sin (modo 1) o asin, mescolata per intensita'
    if (!FishEye.sh.id) {
        static const char *BODY =
            "uniform float mode; uniform vec2 texSize; uniform vec2 center; uniform float radius; uniform float intensity;\n"
            "vec2 fish(vec2 uv) {\n"
            "  vec2 tc = uv * texSize - center; float dist = length(tc) / radius;\n"
            "  if (dist > 1.0) { float f = mode > 0.0 ? sin(dist * 1.570795) : asin(dist) / 1.570795; tc *= mix(1.0, f, intensity); }\n"
            "  return (tc + center) / texSize;\n"
            "}\n";
        char fs[1024];
#ifdef __vita__
        snprintf(fs, sizeof(fs), "#version 100\nprecision mediump float;\nvarying vec2 fragTexCoord;\nvarying vec4 fragColor;\nuniform sampler2D texture0;\n%s"
                 "void main() { gl_FragColor = texture2D(texture0, fish(fragTexCoord)) * fragColor; }\n", BODY);
#else
        snprintf(fs, sizeof(fs), "#version 330\nin vec2 fragTexCoord;\nin vec4 fragColor;\nuniform sampler2D texture0;\nout vec4 finalColor;\n%s"
                 "void main() { finalColor = texture(texture0, fish(fragTexCoord)) * fragColor; }\n", BODY);
#endif
        FishEye.sh = LoadShaderFromMemory(NULL, fs);
        FishEye.locMode = GetShaderLocation(FishEye.sh, "mode"), FishEye.locTex = GetShaderLocation(FishEye.sh, "texSize");
        FishEye.locCenter = GetShaderLocation(FishEye.sh, "center"), FishEye.locRadius = GetShaderLocation(FishEye.sh, "radius"), FishEye.locInt = GetShaderLocation(FishEye.sh, "intensity");
    }
    float mode = FishEye.mode, tex[2] = { game_width, game_height }, c[2] = { 0.5f * game_width, game_height - 0.5f * game_height };
    SetShaderValue(FishEye.sh, FishEye.locMode, &mode, SHADER_UNIFORM_FLOAT);
    SetShaderValue(FishEye.sh, FishEye.locTex, tex, SHADER_UNIFORM_VEC2);
    SetShaderValue(FishEye.sh, FishEye.locCenter, c, SHADER_UNIFORM_VEC2);
    SetShaderValue(FishEye.sh, FishEye.locRadius, &FishEye.radius, SHADER_UNIFORM_FLOAT);
    SetShaderValue(FishEye.sh, FishEye.locInt, &FishEye.intensity, SHADER_UNIFORM_FLOAT);
    BeginShaderMode(FishEye.sh);
}

// ============================================================================
// Boss Rash (RASH 0x321d) e i boss "normali" del finale: Maddener (0xa58f), Stalker (0x1afe), Trickster (0xa25a),
// Drowner (0x14807, Rash 0xdb12), Ender Rash (0x9201 su 0x4d66) con le zone (0xde50, pool 0x9612) e le falci (0x529e), granchio Rash (0x4e24)
// ============================================================================
static void Boss_ringHide(void *ctx) { ((Sprite *)ctx)->visible = 0; }
static void Boss_ring(Enemy *e) {  // ringSprite: scene.add.image('vfx', 'sPFX_ring_64.png').setScale(0), ADD
    if (e->ringSprite) return;
    Sprite *r = e->ringSprite = calloc(1, sizeof(Sprite));
    sprite_init(r, frame_get("vfx", "sPFX_ring_64.png"), e->s.x, e->s.y);
    sprite_setScale(r, 0), r->blendAdd = 1;
    children_add(r);
}
static void Boss_enterStart(void *ctx) { sprite_setScale(&((Enemy *)ctx)->s, 0); }
static void Boss_enter(Enemy *e) {  // OnEnterTween nuovo a ogni riciclo: da 0 alla scala dei dati in 300 ms
    sprite_setScale(&e->s, 0);
    e->OnEnterTween = tweens_add((TweenConfig){ .props = { { &e->s.scaleX, &e->s.scaleY, e->scaleMul } }, .nprops = 1, .duration = 0x12c, .onStart = Boss_enterStart, .ctx = e });
}
static void Boss_ringStart(void *ctx) { Enemy *e = ctx; e->ringSprite->x = e->s.x, e->ringSprite->y = e->s.y, sprite_setScale(e->ringSprite, 0), e->ringSprite->visible = 1; }
static void Boss_DeathScream(Enemy *e) {
    Sound_PlaySound("Deathscream", 4, 1, 0, 0x96, 2);
    tweens_add((TweenConfig){ .props = { { &e->ringSprite->scaleX, &e->ringSprite->scaleY, 0x10 } }, .nprops = 1, .duration = 0x12c, .repeat = 1,
                              .onStart = Boss_ringStart, .onComplete = Boss_ringHide, .ctx = e });
}
static int Boss_isCaster(const char *t) {  // armi che li battono subito (e niente minigioco: hasLostTreasure)
    return t && (!strcmp(t, "PENTAGRAM") || !strcmp(t, "ROSARY") || !strcmp(t, "SIRE") || !strcmp(t, "CORRIDOR") || !strcmp(t, "SHROUD"));
}
static void Boss_defeat(Enemy *e) { if (e->onDefeat) { void (*f)(Enemy *) = e->onDefeat; e->onDefeat = NULL; f(e); } }
// il minigioco di Panini (Exdash sbloccato: Invio + Giu') di Stalker, Trickster e Drowner: F3

// --- BOSS_MADDENER_NORMAL: un angelo (alias della Cappella) che entra con un "!" a sinistra del giocatore ---------------------------------
static void Maddener_warnBack(void *ctx) { Sprite *s = ctx; tweens_add((TweenConfig){ .props = { { &s->scaleX, &s->scaleY, 0 } }, .nprops = 1, .duration = 0xc8, .delay = 0xc8 }); }
static void Maddener_warnSound(void *ctx) { (void)ctx; Sound_PlaySound("Pizza", 0.9f, 1, 0x4b0, 0x96, 2); }
static void E_Maddener_OnRecycle(Enemy *e) {
    E_FAngel_OnRecycle(e);
    Boss_ring(e), Boss_enter(e);
    e->isCullable = 0, e->s.depth = 0x2710, e->isTeleportOnCull = 1;  // isSpinning, spinRadius, runningTweenValue, rosaried: mai letti
    sprite_setOrigin(&e->s, 0.5f, 0.5f);
    e->s.x = Core.Player->s.x - (0.5f * game_height - 0x18), e->s.y = Core.Player->s.y;
    if (e->idle.n) anims_play(&e->s, &e->idle, 0);
    Sprite *w = calloc(1, sizeof(Sprite));  // SingleWarning(x + 32, y - 16)
    sprite_init(w, frame_get("UI", "ExclamationMark.png"), e->s.x + 0x20, e->s.y - 0x10);
    sprite_setScale(w, 0), sprite_setOrigin(w, 0.5f, 1), w->depth = 0x2328;
    children_add(w);
    tweens_add((TweenConfig){ .props = { { &w->scaleX, &w->scaleY, 1 } }, .nprops = 1, .duration = 0xc8, .delay = 0x3e8, .onStart = Maddener_warnSound, .onComplete = Maddener_warnBack, .ctx = w });
}
static void E_Maddener_Die(Enemy *e) { E_FAngel_Die(e); Boss_DeathScream(e); Boss_defeat(e); }
static void E_Maddener_DeSpawn(Enemy *e) { base_EnemyDeSpawn(e); Boss_defeat(e); }
static const EnemyVT E_Maddener = { .OnRecycle = E_Maddener_OnRecycle, .Die = E_Maddener_Die, .DeSpawn = E_Maddener_DeSpawn, .Disappear = E_FAngel_Disappear };

// --- BOSS_STALKER_NORMAL: lo Stalker che si puo' battere (le armi "da caccia" lo uccidono subito, Stained Glass fa 10 volte il danno) -------
static void E_StalkerN_OnRecycle(Enemy *e) {
    base_EnemyOnRecycle(e);
    sprite_setTint(&e->s, 0xccccff);
    Boss_ring(e), Boss_enter(e);
    e->defaultSpeed = num(enemy_data(e), "speed", 0), e->sineF = 1, e->isCullable = 0, e->isTeleportOnCull = 1, e->s.alpha = 0.8f, e->hasLostTreasure = 0;
    tween_restartOrAdd(&e->OnSineTween, (TweenConfig){ .props = { { &e->sineF, NULL, 0.1f }, { &e->s.alpha, NULL, 0.6f } }, .nprops = 2, .duration = 0x7d0, .repeat = -1, .yoyo = 1, .ease = Ease_SineInOut });
}
static void E_StalkerN_Update(Enemy *e) { e->speed = e->defaultSpeed * e->sineF; base_EnemyUpdate(e); Panini_uppercut(e); }
static void E_StalkerN_Die(Enemy *e) { base_EnemyDie(e); Boss_DeathScream(e); Boss_defeat(e); }
static void E_StalkerN_GetDamaged(Enemy *e, float amount, int hitVFX, float kb, const char *t) {
    if (e->hasLostTreasure) return;
    if (Boss_isCaster(t)) { Enemy_Die(e); e->hasLostTreasure = 1; return; }
    if (t && !strcmp(t, "WINDOW")) amount *= 0xa;
    base_EnemyGetDamaged(e, amount, hitVFX, kb, t);
}
static const EnemyVT E_StalkerN = { .OnRecycle = E_StalkerN_OnRecycle, .Die = E_StalkerN_Die, .GetDamaged = E_StalkerN_GetDamaged, .Update = E_StalkerN_Update, .Disappear = E_Noob_Disappear };

// --- BOSS_TRICKSTER_NORMAL: ogni 30 s un anello di 48 gemme-poltergeist che esplodono; battuto, le fa esplodere tutte -------------------
typedef struct { EnemyPool *gemPool, *gemPoolStatic; Timer gemSummonEvent; } TricksterX;
static void Gems_disappear(void *ctx) {  // 'gems disappear': non contano tra i nemici degli eventi
    EventGroup *g = ctx;
    for (int i = 0; i < g->n; i++) if (!g->list[i]->isDead) g->list[i]->isCullable = 1, Enemy_Disappear(g->list[i]);
}
static void Trickster_SummonGems(Enemy *e, float d, int count, float k, int isStatic) {
    TricksterX *t = e->x;
    float a = 2 * PI * frand();
    EventGroup *g = StageEvent_group(count);
    for (int i = 0; i < count; i++) {
        float x = Core.Player->s.x + 0.8f * cosf(a) * (game_width * k), y = Core.Player->s.y + 0.8f * sinf(a) * (game_height * k);
        a += PI / (0.5f * count);
        Enemy *gem = EnemyPool_SpawnAt(isStatic ? t->gemPoolStatic : t->gemPool, x, y);
        if (gem) gem->isCullable = 0, g->list[g->n++] = gem;
    }
    time_addEvent(d ? d : 0xea60, 0, 0, Gems_disappear, g);  // 'gems disappear'
}
static void Trickster_summon(void *ctx) { Enemy *e = ctx; if (!e->isDead) Trickster_SummonGems(e, 0x7530, 0x30, 0.8f, frand() >= 0.5f); }
static void E_Trickster_OnRecycle(Enemy *e) {
    if (!e->x) { TricksterX *t = e->x = calloc(1, sizeof(TricksterX)); t->gemSummonEvent = (Timer){ -1, 0 }; }
    TricksterX *t = e->x;
    base_EnemyOnRecycle(e);
    Boss_ring(e);
    if (!t->gemPool) t->gemPoolStatic = EnemyPool_new("POLTER_GEM_STATIC"), t->gemPool = EnemyPool_new("POLTER_GEM");
    Boss_enter(e);
    Trickster_SummonGems(e, 0x7530, 0x30, 0.8f, frand() >= 0.5f);
    time_removeEvent(t->gemSummonEvent);
    t->gemSummonEvent = time_addEvent(0x7530, 0, -1, Trickster_summon, e);
    e->defaultSpeed = num(enemy_data(e), "speed", 0), e->sineF = 1, e->isCullable = 0, e->isTeleportOnCull = 1, e->hasLostTreasure = 0;
    tween_restartOrAdd(&e->OnSineTween, (TweenConfig){ .props = { { &e->sineF, NULL, 0.1f } }, .nprops = 1, .duration = 0x7d0, .repeat = -1, .yoyo = 1, .ease = Ease_SineInOut });
}
static void E_Trickster_Die(Enemy *e) {
    TricksterX *t = e->x;
    base_EnemyDie(e);
    Boss_DeathScream(e), Boss_defeat(e);
    for (int i = 0; i < t->gemPool->n_spawned; i++) Enemy_OnSelfDestruct(t->gemPool->spawned[i]);
    for (int i = 0; i < t->gemPoolStatic->n_spawned; i++) Enemy_OnSelfDestruct(t->gemPoolStatic->spawned[i]);
}
static void E_Trickster_DeSpawn(Enemy *e) { base_EnemyDeSpawn(e); time_removeEvent(((TricksterX *)e->x)->gemSummonEvent); }
static const EnemyVT E_Trickster = { .OnRecycle = E_Trickster_OnRecycle, .Die = E_Trickster_Die, .GetDamaged = E_StalkerN_GetDamaged, .Update = E_StalkerN_Update,
                                     .DeSpawn = E_Trickster_DeSpawn, .Disappear = E_Noob_Disappear };

// --- BOSS_XLTRICKSTER (0x10ee5): il guardiano del pianoforte; fermo (speed 0), anelli di 48 gemme, poltergeist e ombre ogni 10 s --------
typedef struct { EnemyPool *gemPool, *gemPoolStatic, *polterPool, *shadePool; Timer gemSummonEvent; } XLTricksterX;
static void XLGems_cullable(void *ctx) {  // 'gems disappear': tornano solo eliminabili fuori schermo
    EventGroup *g = ctx;
    for (int i = 0; i < g->n; i++) if (!g->list[i]->isDead) g->list[i]->isCullable = 1;
    free(g);
}
static void XLTrickster_SummonAll(Enemy *e, float d, int count, float k) {
    XLTricksterX *t = e->x;
    d = d ? d : 0xea60;
    float a = 2 * PI * frand();
    EventGroup *g = StageEvent_group(count);
    for (int i = 0; i < count; i++) {
        EnemyPool *pools[3] = { t->gemPool, t->polterPool, t->shadePool }, *pool = pools[(int)floorf(frand() * 3)];  // RND.pick
        float x = Core.Player->s.x + 0.8f * cosf(a) * (game_width * k), y = Core.Player->s.y + 0.8f * sinf(a) * (game_height * k);
        a += PI / (0.5f * count);
        Enemy *s = EnemyPool_SpawnAt(pool, x, y);
        if (s) s->isCullable = 0, s->speed = 0xfa, g->list[g->n++] = s;
    }
    time_addEvent(d, 0, 0, XLGems_cullable, g);
}
static void XLTrickster_summon(void *ctx) { Enemy *e = ctx; if (!e->isDead) XLTrickster_SummonAll(e, 0x7530, 0x30, 0.8f); }
static void E_XLTrickster_OnRecycle(Enemy *e) {
    if (!e->x) { XLTricksterX *t = e->x = calloc(1, sizeof(XLTricksterX)); t->gemSummonEvent = (Timer){ -1, 0 }; }
    XLTricksterX *t = e->x;
    base_EnemyOnRecycle(e);
    if (!t->gemPool)
        t->gemPoolStatic = EnemyPool_new("POLTER_GEM_STATIC"), t->gemPool = EnemyPool_new("POLTER_GEM"), t->polterPool = EnemyPool_new("POLTER"), t->shadePool = EnemyPool_new("SHADERED");
    Boss_enter(e);
    if (e->maxHp < 0x1a04) e->maxHp = 0x1a04, e->hp = e->maxHp;
    e->hp = e->maxHp;
    if (getenv("VS_BOSSHP")) e->hp = e->maxHp = atof(getenv("VS_BOSSHP"));  // sviluppo: HP del boss del pianoforte
    XLTrickster_SummonAll(e, 0x2710, 0x30, 0.8f);
    time_removeEvent(t->gemSummonEvent);
    t->gemSummonEvent = time_addEvent(0x2710, 0, -1, XLTrickster_summon, e);
    e->defaultSpeed = num(enemy_data(e), "speed", 0), e->sineF = 1, e->isCullable = 0, e->hasLostTreasure = 0;
    tween_restartOrAdd(&e->OnSineTween, (TweenConfig){ .props = { { &e->sineF, NULL, 0.1f } }, .nprops = 1, .duration = 0x7d0, .repeat = -1, .yoyo = 1, .ease = Ease_SineInOut });
}
static void E_XLTrickster_GetDamaged(Enemy *e, float amount, int hitVFX, float kb, const char *t) {
    if (!e->hasLostTreasure && t && (!strcmp(t, "ROSARY") || !strcmp(t, "SIRE") || !strcmp(t, "CORRIDOR") || !strcmp(t, "SHROUD") || !strcmp(t, "VICTORY") || !strcmp(t, "CART")))
        e->hasLostTreasure = 1;
    if (!t || (strcmp(t, "ROSARY") && strcmp(t, "SIRE"))) base_EnemyGetDamaged(e, amount, hitVFX, kb, t);
}
static void XLTrickster_onDefeat(Enemy *e) { if (e->onDefeat) ((void (*)(Enemy *))e->onDefeat)(e); }  // senza azzerarlo: Disappear e Die lo chiamano entrambi
static void E_XLTrickster_Die(Enemy *e) { base_EnemyDie(e); XLTrickster_onDefeat(e); }
static void E_XLTrickster_Disappear(Enemy *e) {
    tween_stop(e->OnSineTween);
    e->sineF = -2, e->isCullable = 1, e->isTeleportOnCull = 0;
    tweens_add((TweenConfig){ .props = { { &e->sineF, NULL, -0xa } }, .nprops = 1, .duration = 0x7d0 });
    XLTrickster_onDefeat(e);
}
static void E_XLTrickster_DeSpawn(Enemy *e) { base_EnemyDeSpawn(e); time_removeEvent(((XLTricksterX *)e->x)->gemSummonEvent); }  // spritte: Panini_update
static const EnemyVT E_XLTrickster = { .OnRecycle = E_XLTrickster_OnRecycle, .Die = E_XLTrickster_Die, .GetDamaged = E_XLTrickster_GetDamaged, .Update = E_StalkerN_Update,
                                       .DeSpawn = E_XLTrickster_DeSpawn, .Disappear = E_XLTrickster_Disappear };

// --- BOSS_SHARD_INFERNAS (0xc4f7): esce dalla bara giusta; battuto sblocca MaFaiPianooo e Avatar, toglie le armi e chiama la mano bianca ---
static int Infernas_found;
static void E_Infernas_OnRecycle(Enemy *e) {
    base_EnemyOnRecycle(e);
    e->isCullable = 0;
    sprite_setScale(&e->s, 0);
    e->OnEnterTween = tweens_add((TweenConfig){ .props = { { &e->s.scaleX, &e->s.scaleY, 2 } }, .nprops = 1, .duration = 0x1f4 });
    if (getenv("VS_BOSSHP")) e->hp = e->maxHp = atof(getenv("VS_BOSSHP"));  // sviluppo: HP del boss del pianoforte
}
static void E_Infernas_GetDamaged(Enemy *e, float amount, int hitVFX, float kb, const char *t) { (void)hitVFX; base_EnemyGetDamaged(e, amount, HIT_NONE, kb, t); }
static void Infernas_shakeDone(void *ctx) {
    (void)ctx;
    camera_followOffsetX = 0;
    if (Infernas_found && Core.n_CharQueue < 8) Core.CharQueue[Core.n_CharQueue++] = "AVATAR";
}
static void Infernas_hand(void *ctx) { (void)ctx; WhiteHand_Summon(); }
static void Infernas_BlockInput(void) {
    Core.canPause = 0;
    Player_SetInvulForMilliSeconds(Core.Player, 0x7530);
    Player_restoreTint(Core.Player);
    time_addEvent(0x64, 0, 0, Player_restoreTint, Core.Player);
    while (Core.n_weapons > 0) Weapon_CleanUp(Core.Weapons[--Core.n_weapons]);  // Weapons.pop().CleanUp()
    while (Core.n_HiddenWeapons > 0) Weapon_CleanUp(Core.HiddenWeapons[--Core.n_HiddenWeapons]);
}
static void E_Infernas_Die(Enemy *e) {
    if (e->isDead) return;
    Infernas_found = 0;
    if (!po_has("UnlockedCharacters", "AVATAR")) Sound_PlaySound("ThingFound", 1, 0.5f, -0x3e8, 0, 0), AchievementManager_UnlockSecret("MaFaiPianooo"), Infernas_found = 1;
    Sound_PlaySound("Crystal12", 1.5f, 1, -0x258 * frand(), 0, 0);
    FrameFreeze_ms = 0x78;  // SceneManager.FrameFreeze
    tweens_add((TweenConfig){ .props = { { &camera_followOffsetX, NULL, 2 } }, .nprops = 1, .duration = 0x10, .yoyo = 1, .repeat = 6,
                              .onStart = BridgeBoss_shakeStart, .onComplete = Infernas_shakeDone });
    time_addEvent(0x1f4, 0, 0, Infernas_hand, NULL);
    Infernas_BlockInput();
    base_EnemyDie(e);
}
static void E_Infernas_Disappear(Enemy *e) { (void)e; }
static const EnemyVT E_Infernas = { .OnRecycle = E_Infernas_OnRecycle, .Die = E_Infernas_Die, .GetDamaged = E_Infernas_GetDamaged, .Disappear = E_Infernas_Disappear };

// --- BOSS_DROWNER_NORMAL (0x14807) e _RASH (0xdb12): il Drowner battibile, con l'acqua; impazzisce dal minuto 10 (Rash: 15) -------------
typedef struct { DrownerX d; int GoNutsMinute, rash; float distanceMultiplier; } DrownerNX;
static void E_DrownerN_OnRecycle(Enemy *e) {
    if (!e->x) {
        DrownerNX *n = e->x = calloc(1, sizeof(DrownerNX));
        n->rash = !strcmp(e->enemyType, "BOSS_DROWNER_RASH");
        n->GoNutsMinute = n->rash ? 0xf : 0xa, n->distanceMultiplier = n->rash ? 0.3f : 0.45f;
    }
    E_Drowner_OnRecycle(e);  // DrownerX in testa: acqua, goccioline, isFresh
    Boss_ring(e), Boss_enter(e);
}
static void E_DrownerN_Update(Enemy *e) {
    DrownerNX *n = e->x;
    DrownerX *d = &n->d;
    float delta = Enemies_delta;
    if (d->isFresh) e->s.x = Core.Player->s.x, e->s.y = n->rash ? fmaxf(0x580, Core.Player->s.y + 0.5f * game_height) : Core.Player->s.y + 0.5f * game_height, d->isFresh = 0;  // GetSpawnY
    e->isTeleportOnCull = 0, e->speed = 0;
    base_EnemyUpdate(e);
    Panini_uppercut(e);
    if (!d->dismissed) e->s.x = approach(e->s.x, Core.Player->s.x - game_width * n->distanceMultiplier + 0x60, 0x64 * delta);
    float k = Core.SurvivedSeconds > 0x3c * n->GoNutsMinute ? 1.3f : 0.1f;
    if (!po_is("SelectedHyper")) k *= 0.5f;
    if (Core.Player->s.y - 0xc < e->s.y) e->s.y = approach(e->s.y, Core.Player->s.y - 0xc, k);
    if (d->bullet) {
        d->bullet->s.x = Core.Player->s.x, d->bullet->s.y = e->s.y;
        if (Core.Player->s.y - e->s.y > 0.5f * game_height) d->bullet->s.y = 0xc + Core.Player->s.y - 0.5f * game_height;
    }
    d->PfxEmitter->boundsY = e->s.y - 2;
    d->PfxEmitter->x = 0x18 + e->s.x, d->PfxEmitter->y = -0x42 + e->s.y;
    d->particlesManager->s.depth = e->s.depth - 1;
}
static void E_DrownerN_Die(Enemy *e) { base_EnemyDie(e); Boss_DeathScream(e); Boss_defeat(e); Drowner_Dismiss(e); }
static const EnemyVT E_DrownerN = { .OnRecycle = E_DrownerN_OnRecycle, .Die = E_DrownerN_Die, .GetDamaged = E_StalkerN_GetDamaged, .Update = E_DrownerN_Update,
                                    .DeSpawn = E_Drowner_DeSpawn, .Disappear = E_Drowner_Disappear };

// --- BULLET_SCYTHE (0x529e): la falce dell'Ender, va dritta, gira e sparisce dopo 5,5 s o toccando il giocatore ------------------------------
static void E_Scythe_DeSpawn(Enemy *e) { if (e->isDespawning) return; e->isDespawning = 1; base_EnemyDeSpawn(e); }  // .stop senza parentesi (sic)
static void E_Scythe_deathDone(void *ctx) { E_Scythe_DeSpawn(ctx); }
static void E_Scythe_DeathTween(Enemy *e) {
    tween_stop(e->OnLifetimeTween);
    if (tween_get(e->ScaleTween)) tween_stop(e->ScaleTween), tween_restart(e->ScaleTween);
    else e->ScaleTween = tweens_add((TweenConfig){ .props = { { &e->s.scaleX, &e->s.scaleY, 0 } }, .nprops = 1, .duration = 0x64, .onComplete = E_Scythe_deathDone, .ctx = e, .persist = 1 });
}
static void E_Scythe_Disappear(Enemy *e) { if (!e->isDead) e->isDead = 1, E_Scythe_DeathTween(e); }
static void E_Scythe_lifeDone(void *ctx) { E_Scythe_Disappear(ctx); }
static void E_Scythe_OnRecycle(Enemy *e) {
    base_EnemyOnRecycle(e);
    sprite_setScale(&e->s, 0), e->isDespawning = 0, e->lifetime = 1, e->sineF = 0;  // sineF: myAngle
    cJSON *d = enemy_data(e);
    e->power = num(d, "power", 0);
    sprite_setTint(&e->s, has(d, "tint") ? (unsigned)num(d, "tint", 0) : 0xffffff);
    tween_restartOrAdd(&e->OnEnterTween, (TweenConfig){ .props = { { &e->s.scaleX, &e->s.scaleY, 1 } }, .nprops = 1, .duration = 0x64 });
    tween_restartOrAdd(&e->OnLifetimeTween, (TweenConfig){ .props = { { &e->lifetime, NULL, 0 } }, .nprops = 1, .duration = 0x64, .delay = 0x157c, .onComplete = E_Scythe_lifeDone, .ctx = e });
    sprite_setOrigin(&e->s, 0.5f, 0.5f);
}
static void E_Scythe_GetDamaged(Enemy *e, float amount, int hitVFX, float kb, const char *t) { (void)e, (void)amount, (void)hitVFX, (void)kb, (void)t; }
static void E_Scythe_OnPlayerOverlap(Enemy *e) { base_EnemyOnPlayerOverlap(e); E_Scythe_Disappear(e); }
static void E_Scythe_Update(Enemy *e) { base_EnemyUpdate(e); e->s.flipX = 0, e->sineF += Enemies_delta, e->s.angle = e->sineF; }
static const EnemyVT E_Scythe = { .OnRecycle = E_Scythe_OnRecycle, .Die = E_Scythe_Disappear, .GetDamaged = E_Scythe_GetDamaged, .Update = E_Scythe_Update,
                                  .DeSpawn = E_Scythe_DeSpawn, .Disappear = E_Scythe_Disappear, .OnPlayerOverlap = E_Scythe_OnPlayerOverlap };

// --- Le zone dell'Ender (0xde50): un rettangolo rosso lampeggia tre volte, poi si annerisce e per un po' fa male; quattro "pelli" di particelle ---
enum { SKIN_WEAPONS, SKIN_COFFINS, SKIN_TRAINEES, SKIN_EXPLOSIONS };
typedef struct EnderZone {
    Sprite s, GroundFx;  // s: WhiteDot nero scalato al rettangolo; GroundFx: scene.add.rectangle rosso, ADD (dimensioni in w, h)
    float w, h, damage, duration, hitDelay;
    int skin, follow, lockX, lockY, activateDamage, hasHit;
    Timer HitboxTimer;
    TweenRef despawnTimer;
    ParticleManager *pm[4];
    ParticleEmitter *em[4][2], *cur1, *cur2;
    struct EnderZonePool *pool;
} EnderZone;
typedef struct EnderZonePool { EnderZone **stored, **spawned; int nstored, nspawned, capstored, capspawned; } EnderZonePool;
static void EnderZone_rectDraw(Sprite *s) {
    EnderZone *z = s->owner;
    if (!s->visible || s->alpha <= 0) return;
    float w = z->w * s->scaleX, h = z->h * s->scaleY;
    BeginBlendMode(BLEND_ADDITIVE);
    DrawRectangleRec((Rectangle){ s->x - 0.5f * w - camera_scrollX, s->y - 0.5f * h - camera_scrollY, w, h }, hexc(0xff0000, s->alpha));
    EndBlendMode();
}
static void EnderZone_stopAll(EnderZone *z) { for (int i = 0; i < 4; i++) emitter_stop(z->em[i][0]), emitter_stop(z->em[i][1]); }
static void EnderZone_DeSpawn(EnderZone *z) {
    EnderZonePool *p = z->pool;
    z->s.active = 0;
    for (int i = 0; i < p->nspawned; i++)  // Return
        if (p->spawned[i] == z) { memmove(&p->spawned[i], &p->spawned[i + 1], (p->nspawned - i - 1) * sizeof(*p->spawned)); p->nspawned--; break; }
    if (p->nstored == p->capstored) p->stored = realloc(p->stored, (p->capstored = p->capstored ? p->capstored * 2 : 8) * sizeof(*p->stored));
    p->stored[p->nstored++] = z;
    children_remove(&z->s);
    z->activateDamage = 0;
    tween_stop(z->despawnTimer), z->despawnTimer = TWEEN_NONE;
    time_removeEvent(z->HitboxTimer);
    z->GroundFx.visible = 0, z->s.visible = 0;
    EnderZone_stopAll(z);
}
static void EnderZone_done(void *ctx) { EnderZone *z = ctx; z->activateDamage = 0; EnderZone_stopAll(z); EnderZone_DeSpawn(z); }
static void EnderZone_armed(void *ctx) { ((EnderZone *)ctx)->activateDamage = 1; }
static void EnderZone_shootStart(void *ctx) { EnderZone *z = ctx; z->s.visible = 1, z->s.alpha = 0; }
static void EnderZone_Shoot(void *ctx) {
    EnderZone *z = ctx;
    Sound_PlaySound("Explosion", 0.5f, 1, 0x1f4 * (frand() - 0.5f), 0x96, 3);
    tweens_add((TweenConfig){ .props = { { &z->s.scaleX, NULL, z->w }, { &z->s.scaleY, NULL, z->h }, { &z->s.alpha, NULL, 0.1f } }, .nprops = 3, .duration = 0x1f4,
                              .onStart = EnderZone_shootStart, .onComplete = EnderZone_armed, .ctx = z });
    emitter_start(z->em[z->skin][0]), emitter_start(z->em[z->skin][1]);
    z->cur1 = z->em[z->skin][0], z->cur2 = z->em[z->skin][1];
    ParticleManager *m = z->pm[z->skin];
    float wx[4] = { z->s.x, z->s.x, z->s.x - 0.4f * z->w, z->s.x + 0.4f * z->w }, wy[4] = { z->s.y - 0x20, z->s.y - 0x20, z->s.y, z->s.y };
    m->wellX = wx[z->skin], m->wellY = wy[z->skin];
    z->despawnTimer = tweens_add((TweenConfig){ .props = { { &z->GroundFx.scaleY, NULL, z->GroundFx.scaleY } }, .nprops = 1, .duration = z->duration, .onComplete = EnderZone_done, .ctx = z });  // 'nothing'
}
static void EnderZone_rearm(void *ctx) { ((EnderZone *)ctx)->hasHit = 0; }
static void EnderZone_fxStart(void *ctx) { ((EnderZone *)ctx)->GroundFx.visible = 1; }
static EnderZone *EnderZone_new(EnderZonePool *pool) {
    EnderZone *z = calloc(1, sizeof(EnderZone));
    z->pool = pool, z->HitboxTimer = (Timer){ -1, 0 }, z->despawnTimer = TWEEN_NONE;
    sprite_init(&z->s, frame_get("vfx", "WhiteDot.png"), 0, 0);
    z->s.visible = 0, z->s.alpha = 0.2f, sprite_setOrigin(&z->s, 0.5f, 0.5f), sprite_setTintFill(&z->s, 0);
    sprite_init(&z->GroundFx, NULL, 0, 0);
    z->GroundFx.owner = z, z->GroundFx.draw = EnderZone_rectDraw, z->GroundFx.alpha = 0, z->GroundFx.visible = 0, z->GroundFx.scaleX = z->GroundFx.scaleY = 1;
    children_add(&z->GroundFx);
    static const char *const W[17] = { "Axe.png", "Cat.png", "Cross.png", "Diamond2.png", "Garlic.png", "Guns.png", "Guns2.png", "HolyBook.png", "HolyWater.png", "Knife.png",
                                       "LighningRing.png", "Pentagram.png", "Song.png", "trapano.png", "WandHoly.png", "WandFire.png", "Whip.png" };
    static const char *const H[5] = { "HoodieR_i01.png", "HoodieP_i01.png", "HoodieG_i01.png", "HoodieB_i01.png", "HoodieY_i01.png" };
    EmitterConfig c;
    for (int i = 0; i < 4; i++) {
        z->pm[i] = particles_add();
        z->pm[i]->hasWell = 1, z->pm[i]->wellPower = 1 * 0x14, z->pm[i]->wellEpsilon = 0x32 * 0x32;
    }
    c = (EmitterConfig){ .nframes = 17, .lifespan = EOP(0x3e8), .angle = { 0x46, 0x6e, 1 }, .angleSteps = 0x15, .speed = ERND(0x258, 0x320), .quantity = 1, .scale = ERANGE(2, 0),
                         .frequency = 1, .bounce = 0.9f, .collideTop = 1, .collideBottom = 1, .collideLeftRight = 1, .boundsW = 0x64, .boundsH = 0x64, .on = 0 };
    for (int i = 0; i < 17; i++) c.frames[i] = frame_get("items", W[i]);
    z->em[SKIN_WEAPONS][1] = particles_createEmitter(z->pm[SKIN_WEAPONS], c);
    c.angleSteps = 0x10, c.speed = ERND(0x190, 0x258), c.quantity = 2;
    z->em[SKIN_WEAPONS][0] = particles_createEmitter(z->pm[SKIN_WEAPONS], c);
    c = (EmitterConfig){ .frames = { frame_get("items", "CoffinLid.png"), frame_get("items", "Coffin.png") }, .nframes = 2, .lifespan = EOP(0x3e8), .rotate = ERND(0, 0x168),
                         .angle = { 0, 0x168, 1 }, .angleSteps = 0x15, .speed = ERND(0x190, 0x258), .quantity = 1, .scale = ERANGE(1, 0), .frequency = 1, .bounce = 0.9f,
                         .collideTop = 1, .collideBottom = 1, .collideLeftRight = 1, .boundsW = 0x64, .boundsH = 0x64, .on = 0 };
    z->em[SKIN_COFFINS][1] = particles_createEmitter(z->pm[SKIN_COFFINS], c);
    c.angleSteps = 0x10, c.speed = ERND(0x12c, 0x190), c.bounce = 0.5f;
    z->em[SKIN_COFFINS][0] = particles_createEmitter(z->pm[SKIN_COFFINS], c);
    c = (EmitterConfig){ .nframes = 5, .lifespan = EOP(0x3e8), .angle = { 0xa0, 0xc8, 1 }, .angleSteps = 0x10, .speed = ERND(0x1f4, 0x258), .quantity = 1, .scale = ERANGE(1, 1),
                         .frequency = 1, .alpha = ERANGE(0.5f, 0), .bounce = 0.9f, .collideTop = 1, .collideBottom = 1, .collideLeftRight = 1, .boundsW = 0x64, .boundsH = 0x64, .on = 0 };
    for (int i = 0; i < 5; i++) c.frames[i] = frame_get("enemies3", H[i]);
    z->em[SKIN_TRAINEES][1] = particles_createEmitter(z->pm[SKIN_TRAINEES], c);
    c.lifespan = EOP(0x7d0), c.speed = ERND(0x1c2, 0x226), c.alpha = (EmitterOp){ 0 }, c.collideLeftRight = 0, c.hasZoneRect = 1, c.zoneRect = (Rectangle){ 0, -0x20, 0, 0x40 };  // Line(0,-32,0,32)
    z->em[SKIN_TRAINEES][0] = particles_createEmitter(z->pm[SKIN_TRAINEES], c);
    c = (EmitterConfig){ .frames = { frame_get("vfx", "Smoke1.png"), frame_get("vfx", "Smoke2.png") }, .nframes = 2, .lifespan = EOP(0x3e8), .rotate = ERND(0, 0x168),
                         .angle = { -0x14, 0x14, 1 }, .angleSteps = 0x10, .speed = ERND(0x320, 0x4b0), .quantity = 2, .scale = ERANGE(2, 1), .frequency = 1, .alpha = ERANGE(0.5f, 0),
                         .bounce = 0.9f, .collideTop = 1, .collideBottom = 1, .collideLeftRight = 1, .boundsW = 0x64, .boundsH = 0x64, .on = 0 };
    z->em[SKIN_EXPLOSIONS][1] = particles_createEmitter(z->pm[SKIN_EXPLOSIONS], c);
    c.frames[0] = frame_get("vfx", "HitSmoke1.png"), c.frames[1] = frame_get("vfx", "HitSmoke2.png"), c.scale = ERANGE(1, 0), c.alpha = (EmitterOp){ 0 }, c.blendAdd = 1;
    c.collideLeftRight = 0, c.hasZoneRect = 1, c.zoneRect = (Rectangle){ 0, -0x20, 0, 0x40 };
    z->em[SKIN_EXPLOSIONS][0] = particles_createEmitter(z->pm[SKIN_EXPLOSIONS], c);
    return z;
}
static void EnderZone_OnRecycle(EnderZone *z) {
    z->s.active = 1, z->GroundFx.scaleX = z->GroundFx.scaleY = 1, sprite_setScale(&z->s, 0), z->GroundFx.depth = 1;
    z->lockX = z->lockY = 0, z->activateDamage = 0, z->hasHit = 0;
    time_removeEvent(z->HitboxTimer);
    z->HitboxTimer = time_addEvent(z->hitDelay, 1, 0, EnderZone_rearm, z);
    tweens_add((TweenConfig){ .props = { { &z->GroundFx.alpha, NULL, 0.5f } }, .nprops = 1, .yoyo = 1, .repeat = 2, .duration = 0x12c, .onStart = EnderZone_fxStart, .onComplete = EnderZone_Shoot, .ctx = z });
    tween_stop(z->despawnTimer), z->despawnTimer = TWEEN_NONE;
    Sound_PlaySound("Pizza", 0.9f, 1, 0x1f4 * frand(), 0x96, 2);
}
static EnderZone *EnderZone_SpawnAt(EnderZonePool *p, float x, float y, float w, float h, float damage, float duration, float hitDelay, int skin, int follow) {
    EnderZone *z = p->nstored ? p->stored[--p->nstored] : NULL;
    if (!z) z = EnderZone_new(p), z->s.x = z->s.y = -0x3e8, z->hitDelay = 0x1f4, EnderZone_OnRecycle(z);  // Init
    if (p->nspawned == p->capspawned) p->spawned = realloc(p->spawned, (p->capspawned = p->capspawned ? p->capspawned * 2 : 8) * sizeof(*p->spawned));
    p->spawned[p->nspawned++] = z;
    z->s.x = x, z->s.y = y;
    z->GroundFx.x = x, z->GroundFx.y = y, z->w = w, z->h = h, z->s.scaleX = w, z->s.scaleY = h;  // SetExplosionSize
    z->damage = damage, z->duration = duration, z->hitDelay = hitDelay;  // SetExplosionDamage
    z->skin = skin, z->follow = follow;
    children_add(&z->s);
    EnderZone_OnRecycle(z);
    return z;
}
static void EnderZone_Update(EnderZone *z, float delta) {
    if (z->follow) z->s.x = approach(z->s.x, Core.Player->s.x, 0.01f * delta), z->s.y = approach(z->s.y, Core.Player->s.y, 0.01f * delta);
    if (z->lockX) z->s.x = Core.Player->s.x;
    if (z->lockY) z->s.y = Core.Player->s.y;
    z->GroundFx.x = z->s.x, z->GroundFx.y = z->s.y;
    if (!z->cur1) return;
    float ex[4] = { z->s.x, z->s.x, z->s.x + 0.5f * z->w, z->s.x - 0.5f * z->w }, ey[4] = { z->s.y - 0.5f * z->h, z->s.y, z->s.y, z->s.y };  // in alto, al centro, a destra, a sinistra
    ParticleEmitter *c[2] = { z->cur1, z->cur2 };
    for (int i = 0; i < 2; i++) {
        c[i]->x = ex[z->skin], c[i]->y = ey[z->skin];
        c[i]->c.boundsX = z->GroundFx.x - 0.5f * z->w, c[i]->boundsY = z->GroundFx.y - 0.5f * z->h, c[i]->c.boundsW = z->w, c[i]->c.boundsH = z->h;  // SetEmittersBounds
    }
    float px = Core.Player->s.x, py = Core.Player->s.y;
    if (!z->hasHit && z->activateDamage && px >= z->s.x - 0.5f * z->w && px <= z->s.x + 0.5f * z->w && py >= z->s.y - 0.5f * z->h && py <= z->s.y + 0.5f * z->h)
        z->hasHit = 1, Player_GetDamaged(Core.Player, z->damage);
}

// --- BOSS_ENDER (0x4d66) / BOSS_ENDER_RASH (0x9201): scudo per 90 s (Rash 45), ogni 5 s una zona scelta dalla vita rimasta, falci sempre piu' fitte ---
typedef struct { EnderZonePool zones; EnemyPool *scythePool; Timer shieldTimer, AItimer; float totalTime, scitheTime, shieldDamage, ShieldTime, attacksDurationMultiplier; int hasShield; } EnderX;
static void Ender_shieldOff(void *ctx) { Enemy *e = ctx; EnderX *x = e->x; x->hasShield = 0, e->hp -= x->shieldDamage; }
static void Ender_TriggerExplosion(void *ctx);
static void E_Ender_OnRecycle(Enemy *e) {
    if (!e->x) {
        EnderX *x = e->x = calloc(1, sizeof(EnderX));
        int rash = !strcmp(e->enemyType, "BOSS_ENDER_RASH");
        x->ShieldTime = rash ? 0xafc8 : 0x15f90, x->attacksDurationMultiplier = rash ? 0.6f : 1, x->shieldTimer = x->AItimer = (Timer){ -1, 0 };
    }
    EnderX *x = e->x;
    base_EnemyOnRecycle(e);
    e->isTeleportOnCull = 1, x->totalTime = 0, x->scitheTime = 0x1388, x->shieldDamage = 0;
    Boss_ring(e);
    if (!x->scythePool) x->scythePool = EnemyPool_new("BULLET_SCYTHE");
    time_removeEvent(x->AItimer);  // StartVerySmartAI
    x->AItimer = time_addEvent(0x1388, 0, -1, Ender_TriggerExplosion, e);
    x->hasShield = 1;
    time_removeEvent(x->shieldTimer);
    x->shieldTimer = time_addEvent(x->ShieldTime, 0, 0, Ender_shieldOff, e);
}
static void E_Ender_GetDamaged(Enemy *e, float amount, int hitVFX, float kb, const char *t) {
    (void)t;
    EnderX *x = e->x;
    if (amount > 0) Core_ShowDamageAt(e->s.x, e->s.y, amount);
    if (x->hasShield) x->shieldDamage += amount; else e->hp -= amount;
    if (e->hp <= 0) Enemy_Die(e); else e->damageKB = kb;
    Sound_PlaySound("Hit", 0.5f, 1, 0x1f4 * (frand() - 0.5f), 0x96, 3);
    if (hitVFX != HIT_NONE) Core_ShowHitVFXAt(e->s.x, e->s.y, hitVFX);
    Enemy_OnGetDamaged(e, hitVFX);
}
static void E_Ender_Update(Enemy *e) {
    EnderX *x = e->x;
    base_EnemyUpdate(e);
    if (e->isDead) return;
    float left = x->hasShield ? e->maxHp - x->shieldDamage : e->hp;
    x->scitheTime = 0x1f4 + fmaxf(0, left / e->maxHp * 0xfa0);
    for (int i = 0; i < x->zones.nspawned; i++) EnderZone_Update(x->zones.spawned[i], Enemies_delta);
    x->totalTime += Enemies_delta;
    if (x->totalTime > x->scitheTime) x->totalTime = 0, EnemyPool_SpawnAt(x->scythePool, e->s.x, e->s.y);  // ThrowScithe
}
static void Ender_zone(Enemy *e, int skin, float dx, float dy, int follow, float duration) {  // DamagingZone_*: colonne (Weapons, Coffins) o righe (Trainees, Explosions)
    EnderX *x = e->x;
    int col = skin == SKIN_WEAPONS || skin == SKIN_COFFINS;
    EnderZone *z = EnderZone_SpawnAt(&x->zones, Core.Player->s.x + dx, Core.Player->s.y + dy, col ? 0x64 : game_width, col ? game_height : 0x64, 0xc,
                                     duration * x->attacksDurationMultiplier, 0x1f4, skin, follow);
    if (col) z->lockY = 1; else z->lockX = 1;
}
static void Ender_TriggerExplosion(void *ctx) {
    Enemy *e = ctx;
    EnderX *x = e->x;
    if (e->isDead) { time_removeEvent(x->AItimer); return; }
    float step = e->maxHp / 9, left = x->hasShield ? e->maxHp - x->shieldDamage : e->hp;
    int k = 9 - (int)roundf(left / step);
    static const char *const BAG8[4] = { "Trainees", "Coffins", "Weapons", "Explosions" };
    const char *a = k == 0 ? "Trainees" : k == 1 ? "Coffins" : k == 2 ? (frand() < 0.5f ? "DoubleTrainees" : "DoubleCoffins") : k == 3 ? "Explosions"
                  : k == 4 ? "DoubleExplosions" : k == 5 ? "Weapons" : k == 6 ? "DoubleWeapons" : BAG8[(int)floorf(frand() * 4)];
    if (!strcmp(a, "Coffins")) Ender_zone(e, SKIN_COFFINS, 0, 0, 1, 0x2710);
    else if (!strcmp(a, "Trainees")) Ender_zone(e, SKIN_TRAINEES, 0, 0, 1, 0x1388);
    else if (!strcmp(a, "Explosions")) Ender_zone(e, SKIN_EXPLOSIONS, 0, 0, 1, 0x2328);
    else if (!strcmp(a, "DoubleWeapons")) Ender_zone(e, SKIN_WEAPONS, -0x96, 0, 0, 0x2710), Ender_zone(e, SKIN_WEAPONS, 0x96, 0, 0, 0x2710);
    else if (!strcmp(a, "DoubleCoffins")) Ender_zone(e, SKIN_COFFINS, -0x15e, 0, 1, 0xfa0), Ender_zone(e, SKIN_COFFINS, 0x15e, 0, 1, 0xfa0);
    else if (!strcmp(a, "DoubleTrainees")) Ender_zone(e, SKIN_TRAINEES, 0, -0x64, 0, 0x2328), Ender_zone(e, SKIN_TRAINEES, 0, 0x64, 0, 0x2328);
    else if (!strcmp(a, "DoubleExplosions")) Ender_zone(e, SKIN_EXPLOSIONS, 0, -0x64, 0, 0x2710), Ender_zone(e, SKIN_EXPLOSIONS, 0, 0x64, 0, 0x2710);
    else Ender_zone(e, SKIN_WEAPONS, 0, 0, 1, 0x2710);
}
static float Ease_BounceInOut(float v) {  // math/easing/bounce/InOut.js
    int rev = 0;
    if (v < 0.5f) v = 1 - v * 2, rev = 1; else v = v * 2 - 1;
    if (v < 1 / 2.75f) v = 7.5625f * v * v;
    else if (v < 2 / 2.75f) v -= 1.5f / 2.75f, v = 7.5625f * v * v + 0.75f;
    else if (v < 2.5f / 2.75f) v -= 2.25f / 2.75f, v = 7.5625f * v * v + 0.9375f;
    else v -= 2.625f / 2.75f, v = 7.5625f * v * v + 0.984375f;
    return rev ? (1 - v) * 0.5f : v * 0.5f + 0.5f;
}
static void E_EnderRash_Die(Enemy *e) {  // 0x9201: niente camera ne' Mano Bianca (quelli sono del finale, F3): gemme, forziere e lo schiacciamento
    if (e->isDead) return;
    e->isDead = 1;
    float v = EnemySpeed * e->speed * -e->deathKB * e->slow;
    sprite_setVelocity(&e->s, v * e->_currentDirection.x, v * e->_currentDirection.y);
    time_removeEvent(e->_blinkTimeout);
    int value = (int)floorf((frand() + 0.5f) * e->xp);
    if (value > 0) Core_MakeGem(e->s.x, e->s.y, value);
    if (e->treasure) { int lv = e->treasureLevel; Stage_SetTreasureLevelFromChance(e->treasure, &lv); Core_MakeTreasure(e->s.x, e->s.y, e->treasure, lv); e->treasure = NULL; }
    if (GoldFever_isActive()) GoldFever_OnEnemyDeath(e);
    json_inc(tbl0("enemies", e->enemyType), "killedAmount");
    Core.kills++, MainUI_UpdateKills();
    anims_stop(&e->s);
    Boss_DeathScream(e);
    tweens_add((TweenConfig){ .props = { { &e->s.scaleX, NULL, 0 }, { &e->s.scaleY, NULL, 5 } }, .nprops = 2, .duration = 0x7d0, .ease = Ease_BounceInOut });  // SpecialDeathAnimation
}
static const EnemyVT E_EnderRash = { .OnRecycle = E_Ender_OnRecycle, .Die = E_EnderRash_Die, .GetDamaged = E_Ender_GetDamaged, .Update = E_Ender_Update };

// --- RASH (0x321d): l'arena con 2000 spettatori che si agitano (i cerchi delle pizze e i limiti rigidi: codice morto nell'originale) ---------------
static struct { Blitter *bl; struct { float vx, vy, left, right, top, bottom; } *d; } Rash;
static void Rash_Create(void) {
    static const char *const WATCH[16] = { "stklAntonio_0.png", "stklArca_0.png", "stklChristine_0.png", "stklConcetta_0.png", "stklDommario_0.png", "stklGennaro_0.png",
                                           "stklGiovanna_0.png", "stklImelda_0.png", "stklKrochi_0.png", "stklLama_0.png", "stklOld3_0.png", "stklPasqualina_0.png",
                                           "stklPoppea_0.png", "stklPorta_0.png", "stklPugnala_0.png", "stklSuora_0.png" };
    memset(&Rash, 0, sizeof(Rash));
    Blitter *bl = Rash.bl = Blitter_add();  // tutti e quattro i gruppi nel blitter di sinistra (sic)
    static const char *const INV[2] = { "Migno1_0.png", "Werewolf1_0.png" };
    int inv = po_is("SelectedInverse");  // watchersTexture = enemies, watchers = Migno e lupo mannaro
    bl->s.scrollFactor0 = 0, bl->s.blendAdd = 0, bl->s.depth = 0;
    bl->bobs = calloc(bl->cap = 0x7d0, sizeof(Bob));
    Rash.d = calloc(0x7d0, sizeof(*Rash.d));
    for (int g = 0; g < 4; g++)
        for (int i = 0; i < 0x1f4; i++) {
            float x = g == 0 ? 0x140 + 0x100 * frand() : g == 1 ? 0x5a0 + 0x100 * frand() : g == 2 ? 0x120 + 0x580 * frand() : 0x140 + 0x580 * frand();
            float y = g < 2 ? 0x180 + 0x400 * frand() : g == 2 ? 0x180 + 0x80 * frand() : 0x590 + 0x80 * frand();
            int k = bl->n++;
            bl->bobs[k] = (Bob){ x, y, 1, 0, 0, 0, inv ? frame_get("enemies", INV[i % 2]) : frame_get("enemies3", WATCH[i % 16]) };
            Rash.d[k].vx = frand() - 0.5f, Rash.d[k].vy = frand() - 0.5f, Rash.d[k].right = x + 2, Rash.d[k].left = x - 2, Rash.d[k].top = y + 4, Rash.d[k].bottom = y;
            // flipX dei Bob: il Blitter qui non specchia (semplificazione: nessun Bob ribaltato, aggiungerlo a Blitter_draw se si nota)
        }
}
static void Rash_Update(float delta) {
    (void)delta;
    for (int i = 0; i < Rash.bl->n; i++) {  // UpdateBlitter: tremolano in una scatola di 4x4
        Bob *b = &Rash.bl->bobs[i];
        b->y += Rash.d[i].vy, b->x += Rash.d[i].vx;
        if (b->x > Rash.d[i].right || b->x < Rash.d[i].left) Rash.d[i].vx *= -1;
        if (b->y > Rash.d[i].top || b->y < Rash.d[i].bottom) Rash.d[i].vy *= -1;
    }
}
static void Rash_OnInitCompleted(void) { Core_SetHardBounds(0x200, 0x200, 0x600, 0x600); }
static const FancyBG FB_Rash = { Rash_Create, Rash_Update, NULL, NULL, Rash_OnInitCompleted };
