// --- 0x15196: D_MASK_* (le maschere in orbita del Directer, nemici fermi: si rompono solo con BreakOnNextAttack) -------------------
// 0xa2b: D_SKULL / D_EYE, una maschera con gli occhi sopra (eyes_1, alpha 0.5 in yoyo)
typedef struct { int canBreak, isInvul; Sprite eyes; int hasEyes; } DMaskX;
static void DirecterE_OnMaskBroken(Enemy *d);
static void DMask_shakeStart(void *c) { (void)c; camera_followOffsetX = -2; }
static void DMask_shakeDone(void *c) { (void)c; camera_followOffsetX = 0; }
static DMaskX *DMask_x(Enemy *e) { if (!e->x) e->x = calloc(1, sizeof(DMaskX)); return e->x; }
static void E_DMask_OnRecycle(Enemy *e) {
    DMask_x(e);
    base_EnemyOnRecycle(e);
    e->isCullable = 0;
    sprite_setScale(&e->s, 0);
    tweens_add((TweenConfig){ .props = { { &e->s.scaleX, &e->s.scaleY, 1 } }, .nprops = 1, .duration = 0x64 });  // OnEnterTween
}
static void E_DMask_Update(Enemy *e) { e->s.depth = e->s.y - Core.Player->s.y; }  // la posizione la da' il Directer
static void E_DMask_GetDamaged(Enemy *e, float amount, int hitVFX, float kb, const char *t) {
    DMaskX *m = DMask_x(e);
    if (m->isInvul) return;
    if (m->canBreak) {
        base_EnemyDisappear(e);
        Sound_PlaySound("Crystal12", 1.5f, 1, -0x258 * frand(), 0, 0);
        FrameFreeze_ms = 0x78;  // SceneManager.FrameFreeze
        tweens_add((TweenConfig){ .props = { { &camera_followOffsetX, NULL, 2 } }, .nprops = 1, .duration = 0x10, .yoyo = 1, .repeat = 6, .onStart = DMask_shakeStart, .onComplete = DMask_shakeDone });
        if (e->owner) DirecterE_OnMaskBroken(e->owner);
    }
    base_EnemyGetDamaged(e, amount, hitVFX, kb, t);
}
static void E_DMask_Nop(Enemy *e) { (void)e; }  // Die / Disappear vuoti: le maschere non muoiono
static void DMask_ScriptedDisappear(Enemy *e) { base_EnemyDisappear(e); }
static void DMask_BreakOnNextAttack(Enemy *e, int v) { DMask_x(e)->canBreak = v; }
static const EnemyVT E_DMask = { .OnRecycle = E_DMask_OnRecycle, .Die = E_DMask_Nop, .GetDamaged = E_DMask_GetDamaged, .Update = E_DMask_Update, .Disappear = E_DMask_Nop };
static void E_DSkull_OnRecycle(Enemy *e) {
    DMaskX *m = DMask_x(e);
    if (!m->hasEyes) {  // costruttore: gli occhi
        m->hasEyes = 1;
        sprite_init(&m->eyes, frame_get("enemiesM", "eyes_1.png"), e->s.x, e->s.y);
        children_add(&m->eyes);
        tweens_add((TweenConfig){ .props = { { &m->eyes.alpha, NULL, 0.5f } }, .nprops = 1, .duration = 0x1f4, .yoyo = 1, .repeat = -1 });
    }
    E_DMask_OnRecycle(e);
    m->eyes.visible = 1;
    sprite_setOrigin(&m->eyes, e->s.originX, e->s.originY);
}
static void E_DSkull_Update(Enemy *e) {
    DMaskX *m = DMask_x(e);
    e->s.depth = e->s.y - Core.Player->s.y;
    m->eyes.depth = e->s.depth + 0x3e8, m->eyes.scaleX = e->s.scaleX, m->eyes.scaleY = e->s.scaleY, m->eyes.x = e->s.x, m->eyes.y = e->s.y + 4;
}
static void E_DSkull_DeSpawn(Enemy *e) { base_EnemyDeSpawn(e); DMask_x(e)->eyes.visible = 0; }
static const EnemyVT E_DSkull = { .OnRecycle = E_DSkull_OnRecycle, .Die = E_DMask_Nop, .GetDamaged = E_DMask_GetDamaged, .Update = E_DSkull_Update, .Disappear = E_DMask_Nop, .DeSpawn = E_DSkull_DeSpawn };

// --- 0x1016f (shootingEyesManager) + 0x7010 (pool) + 0x7d30: l'occhio-stella che piomba ad arco sul punto e esplode ----------------------
// Avviso: "!" e cerchio a terra, poi la stella percorre un mezzo cerchio (raggio meta' schermo) in 500 ms dopo 1,5 s; esplosione di raggio 60, danno 15.
typedef struct EyeBlast {
    Sprite s;  // disegno: cerchi (avviso e esplosione) + scia ad arco
    Sprite star, warn;
    Animation explode;
    ParticleManager *pm;
    ParticleEmitter *pfx, *pfx2;
    float radius, damage, arcAngle, arcRadius, groundR, groundA, warnA, fxR;
    unsigned color;
    int exploding, hasHit, alive, groundOn, fxOn, trailOn;
    TweenRef arcTween, despawn;
} EyeBlast;
static struct { EyeBlast *e[48]; int n; } EyeBlasts;
static void EyeBlast_draw(Sprite *s) {
    EyeBlast *b = s->owner;
    float cx = s->x - camera_scrollX, cy = s->y - camera_scrollY;
    BeginBlendMode(BLEND_ADDITIVE);
    if (b->groundOn && b->groundA > 0) DrawCircle((int)cx, (int)cy, fmaxf(1, b->groundR), hexc(b->color, b->groundA));  // GroundWarning
    if (b->fxOn) DrawCircle((int)cx, (int)cy, fmaxf(1, b->fxR), hexc(b->color, 0.4f));                                    // GroundFx
    if (b->trailOn && b->arcAngle > 180) {  // trail: arco da 180 al punto corrente, centro (x - arcRadius, y), due passate
        float ax = cx - b->arcRadius, ay = cy;
        DrawRing((Vector2){ ax, ay }, b->arcRadius - 2, b->arcRadius + 2, 180, b->arcAngle, 48, hexc(b->color, 0.5f));
        DrawRing((Vector2){ ax, ay }, b->arcRadius - 1, b->arcRadius + 1, 180, b->arcAngle, 48, hexc(b->color, 0.8f));
    }
    EndBlendMode();
}
static void EyeBlast_DeSpawn(EyeBlast *b) {
    b->alive = 0, b->exploding = 0, b->star.visible = 0, b->warn.visible = 0, b->fxOn = 0, b->groundOn = 0, b->trailOn = 0;
    emitter_stop(b->pfx), emitter_stop(b->pfx2);
    tween_stop(b->despawn), b->despawn = TWEEN_NONE;
    children_remove(&b->s);
}
static void EyeBlast_despawnCb(void *c) { EyeBlast_DeSpawn(c); }
static void EyeBlast_Explode(void *c) {
    EyeBlast *b = c;
    anims_play(&b->star, &b->explode, 0);
    b->exploding = 1, b->hasHit = 0;
    b->pm->wellX = b->s.x, b->pm->wellY = b->s.y - 0x14;
    b->pfx->x = b->pfx2->x = b->s.x, b->pfx->y = b->pfx2->y = b->s.y;
    emitter_start(b->pfx), emitter_start(b->pfx2);
    if (po_is("FlashingVFXEnabled")) b->fxOn = 1, b->fxR = 1;
    tween_stop(b->despawn);
    b->despawn = tweens_add((TweenConfig){ .props = { { &b->fxR, NULL, b->radius } }, .nprops = 1, .duration = 0x96, .onComplete = EyeBlast_despawnCb, .ctx = b });
    b->trailOn = 0;  // trail alpha -> 0 in 100 ms
    Sound_PlaySound("Explosion", 0.5f, 1, 0x1f4 * (frand() - 0.5f), 0x96, 3);
}
static void EyeBlast_arcStart(void *c) { EyeBlast *b = c; b->trailOn = 1, b->star.visible = 1; }
static void EyeBlast_warnBack(void *c) { EyeBlast *b = c; tweens_add((TweenConfig){ .props = { { &b->warn.scaleX, &b->warn.scaleY, 0 } }, .nprops = 1, .duration = 0xc8, .delay = 0xc8 }); }
static EyeBlast *EyeBlast_SpawnAt(float x, float y, float damage, float radius) {
    EyeBlast *b = NULL;
    for (int i = 0; i < EyeBlasts.n; i++) if (!EyeBlasts.e[i]->alive) { b = EyeBlasts.e[i]; break; }
    if (!b && EyeBlasts.n < 48) {  // Make + Init
        b = EyeBlasts.e[EyeBlasts.n++] = calloc(1, sizeof(EyeBlast));
        sprite_init(&b->s, NULL, 0, 0), b->s.owner = b, b->s.draw = EyeBlast_draw;
        b->pm = particles_add();
        static const char *const BL[3] = { "Blood1.png", "Blood2.png", "Blood3.png" };
        EmitterConfig c = { .frames = { frame_get("vfx", BL[0]), frame_get("vfx", BL[1]), frame_get("vfx", BL[2]) }, .nframes = 3, .rotate = ERND(0, 0x168), .quantity = 2, .scale = ERANGE(1, 0), .frequency = 2, .on = 0 };
        c.lifespan = EOP(0x3e8), c.angle = (EmitterOp){ 0, 0xb4, 0 }, c.angleSteps = 0x10, c.speed = ERND(0x64, 0xc8), c.alpha = ERANGE(0.5f, 0);
        b->pfx2 = particles_createEmitter(b->pm, c);
        c.lifespan = EOP(0x1f4), c.angle = (EmitterOp){ 0, 0x168, 0 }, c.speed = ERND(0x50, 0x78), c.alpha = EOP(1), c.blendAdd = 1;
        b->pfx = particles_createEmitter(b->pm, c);
        b->pm->hasWell = 1, b->pm->wellPower = 1 * 0x14, b->pm->wellEpsilon = 0x32 * 0x32;
        sprite_init(&b->warn, frame_get("UI", "ExclamationMark.png"), 0, 0), sprite_setScale(&b->warn, 0), sprite_setOrigin(&b->warn, 0.5f, 1), b->warn.depth = 0x2328;
        sprite_init(&b->star, frame_get("enemies2", "eye_0.png"), 0, 0), sprite_setScale(&b->star, 2), sprite_setOrigin(&b->star, 0.5f, 1), b->star.depth = 0x2328, b->star.angle = 0xf;
        make_anim(&b->explode, "enemies2", "eye_", 5, 0x15, 0, 0x1e, 0);
        children_add(&b->warn), children_add(&b->star);
    }
    if (!b) return NULL;
    static const unsigned COL[3] = { 0xff8800, 0xffff00, 0xff4400 };
    b->alive = 1, b->s.x = x, b->s.y = y, b->damage = damage, b->radius = radius, b->color = COL[RND_between(0, 2)];
    b->s.depth = b->pm->s.depth = y + 1 - Core.Player->s.y;
    children_add(&b->s);
    // OnRecycle
    b->star.visible = 0, sprite_setFrame(&b->star, frame_get("enemies2", "eye_0.png")), anims_stop(&b->star);
    b->arcRadius = 0.5f * game_width, b->exploding = 0, b->hasHit = 1;
    b->warn.x = x, b->warn.y = y - 0x10, sprite_setScale(&b->warn, 0), b->warn.visible = 1;
    b->groundA = 0, b->groundR = 1, b->groundOn = 1;
    Sound_PlaySound("Pizza", 0.9f, 1, 0x1f4 * frand(), 0x96, 2);
    tweens_add((TweenConfig){ .props = { { &b->warn.scaleX, &b->warn.scaleY, 1 } }, .nprops = 1, .duration = 0xc8, .onComplete = EyeBlast_warnBack, .ctx = b });
    tweens_add((TweenConfig){ .props = { { &b->groundA, NULL, 0.2f }, { &b->groundR, NULL, radius } }, .nprops = 2, .duration = 0x1f4, .yoyo = 1, .repeat = 1 });
    b->arcAngle = 0xb4;
    tween_stop(b->arcTween);
    b->arcTween = tweens_add((TweenConfig){ .props = { { &b->arcAngle, NULL, 0x168 } }, .nprops = 1, .duration = 0x1f4, .delay = 0x5dc, .onStart = EyeBlast_arcStart, .onComplete = EyeBlast_Explode, .ctx = b });
    return b;
}
static void EyeBlasts_Update(float delta) {  // explosionEyePool.Update: danno alla prima entrata nel cerchio, poi la scia
    for (int i = 0; i < EyeBlasts.n; i++) {
        EyeBlast *b = EyeBlasts.e[i];
        if (!b->alive) continue;
        if (!b->hasHit && b->exploding) {
            float dx = Core.Player->s.x - b->s.x, dy = Core.Player->s.y - b->s.y;
            if (dx * dx + dy * dy <= b->radius * b->radius) b->hasHit = 1, Player_GetDamaged(Core.Player, b->damage);
        }
        if (b->star.visible && !b->exploding) {  // trailUpdate: la stella sull'arco
            float a = b->arcAngle * DEG2RAD;
            b->star.x = b->s.x - b->arcRadius + cosf(a) * b->arcRadius, b->star.y = b->s.y + sinf(a) * b->arcRadius;
        }
        sprite_animsUpdate(&b->star, delta);
    }
    (void)delta;
}
static void ShootingEyes_shootOne(float k) {  // shootOne: un punto a caso nella meta' centrale dello schermo attorno al giocatore
    float x = Core.Player->s.x + (frand() - 0.5f) * game_width * 0.5f * k, y = Core.Player->s.y + (frand() - 0.5f) * game_height * 0.5f * k;
    EyeBlast_SpawnAt(x, y, 0xf, 0x3c);
}
static void ShootingEyes_Stop(void) { for (int i = 0; i < EyeBlasts.n; i++) if (EyeBlasts.e[i]->alive) EyeBlast_DeSpawn(EyeBlasts.e[i]); }

// --- 0x5b89: D_CLUSTER_COINS / D_CLUSTER_GEMS (fase 4): maschere che a ogni colpo spruzzano monete o gemme verso il giocatore -------------
typedef struct { DMaskX m; ParticleManager *pm; ParticleEmitter *pfx; int canEmit; Timer particlesTimer; } DClusterX;
static void DCluster_canEmit(void *c) { ((DClusterX *)((Enemy *)c)->x)->canEmit = 1; }
static void E_DCluster_OnRecycle(Enemy *e) {
    if (!e->x) e->x = calloc(1, sizeof(DClusterX)), ((DClusterX *)e->x)->canEmit = 1, ((DClusterX *)e->x)->particlesTimer = (Timer){ -1, 0 };
    DClusterX *c = e->x;
    E_DMask_OnRecycle(e);
    const char *fr = !strcmp(e->enemyType, "D_CLUSTER_GEMS") ? "GemBlue.png" : "CoinGold.png";
    if (!c->pm) c->pm = particles_add();  // scene.add.particles('items').createEmitter (uno nuovo a ogni riciclo nell'originale)
    c->pfx = particles_createEmitter(c->pm, (EmitterConfig){ .frames = { frame_get("items", fr) }, .nframes = 1, .quantity = 0xa, .lifespan = EOP(0x7d0), .alpha = ERANGE(1, 0),
        .angle = ERND(0xe1, 0x13b), .speed = ERND(0xe1, 0x113), .scale = ERANGE(2, 0), .gravityY = 0x320, .bounce = 0.2f, .collideBottom = 1, .boundsH = 1e9f, .on = 0 });
}
static void E_DCluster_GetDamaged(Enemy *e, float amount, int hitVFX, float kb, const char *t) {
    DClusterX *c = e->x;
    if (c->m.isInvul) return;
    if (c->canEmit) {  // (sic) canEmitParticles non torna mai falso: emette a ogni colpo
        emitter_emitParticleAt(c->pfx, e->s.x, e->s.y, 0);
        time_removeEvent(c->particlesTimer);
        c->particlesTimer = time_addEvent(0x5dc, 0, 0, DCluster_canEmit, e);
        if (!strcmp(e->enemyType, "D_CLUSTER_COINS")) {
            Pickup *p = Core_MakePickup(e->s.x, e->s.y, "COIN");
            if (p) p->time = 1, p->goToPlayer = 1, p->value = 0.5f, p->feverMS = 0xa;
        } else {
            Pickup *p = Core_MakePickup(e->s.x, e->s.y, "GEM");
            if (p) p->time = 1, p->goToPlayer = 1, p->value = 3;
        }
    }
    base_EnemyGetDamaged(e, amount, hitVFX, kb, t);
}
static const EnemyVT E_DCluster = { .OnRecycle = E_DCluster_OnRecycle, .Die = E_DMask_Nop, .GetDamaged = E_DCluster_GetDamaged, .Update = E_DMask_Update, .Disappear = E_DMask_Nop };

// --- 0x185e5: DIRECTER, il nemico. Maschere in orbita (7 pool), mani (12 animazioni), attacchi per fase, la mano bianca -----------------
enum { DH_IDLE, DH_ITALIAN, DH_POINT, DH_THROW, DH_SNAP_START, DH_SNAP_DO, DH_PINCH_START, DH_PINCH_DO, DH_REVEAL_START, DH_REVEAL_DO, DH_REVIVE_START, DH_REVIVE_DO, DH_N };
