static void DirecterE_drawStars(Sprite *s);
static void Directer_hand(Sprite *h, int a) { anims_play(h, &DirecterHandAnims[a], 0); }
static void DirecterE_MakeMasks(Enemy *e) {
    DirecterEX *d = e->x;
    for (int i = 0; i < 7; i++) d->eye[i] = EnemyPool_SpawnAt(d->pool_mask[i], e->s.x, e->s.y), d->eye[i]->owner = e;
}
static void DirecterE_clearEyes(DirecterEX *d) { for (int i = 0; i < 7; i++) if (d->eye[i] && !d->eye[i]->isDead) DMask_ScriptedDisappear(d->eye[i]); }
static void DirecterE_MakeSkulls(Enemy *e) {  // fase 3: cinque teschi con gli occhi 1-5 e due occhi specchiati
    DirecterEX *d = e->x;
    DirecterE_clearEyes(d);
    for (int i = 0; i < 7; i++) {
        d->eye[i] = EnemyPool_SpawnAt(i < 5 ? d->pool_skulls : d->pool_eyes, e->s.x, e->s.y);
        DMaskX *m = DMask_x(d->eye[i]);
        if (i < 5) sprite_setFrame(&m->eyes, frame_get("enemiesM", TextFormat("eyes_%d.png", i + 1)));
        else m->eyes.visible = 0, d->eye[i]->s.flipX = 1;  // SetEyes() senza fotogramma: nascosti
        d->eye[i]->owner = e;
    }
}
static void DirecterE_MakeTreasures(Enemy *e) {  // fase 4: gemme e oro alternati
    DirecterEX *d = e->x;
    DirecterE_clearEyes(d);
    for (int i = 0; i < 7; i++) d->eye[i] = EnemyPool_SpawnAt(i % 2 ? d->pool_gold : d->pool_gems, e->s.x, e->s.y), d->eye[i]->owner = e;
}
static void DirecterE_Shrink(Enemy *e) {  // fase 5: maschere via, il Directer si rimpicciolisce e resta un cuore che pulsa
    DirecterEX *d = e->x;
    DirecterE_clearEyes(d);
    e->s.body.enable = 0;
    tweens_add((TweenConfig){ .props = { { &e->s.scaleX, &e->s.scaleY, 0 } }, .nprops = 1, .duration = 0x3e8 });
    sprite_init(&d->heart, frame_get("items", "HeartRuby.png"), e->s.x, e->s.y), d->heart.depth = e->s.depth - 1, d->heartOn = 1;
    children_add(&d->heart);
    tweens_add((TweenConfig){ .props = { { &d->heart.scaleX, &d->heart.scaleY, 1.1f } }, .nprops = 1, .duration = 0x3e8, .yoyo = 1, .repeat = -1, .ease = Ease_SineInOut });
}
static void DirecterE_MakeMasksBreakable(Enemy *e) {
    DirecterEX *d = e->x;
    d->breakTimer = 0, d->BreakEnabled = 1;
    for (int i = 0; i < 7; i++) if (d->eye[i] && !d->eye[i]->isDead) DMask_BreakOnNextAttack(d->eye[i], 1);
}
static void DirecterE_OnMaskBroken(Enemy *e) {
    DirecterEX *d = e->x;
    d->BrokenMasks++, d->breakTimer = 0;
    for (int i = 0; i < 7; i++) if (d->eye[i] && !d->eye[i]->isDead) DMask_BreakOnNextAttack(d->eye[i], 0);
}
static void DirecterE_handBack(void *c) { Sprite *h = c; Directer_hand(h, DH_IDLE), h->flipY = 1; }
static void DirecterE_ThrowEgg(Enemy *e, Sprite *h, float x, float y) {  // ThrowEggR / ThrowEggL (sic: L senza coordinate parte dalla mano destra)
    DirecterEX *d = e->x;
    Directer_hand(h, DH_THROW), h->flipY = 0;
    if (x) EnemyPool_SpawnAt(d->pool_eggs, x, y);
    else EnemyPool_SpawnAt(d->pool_eggs, d->RightHand.x, d->RightHand.y);
    time_addEvent(0x1f4, 0, 0, DirecterE_handBack, h);
}
static void DirecterE_zone(Enemy *e, float dy) {  // DamagingZone_Explosions: una riga larga lo schermo che segue il giocatore in x
    DirecterEX *d = e->x;
    EnderZone *z = EnderZone_SpawnAt(&d->explosions, Core.Player->s.x, Core.Player->s.y + dy, game_width, 0x64, 0xc, 0x2710 * d->attacksDurationMultiplier, 0x1f4, SKIN_EXPLOSIONS, 0);
    z->lockX = 1;
}
static void DirecterE_shootOne(void *c) { ShootingEyes_shootOne(*(float *)&c); }
static void DirecterE_ShootEyes(int n, float delay, float k) {
    for (int i = 0; i < n; i++) {
        void *kk;
        memcpy(&kk, &k, sizeof(float));
        time_addEvent(delay * i, 0, 0, DirecterE_shootOne, kk);
    }
}
static void DirecterE_whiteKill(void *c) {  // la mano bianca arriva al centro: il giocatore muore
    DirecterEX *d = c;
    Core.Player->hp = 0;
    Player_Die(Core.Player);
    tweens_add((TweenConfig){ .props = { { &d->RightHand.scaleX, &d->RightHand.scaleY, 0 }, { &d->WhiteHand.scaleX, &d->WhiteHand.scaleY, 0 } }, .nprops = 2, .duration = 0x1f4 });
}
static void DirecterE_whiteStart(void *c) { Directer_hand(&((DirecterEX *)c)->RightHand, DH_PINCH_DO); }
static void DirecterE_whiteUpdate(void *c) { DirecterEX *d = c; d->RightHand.x = d->WhiteHand.x - 0xc; }
static void DirecterE_DragInWhiteHand(Enemy *e) {
    DirecterEX *d = e->x;
    d->WhiteHand.x = game_width + 0x20, sprite_setScale(&d->WhiteHand, 2), d->WhiteHand.visible = 1;
    d->RightHand.flipX = 1, d->RightHand.flipY = 0, sprite_setOrigin(&d->RightHand, 1, 0.5f), d->RightHand.x = d->WhiteHand.x - 0xc, d->RightHand.y = 0.5f * game_height - 0x20;
    sprite_setScale(&d->RightHand, 4), Directer_hand(&d->RightHand, DH_PINCH_START), d->RightHand.scrollFactor0 = 1, d->RightHand.visible = 1;
    tweens_add((TweenConfig){ .props = { { &d->RightHand.scaleX, &d->RightHand.scaleY, 1 } }, .nprops = 1, .duration = 0x3e8 });
    tweens_add((TweenConfig){ .props = { { &d->WhiteHand.x, NULL, 0.5f * game_width }, { &d->RightHand.x, NULL, 0.5f * game_width } }, .nprops = 2, .duration = 0xbb8, .delay = 0x44c,
                              .onStart = DirecterE_whiteStart, .onUpdate = DirecterE_whiteUpdate, .onComplete = DirecterE_whiteKill, .ctx = d });
}
static void DirecterE_CheckAttack(Enemy *e) {
    DirecterEX *d = e->x;
    switch (d->currentPhase) {
    case 0:  // Attack_Behaviour0
        if ((int)floorf(2 * frand()) == 0) PlaySwarm(0x4e20, 0x32, "BATSWARM");
        else PlaySwarm(0xea60, 0x10, "TRAINEE_Y");
        break;
    case 1: {
        d->attack1Index++;
        DirecterE_ThrowEgg(e, &d->RightHand, 0, 0);
        static const char *const T[5] = { "BATSWARM", "MUD", "MILK", "SKULLINO", "TRAINEE_Y" };
        int r = (int)floorf(5 * frand());
        if (r == 0) PlaySwarm(0x4e20, 0x32, T[r]);
        else PlaySwarm(0xea60, (r == 4 ? 0x10 : 0x18) + d->attack1Index, T[r]);
        break;
    }
    case 2: {
        float x = Core.Player->s.x + 0.5f * game_width, y = Core.Player->s.y;
        DirecterE_ThrowEgg(e, &d->LeftHand, x, y - 0x50), DirecterE_ThrowEgg(e, &d->RightHand, x, y + 0x50);
        switch (d->stageIndex) {  // gli sciami dello stage che scorre sullo sfondo (attack2Index resta 0, sic)
        case 0: PlaySwarm(0x4e20, 0x32, "BATSWARM"), PlaySwarm(0xea60, 0x18 + d->attack2Index, "ZOMBIE"); break;
        case 1: PlaySwarm(0xea60, 0xc, "MUMMY"), PlaySwarm(0xea60, 0xc + d->attack2Index, "GHOST"); break;
        case 2: PlaySwarm(0xea60, 0xc, "LIZARD1_2"), PlaySwarm(0xea60, 0x18 + d->attack2Index, "FISHMAN_1"); break;
        case 3: PlaySwarm(0xea60, 0x18, "SKULOROSSO"), PlaySwarm(0xea60, 0xc + d->attack2Index, "DULL0"); break;
        case 4: PlaySwarm(0xea60, 0x10 + d->attack2Index, "TRAINEE_Y"), PlaySwarm(0xea60, 0x18, "SKELETON"); break;
        }
        break;
    }
    case 3:
        d->attack3Index++;
        if (Core.Player->revivals >= 1 && d->attack3Index > 3) d->attack3Index = 0, DirecterE_DragInWhiteHand(e);
        switch ((int)floorf(5 * frand())) {
        case 0: DirecterE_ShootEyes(5, 0x3c, 1); break;
        case 1: DirecterE_zone(e, -0x64), DirecterE_zone(e, 0x64); break;
        case 2: DirecterE_ShootEyes(0xa, 0x1e, 1); break;
        case 3: DirecterE_ShootEyes(0x14, 0x64, 0.5f); break;
        case 4: DirecterE_zone(e, -0xc8), DirecterE_zone(e, 0xc8); break;
        }
        PlaySwarm(0xea60, 0xc + (d->attack3Index < 0xc ? d->attack3Index : 0xc), "D_WEAK_EYE");
        break;
    case 4: {
        if (!po_is("HasSeenFinalFireworks") && d->attack4Index < 1) DirecterE_DragInWhiteHand(e);
        d->attack4Index++;
        if (Core.Enemies.n > 0x6c) return;
        Vector2 pt[5];  // Ellipse(player, 1.4 w, 1.4 h).getPoints(5), rimescolati
        for (int i = 0; i < 5; i++) pt[i] = (Vector2){ Core.Player->s.x + 0.7f * game_width * cosf(2 * PI * i / 5), Core.Player->s.y + 0.7f * game_height * sinf(2 * PI * i / 5) };
        for (int i = 4; i > 0; i--) { int j = (int)floorf(frand() * (i + 1)); Vector2 t = pt[i]; pt[i] = pt[j], pt[j] = t; }
        for (int i = 0; i < 5; i++) {
            Enemy *r = EnemyPool_SpawnAt(d->pool_reapersA, pt[i].x, pt[i].y);
            if (r) r->isCullable = 0, r->isTeleportOnCull = 1;
        }
        break;
    }
    }
}
static float DirecterE_approach(float v, float t, float s) { return v < t ? fminf(v + s, t) : fmaxf(v - s, t); }
static void DirecterE_moveStart(void *c) { DirecterEX *d = c; d->xOffset = d->currentPhase >= 4 ? -0.3f * game_width : d->currentPhase == 3 ? -0.4f * game_width : -0.45f * game_width, d->yOffset = 8; }
static void DirecterE_Movement(Enemy *e, float delta) {  // Movement_Behaviour0 / 3 / 4: insegue in y, sta a sinistra del giocatore in x con un'oscillazione
    DirecterEX *d = e->x;
    if (d->currentPhase <= 2 && !tween_get(d->moveTween0))
        d->moveTween0 = tweens_add((TweenConfig){ .props = { { &d->xOffset, NULL, -0.2f * game_width } }, .nprops = 1, .duration = 0x7d0, .repeat = -1, .yoyo = 1, .ease = Ease_SineInOut, .onStart = DirecterE_moveStart, .ctx = d });
    if (d->currentPhase == 3 && !tween_get(d->moveTween3))
        tween_stop(d->moveTween0), d->moveTween3 = tweens_add((TweenConfig){ .props = { { &d->xOffset, NULL, -0.25f * game_width }, { &d->yOffset, NULL, -8 } }, .nprops = 2, .duration = 0x3e8,
                                                                            .repeat = -1, .yoyo = 1, .ease = Ease_SineInOut, .onStart = DirecterE_moveStart, .ctx = d });
    if (d->currentPhase == 4 && !tween_get(d->moveTween4))
        tween_stop(d->moveTween3), d->moveTween4 = tweens_add((TweenConfig){ .props = { { &d->xOffset, NULL, -0.2f * game_width }, { &d->yOffset, NULL, -8 } }, .nprops = 2, .duration = 0x7d0,
                                                                            .repeat = -1, .yoyo = 1, .ease = Ease_SineInOut, .onStart = DirecterE_moveStart, .ctx = d });
    if (d->currentPhase > 4) return;
    float s = PlayerPxSpeed * Core.Player->moveSpeed * 0.9f * (0.001f * delta);
    e->s.y = DirecterE_approach(e->s.y, Core.Player->s.y, s), e->s.x = Core.Player->s.x + d->xOffset;
}
static void E_Directer_OnRecycle(Enemy *e) {
    if (!e->x) {  // costruttore
        DirecterEX *d = e->x = calloc(1, sizeof(DirecterEX));
        d->breakDelay = 0x3e8, d->attackDelay = 0x1388, d->attacksDurationMultiplier = 1, d->HasHands = 1;
        static const float A[7] = { 0, 0.23f, 0.41f, 0.61f, 0.71f, 0.79f, 0.83f }, S[7] = { 2, 1.75f, 1.5f, 1.25f, 1, 0.75f, 0.5f }, S2[7] = { 0.5f, 0.75f, 1, 1.25f, 1.5f, 1.75f, 2 };
        static const float D[7] = { 0x3f1, 0x4c1, 0x5d1, 0x653, 0x745, 0x833, 0x925 };
        for (int i = 0; i < 7; i++) {
            d->radius[i] = 0x40, d->myAngle[i] = 2 * PI * A[i], d->scale[i] = S[i];
            tweens_add((TweenConfig){ .props = { { &d->radius[i], NULL, 0x20 } }, .nprops = 1, .duration = D[i], .yoyo = 1, .repeat = -1 });
            tweens_add((TweenConfig){ .props = { { &d->scale[i], NULL, S2[i] } }, .nprops = 1, .duration = D[i], .yoyo = 1, .repeat = -1 });
        }
        sprite_init(&d->WhiteHand, frame_get("enemies3", "WhiteHand_i01.png"), game_width + 0x20, 0.5f * game_height);  // MakeWhiteHand
        make_anim(&d->whiteIdle, "enemies3", "WhiteHand_i0", 1, 4, 0, 0x3c, -1);
        anims_play(&d->WhiteHand, &d->whiteIdle, 0);
        sprite_setOrigin(&d->WhiteHand, 0.5f, 1), sprite_setScale(&d->WhiteHand, 2), d->WhiteHand.scrollFactor0 = 1, d->WhiteHand.depth = 0x2710;
        children_add(&d->WhiteHand);
        static const struct { const char *p; int a, b, rep; } HA[DH_N] = { { "hand_", 1, 4, -1 }, { "hand_italian_", 1, 2, -1 }, { "hand_point_", 1, 2, -1 }, { "hand_throw_", 1, 4, 0 },
            { "hand_snap_", 1, 3, -1 }, { "hand_snap_", 4, 5, 0 }, { "hand_pinch_", 1, 2, -1 }, { "hand_pinch_", 3, 4, 0 }, { "hand_reveal_", 1, 2, -1 }, { "hand_reveal_", 3, 4, 0 },
            { "hand_revive_", 1, 2, -1 }, { "hand_revive_", 3, 7, 0 } };
        for (int i = 0; i < DH_N; i++) make_anim(&DirecterHandAnims[i], "enemiesM", HA[i].p, HA[i].a, HA[i].b, 2, 8, HA[i].rep);
        for (int k = 0; k < 2; k++) {
            Sprite *h = k ? &d->RightHand : &d->LeftHand;
            sprite_init(h, frame_get("enemiesM", "hand_01.png"), e->s.x, e->s.y);
            sprite_setOrigin(h, k ? 0 : 1, 0.5f), h->flipX = k;
            Directer_hand(h, DH_ITALIAN);
            children_add(h);
        }
        static const char *const P[7] = { "D_MASK_SUN", "D_MASK_MOON", "D_MASK_CITY", "D_MASK_WINDS", "D_MASK_VOLCANO", "D_MASK_GREED", "D_MASK_VOID" };
        for (int i = 0; i < 7; i++) d->pool_mask[i] = EnemyPool_new(P[i]);
        d->pool_skulls = EnemyPool_new("D_SKULL"), d->pool_eyes = EnemyPool_new("D_EYE"), d->pool_gold = EnemyPool_new("D_CLUSTER_COINS"), d->pool_gems = EnemyPool_new("D_CLUSTER_GEMS");
        d->pool_eggs = EnemyPool_new("BULLET_EGG"), d->pool_reapersA = EnemyPool_new("D_WEAK_REAPER_A");
        base_EnemyOnRecycle(e);  // OnRecycle prima di MakeMasks: le maschere nascono sul Directer
        e->isCullable = 0, sprite_setOrigin(&e->s, 0.5f, 0.5f), sprite_setScale(&e->s, 5);
        body_setCircle(&e->s.body, 0xc, 3, 3);
        DirecterE_MakeMasks(e);
        e->s.draw = DirecterE_drawStars;
        TheDirecter = e;
        return;
    }
    base_EnemyOnRecycle(e);
    e->isCullable = 0, sprite_setOrigin(&e->s, 0.5f, 0.5f), sprite_setScale(&e->s, 5), body_setCircle(&e->s.body, 0xc, 3, 3);
}
static void E_Directer_Update(Enemy *e) {
    DirecterEX *d = e->x;
    float delta = Enemies_delta;
    d->t += delta;
    DirecterE_Movement(e, delta);
    d->attackTimer += delta;
    if (d->attackTimer >= d->attackDelay) d->attackTimer = 0, DirecterE_CheckAttack(e);
    if (d->BreakEnabled && (d->breakTimer += delta) > d->breakDelay) d->breakTimer = 0, DirecterE_MakeMasksBreakable(e);
    e->s.depth = d->currentPhase >= 4 ? 0 : -game_height;
    for (int i = 0; i < 7; i++) if (d->eye[i]) d->eye[i]->s.depth = 0x49 + d->eye[i]->s.y - Core.Player->s.y, sprite_setScale(&d->eye[i]->s, d->scale[i]);
    if (d->HasHands) d->LeftHand.x = e->s.x - 0x30, d->LeftHand.y = e->s.y, d->RightHand.x = e->s.x + 0x30, d->RightHand.y = e->s.y, d->LeftHand.depth = d->RightHand.depth = e->s.depth + 2;
    for (int i = 0; i < 7; i++) d->myAngle[i] += PI / 0x168 * delta * 0.25f;
    static const int RY[7] = { 1, 3, 5, 0, 2, 4, 6 };
    for (int i = 0; i < 7; i++) if (d->eye[i]) d->eye[i]->s.x = e->s.x + 0x6c * cosf(d->myAngle[i]), d->eye[i]->s.y = -0x40 + e->s.y + sinf(d->myAngle[(i + 1) % 7]) * d->radius[RY[i]];
    for (int i = 0; i < d->explosions.nspawned; i++) EnderZone_Update(d->explosions.spawned[i], delta);
    EyeBlasts_Update(delta);
    sprite_animsUpdate(&d->LeftHand, delta), sprite_animsUpdate(&d->RightHand, delta), sprite_animsUpdate(&d->WhiteHand, delta);
    if (d->heartOn) d->heart.x = e->s.x, d->heart.y = e->s.y;
}
static void E_Directer_GetDamaged(Enemy *e, float amount, int hitVFX, float kb, const char *t) {
    DirecterEX *d = e->x;
    if (d->isInvul) return;
    d->TotalDamage += amount, d->DirectHits++;
    base_EnemyGetDamaged(e, amount, hitVFX, kb, t);
}
static const EnemyVT E_Directer = { .OnRecycle = E_Directer_OnRecycle, .Die = E_DMask_Nop, .GetDamaged = E_Directer_GetDamaged, .Update = E_Directer_Update, .Disappear = E_DMask_Nop };
// TriggerPhase1-5 (le chiama il fancyBG della Machine su OnPhaseN)
static void DirecterE_handsGone(void *c) {  // AutoPositionHands: dopo la fase 2 le mani stanno sul bordo destro dello schermo
    DirecterEX *d = c;
    d->HasHands = 0;
    d->RightHand.flipX = 0, sprite_setOrigin(&d->RightHand, 1, 0.5f), d->LeftHand.scrollFactor0 = d->RightHand.scrollFactor0 = 1;
    d->LeftHand.x = game_width, d->LeftHand.y = 0.5f * game_height - 0x50, d->RightHand.x = game_width, d->RightHand.y = 0.5f * game_height + 0x50;
    d->LeftHand.depth = d->RightHand.depth = game_height;
    tweens_add((TweenConfig){ .props = { { &d->LeftHand.scaleX, &d->LeftHand.scaleY, 1 }, { &d->RightHand.scaleX, &d->RightHand.scaleY, 1 } }, .nprops = 2, .duration = 0x1f4 });
}
static void DirecterE_TriggerPhase(Enemy *e, int n) {
    DirecterEX *d = e->x;
    d->currentPhase = n;
    switch (n) {
    case 1:
        d->attackDelay = 0x1388;
        Directer_hand(&d->LeftHand, DH_IDLE), Directer_hand(&d->RightHand, DH_IDLE), d->LeftHand.flipY = d->RightHand.flipY = 1;
        break;
    case 2:
        d->attackDelay = 0x1388;
        tweens_add((TweenConfig){ .props = { { &d->LeftHand.scaleX, &d->LeftHand.scaleY, 0 }, { &d->RightHand.scaleX, &d->RightHand.scaleY, 0 } }, .nprops = 2, .duration = 0x1f4, .onComplete = DirecterE_handsGone, .ctx = d });
        break;
    case 3:
        d->DirectHits = 0;
        DirecterE_MakeSkulls(e);
        tweens_add((TweenConfig){ .props = { { &d->LeftHand.scaleX, &d->LeftHand.scaleY, 0 }, { &d->RightHand.scaleX, &d->RightHand.scaleY, 0 } }, .nprops = 2, .duration = 0x1f4 });
        break;
    case 4: d->attackDelay = 0x1f4, DirecterE_MakeTreasures(e); break;
    case 5: DirecterE_Shrink(e); break;
    }
}
static void DStars_draw(Sprite *s, float t);
static void DirecterE_drawStars(Sprite *s) { DStars_draw(s, ((DirecterEX *)((Enemy *)s->owner)->x)->t); }

static Texture2D img_texture(const char *key);
static float lerp01(float t, float start, float dur);
static float ease_sine_inout(float k);
static int Machine_colorOn;
