static void ChS_fxDraw(Sprite *s) { (void)s; SnapFX_draw(ChS.t); }
static void Chapel_snapHide(void *c) { (void)c; tweens_add((TweenConfig){ .props = { { &Chapel.snap.alpha, NULL, 0 } }, .nprops = 1, .duration = 0x12c }); }
static void Chapel_snapPlay(float hideAfter) {  // snap.setAlpha(1), play('snap'), alpha 0 in 300 ms dopo hideAfter
    Chapel.snap.alpha = 1;
    anims_play(&Chapel.snap, &Chapel.snapAnim, 0);
    time_addEvent(hideAfter, 0, 0, Chapel_snapHide, NULL);
}
static void Chapel_snapSound(void) { Sound_PlaySound("BGM_GameOver", 1.6f, 1, 1000, 0, 0); }
static void Chapel_eggsGo(void *c) { (void)c; Chapel_snapSound(); SnapFX_eggs(ChS.t); }
static void Chapel_SnapEggs(void) {  // minuto 4
    if (!po_is("SelectedGoldenEggs")) return;
    int n = EggManager_RemoveBonuses();
    if (n <= 0) return;
    SnapFX.nEggs = n < 0x1f4 ? n : 0x1f4;
    Chapel_snapPlay(0x1f4 + 0x258 + 0xa * SnapFX.nEggs);
    time_addEvent(0x1f4, 0, 0, Chapel_eggsGo, NULL);
}
static void Chapel_yellowsGo(void *c) {  // dopo 500 ms: suono, armi e anelli via, le icone girano e spariscono
    (void)c;
    Chapel_snapSound();
    SnapFX.nPowers = 0, SnapFX.powersAt = ChS.t;
    if (Core_GetWeapon("SHROUD")) SnapFX.powers[SnapFX.nPowers++] = "cape.png", Core_RemoveWeapon("SHROUD");
    if (Core_GetWeapon("CORRIDOR")) SnapFX.powers[SnapFX.nPowers++] = "portal.png", Core_RemoveWeapon("CORRIDOR");
    static const char *const icon[4] = { "goldring.png", "silverring.png", "bsleft.png", "bsright.png" };
    for (int i = 0; i < 4; i++) if (ChS.yellow[i]) SnapFX.powers[SnapFX.nPowers++] = icon[i];
    for (int i = 0; i < 4; i++) if (ChS.yellow[i]) Pickup_DeSpawn(ChS.yellow[i]), ChS.yellow[i] = NULL;
}
static void Chapel_SnapYellows(void) {  // all'ingresso: Crimson Shroud, Infinite Corridor e le loro parti a terra
    static const char *const W[4] = { "GOLD", "SILVER", "LEFT", "RIGHT" };
    int any = Core_GetWeapon("SHROUD") || Core_GetWeapon("CORRIDOR");
    for (int k = 0; k < 4; k++) {
        ChS.yellow[k] = NULL;
        for (int i = 0; i < Core.PickupGroup.n && !ChS.yellow[k]; i++) {
            Pickup *p = Core.PickupGroup.items[i]->owner;
            if (p->weaponType && !strcmp(p->weaponType, W[k])) ChS.yellow[k] = p, any = 1;
        }
    }
    if (!any) return;
    Chapel_snapPlay(0x3e8);
    time_addEvent(0x1f4, 0, 0, Chapel_yellowsGo, NULL);
}
static void Chapel_ToggleBlue(int on) {
    Chapel.skyBlue.s.visible = Chapel.cloudsBlue.s.visible = Chapel.cloudsAddBlue.s.visible = on;
    if (on) Chapel.floorLights.s.tint = Chapel.skyLights.s.tint = 0xffffff;
}
static void Chapel_ToggleRed(int on) {
    Chapel.skyRed.s.visible = Chapel.cloudsRed.s.visible = Chapel.cloudsAddRed.s.visible = on;
    if (on) Chapel.floorLights.s.tint = Chapel.skyLights.s.tint = 0xff4422;  // semplificazione: setTint(0xff0000, 0xff0088, 0xff0000, 0xffff00) ai vertici, qui la media
}
static void Chapel_ToggleAlias(int on) {  // gli angeli (alias: FANGEL, TRAINEE_Y e il Maddener) cambiano aspetto
    for (int i = 0; i < Core.Enemies.n; i++) {
        Enemy *e = Core.Enemies.items[i]->owner;
        if (e->isDead || (e->vt != &E_FAngel && e->vt != &E_Maddener) || !e->x) continue;
        BridgeX *b = e->x;
        if (on && b->aliasIdle.n) anims_play(&e->s, &b->aliasIdle, 0);
        else if (!on && e->idle.n) anims_play(&e->s, &e->idle, 0);
    }
}
static void Chapel_faderOut(void *c) { (void)c; tweens_add((TweenConfig){ .props = { { &Chapel.whiteFader.alpha, NULL, 0 } }, .nprops = 1, .duration = 0x1f4 }); }
static void Chapel_RevertMad(Enemy *e);
static void Chapel_madIn(void *c) {
    Chapel_ToggleBlue(0), Chapel_ToggleRed(1), Chapel_ToggleAlias(1), Chapel.alias = 1;
    if (ChS.maddener) ChS.maddener->onDefeat = Chapel_RevertMad;
    Chapel_faderOut(c);
}
static void Chapel_madOut(void *c) { Chapel_ToggleBlue(1), Chapel_ToggleRed(0), Chapel_ToggleAlias(0), Chapel.alias = 0; Chapel_faderOut(c); }
static void Chapel_FadeToMad(void *c) {  // un lampo bianco e la Cappella diventa rossa
    (void)c;
    if (!ChS.maddener || ChS.maddener->isDead) return;
    tweens_add((TweenConfig){ .props = { { &Chapel.whiteFader.alpha, NULL, 1 } }, .nprops = 1, .duration = 0x1f4, .delay = 0x1f4, .onComplete = Chapel_madIn });
}
static void Chapel_RevertMad(Enemy *e) {
    (void)e;
    Chapel.alias = 0, ChS.maddener = NULL;
    tweens_add((TweenConfig){ .props = { { &Chapel.whiteFader.alpha, NULL, 1 } }, .nprops = 1, .duration = 0x1f4, .delay = 0x1f4, .onComplete = Chapel_madOut });
}
