// Lang.getLang con un parametro: sostituisce %0
static const char *lang1(const char *key, const char *a0) {
    static char buf[4][256];
    static int k;
    char *o = buf[k++ & 3];
    const char *s = tr(key), *p = strstr(s, "%0");
    if (!p) { snprintf(o, 256, "%s", s); return o; }
    snprintf(o, 256, "%.*s%s%s", (int)(p - s), s, a0, p + 2);
    return o;
}
static const char *fix(float v, int d) {  // Number.toFixed: a parita' l'intero piu' grande (0.5 -> "1"), printf arrotonda al pari
    static char b[8][32];
    static int k;
    char *o = b[k++ & 7];
    double p = pow(10, d), a = floor(fabs((double)v) * p + 0.5) / p;
    snprintf(o, 32, "%.*f", d, v < 0 ? -a : a);
    return o;
}

// LevelUpPanel.ParseLevelUpInfo
static void ParseLevelUpInfo(cJSON *lv, int all, char *out, size_t cap) {
    out[0] = 0;
    for (cJSON *it = lv ? lv->child : NULL; it; it = it->next) {
        const char *k = it->string;
        float V = (float)it->valuedouble;
        char add[256] = "";
        const char *A = all ? tr("weaponLevelUp_all") : "";
        if (!strcmp(k, "power")) snprintf(add, sizeof(add), "%s", all ? lang1("weaponLevelUp_damageAll", fix(100 * V, 0)) : lang1("weaponLevelUp_damage", fix(10 * V, 0)));
        else if (!strcmp(k, "area")) snprintf(add, sizeof(add), "%s%s", A, lang1("weaponLevelUp_area", fix(100 * V, 0)));
        else if (!strcmp(k, "speed")) snprintf(add, sizeof(add), "%s%s", A, lang1("weaponLevelUp_speed", fix(100 * V, 0)));
        else if (!strcmp(k, "amount")) snprintf(add, sizeof(add), "%s%s", A, (int)V > 1 ? lang1("weaponLevelUp_projectiles", fix(V, 0)) : lang1("weaponLevelUp_projectile", fix(V, 0)));
        else if (!strcmp(k, "penetrating")) snprintf(add, sizeof(add), "%s%s", A, (int)V > 1 ? lang1("weaponLevelUp_enemies", fix(V, 0)) : lang1("weaponLevelUp_enemy", fix(V, 0)));
        else if (!strcmp(k, "charges")) snprintf(add, sizeof(add), "%s", (int)V > 1 ? lang1("weaponLevelUp_charges", fix(V, 0)) : lang1("weaponLevelUp_charge", fix(V, 0)));
        else if (!strcmp(k, "duration")) snprintf(add, sizeof(add), "%s", all ? lang1("weaponLevelUp_effectPerc", fix(100 * V, 0)) : lang1("weaponLevelUp_effect", fix(0.001f * V, 1)));
        else if (!strcmp(k, "cooldown")) snprintf(add, sizeof(add), "%s%s", A, lang1("weaponLevelUp_cooldownPerc", fix(-100 * V, 1)));
        else if (!strcmp(k, "interval")) snprintf(add, sizeof(add), "%s%s", A, V < 0 ? lang1("weaponLevelUp_cooldown", fix(-0.001f * V, 1)) : lang1("weaponLevelUp_cooldownIncreased", fix(0.001f * V, 1)));
        else if (!strcmp(k, "maxHp")) snprintf(add, sizeof(add), "%s", lang1("weaponLevelUp_health", fix(100 * V, 0)));
        else if (!strcmp(k, "growth")) snprintf(add, sizeof(add), "%s", V < 0 ? lang1("weaponLevelUp_xpDecreased", fix(100 * V, 0)) : lang1("weaponLevelUp_xp", fix(100 * V, 0)));
        else if (!strcmp(k, "moveSpeed")) snprintf(add, sizeof(add), "%s", lang1("weaponLevelUp_movement", fix(100 * V, 0)));
        else if (!strcmp(k, "magnet")) snprintf(add, sizeof(add), "%s", lang1("weaponLevelUp_range", fix(100 * V, 0)));
        else if (!strcmp(k, "luck")) snprintf(add, sizeof(add), "%s", lang1("weaponLevelUp_luck", fix(100 * V, 0)));
        else if (!strcmp(k, "regen")) snprintf(add, sizeof(add), "%s", lang1("weaponLevelUp_recovery", fix(V, 1)));
        else if (!strcmp(k, "greed")) snprintf(add, sizeof(add), "%s", lang1("weaponLevelUp_value", fix(100 * V, 0)));
        else if (!strcmp(k, "armor")) snprintf(add, sizeof(add), "%s", lang1("weaponLevelUp_reduceDamage", fix(V, (V == (int)V) ? 0 : 1)));
        else if (!strcmp(k, "shieldInvulTime")) snprintf(add, sizeof(add), "%s", lang1("weaponLevelUp_shield", fix(0.001f * V, 1)));
        else if (!strcmp(k, "revivals")) snprintf(add, sizeof(add), "%s", lang1("weaponLevelUp_revivals", fix(V, 0)));
        else if (!strcmp(k, "curse")) snprintf(add, sizeof(add), "%s", lang1("weaponLevelUp_curse", fix(100 * V, 0)));
        else if (!strcmp(k, "desc") && cJSON_IsString(it)) snprintf(add, sizeof(add), "%s\n", it->valuestring);
        else if (!strcmp(k, "override") && cJSON_IsString(it)) { snprintf(out, cap, "%s\n", it->valuestring); continue; }
        // customDesc / customOverride: armi speciali non ancora tradotte
        strncat(out, add, cap - strlen(out) - 1);
    }
}


static void Player_SetInvulForMilliSecondsNonCumulative(Player *p, float ms) {
    Player_setIsInvul(p, 1);
    if (p->invulTime < ms) p->invulTime = ms;
}



static float text_wrap(const char *s, Vector2 p, float size, float wrap, Color c) {  // y dell'ultima riga; c.a 0 = misura e basta
    char line[256] = "";
    float y = p.y;
    const char *w = s;
    while (*w) {
        const char *e = w;
        while (*e && *e != ' ' && *e != '\n') e++;
        char cand[256];
        snprintf(cand, sizeof(cand), "%s%s%.*s", line, *line ? " " : "", (int)(e - w), w);
        if (MeasureTextEx(vs_font, cand, size, 1).x > wrap && *line) {
            if (c.a) DrawTextEx(vs_font, line, (Vector2){ p.x, y }, size, 1, c);
            y += size * 1.15f;
            snprintf(line, sizeof(line), "%.*s", (int)(e - w), w);
        } else {
            snprintf(line, sizeof(line), "%s", cand);
        }
        if (*e == '\n') { if (c.a) DrawTextEx(vs_font, line, (Vector2){ p.x, y }, size, 1, c); y += size * 1.15f; line[0] = 0; }
        w = *e ? e + 1 : e;
    }
    if (*line && c.a) DrawTextEx(vs_font, line, (Vector2){ p.x, y }, size, 1, c);
    return y;
}

static void TS_frame(const char *atlas, const char *name, float x, float y, float ox, float oy, float sc, float ang, Color c, int add);
// LevelUpWeaponPanel.ParseLimitBreakUpInfo
static void ParseLimitBreakUpInfo(cJSON *kv, char *out, size_t cap) {
    out[0] = 0;
    for (cJSON *it = kv ? kv->child : NULL; it; it = it->next) {
        const char *k = it->string;
        float V = (float)it->valuedouble;
        char add[256] = "";
        if (!strcmp(k, "power")) snprintf(add, sizeof(add), "%s", lang1("limitBreak_might", fix(10 * V, 0)));
        else if (!strcmp(k, "area")) snprintf(add, sizeof(add), "%s", lang1("limitBreak_area", fix(100 * V, 0)));
        else if (!strcmp(k, "speed")) snprintf(add, sizeof(add), "%s", lang1("limitBreak_speed", fix(100 * V, 0)));
        else if (!strcmp(k, "amount")) snprintf(add, sizeof(add), "%s", lang1("limitBreak_amount", fix(V, 0)));
        else if (!strcmp(k, "penetrating")) snprintf(add, sizeof(add), "%s", lang1("limitBreak_passes", fix(V, 0)));
        else if (!strcmp(k, "duration")) snprintf(add, sizeof(add), "%s", lang1("limitBreak_duration", fix(V, 0)));
        else if (!strcmp(k, "cooldown")) snprintf(add, sizeof(add), "%s", lang1("limitBreak_cooldown", fix(-100 * V, 1)));
        else if (!strcmp(k, "critChance")) snprintf(add, sizeof(add), "%s", lang1("limitBreak_critical", fix(100 * V, 1)));
        else if (!strcmp(k, "chance")) snprintf(add, sizeof(add), "%s", lang1("limitBreak_chance", fix(100 * V, 1)));
        else if (!strcmp(k, "desc") && cJSON_IsString(it)) snprintf(add, sizeof(add), "%s\n", it->valuestring);
        else if (!strcmp(k, "override") && cJSON_IsString(it)) { snprintf(out, cap, "%s\n", it->valuestring); continue; }
        strncat(out, add, cap - strlen(out) - 1);
    }
}

// 0x15db6: il pannello di un'arma (level-up e oggetto trovato); lb: AssignLimitBreakData
static float fit_size(const char *s, float size, float maxW);
static void ui_arrows(float x, float y, float halfW, float t);
