static struct {
    int active, canSeeReviveButton, buttonsOn, rewardOn, sel;  // sel: 0 QuitButton, 1 ReviveButton (UI_grid 1 x 2)
    float t, tButtons, tQuit, bonusFrom, tReward, tRevive;
} GO;
static struct { float totalCoins; int awardGivenXTimes; } GOS;  // campi del costruttore della scena: restano tra un game over e l'altro

static void text_at(const char *s, float x, float y, float size, float ox, float oy, Color c) {  // Text con origine (ox, oy)
    Vector2 m = MeasureTextEx(vs_font, s, size, 0);
    DrawTextEx(vs_font, s, (Vector2){ roundf(x - ox * m.x), roundf(y - oy * m.y) }, size, 0, c);
}
static void ui_arrows(float x, float y, float halfW, float t) {  // UI_overlayScene: frecce ai lati del selezionato
    char an[16];
    snprintf(an, sizeof(an), "arrow_%02d.png", (int)(t / (1000.0f / 6)) % 8 + 1);
    TS_frame("UI", an, x - halfW, y, 1, 0.5f, 2, 0, WHITE, 0);
    const Frame *af = frame_get("UI", an);
    if (!af) return;
    Sprite a;
    sprite_init(&a, af, x + halfW, y);
    sprite_setOrigin(&a, 0, 0.5f);  // flip sul posto: con 0 la freccia sta fuori dal bottone come quella a sinistra
    sprite_setScale(&a, 2);
    a.flipX = 1;
    a.scrollFactor0 = 1;
    scene_render_one(&a, (Shader){ 0 });
}
