// Player.Revive (0x869f): la tinta e l'oscillazione lasciate dall'animazione di morte restano come nell'originale
static void Player_Revive(Player *p, float k) {
    p->isDead = 0;
    p->s.body.enable = 1;
    sprite_setScale(&p->s, PixelScale);
    Player_RecoverHp(p, p->maxHp * k, 0, 0);
    Player_SetInvulForMilliSeconds(p, 0x7d0);
    p->hasLastBreath = 1;
    PlayerUI_Update();
    if (Player_is(p, "PAVONE")) Core_RosaryDamage();  // 0x14f3e
    if (Player_is(p, "LUMINAIRE")) Lum_Revive(p);
}
