// 0xc450: AchievementManager (achievement e segreti sbloccati a fine partita; i premi: armi, personaggi, stage,
// hyper, reliquie, monete, ranghi dei potenziamenti, arcane). CheckAchievements_Moonspell/Foscari: DLC, F5
// ============================================================================
static const char *AM_NewAchievements[160], *AM_NewSecrets[128];
static int AM_nNew, AM_nNewSecrets;
static double killed(const char *e) { return num(tbl0("enemies", e), "killedAmount", 0); }
static double pickedAmount(const char *i) { return num(cJSON_GetObjectItem(data_get("items"), i), "pickedupAmount", 0); }
static int hasItem(const char *i) { return po_has("CollectedItems", i); }
static int stageIs(const char *s) { return po_str("SelectedStage") && !strcmp(po_str("SelectedStage"), s); }
static int charIs(const char *c) { return Core.Player && !strcmp(Core.Player->characterType, c); }
static int weaponLv(const char *t, int lv) { Weapon *w = Core_GetWeapon(t); return w && w->level >= lv; }
static void AM_grant(cJSON *a) {  // i premi comuni di UnlockAchievement / UnlockSecret
    const char *w = str(a, "weaponToUnlock"), *c = str(a, "characterToUnlock"), *st = str(a, "stageToUnlock"), *hy = str(a, "hyperToUnlock"), *r = str(a, "relicToUnlock"), *pu = str(a, "powerUpToUnlock");
    if (w) { if (!po_has("UnlockedWeapons", w)) po_push("UnlockedWeapons", w); obj_set(tbl0("weapons", w), "isUnlocked", cJSON_CreateTrue()); }
    if (c) { if (!po_has("UnlockedCharacters", c)) po_push("UnlockedCharacters", c); obj_set(tbl0("characters", c), "hidden", cJSON_CreateFalse()); }
    if (st) { if (!po_has("UnlockedStages", st)) po_push("UnlockedStages", st); obj_set(tbl0("stages", st), "unlocked", cJSON_CreateTrue()), obj_set(tbl0("stages", st), "hidden", cJSON_CreateFalse()); }
    if (hy) { if (!po_has("UnlockedHypers", hy)) po_push("UnlockedHypers", hy); obj_set(cJSON_GetObjectItem(tbl0("stages", hy), "hyper"), "unlocked", cJSON_CreateTrue()); }
    if (r) { if (!hasItem(r)) po_push("CollectedItems", r); obj_set(cJSON_GetObjectItem(data_get("items"), r), "seen", cJSON_CreateTrue()); }
    if (num(a, "goldPrize", 0)) PlayerOptions_AddCoinsFlat(num(a, "goldPrize", 0));
    if (pu) { po_push("UnlockedPowerUpRanks", pu); cJSON *p = tbl0("powerups", pu); obj_set(p, "hidden", cJSON_CreateFalse()), obj_set(p, "unlockedRank", cJSON_CreateNumber(num(p, "unlockedRank", 0) + 1)); }
    cJSON *ar = cJSON_GetObjectItem(a, "arcanaToUnlock");
    if (cJSON_IsNumber(ar) && ar->valuedouble >= 0) {
        char b[16];
        snprintf(b, sizeof(b), "%d", ar->valueint);
        if (!po_has("UnlockedArcanas", b)) cJSON_AddItemToArray(po("UnlockedArcanas"), cJSON_CreateNumber(ar->valueint));
        obj_set(tbl0("arcana", b), "unlocked", cJSON_CreateTrue());
    }
}
static void AchievementManager_UnlockAchievement(const char *k) {
    cJSON *a = cJSON_GetObjectItem(data_get("achievements"), k);
    if (!a) { TraceLog(LOG_INFO, "VS: %s", k); return; }
    if (cJSON_IsTrue(cJSON_GetObjectItem(a, "achieved"))) return;
    obj_set(a, "achieved", cJSON_CreateTrue());
    trophies_unlock(k);
    AM_grant(a);  // (sic) qui le armi restano hidden; UnlockSecret le mostra
    if (!po_has("Achievements", k)) po_push("Achievements", k);
    if (AM_nNew < 160) AM_NewAchievements[AM_nNew++] = cJSON_GetObjectItem(data_get("achievements"), k)->string;
}
static int AchievementManager_UnlockSecret(const char *k) {
    cJSON *s = cJSON_GetObjectItem(data_get("secrets"), k);
    if (!s || cJSON_IsTrue(cJSON_GetObjectItem(s, "achieved"))) return 0;
    obj_set(s, "achieved", cJSON_CreateTrue());
    const char *w = str(s, "weaponToUnlock");
    AM_grant(s);
    if (w) obj_set(tbl0("weapons", w), "hidden", cJSON_CreateFalse());
    if (!po_has("Secrets", k)) po_push("Secrets", k);
    if (AM_nNewSecrets < 128) AM_NewSecrets[AM_nNewSecrets++] = s->string;
    PlayerOptions_Save();
    return 1;
}
