static struct {
    int visible;
    UIButton BackButton, OptionsButton, ExitButton, CoinsBG;
    int backOn, optionsOn, exitOn;
    char CoinsText[16];
} TB;
static int menu_quit;  // Integration.closeGame
static void TopBar_UpdateCoins(void) {
    double c = po_num("Coins");
    if (c < 0x989680) snprintf(TB.CoinsText, sizeof(TB.CoinsText), "%.0f", c);
    else snprintf(TB.CoinsText, sizeof(TB.CoinsText), "9999999");
}
static void TopBar_DisableBack(void) { TB.BackButton.visible = 0; TB.backOn = 0; UIButton_off(&TB.BackButton); }
static void TopBar_DisableOptions(void) {
    TB.OptionsButton.visible = 0, TB.optionsOn = 0; UIButton_off(&TB.OptionsButton);
    TB.ExitButton.visible = 0, TB.exitOn = 0; UIButton_off(&TB.ExitButton);
}
static void (*TB_backCb)(void), (*TB_optionsCb)(void);
static void TB_onBack(void *ctx) {
    (void)ctx;
    void (*cb)(void) = TB_backCb;
    UIButton_off(&TB.BackButton);
    if (cb) cb();
    Sound_PlaySimple("ClickOut", 0);
    PlayerOptions_Save();
}
static void TB_onOptions(void *ctx) {
    (void)ctx;
    void (*cb)(void) = TB_optionsCb;
    UIButton_off(&TB.OptionsButton);
    if (cb) cb();
    Sound_PlaySimple("ClickOut", 0);
}
static void TB_onExit(void *ctx) { (void)ctx; Sound_PlaySimple("ClickOut", 0); menu_quit = 1; }
static void TopBar_EnableBack(void (*cb)(void)) {
    TB.BackButton.visible = 1, TB.backOn = 1, TB_backCb = cb;
    UIButton_on(&TB.BackButton, TB_onBack, NULL);
    TopBar_DisableOptions();
}
static void TopBar_EnableOptions(void (*cb)(void)) {
    TB.OptionsButton.visible = 1, TB.optionsOn = 1, TB_optionsCb = cb;
    UIButton_on(&TB.OptionsButton, TB_onOptions, NULL);
    TopBar_DisableBack();
    TB.ExitButton.visible = 1, TB.exitOn = 1;  // Integration.isDesktop(): anche sulla Vita si esce dal gioco
    UIButton_on(&TB.ExitButton, TB_onExit, NULL);
}
static void SceneManager_OptionsFromMainMenu(void);
static const char *TB_title;  // Vita: il titolo della schermata nella barra in alto (NULL nel menu principale)
static void TopBar_create(void) {  // Vita: barra alta 52 px, Indietro o Opzioni a sinistra, monete a destra
    memset(&TB, 0, sizeof(TB));
    UIButton_set(&TB.BackButton, "BackButton", 12, 8, 150, 36, 1, 0, 0);
    UIButton_set(&TB.OptionsButton, "OptionsButton", 12, 8, 150, 36, 1, 0, 0);
    UIButton_set(&TB.ExitButton, "BackButton", 12, 8, 150, 36, 1, 0, 0);
    TB.ExitButton.visible = 0;  // sulla Vita si esce col tasto PS
    UIButton_set(&TB.CoinsBG, "ProgressBox", MENU_W - 16, 8, 170, 36, 1, 1, 0);
    TopBar_UpdateCoins();
    TB.visible = 0;  // Hide
    TB_title = NULL;
    TopBar_DisableBack();
}
static void TopBar_Show(void) { TB.visible = 1; TopBar_EnableOptions(SceneManager_OptionsFromMainMenu); }
static void TopBar_update(void) {
    if (!TB.visible) return;
    UIButton *B[3] = { &TB.BackButton, &TB.OptionsButton, &TB.ExitButton };
    for (int i = 0; i < 3; i++) if (UIButton_clicked(B[i])) break;
}
static void TopBar_draw(void) {
    if (!TB.visible) return;
    DrawRectangle(0, 0, MENU_W, 52, (Color){ 12, 6, 10, 200 });
    DrawRectangle(0, 50, MENU_W, 2, rgb(0x8a6a2a, 1));
    TB.ExitButton.visible = 0;
    UIButton *b = TB.BackButton.visible ? &TB.BackButton : TB.OptionsButton.visible ? &TB.OptionsButton : NULL;
    if (b) {
        UIButton_draw(b, 1);
        vui_glyph(b == &TB.BackButton ? G_CIRCLE : G_TRIANGLE, b->x + 20, b->y + 18, 11);
        text_at(tr(b == &TB.BackButton ? "topBar_back" : "topBar_options"), b->x + 38, b->y + 18, fit_size(tr("topBar_back"), 22, 104), 0, 0.5f, WHITE);
    }
    if (TB_title) text_at(TB_title, 206, 26, fit_size(TB_title, 32, 534), 0, 0.5f, rgb(VUI_GOLD, 1));  // dopo la freccia del cursore su Indietro
    UIButton_draw(&TB.CoinsBG, 1);
    float L = UI_left(&TB.CoinsBG);
    TS_frame("UI", "MoneyPile.png", L + 8, 26, 0, 0.5f, 1.5f, 0, WHITE, 0);
    text_at(TB.CoinsText, L + bW(&TB.CoinsBG) - 12, 26, 26, 1, 0.5f, WHITE);
}

