    UIButton *B[] = { &MM.StartButton, &MM.PowerupButton, &MM.CollectionButton, &MM.AchievementButton, &MM.BestiaryButton, &MM.SecretsButton, &MM.CreditsButton };
    for (size_t i = 0; i < sizeof(B) / sizeof(*B); i++) UIButton_draw(B[i], 1);
