#define CS_MAX 96
typedef struct { struct { const char *name, *powerupType, *type; int omni; float value; int tinted; } s[23]; } CharStatsPanel;  // 0xe199
typedef struct { const char *ch; float x, y; unsigned bgTint; UIButton hit; } CharPanel;
