    int active, n, Columns, Rows, ShowScrollbar, isReadyToStart, isStartingGameMode, hasGoldenEggs, hasNoseglasses;
    int gridBottom, gridLast, hcVisible, statsVisible, levelVisible, moveButtonsAcross, statsOpen;  // statsOpen: Vita, quadrato
    const char *Highlighted;
    CharPanel panels[CS_MAX], *HighlightedPanel, *currentlyHighlightedPanel;
    float scY, scMaxY, scMinY, scH, y0;  // ScrollableContainer (y, MaxY, MinY, trueHeight) e SceneContainer.y
    float scrollTopY, scrollHeight, hcX, hcY, t, openAt;
    float cpX, cpY, cpW, buttonX, buttonW, descW;  // CharConfirmationPanel
