// Number.toString di JS per i numeri delle schede (la rappresentazione piu' corta che torna uguale)
static const char *js_num(double v) {
    static char b[4][32];
    static int k;
    char *o = b[k++ & 3];
    if (isnan(v)) return "NaN";
    int p = 0;
    while (++p < 17 && (snprintf(o, 32, "%.*g", p, v), strtod(o, NULL) != v)) {}
    if (p == 17) snprintf(o, 32, "%.17g", v);
    double a = fabs(v);
    if (strchr(o, 'e') && a >= 1e-6 && a < 1e21) {  // JS scrive in notazione fissa fra 1e-6 e 1e21: 140, non 1.4e+02
        int d = p - 1 - (int)floor(log10(a));
        snprintf(o, 32, "%.*f", d > 0 ? d : 0, v);
    }
    return o;
}
static const char *stage_text(const char *id, const char *field) {  // stageName/description/hyperTips localizzati, se no i dati
    const char *s = tr_of("stageLang", id, field);
    return *s ? s : str(tbl0("stages", id), field) ? str(tbl0("stages", id), field) : "";
}

