    if (SS.rpExists && SS.rpVisible) row[n++] = &SS.rpBox;
    for (int i = 0; i < 6; i++) if (SS.toggles[i].visible) row[n++] = &SS.toggles[i].box;
    float y0 = n > 4 ? 362 : 400;
    for (int i = 0; i < n; i++) row[i]->x = 414 + i % 4 * 127, row[i]->y = y0 + i / 4 * 38, row[i]->w = 122, row[i]->h = 34, row[i]->sc = 1, row[i]->ox = row[i]->oy = 0;
