                snprintf(pre, sizeof(pre), "%.*si", (int)(strstr(fn, "0.png") ? strstr(fn, "0.png") - fn : (long)strlen(fn)), fn);
                make_anim(an, tn, pre, 1, (int)num(d, "idleFrameCount", 0), 2, 8, -1);
